function isValid(s) {
    const stack = [];

    for (const c of s) {
        if (c === '(' || c === '{' || c === '[') {
            stack.push(c);
        } else {
            if (!stack.length) return false;
            if (c === ')' && stack[stack.length - 1] !== '(') return false;
            if (c === '}' && stack[stack.length - 1] !== '{') return false;
            if (c === ']' && stack[stack.length - 1] !== '[') return false;
            stack.pop();
        }
    }

    return stack.length === 0;
}

