    ListNode dummy(0);
    dummy.next = head;
    ListNode *prev = &dummy;
    cur = head;

    while (len >= k) {
        for (int i = 1; i < k; i++) {
            ListNode *temp = cur->next;
            cur->next = temp->next;
            temp->next = prev->next;
            prev->next = temp;
        }
        prev = cur;
        cur = cur->next;
        len -= k;
    }

    return dummy.next;
}

