function divide(dividend, divisor) {
    if (dividend === -Math.pow(2, 31) && divisor === -1) {
        return Math.pow(2, 31) - 1;
    }

    const sign = (dividend > 0) ^ (divisor > 0) ? -1 : 1;

    let dvd = Math.abs(dividend);
    let dvs = Math.abs(divisor);
    let ans = 0;

    while (dvd >= dvs) {
        let temp = dvs;
        let multiple = 1;
        while (dvd >= (temp << 1)) {
            temp <<= 1;
            multiple <<= 1;
        }
        dvd -= temp;
        ans += multiple;
    }

    return ans * sign;
}

