function nextPermutation(nums) {
    let n = nums.length, k = n - 2, l;
    while(k >= 0 && nums[k] >= nums[k + 1]) k--;

    if(k < 0) {
        nums.sort((a, b) => a - b);
    } else {
        for (l = n - 1; l > k; l--) {
            if (nums[l] > nums[k]) break;
        }
        [nums[k], nums[l]] = [nums[l], nums[k]];
        let tempArr = nums.slice(k + 1).sort((a, b) => a - b);
        nums.splice(k + 1, n - k - 1, ...tempArr);
    }
}

