string multiply(string num1, string num2) {
    int m = num1.size(), n = num2.size();
    string res(m + n, '0');
    for (int i = m - 1; i >= 0; i--) {
        for (int j = n - 1; j >= 0; j--) {
            int p1 = i + j, p2 = i + j + 1;
            int mult = (num1[i] - '0') * (num2[j] - '0') + (res[p2] - '0');
            res[p1] += mult / 10;
            res[p2] = (mult % 10) + '0';
        }
    }
    while (res.size() > 1 && res[0] == '0')
        res.erase(res.begin());
    return res;
}

