        for (let j = n - 1; j >= 0; j--) {
            let mult = (num1[i] - '0') * (num2[j] - '0');
            let p1 = i + j, p2 = i + j + 1;
            let sum = mult + pos[p2];
            pos[p1] += Math.floor(sum / 10);
            pos[p2] = sum % 10;
        }
    }

    while (pos.length > 1 && pos[0] == 0)
        pos.shift();
    return pos.join('');
}

