function helper(nums, index, results) {
  if (index === nums.length - 1) {
    results.push(nums.slice());
    return;
  }

  for (let i = index; i < nums.length; i++) {
    [nums[index], nums[i]] = [nums[i], nums[index]];
    helper(nums, index + 1, results);
    [nums[index], nums[i]] = [nums[i], nums[index]];
  }
}

