#include <vector>
#include <string>

bool isSafe(const std::vector<std::string>& board, int row, int col, int n) {
    for (int i = 0; i < col; ++i) {
        if (board[row][i] == 'Q') return false;
    }
    for (int i = row, j = col; i >= 0 && j >= 0; --i, --j) {
        if (board[i][j] == 'Q') return false;
    }
    for (int i = row, j = col; i < n && j >= 0; ++i, --j) {
        if (board[i][j] == 'Q') return false;
    }
    return true;
}

void solve(std::vector<std::vector<std::string>>& result, std::vector<std::string>& board, int n, int col) {
    if (col == n) {
        result.push_back(board);
        return;
    }
    for (int row = 0; row < n; ++row) {
        if (isSafe(board, row, col, n)) {
            board[row][col] = 'Q';
            solve(result, board, n, col + 1);
            board[row][col] = '.';
        }
    }
}

std::vector<std::vector<std::string>> solveNQueens(int n) {
    std::vector<std::vector<std::string>> result;
    std::vector<std::string> board(n, std::string(n, '.'));
    solve(result, board, n, 0);
    return result;
}

python_code:
def solveNQueens(n):
    def isSafe(board, row, col):
        for i in range(col):
            if board[row][i] == 'Q': return False
        i, j = row, col
        while i >= 0 and j >= 0:
            if board[i][j] == 'Q': return False
            i, j = i - 1, j - 1
        i, j = row, col
        while i < n and j >= 0:
            if board[i][j] == 'Q': return False
            i, j = i + 1, j - 1
        return True

    def solve(result, board, n, col):
        if col == n:
            result.append(board.copy())
            return
        for row in range(n):
            if isSafe(board, row, col):
                board[row] = board[row][:col] + 'Q' + board[row][col + 1:]
                solve(result, board, n, col + 1)
                board[row] = board[row][:col] + '.' + board[row][col + 1:]

    result, board = [], ['.' * n for _ in range(n)]
    solve(result, board, n, 0)
    return result

javascript_code:
function solveNQueens(n) {
  function isSafe(board, row, col) {
    for (let i = 0; i < col; i++)
      if (board[row][i] == 'Q') return false;
    for (let i = row, j = col; i >= 0 && j >= 0; i--, j--)
      if (board[i][j] == 'Q') return false;
    for (let i = row, j = col; i < n && j >= 0; i++, j--)
      if (board[i][j] == 'Q') return false;
    return true;
  }

  function solve(result, board, n, col) {
    if (col == n) {
      result.push(board.map(row => row.join('')));
      return;
    }
    for (let row = 0; row < n; row++) {
      if (isSafe(board, row, col)) {
        board[row][col] = 'Q';
        solve(result, board, n, col + 1);
        board[row][col] = '.';
      }
    }
  }

  const result = [];
  const board = Array.from({ length: n }, () => Array(n).fill('.'));
  solve(result, board, n, 0);
  return result;
}

java_code:
import java.util.ArrayList;

public int totalNQueens(int n) {
    ArrayList<Integer> cols = new ArrayList<>();
    return backtrack(n, cols);
}

public int backtrack(int n, ArrayList<Integer> cols) {
    if (cols.size() == n) {
        return 1;
    }

    int count = 0;
    for (int i = 0; i < n; i++) {
        if (isSafe(cols, i)) {
            cols.add(i);
            count += backtrack(n, cols);
            cols.remove(cols.size() - 1);
        }
    }
    return count;
}

public boolean isSafe(ArrayList<Integer> cols, int row) {
    int col = cols.size();
    for (int i = 0; i < cols.size(); i++) {
        if (cols.get(i) == row || Math.abs(i - col) == Math.abs(cols.get(i) - row)) {
            return false;
        }
    }
    return true;
}

