    return true;
}

void backtrack(int n, vector<int> &cols, int &count) {
    if (cols.size() == n) {
        count++;
        return;
    }

    for (int i = 0; i < n; i++) {
        if (isSafe(cols, i)) {
            cols.push_back(i);
            backtrack(n, cols, count);
            cols.pop_back();
        }
    }
}

int totalNQueens(int n) {
    vector<int> cols;
    int count = 0;
    backtrack(n, cols, count);
    return count;
}

