function addBinary(a, b) {
    let result = "";
    let i = a.length - 1, j = b.length - 1, carry = 0;
    while (i >= 0 || j >= 0 || carry) {
        if (i >= 0) carry += parseInt(a[i--], 10);
        if (j >= 0) carry += parseInt(b[j--], 10);
        result = (carry % 2) + result;
        carry = Math.floor(carry / 2);
    }
    return result;
}

java_code:
import java.util.ArrayList;
import java.util.List;

public List<String> fullJustify(String[] words, int maxWidth) {
    List<String> result = new ArrayList<>();
    int idx = 0;
    while (idx < words.length) {
        int totalChars = words[idx].length();
        int last = idx + 1;
        while (last < words.length) {
            if (totalChars + 1 + words[last].length() > maxWidth) break;
            totalChars += 1 + words[last].length();
            last++;
        }
        int gaps = last - idx - 1;
        StringBuilder line = new StringBuilder();
        if (last == words.length || gaps == 0) {
            for (int i = idx; i < last; i++) {
                line.append(words[i]);
                if (i < last - 1) line.append(" ");
            }
            while (line.length() < maxWidth) line.append(" ");
        } else {
            int evenSpaces = (maxWidth - totalChars) / gaps;
            int extraSpaces = (maxWidth - totalChars) % gaps;
            for (int i = idx; i < last; i++) {
                line.append(words[i]);
                if (i < last - 1) {
                    line.append(" ".repeat(evenSpaces + (i - idx < extraSpaces ? 1 : 0)));
                }
            }
        }
        idx = last;
        result.add(line.toString());
    }
    return result;
}

