using namespace std;

vector<string> fullJustify(vector<string>& words, int maxWidth) {
    vector<string> result;
    int idx = 0;
    while (idx < words.size()) {
        int totalChars = words[idx].size();
        int last = idx + 1;
        while (last < words.size()) {
            if (totalChars + 1 + words[last].length() > maxWidth) break;
            totalChars += 1 + words[last].length();
            last++;
        }
        int gaps = last - idx - 1;
        stringstream line;
        if (last == words.size() || gaps == 0) {
            for (int i = idx; i < last; i++) {
                line << words[i];
                if (i < last - 1) line << " ";
            }
            line << string(maxWidth - line.str().size(), ' ');
        } else {
            int evenSpaces = (maxWidth - totalChars) / gaps;
            int extraSpaces = (maxWidth - totalChars) % gaps;
            for (int i = idx; i < last; i++) {
                line << words[i];
                if (i < last - 1) {
                    line << string(evenSpaces + (i - idx < extraSpaces ? 1 : 0), ' ');
                }
            }
        }
        idx = last;
        result.push_back(line.str());
    }
    return result;
}

python_code:
def fullJustify(words, maxWidth):
    result = []
    idx = 0
    while idx < len(words):
        total_chars = len(words[idx])
        last = idx + 1
        while last < len(words):
            if total_chars + 1 + len(words[last]) > maxWidth:
                break
            total_chars += 1 + len(words[last])
            last += 1
        gaps = last - idx - 1
        line = []
        if last == len(words) or gaps == 0:
            for i in range(idx, last):
                line.append(words[i])
                if i < last - 1:
                    line.append(" ")
            while sum(len(w) for w in line) < maxWidth:
                line.append(" ")
        else:
            even_spaces = (maxWidth - total_chars) // gaps
            extra_spaces = (maxWidth - total_chars) % gaps
            for i in range(idx, last):
                line.append(words[i])
                if i < last - 1:
                    line.append(" " * (even_spaces + (1 if i - idx < extra_spaces else 0)))
        idx = last
        result.append("".join(line))
    return result

