function combine(n, k) {
    const result = [];
    backtrack(n, k, 1, [], result);
    return result;
}

function backtrack(n, k, start, current, result) {
    if (current.length === k) {
        result.push([...current]);
        return;
    }

    for (let i = start; i <= n; i++) {
        current.push(i);
        backtrack(n, k, i + 1, current, result);
        current.pop();
    }
}

