    int n = board[0].size();

    function<bool(int, int, int)> dfs = [&](int i, int j, int k) {
        if (i < 0 || i >= m || j < 0 || j >= n || board[i][j] != word[k])
            return false;
        if (k == word.length() - 1)
            return true;

        char temp = board[i][j];
        board[i][j] = '/';
        bool res = dfs(i + 1, j, k + 1) || dfs(i - 1, j, k + 1) || dfs(i, j + 1, k + 1) || dfs(i, j - 1, k + 1);
        board[i][j] = temp;
        return res;
    };

    for (int i = 0; i < m; i++)
        for (int j = 0; j < n; j++)
            if (dfs(i, j, 0))
                return true;
    return false;
}

