import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

public List<List<Integer>> subsetsWithDup(int[] nums) {
    Set<List<Integer>> result = new HashSet<>();
    Arrays.sort(nums);
    backtrack(nums, 0, new ArrayList<Integer>(), result);
    return new ArrayList<>(result);
}

private void backtrack(int[] nums, int index, List<Integer> subset, Set<List<Integer>> result) {
    result.add(new ArrayList<>(subset));
    for (int i = index; i < nums.length; i++) {
        subset.add(nums[i]);
        backtrack(nums, i + 1, subset, result);
        subset.remove(subset.size() - 1);
    }
}

cpp_code:
#include <vector>
#include <set>
using namespace std;

vector<vector<int>> subsetsWithDup(vector<int>& nums) {
    set<vector<int>> result;
    vector<int> subset;
    sort(nums.begin(), nums.end());
    backtrack(nums, 0, subset, result);
    return vector<vector<int>>(result.begin(), result.end());
}

void backtrack(vector<int>& nums, int index, vector<int>& subset, set<vector<int>>& result) {
    result.insert(subset);
    for (int i = index; i < nums.size(); i++) {
        subset.push_back(nums[i]);
        backtrack(nums, i + 1, subset, result);
        subset.pop_back();
    }
}

