var numDecodings = function(s) {
    const n = s.length;
    const dp = new Array(n + 1).fill(0);
    dp[0] = 1;
    dp[1] = s[0] !== '0' ? 1 : 0;

    for (let i = 2; i <= n; i++) {
        const oneDigit = parseInt(s.slice(i - 1, i), 10);
        const twoDigits = parseInt(s.slice(i - 2, i), 10);

        if (oneDigit >= 1)
            dp[i] += dp[i - 1];
        if (twoDigits >= 10 && twoDigits <= 26)
            dp[i] += dp[i - 2];
    }
    return dp[n];
};

