    let pre = dummy;
    for (let i = 1; i < left; ++i) pre = pre.next;
    let cur = pre.next;
    for (let i = left; i < right; ++i) {
        const t = cur.next;
        cur.next = t.next;
        t.next = pre.next;
        pre.next = t;
    }
    return dummy.next;
}

