import java.util.ArrayList;
import java.util.List;

public List<String> restoreIpAddresses(String s) {
    List<String> result = new ArrayList<>();
    dfs(s, 0, "", result, 0);
    return result;
}

private void dfs(String s, int start, String ip, List<String> result, int part) {
    if (part == 4 && start == s.length()) {
        result.add(ip.substring(0, ip.length() - 1));
        return;
    }
    if (part == 4 || start >= s.length()) return;

    int num = 0;
    for (int i = start; i < s.length(); i++) {
        num = num * 10 + (s.charAt(i) - '0');
        if (num > 255) break;
        dfs(s, i + 1, ip + s.charAt(i) + ".", result, part + 1);
        if (num == 0) break;
    }
}

cpp_code:
#include<vector>
#include<string>
using namespace std;

vector<string> restore_ip_address(string s) {
    vector<string> result;
    string ip;
    dfs(result, s, ip, 0, 0);
    return result;
}

void dfs(vector<string>& result, string s, string ip, int start, int part) {
    if (part == 4 && start == s.size()) {
        ip.pop_back();
        result.push_back(ip);
        return;
    }
    if (part == 4 || start == s.size()) return;

    int num = 0;
    for (int i = start; i < s.size(); i++) {
        num = num * 10 + (s[i] - '0');
        if (num > 255) break;
        ip += s[i];
        dfs(result, s, ip + '.', i + 1, part + 1);
        if (num == 0) break;
    }
}

python_code:
def restore_ip_addresses(s):
    def dfs(s, start, ip, result, part):
        if part == 4 and start == len(s):
            result.append(ip[:-1])
            return
        if part == 4 or start >= len(s):
            return

        num = 0
        for i in range(start, len(s)):
            num = num * 10 + int(s[i])
            if num > 255:
                break
            dfs(s, i + 1, ip + s[i] + ".", result, part + 1)
            if num == 0:
                break

    result = []
    dfs(s, 0, "", result, 0)
    return result

