    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
    TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
};

TreeNode* buildTree(vector<int>& preorder, vector<int>& inorder, unordered_map<int, int>& in_map, int& pre_idx, int in_left, int in_right) {
    if (in_left > in_right) return nullptr;

    int root_val = preorder[pre_idx];
    TreeNode* root = new TreeNode(root_val);
    int idx = in_map[root_val];

    pre_idx++;
    root->left = buildTree(preorder, inorder, in_map, pre_idx, in_left, idx - 1);
    root->right = buildTree(preorder, inorder, in_map, pre_idx, idx + 1, in_right);

    return root;
}

TreeNode* buildTree(vector<int>& preorder, vector<int>& inorder) {
    unordered_map<int, int> in_map;
    int pre_idx = 0;
    for (int i =  0; i < inorder.size(); i++) {
        in_map[inorder[i]] = i;
    }
    return buildTree(preorder, inorder, in_map, pre_idx, 0, inorder.size() - 1);
}

