function pathSum(root, targetSum) {
    const ans = [];
    const helper = (root, targetSum, current) => {
        if (!root) return;
        current.push(root.val);
        if (!root.left && !root.right && targetSum === root.val) {
            ans.push([...current]);
        }
        helper(root.left, targetSum - root.val, current);
        helper(root.right, targetSum - root.val, current);
        current.pop();
    };

    helper(root, targetSum, []);
    return ans;
}

