        return null;
    }

    const queue = [root];

    while(queue.length) {
        let levelSize = queue.length;
        let prev = null;

        for(let i = 0; i < levelSize; i++) {
            let currentNode = queue.shift();

            if(prev) {
                prev.next = currentNode;
            }
            prev = currentNode;

            if(currentNode.left) queue.push(currentNode.left);
            if(currentNode.right) queue.push(currentNode.right);
        }
    }

    return root;
}

