function isPalindrome(s) {
    const cleaned = s.toLowerCase().replace(/[^a-z0-9]/g, '');
    let left = 0, right = cleaned.length - 1;
    while (left < right) {
        if (cleaned[left++] !== cleaned[right--]) return false;
    }
    return true;
}

java_code:
import java.util.*;

public List<List<String>> findLadders(String beginWord, String endWord, List<String> wordList) {
    Set<String> dict = new HashSet<>(wordList);
    if (!dict.contains(endWord)) {
        return Collections.emptyList();
    }

    Map<String, List<String>> adjacent = new HashMap<>();
    Map<String, Integer> distance = new HashMap<>();
    Queue<String> queue = new LinkedList<>();
    queue.offer(beginWord);
    distance.put(beginWord, 0);

    while (!queue.isEmpty()) {
        String current = queue.poll();
        if (current.equals(endWord)) {
            break;
        }
        for (String neighbor : neighbors(current)) {
            if (!dict.contains(neighbor)) {
                continue;
            }
            if (!distance.containsKey(neighbor)) {
                distance.put(neighbor, distance.get(current) + 1);
                queue.offer(neighbor);
            }
            if (distance.get(neighbor).equals(distance.get(current) + 1)) {
                adjacent.computeIfAbsent(current, k -> new ArrayList<>()).add(neighbor);
            }
        }
    }

    List<List<String>> result = new ArrayList<>();
    List<String> path = new ArrayList<>();
    path.add(beginWord);
    backtrack(beginWord, endWord, path, adjacent, result);
    return result;
}

private void backtrack(String current, String endWord, List<String> path, Map<String, List<String>> adjacent, List<List<String>> result) {
    if (current.equals(endWord)) {
        result.add(new ArrayList<>(path));
        return;
    }
    for (String next : adjacent.getOrDefault(current, Collections.emptyList())) {
        path.add(next);
        backtrack(next, endWord, path, adjacent, result);
        path.remove(path.size() - 1);
    }
}

private List<String> neighbors(String word) {
    List<String> result = new ArrayList<>();
    char[] chars = word.toCharArray();
    for (int i = 0; i < chars.length; i++) {
        char original = chars[i];
        for (char j = 'a'; j <= 'z'; j++) {
            if (j == original) {
                continue;
            }
            chars[i] = j;
            result.add(new String(chars));
        }
        chars[i] = original;
    }
    return result;
}

cpp_code:
#include <vector>
#include <string>
#include <queue>
#include <unordered_set>
#include <unordered_map>

std::vector<std::vector<std::string>> findLadders(std::string beginWord, std::string endWord, std::vector<std::string>& wordList) {
    std::unordered_set<std::string> dict(wordList.begin(), wordList.end());
    if (dict.find(endWord) == dict.end()) {
        return {};
    }
    std::unordered_map<std::string, std::vector<std::string>> adjacent;
    std::unordered_map<std::string, int> distance;

    auto neighbors = [&](const std::string& word) {
        std::vector<std::string> result;
        std::string temp = word;
        for (char& ch : temp) {
            char original = ch;
            for (int i = 'a'; i <= 'z'; ++i) {
                ch = i;
                if (dict.count(temp) && temp != word) {
                    result.push_back(temp);
                }
            }
            ch = original;
        }
        return result;
    };

    std::queue<std::string> q;
    q.push(beginWord);
    distance[beginWord] = 0;

    while (!q.empty()) {
        std::string current = q.front();
        q.pop();
        if (current == endWord) {
            break;
        }
        for (const std::string& neighbor : neighbors(current)) {
            if (!distance.count(neighbor)) {
                distance[neighbor] = distance[current] + 1;
                q.push(neighbor);
            }
            if (distance[neighbor] == distance[current] + 1) {
                adjacent[current].push_back(neighbor);
            }
        }
    }

    std::vector<std::vector<std::string>> result;
    std::vector<std::string> path = {beginWord};
    std::function<void(const std::string&)> backtrack = [&](const std::string& word) {
        if (word == endWord) {
            result.push_back(path);
            return;
        }
        for (const std::string& next : adjacent[word]) {
            path.push_back(next);
            backtrack(next);
            path.pop_back();
        }
    };

    backtrack(beginWord);
    return result;
}

python_code:
from collections import defaultdict, deque

def findLadders(beginWord, endWord, wordList):
    wordList = set(wordList)
    if endWord not in wordList:
        return []

    adjacent = defaultdict(list)
    distance = defaultdict(int)
    queue = deque([beginWord])
    distance[beginWord] = 0

    def neighbors(word):
        for i in range(len(word)):
            for j in range(ord('a'), ord('z') + 1):
                yield word[:i] + chr(j) + word[i + 1:]

    while queue:
        current = queue.popleft()
        if current == endWord:
            break
        for neighbor in neighbors(current):
            if neighbor not in wordList:
                continue
            if neighbor not in distance:
                distance[neighbor] = distance[current] + 1
                queue.append(neighbor)
            if distance[neighbor] == distance[current] + 1:
                adjacent[current].append(neighbor)

    result = []
    path = [beginWord]

    def backtrack(word):
        if word == endWord:
            result.append(path[:])
        else:
            for next_word in adjacent[word]:
                path.append(next_word)
                backtrack(next_word)
                path.pop()

    backtrack(beginWord)
    return result

