class Node {
    public int val;
    public Node next;
    public Node random;

    public Node(int val) {
        this.val = val;
        this.next = null;
        this.random = null;
    }
}

public Node copyRandomList(Node head) {
    if (head == null) return null;

    Node curr = head;
    while (curr != null) {
        Node temp = new Node(curr.val);
        temp.next = curr.next;
        curr.next = temp;
        curr = curr.next.next;
    }

    curr = head;
    while (curr != null) {
        if (curr.random != null) {
            curr.next.random = curr.random.next;
        }
        curr = curr.next.next;
    }

    Node orig = head;
    Node copy = head.next;
    Node copy_head = copy;

    while (orig != null && copy != null) {
        orig.next = copy.next;
        orig = orig.next;
        if (orig != null) {
            copy.next = orig.next;
            copy = copy.next;
        }
    }

    return copy_head;
}

