};

vector<int> postorderTraversal(TreeNode* root) {
    vector<int> result;
    stack<TreeNode*> s;

    if (!root) return result;

    s.push(root);
    while (!s.empty()) {
        TreeNode *current = s.top();
        s.pop();
        result.insert(result.begin(), current->val);
        if (current->left) s.push(current->left);
        if (current->right) s.push(current->right);
    }

    return result;
}

