    ListNode next;
}

public ListNode insertionSortList(ListNode head) {
    ListNode dummy = new ListNode(0);
    ListNode cur;

    while (head != null) {
        cur = dummy;
        while (cur.next != null && cur.next.val < head.val) {
            cur = cur.next;
        }

        ListNode temp = head.next;
        head.next = cur.next;
        cur.next = head;
        head = temp;
    }

    return dummy.next;
}

