python_code:
class Solution:
    def __init__(self):
        self.buffer_index = 0
        self.buffer_len = 0
        self.buf4 = [None] * 4

    def read(self, buf, n):
        cnt = 0
        while cnt < n:
            if self.buffer_index == self.buffer_len:
                self.buffer_len = self.read4(self.buf4)
                self.buffer_index = 0
            if self.buffer_len == 0:
                break
            while cnt < n and self.buffer_index < self.buffer_len:
                buf[cnt] = self.buf4[self.buffer_index]
                cnt += 1
                self.buffer_index += 1
        return cnt

    def read4(self, buf4):
        return 0

