class Solution {
    constructor() {
        this.buffer_index = 0;
        this.buffer_len = 0;
        this.buf4 = new Array(4);
    }

    read(buf, n) {
        let cnt = 0;
        while (cnt < n) {
            if (this.buffer_index === this.buffer_len) {
                this.buffer_len = this.read4(this.buf4);
                this.buffer_index = 0;
            }
            if (this.buffer_len === 0) break;
            while (cnt < n && this.buffer_index < this.buffer_len) {
                buf[cnt++] = this.buf4[this.buffer_index++];
            }
        }
        return cnt;
    }

    read4(buf4) {
        return 0;
    }
}

