int maximumGap(vector<int>& nums) {
    if (nums.size() < 2) return 0;

    int min_val = *min_element(nums.begin(), nums.end());
    int max_val = *max_element(nums.begin(), nums.end());
    int len = nums.size();
    int bucket_size = max(1, (max_val - min_val) / (len - 1));
    int bucket_num = (max_val - min_val) / bucket_size + 1;
    vector<pair<int, int>> buckets(bucket_num, {INT_MAX, INT_MIN});

    for (int num : nums) {
        int idx = (num - min_val) / bucket_size;
        buckets[idx].first = min(buckets[idx].first, num);
        buckets[idx].second = max(buckets[idx].second, num);
    }

    int max_gap = 0, prev_max = min_val;
    for (auto& bucket : buckets) {
        if (bucket.first == INT_MAX) continue;
        max_gap = max(max_gap, bucket.first - prev_max);
        prev_max = bucket.second;
    }
    return max_gap;
}

javascript_code:
function maximumGap(nums) {
    if (nums.length < 2) return 0;

    let min_val = Math.min(...nums);
    let max_val = Math.max(...nums);
    let len = nums.length;
    let bucket_size = Math.max(1, Math.floor((max_val - min_val) / (len - 1)));
    let bucket_num = Math.floor((max_val - min_val) / bucket_size) + 1;
    let buckets = Array.from({ length: bucket_num }, () => [Infinity, -Infinity]);

    for (let num of nums) {
        let idx = Math.floor((num - min_val) / bucket_size);
        buckets[idx][0] = Math.min(buckets[idx][0], num);
        buckets[idx][1] = Math.max(buckets[idx][1], num);
    }

    let max_gap = 0, prev_max = min_val;
    for (let bucket of buckets) {
        if (bucket[0] === Infinity) continue;
        max_gap = Math.max(max_gap, bucket[0] - prev_max);
        prev_max = bucket[1];
    }
    return max_gap;
}

