import java.util.HashMap;

public String fractionToDecimal(int numerator, int denominator) {
    if (numerator == 0) return "0";
    StringBuilder res = new StringBuilder();
    if ((numerator > 0) ^ (denominator > 0)) res.append('-');
    long num = Math.abs((long)numerator), den = Math.abs((long)denominator);
    res.append(num / den);
    num %= den;
    if (num == 0) return res.toString();
    res.append('.');
    HashMap<Long, Integer> map = new HashMap<>();
    while (num != 0) {
        if (map.containsKey(num)) {
            res.insert(map.get(num), "(");
            res.append(")");
            break;
        }
        map.put(num, res.length());
        num *= 10;
        res.append(num / den);
        num %= den;
    }
    return res.toString();
}

cpp_code:
#include <unordered_map>
std::string fractionToDecimal(int numerator, int denominator) {
    if (numerator == 0) return "0";
    std::string res;
    if ((numerator > 0) ^ (denominator > 0)) res += '-';
    long num = std::abs((long)numerator), den = std::abs((long)denominator);
    res += std::to_string(num / den);
    num %= den;
    if (num == 0) return res;
    res += '.';
    std::unordered_map<int, int> map;
    while (num) {
        if (map.find(num) != map.end()) {
            res.insert(map[num], "(");
            res += ")";
            break;
        }
        map[num] = res.size();
        num *= 10;
        res += std::to_string(num / den);
        num %= den;
    }
    return res;
}

python_code:
def fraction_to_decimal(numerator, denominator):
    if numerator == 0:
        return "0"
    res = []
    if (numerator > 0) ^ (denominator > 0):
        res.append("-")
    num = abs(numerator)
    den = abs(denominator)
    res.append(str(num // den))
    num %= den
    if num == 0:
        return "".join(res)
    res.append(".")
    map = {}
    while num:
        if num in map:
            res.insert(map[num], "(")
            res.append(")")
            break
        map[num] = len(res)
        num *= 10
        res.append(str(num // den))
        num %= den
    return "".join(res)

javascript_code:
function fractionToDecimal(numerator, denominator) {
    if (numerator === 0) return "0";
    let res = "";
    if ((numerator > 0) ^ (denominator > 0)) res += '-';
    let num = Math.abs(numerator), den = Math.abs(denominator);
    res += Math.floor(num / den);
    num %= den;
    if (num === 0) return res;
    res += '.';
    let map = new Map();
    while (num) {
        if (map.has(num)) {
            res = res.slice(0, map.get(num)) + "(" + res.slice(map.get(num)) + ")";
            break;
        }
        map.set(num, res.length);
        num *= 10;
        res += Math.floor(num / den);
        num %= den;
    }
    return res;
}

