        stk.pop();
        pushLeft(top->right);
        return top->val;
    }

    bool hasNext() {
        return !stk.empty();
    }

private:
    void pushLeft(TreeNode* node) {
        while (node) {
            stk.push(node);
            node = node->left;
        }
    }
};

