    std::unordered_map<std::string, int> dna_counter;

    for (size_t i = 0; i <= s.length() - 10; ++i) {
        std::string sequence = s.substr(i, 10);
        dna_counter[sequence]++;
        if (dna_counter[sequence] == 2) {
            result.push_back(sequence);
        }
    }

    return result;
}

