import java.util.*;

public List<String> transpose(List<String> content) {
    List<List<String>> data = new ArrayList<>();
    for (String line : content) {
        List<String> row = new ArrayList<>(Arrays.asList(line.split(" ")));
        data.add(row);
    }

    List<String> result = new ArrayList<>(Collections.nCopies(data.get(0).size(), ""));
    for (int i = 0; i < data.get(0).size(); i++) {
        for (int j = 0; j < data.size(); j++) {
            result.set(i, result.get(i) + (j > 0 ? " " : "") + data.get(j).get(i));
        }
    }

    return result;
}

cpp_code:
#include <vector>
#include <string>
#include <sstream>

std::vector<std::string> transpose(std::vector<std::string> &content)
{
    std::vector<std::vector<std::string>> data;
    for (const std::string &line : content)
    {
        std::vector<std::string> row;
        std::stringstream ss(line);
        std::string word;
        while (ss >> word)
            row.push_back(word);
        data.push_back(row);
    }

    std::vector<std::string> result(data[0].size(), "");
    for (size_t i = 0; i < data[0].size(); ++i)
    {
        for (size_t j = 0; j < data.size(); ++j)
        {
            result[i] += data[j][i];
            if (j < data.size() - 1)
                result[i] += " ";
        }
    }

    return result;
}

