class ListNode {
public:
    int val;
    ListNode* next;
    ListNode(int x) : val(x), next(NULL) {}
};

ListNode* removeElements(ListNode* head, int val) {
    ListNode** current = &head;

    while (*current != NULL) {
        if ((*current)->val == val) {
            ListNode* next = (*current)->next;
            delete *current;
            *current = next;
        } else {
            current = &(*current)->next;
        }
    }

    return head;
}

