bool isIsomorphic(std::string s, std::string t) {
    std::unordered_map<char, char> map1, map2;
    for (size_t i = 0; i < s.size(); ++i) {
        if (map1.find(s[i]) == map1.end()) {
            map1[s[i]] = t[i];
        }
        if (map2.find(t[i]) == map2.end()) {
            map2[t[i]] = s[i];
        }
        if (map1[s[i]] != t[i] || map2[t[i]] != s[i]) {
            return false;
        }
    }
    return true;
}

