    for (int[] p : prerequisites) {
        adjList.get(p[1]).add(p[0]);
        inDegree[p[0]]++;
    }

    Queue<Integer> q = new LinkedList<>();
    for (int i = 0; i < numCourses; i++) {
        if (inDegree[i] == 0) {
            q.offer(i);
        }
    }

    int[] order = new int[numCourses];
    int index = 0;

    while (!q.isEmpty()) {
        int curr = q.poll();
        order[index++] = curr;
        for (int next : adjList.get(curr)) {
            if (--inDegree[next] == 0) {
                q.offer(next);
            }
        }
    }

    return (index == numCourses) ? order : new int[0];
}

