python_code:
class TrieNode:
    def __init__(self):
        self.children = [None] * 26
        self.is_word = False

class WordDictionary:
    def __init__(self):
        self.root = TrieNode()

    def addWord(self, word: str) -> None:
        current = self.root
        for c in word:
            index = ord(c) - ord('a')
            if current.children[index] is None:
                current.children[index] = TrieNode()
            current = current.children[index]
        current.is_word = True

    def search(self, word: str) -> bool:
        return self._search_helper(self.root, word, 0)

    def _search_helper(self, node: TrieNode, word: str, index: int) -> bool:
        if index == len(word):
            return node.is_word

        if word[index] == '.':
            for child_node in node.children:
                if child_node is not None and self._search_helper(child_node, word, index + 1):
                    return True
            return False
        else:
            child_node = node.children[ord(word[index]) - ord('a')]
            if child_node is None:
                return False
            return self._search_helper(child_node, word, index + 1)

