class TrieNode {
    constructor() {
        this.children = new Array(26).fill(null);
        this.is_word = false;
    }
}

class WordDictionary {
    constructor() {
        this.root = new TrieNode();
    }

    addWord(word) {
        let current = this.root;
        for (const c of word) {
            const index = c.charCodeAt(0) - 'a'.charCodeAt(0);
            if (!current.children[index]) {
                current.children[index] = new TrieNode();
            }
            current = current.children[index];
        }
        current.is_word = true;
    }

    search(word) {
        return this._searchHelper(this.root, word, 0);
    }

    _searchHelper(node, word, index) {
        if (index === word.length) {
            return node.is_word;
        }

        if (word[index] === '.') {
            for (let i = 0; i < 26; i++) {
                if (node.children[i] && this._searchHelper(node.children[i], word, index + 1)) {
                    return true;
                }
            }
            return false;
        } else {
            const childIndex = word.charCodeAt(index) - 'a'.charCodeAt(0);
            if (!node.children[childIndex]) {
                return false;
            }
            return this._searchHelper(node.children[childIndex], word, index + 1);
        }
    }
}

java_code:
import java.util.ArrayList;
import java.util.List;

public List<String> findWords(char[][] board, String[] words) {
    List<String> result = new ArrayList<>();
    for (String word : words) {
        if (exist(board, word)) {
            result.add(word);
        }
    }
    return result;
}

private boolean exist(char[][] board, String word) {
    int m = board.length;
    int n = board[0].length;
    boolean[][] visited = new boolean[m][n];
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (dfs(board, word, 0, i, j, visited)) {
                return true;
            }
        }
    }
    return false;
}

private boolean dfs(char[][] board, String word, int index, int i, int j, boolean[][] visited) {
    if (index == word.length()) {
        return true;
    }
    if (i < 0 || j < 0 || i >= board.length || j >= board[0].length || visited[i][j] || board[i][j] != word.charAt(index)) {
        return false;
    }
    visited[i][j] = true;
    boolean found =
            dfs(board, word, index + 1, i - 1, j, visited) ||
            dfs(board, word, index + 1, i + 1, j, visited) ||
            dfs(board, word, index + 1, i, j - 1, visited) ||
            dfs(board, word, index + 1, i, j + 1, visited);
    visited[i][j] = false;
    return found;
}

