function getSkyline(buildings) {
    const points = [];
    for (const [l, r, h] of buildings) {
        points.push([l, -h]);
        points.push([r, h]);
    }
    points.sort((a, b) => a[0] - b[0]);
    const heights = new SortedSet([0]);
    let prev = 0;
    const skyline = [];
    for (const [x, h] of points) {
        if (h < 0) {
            heights.add(-h);
        } else {
            heights.delete(h);
        }
        const cur = heights.last();
        if (cur !== prev) {
            skyline.push([x, cur]);
            prev = cur;
        }
    }
    return skyline;
}

