public class TreeNode {
    TreeNode left;
    TreeNode right;
}

public int countNodes(TreeNode root) {
    if (root == null) return 0;
    int ld = 0, rd = 0;
    TreeNode l = root, r = root;

    while (l != null) {
        l = l.left;
        ld++;
    }

    while (r != null) {
        r = r.right;
        rd++;
    }

    if (ld == rd) return (1 << ld) - 1;
    return 1 + countNodes(root.left) + countNodes(root.right);
}

