public class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode(int x) { val = x; }
}

public int kthSmallest(TreeNode root, int k) {
    Stack<TreeNode> stk = new Stack<>();
    TreeNode curr = root;

    while (true) {
        while (curr != null) {
            stk.push(curr);
            curr = curr.left;
        }

        curr = stk.pop();

        if (--k == 0) return curr.val;

        curr = curr.right;
    }
}

