class Vector2D {
public:
    vector<vector<int>>::iterator i, i_end;
    int j = 0;

    Vector2D(vector<vector<int>>& vec) {
        i = vec.begin();
        i_end = vec.end();
    }

    int next() {
        hasNext();
        return (*i)[j++];
    }

    bool hasNext() {
        while (i != i_end && j == (*i).size()) {
            ++i;
            j = 0;
        }
        return i != i_end;
    }
};

