#include <vector>

void helper(int n, int start, std::vector<int>& path, std::vector<std::vector<int>>& result) {
    if (n == 1) {
        if (path.size() > 1) {
            result.push_back(path);
        }
        return;
    }

    for (int i = start; i <= n; ++i) {
        if (n % i == 0) {
            path.push_back(i);
            helper(n / i, i, path, result);
            path.pop_back();
        }
    }
}

