def getFactors(n):
    def helper(n, start, path, result):
        if n == 1:
            if len(path) > 1:
                result.append(path[:])
            return

        for i in range(start, n + 1):
            if n % i == 0:
                path.append(i)
                helper(n // i, i, path, result)
                path.pop()

    result = []
    helper(n, 2, [], result)
    return result

javascript_code:
function getFactors(n) {
    const result = [];
    const helper = (n, start, path) => {
        if (n === 1) {
            if (path.length > 1) {
                result.push([...path]);
            }
            return;
        }

        for (let i = start; i <= n; i++) {
            if (n % i === 0) {
                path.push(i);
                helper(n / i, i, path);
                path.pop();
            }
        }
    };

    helper(n, 2, []);
    return result;
}

