bool isValidPreorder(vector<int>& preorder) {
    stack<int> stk;
    int lower_bound = INT_MIN;
    for (int num : preorder) {
        if (num < lower_bound) return false;
        while (!stk.empty() && num > stk.top()) {
            lower_bound = stk.top();
            stk.pop();
        }
        stk.push(num);
    }
    return true;
}

