    let stack = [];
    let lowerBound = Number.MIN_SAFE_INTEGER;
    for (let num of preorder) {
        if (num < lowerBound) return false;
        while (stack.length > 0 && num > stack[stack.length - 1]) {
            lowerBound = stack.pop();
        }
        stack.push(num);
    }
    return true;
};

