class ZigzagIterator {
public:
    ZigzagIterator(vector<int>& v1, vector<int>& v2): curr_v(NULL), index1(0), index2(0) {
        if (!v1.empty()) {
            curr_v = &v1;
            other_v = &v2;
        } else if (!v2.empty()) {
            curr_v = &v2;
            other_v = &v1;
        }
    }

    int next() {
        int result = (*curr_v)[index1++];
        if (index2 < other_v->size()) {
            swap(curr_v, other_v);
            swap(index1, index2);
        }
        return result;
    }

    bool hasNext() {
        return curr_v && index1 < curr_v->size();
    }

private:
    vector<int> *curr_v;
    vector<int> *other_v;
    int index1;
    int index2;
};

python_code:
class ZigzagIterator:

    def __init__(self, v1: List[int], v2: List[int]):
        self.v1, self.v2 = v1, v2
        self.index1, self.index2 = 0, 0

    def next(self) -> int:
        if self.index1 < len(self.v1) and (self.index1 <= self.index2 or self.index2 == len(self.v2)):
            result = self.v1[self.index1]
            self.index1 += 1
            return result
        if self.index2 < len(self.v2) and (self.index2 < self.index1 or self.index1 == len(self.v1)):
            result = self.v2[self.index2]
            self.index2 += 1
            return result

    def hasNext(self) -> bool:
        return self.index1 < len(self.v1) or self.index2 < len(self.v2)

