class ZigzagIterator {
    constructor(v1, v2) {
        this.v1 = v1;
        this.v2 = v2;
        this.index1 = 0;
        this.index2 = 0;
    }

    next() {
        if (this.index1 < this.v1.length && (this.index1 <= this.index2 || this.index2 == this.v2.length)) {
            return this.v1[this.index1++];
        }
        if (this.index2 < this.v2.length && (this.index2 < this.index1 || this.index1 == this.v1.length)) {
            return this.v2[this.index2++];
        }
    }

    hasNext() {
        return this.index1 < this.v1.length || this.index2 < this.v2.length;
    }
}

java_code:
import java.util.ArrayList;
import java.util.List;

public List<String> addOperators(String num, int target) {
    List<String> res = new ArrayList<>();
    helper(num, target, 0, 0, 0, "", res);
    return res;
}

private void helper(String num, int target, int pos, long currVal, long prevVal, String currExpr, List<String> res) {
    if (pos == num.length()) {
        if (currVal == target) {
            res.add(currExpr);
        }
        return;
    }

    for (int i = pos; i < num.length(); ++i) {
        if (i != pos && num.charAt(pos) == '0') break;
        long val = Long.parseLong(num.substring(pos, i + 1));
        if (pos == 0) {
            helper(num, target, i + 1, val, val, currExpr + num.substring(pos, i + 1), res);
        } else {
            helper(num, target, i + 1, currVal + val, val, currExpr + "+" + num.substring(pos, i + 1), res);
            helper(num, target, i + 1, currVal - val, -val, currExpr + "-" + num.substring(pos, i + 1), res);
            helper(num, target, i + 1, currVal - prevVal + prevVal * val, prevVal * val, currExpr + "*" + num.substring(pos, i + 1), res);
        }
    }
}

