#include <string>
#include <vector>

void helper(const std::string &num, int target, int pos, long long currVal, long long prevVal, std::string currExpr, std::vector<std::string> &res) {
    if (pos == num.size()) {
        if (currVal == target) {
            res.push_back(currExpr);
        }
        return;
    }

    for (int i = pos; i < num.size(); ++i) {
        if (i != pos && num[pos] == '0') break;
        long long val = std::stoll(num.substr(pos, i - pos + 1));
        if (pos == 0) {
            helper(num, target, i + 1, val, val, currExpr + num.substr(pos, i - pos + 1), res);
        } else {
            helper(num, target, i + 1, currVal + val, val, currExpr + "+" + num.substr(pos, i - pos + 1), res);
            helper(num, target, i + 1, currVal - val, -val, currExpr + "-" + num.substr(pos, i - pos + 1), res);
            helper(num, target, i + 1, currVal - prevVal + prevVal * val, prevVal * val, currExpr + "*" + num.substr(pos, i - pos + 1), res);
        }
    }
}

std::vector<std::string> addOperators(std::string num, int target) {
    std::vector<std::string> res;
    helper(num, target, 0, 0, 0, "", res);
    return res;
}

python_code:
from typing import List

def addOperators(num: str, target: int) -> List[str]:
    def helper(num, target, pos, currVal, prevVal, currExpr):
        if pos == len(num):
            if currVal == target:
                res.append(currExpr)
            return

        for i in range(pos, len(num)):
            if i != pos and num[pos] == '0':
                break

            val = int(num[pos:i + 1])
            if pos == 0:
                helper(num, target, i + 1, val, val, currExpr + num[pos:i + 1])
            else:
                helper(num, target, i + 1, currVal + val, val, currExpr + "+" + num[pos:i + 1])
                helper(num, target, i + 1, currVal - val, -val, currExpr + "-" + num[pos:i + 1])
                helper(num, target, i + 1, currVal - prevVal + prevVal * val, prevVal * val, currExpr + "*" + num[pos:i + 1])

    res = []
    helper(num, target, 0, 0, 0, "")
    return res

javascript_code:
var addOperators = function(num, target) {
    const res = [];
    const helper = (num, target, pos, currVal, prevVal, currExpr) => {
        if (pos === num.length) {
            if (currVal === target) {
                res.push(currExpr);
            }
            return;
        }

        for (let i = pos; i < num.length; ++i) {
            if (i !== pos && num[pos] === '0') break;

            const val = parseInt(num.substring(pos, i + 1));
            if (pos === 0) {
                helper(num, target, i + 1, val, val, currExpr + num.substring(pos, i + 1));
            } else {
                helper(num, target, i + 1, currVal + val, val, currExpr + "+" + num.substring(pos, i + 1));
                helper(num, target, i + 1, currVal - val, -val, currExpr + "-" + num.substring(pos, i + 1));
                helper(num, target, i + 1, currVal - prevVal + prevVal * val, prevVal * val, currExpr + "*" + num.substring(pos, i + 1));
            }
        }
    }

    helper(num, target, 0, 0, 0, "");
    return res;
}

