#include <iterator>

class PeekingIterator : public std::iterator<std::input_iterator_tag, int> {
public:
    PeekingIterator(std::vector<int>::iterator it, std::vector<int>::iterator end) : iterator_(it), end_(end) {
        if (iterator_ != end_) {
            next_val_ = *iterator_;
            ++iterator_;
        }
    }

    int peek() {
        return next_val_;
    }

    int next() {
        int current_val = next_val_;
        if (iterator_ != end_) {
            next_val_ = *iterator_;
            ++iterator_;
        }
        return current_val;
    }

    bool hasNext() const {
        return iterator_ != end_;
    }

private:
    std::vector<int>::iterator iterator_;
    std::vector<int>::iterator end_;
    int next_val_;
};

