        self.iterator = iterator
        self.next_val = next(self.iterator, None)

    def peek(self):
        return self.next_val

    def next(self):
        current_val = self.next_val
        self.next_val = next(self.iterator, None)
        return current_val

    def hasNext(self):
        return self.next_val is not None

