void wallsAndGates(vector<vector<int>>& rooms) {
    const int INF = 2147483647;
    int m = rooms.size();
    int n = rooms[0].size();
    queue<pair<int, int>> q;

    for(int i = 0; i < m; i++) {
        for(int j = 0; j < n; j++) {
            if(rooms[i][j] == 0) {
                q.push(make_pair(i, j));
            }
