    return backtrack(pattern, 0, s, 0, pattern_map, words);
}

bool backtrack(string& pattern, int p_index, string& s, int s_index, unordered_map<char, string>& pattern_map, unordered_set<string>& words) {
    if (p_index == pattern.size() && s_index == s.size()) return true;
    if (p_index == pattern.size() || s_index == s.size()) return false;

    char p = pattern[p_index];
    if (pattern_map.count(p)) {
        string word = pattern_map[p];
        if (s.substr(s_index, word.size()) != word) return false;
        return backtrack(pattern, p_index + 1, s, s_index + word.size(), pattern_map, words);
    } else {
        for (int length = 1; length <= s.size() - s_index; length++) {
            string word = s.substr(s_index, length);
            if (words.count(word)) continue;
            pattern_map[p] = word;
            words.insert(word);
            if (backtrack(pattern, p_index + 1, s, s_index + length, pattern_map, words)) return true;
            pattern_map.erase(p);
            words.erase(word);
        }
    }
    return false;
}

python_code:
def wordPatternMatch(pattern: str, s: str) -> bool:
    def backtrack(p_index, s_index, pattern_map, words):
        if p_index == len(pattern) and s_index == len(s):
            return True
        if p_index == len(pattern) or s_index == len(s):
            return False

        p = pattern[p_index]
        if p in pattern_map:
            word = pattern_map[p]
            if not s.startswith(word, s_index):
                return False
            return backtrack(p_index + 1, s_index + len(word), pattern_map, words)
        else:
            for length in range(1, len(s) - s_index + 1):
                word = s[s_index : s_index + length]
                if word in words:
                    continue
                pattern_map[p] = word
                words.add(word)
                if backtrack(p_index + 1, s_index + length, pattern_map, words):
                    return True
                pattern_map.pop(p)
                words.remove(word)
        return False

    return backtrack(0, 0, {}, set())

javascript_code:
var wordPatternMatch = function(pattern, s) {
    const patternMap = new Map();
    const words = new Set();
    return backtrack(pattern, 0, s, 0, patternMap, words);

    function backtrack(pattern, pIndex, s, sIndex, patternMap, words) {
        if (pIndex == pattern.length && sIndex == s.length) return true;
        if (pIndex == pattern.length || sIndex == s.length) return false;

        let p = pattern[pIndex];
        if (patternMap.has(p)) {
            let word = patternMap.get(p);
            if (s.slice(sIndex, sIndex + word.length) !== word) return false;
            return backtrack(pattern, pIndex + 1, s, sIndex + word.length, patternMap, words);
        } else {
            for (let length = 1; length <= s.length - sIndex; length++) {
                let word = s.substr(sIndex, length);
                if (words.has(word)) continue;
                patternMap.set(p, word);
                words.add(word);
                if (backtrack(pattern, pIndex + 1, s, sIndex + length, patternMap, words)) return true;
                patternMap.delete(p);
                words.delete(word);
            }
        }
        return false;
    }
};

