TreeNode* deserializeHelper(istringstream& is) {
    string val;
    if (!getline(is, val, ',')) return nullptr;
    if (val == "null") return nullptr;
    TreeNode* root = new TreeNode(stoi(val));
    root->left = deserializeHelper(is);
    root->right = deserializeHelper(is);
    return root;
}

