#include <vector>
#include <string>
#include <set>
#include <queue>

using namespace std;

class Solution {
public:
    vector<string> removeInvalidParentheses(string s) {
        set<string> visited;
        queue<string> q;
        vector<string> result;
        bool found = false;

        visited.insert(s);
        q.push(s);

        while (!q.empty()) {
            string cur = q.front();
            q.pop();

            if (isValid(cur)) {
                found = true;
                result.push_back(cur);
            }

            if (found) continue;

            for (int i = 0; i < cur.length(); ++i) {
                if (cur[i] == '(' || cur[i] == ')') {
                    string next = cur.substr(0, i) + cur.substr(i+1);
                    if (visited.find(next) == visited.end()) {
                        visited.insert(next);
                        q.push(next);
                    }
                }
            }
        }
        return result;
    }

    bool isValid(const string &s) {
        int count = 0;
        for (char c : s) {
            if (c == '(') count++;
            if (c == ')') count--;
            if (count < 0) return false;
        }
        return count == 0;
    }
};

python_code:
from collections import deque

class Solution:
    def removeInvalidParentheses(self, s: str):
        visited = set()
        queue = deque([s])
        result = []
        found = False

        while queue:
            cur = queue.popleft()

            if self.is_valid(cur):
                found = True
                result.append(cur)

            if found: continue

            for i in range(len(cur)):
                if cur[i] == '(' or cur[i] == ')':
                    next_str = cur[:i] + cur[i+1:]
                    if next_str not in visited:
                        visited.add(next_str)
                        queue.append(next_str)

        return result

    def is_valid(self, s: str) -> bool:
        count = 0
        for c in s:
            if c == '(': count += 1
            if c == ')':
                count -= 1
                if count < 0: return False
        return count == 0

