class Solution {
    removeInvalidParentheses(s) {
        let visited = new Set();
        let queue = [s];
        let result = [];
        let found = false;

        while (queue.length > 0) {
            let cur = queue.shift();

            if (this.isValid(cur)) {
                found = true;
                result.push(cur);
            }

            if (found) continue;

            for (let i = 0; i < cur.length; i++) {
                if (cur[i] === '(' || cur[i] === ')') {
                    let next = cur.slice(0, i) + cur.slice(i + 1);
                    if (!visited.has(next)) {
                        visited.add(next);
                        queue.push(next);
                    }
                }
            }
        }
        return result;
    }

    isValid(s) {
        let count = 0;
        for (let c of s) {
            if (c === '(') count++;
            if (c === ')') count--;
            if (count < 0) return false;
        }
        return count === 0;
    }
}

