         i >= 0 || j >= 0 || carry > 0; i--, j--) {
        int n1 = i >= 0 ? num1[i] - '0' : 0;
        int n2 = j >= 0 ? num2[j] - '0' : 0;
        int sum = n1 + n2 + carry;
        carry = sum / 10;
        result.push_back('0' + sum % 10);
    }
    std::reverse(result.begin(), result.end());
    return result;
}

