def countSmaller(nums):
    def merge_sort(indices):
        if len(indices) <= 1:
            return indices
        mid = len(indices) // 2
        left = merge_sort(indices[:mid])
        right = merge_sort(indices[mid:])
        return merge(left, right)

    def merge(left, right):
        merged, count = [], 0
        while left and right:
            if nums[left[0]] <= nums[right[0]]:
                counts[left[0]] += count
                merged.append(left.pop(0))
            else:
                count += len(left)
                merged.append(right.pop(0))
        for i in left:
            counts[i] += count
        return merged + left + right

    counts = [0] * len(nums)
    merge_sort(list(range(len(nums))))
    return counts

javascript_code:
function countSmaller(nums) {
    function mergeSort(indices, start, end) {
        if (start >= end) {
            return;
        }

        let mid = start + ((end - start) >> 1);
        mergeSort(indices, start, mid);
        mergeSort(indices, mid + 1, end);

        let i = start, j = mid + 1, k = 0, cnt = 0;
        let temp = [];
        while (i <= mid || j <= end) {
            if (j > end || (i <= mid && nums[indices[i]] <= nums[indices[j]])) {
                cnt += j - mid - 1;
                counts[indices[i]] = cnt;
                temp[k++] = indices[i++];
            } else {
                temp[k++] = indices[j++];
            }
        }

        for (let i = 0; i < k; i++) {
            indices[start + i] = temp[i];
        }
    }

    let counts = Array(nums.length).fill(0);
    let indices = Array.from({length: nums.length}, (_, i) => i);
    mergeSort(indices, 0, nums.length - 1);
    return counts;
}

