#include <string>
#include <vector>
#include <stack>
using namespace std;

string removeDuplicateLetters(string s) {
    vector<int> count(256, 0);
    vector<bool> visited(256, false);
    stack<char> st;

    for (char ch : s) {
        count[ch]++;
    }

    for (char ch : s) {
        count[ch]--;
        if (visited[ch]) continue;
        while (!st.empty() && ch < st.top() && count[st.top()] > 0) {
            visited[st.top()] = false;
            st.pop();
        }
        st.push(ch);
        visited[ch] = true;
    }

    string result = "";
    while (!st.empty()) {
        result = st.top() + result;
        st.pop();
    }
    return result;
}

python_code:
def removeDuplicateLetters(s):
    count = [0] * 256
    visited = [False] * 256
    st = []

    for ch in s:
        count[ord(ch)] += 1

    for ch in s:
        count[ord(ch)] -= 1
        if visited[ord(ch)]:
            continue
        while st and ch < st[-1] and count[ord(st[-1])] > 0:
            visited[ord(st.pop())] = False
        st.append(ch)
        visited[ord(ch)] = True

    return "".join(st)

