        sum += nums[i];
        if(sum == k) maxLength = i + 1;
        if(sumIndex.count(sum - k)) maxLength = max(maxLength, i - sumIndex[sum - k]);
        if(!sumIndex.count(sum)) sumIndex[sum] = i;
    }
    return maxLength;
}

