int countRangeSum(vector<int>& nums, int lower, int upper) {
    int n = nums.size();
    vector<long> sums(n + 1, 0);
    for (int i = 0; i < n; ++i)
        sums[i + 1] = sums[i] + nums[i];

    function<int(int, int)> mergeSort = [&](int start, int end) {
        if (start == end)
            return 0;
        int mid = start + (end - start) / 2;
        int count = mergeSort(start, mid) + mergeSort(mid + 1, end);

        int j = mid + 1, k = mid + 1;
        for (int i = start; i <= mid; ++i) {
            while (j <= end && sums[j] - sums[i] < lower) ++j;
            while (k <= end && sums[k] - sums[i] <= upper) ++k;
            count += k - j;
        }

        inplace_merge(sums.begin() + start, sums.begin() + mid + 1, sums.begin() + end + 1);
        return count;
    };

    return mergeSort(0, n);
}

python_code:
def countRangeSum(nums, lower, upper):
    sums = [0] * (len(nums) + 1)
    for i in range(len(nums)):
        sums[i + 1] = sums[i] + nums[i]

    def mergeSort(start, end):
        if start == end:
            return 0
        mid = start + (end - start) // 2
        count = mergeSort(start, mid) + mergeSort(mid + 1, end)

        j, k = mid + 1, mid + 1
        for i in range(start, mid + 1):
            while j <= end and sums[j] - sums[i] < lower: j += 1
            while k <= end and sums[k] - sums[i] <= upper: k += 1
            count += k - j

        sums[start:end + 1] = sorted(sums[start:end + 1])
        return count

    return mergeSort(0, len(nums))

javascript_code:
function countRangeSum(nums, lower, upper) {
    let sums = new Array(nums.length + 1).fill(0);
    for (let i = 0; i < nums.length; ++i)
        sums[i + 1] = sums[i] + nums[i];

    function mergeSort(start, end) {
        if (start === end)
            return 0;
        let mid = start + Math.floor((end - start) / 2);
        let count = mergeSort(start, mid) + mergeSort(mid + 1, end);

        let j = mid + 1, k = mid + 1;
        for (let i = start; i <= mid; ++i) {
            while (j <= end && sums[j] - sums[i] < lower) ++j;
            while (k <= end && sums[k] - sums[i] <= upper) ++k;
            count += k - j;
        }

        let sortedPart = sums.slice(start, end + 1).sort((a, b) => a - b);
        for (let i = start; i <= end; ++i) {
            sums[i] = sortedPart[i - start];
        }

        return count;
    };

    return mergeSort(0, nums.length);
}

