    if (memo[i][j] !== 0) return memo[i][j];

    let max_len = 0;
    for (let k = 0; k < 4; ++k) {
        const ni = i + dx[k], nj = j + dy[k];
        if (ni >= 0 && ni < matrix.length && nj >= 0 && nj < matrix[0].length && matrix[ni][nj] > matrix[i][j]) {
            max_len = Math.max(max_len, dfs(matrix, memo, ni, nj));
        }
    }

    memo[i][j] = max_len + 1;
    return memo[i][j];
}

