public int minPatches(int[] nums, int n) {
    long maxSum = 0;
    int patches = 0, i = 0;

    while (maxSum < n) {
        if (i < nums.length && nums[i] <= maxSum + 1) {
            maxSum += nums[i];
            i++;
        } else {
            maxSum += maxSum + 1;
            patches++;
        }
    }
    return patches;
}

