#include <string>
#include <sstream>
#include <vector>

bool isValidSerialization(const std::string &preorder) {
    std::istringstream iss(preorder);
    std::string token;
    int node_count = 1;

    while (std::getline(iss, token, ',')) {
        --node_count;
        if (node_count < 0) return false;
        if (token != "#") node_count += 2;
    }

    return node_count == 0;
}

