from collections import defaultdict

def findItinerary(tickets):
    flights = defaultdict(list)
    itinerary = []

    for ticket in tickets:
        flights[ticket[0]].append(ticket[1])
        flights[ticket[0]].sort(reverse=True)

    def dfs(airport):
        while flights[airport]:
            dfs(flights[airport].pop())
        itinerary.append(airport)

    dfs("JFK")

    return itinerary[::-1]

javascript_code:
function findItinerary(tickets) {
    const flights = {};
    const itinerary = [];

    for (const ticket of tickets) {
        if (!flights[ticket[0]]) {
            flights[ticket[0]] = [];
        }
        flights[ticket[0]].push(ticket[1]);
        flights[ticket[0]].sort((a, b) => b.localeCompare(a));
    }

    function dfs(airport) {
        while (flights[airport] && flights[airport].length > 0) {
            dfs(flights[airport].pop());
        }
        itinerary.push(airport);
    }

    dfs("JFK");

    return itinerary.reverse();
}

