TreeInfo largestBSTUtil(TreeNode* root, int &largestBST) {
    if (!root) return {true, 0, INT_MAX, INT_MIN};

    TreeInfo left = largestBSTUtil(root->left, largestBST);
    TreeInfo right = largestBSTUtil(root->right, largestBST);

    if (left.isBST && root->val > left.maxValue && right.isBST && root->val < right.minValue) {
        largestBST = max(largestBST, left.size + 1 + right.size);
        return {true, left.size + 1 + right.size, min(root->val, left.minValue), max(root->val, right.maxValue)};
    }

    return {false, -1, INT_MAX, INT_MIN};
}

int largestBSTSubtree(TreeNode* root) {
    int largestBST = 0;
    largestBSTUtil(root, largestBST);
    return largestBST;
}

