        this.n = n;
    }

    move(row, col, player) {
        const toAdd = player === 1 ? 1 : -1;

        this.rows[row] += toAdd;
        this.cols[col] += toAdd;

        if (row === col) this.diagonal += toAdd;
        if (row + col === this.n - 1) this.anti_diagonal += toAdd;

        if (Math.abs(this.rows[row]) === this.n || 
            Math.abs(this.cols[col]) === this.n || 
            Math.abs(this.diagonal) === this.n || 
            Math.abs(this.anti_diagonal) === this.n)
            return player;

        return 0;
    }
}

