import java.util.Arrays;
import java.util.Comparator;

public int maxEnvelopes(int[][] envelopes) {
    Arrays.sort(envelopes, new Comparator<int[]>() {
        public int compare(int[] a, int[] b) {
            return a[0] == b[0] ? b[1] - a[1] : a[0] - b[0];
        }
    });

    int[] dp = new int[envelopes.length];
    int len = 0;
    for (int[] envelope : envelopes) {
        int idx = Arrays.binarySearch(dp, 0, len, envelope[1]);
        if (idx < 0) {
            idx = -(idx + 1);
        }
        dp[idx] = envelope[1];
        if (idx == len) {
            len++;
        }
    }

    return len;
}

cpp_code:
#include <vector>
#include <algorithm>

int maxEnvelopes(std::vector<std::vector<int>>& envelopes) {
    std::sort(envelopes.begin(), envelopes.end(), [](const std::vector<int>& a, const std::vector<int>& b) {
        return a[0] == b[0] ? a[1] > b[1] : a[0] < b[0];
    });

    std::vector<int> dp;
    for (const auto& envelope : envelopes) {
        auto it = std::lower_bound(dp.begin(), dp.end(), envelope[1]);
        if (it == dp.end()) {
            dp.push_back(envelope[1]);
        } else {
            *it = envelope[1];
        }
    }

    return dp.size();
}

