from sortedcontainers import SortedList

def maxSumSubmatrix(matrix, k):
    rows = len(matrix)
    cols = len(matrix[0])
    max_sum = float('-inf')

    for l in range(cols):
        sums = [0] * rows
        for r in range(l, cols):
            for i in range(rows):
                sums[i] += matrix[i][r]

            sorted_sums = SortedList()
            sorted_sums.add(0)
            curr_sum = 0
            for sum in sums:
                curr_sum += sum
                it = sorted_sums.bisect_left(curr_sum - k)
                if it != len(sorted_sums):
                    max_sum = max(max_sum, curr_sum - sorted_sums[it])
                sorted_sums.add(curr_sum)

    return max_sum

javascript_code:
function maxSumSubmatrix(matrix, k) {
    const rows = matrix.length;
    const cols = matrix[0].length;
    let maxSum = -Infinity;

    function lowerBound(arr, target) {
        let l = 0;
        let r = arr.length;
        while (l < r) {
            const mid = Math.floor((l + r) / 2);
            if (arr[mid] >= target) {
                r = mid;
            } else {
                l = mid + 1;
            }
        }
        return l;
    }

    for (let l = 0; l < cols; ++l) {
        const sums = Array(rows).fill(0);
        for (let r = l; r < cols; ++r) {
            for (let i = 0; i < rows; ++i) {
                sums[i] += matrix[i][r];
            }

            const sortedSums = [0];
            let currSum = 0;
            for (const sum of sums) {
                currSum += sum;
                const it = lowerBound(sortedSums, currSum - k);
                if (it < sortedSums.length)
                    maxSum = Math.max(maxSum, currSum - sortedSums[it]);
                const insertPosition = lowerBound(sortedSums, currSum);
                sortedSums.splice(insertPosition, 0, currSum);
            }
        }
    }

    return maxSum;
}

