java_code:
import java.util.ArrayList;
import java.util.List;

public class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode() {}
    TreeNode(int val) { this.val = val; }
    TreeNode(int val, TreeNode left, TreeNode right) {
        this.val = val;
        this.left = left;
        this.right = right;
    }
}

public List<List<Integer>> findLeaves(TreeNode root) {
    List<List<Integer>> result = new ArrayList<>();
    findLeaves(root, result, 0);
    return result;
}

private int findLeaves(TreeNode node, List<List<Integer>> result, int level) {
    if (node == null) return -1;
    int leftLevel = findLeaves(node.left, result, level + 1);
    int rightLevel = findLeaves(node.right, result, level + 1);
    level = Math.max(leftLevel, rightLevel) + 1;
    if (result.size() <= level) result.add(new ArrayList<>());
    result.get(level).add(node.val);
    return level;
}

cpp_code:
#include <vector>

struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode() : val(0), left(nullptr), right(nullptr) {}
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
    TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
};

void findLeaves(TreeNode* node, std::vector<std::vector<int>>& result, int& level) {
    if (!node) return;
    if (!node->left && !node->right) {
        if (result.size() <= level) {
            result.push_back(std::vector<int>());
        }
        result[level].push_back(node->val);
        node = nullptr;
        return;
    }
    level++;
    findLeaves(node->left, result, level);
    findLeaves(node->right, result, level);
    level--;
}

std::vector<std::vector<int>> findLeaves(TreeNode* root) {
    std::vector<std::vector<int>> result;
    int level = 0;
    while (root) {
        findLeaves(root, result, level);
        if (!root->left && !root->right) root = nullptr;
    }
    return result;
}

