class PhoneDirectory:
    def __init__(self, maxNumbers: int):
        self.available = [True] * maxNumbers
        self.released = deque()

    def get(self) -> int:
        if self.released:
            number = self.released.popleft()
            self.available[number] = False
            return number
        for i in range(len(self.available)):
            if self.available[i]:
                self.available[i] = False
                return i
        return -1

    def check(self, number: int) -> bool:
        return self.available[number]

    def release(self, number: int) -> None:
        if not self.available[number]:
            self.available[number] = True
            self.released.append(number)

javascript_code:
class PhoneDirectory {
    constructor(maxNumbers) {
        this.available = new Array(maxNumbers).fill(true);
        this.released = [];
    }

    get() {
        if (this.released.length > 0) {
            let number = this.released.shift();
            this.available[number] = false;
            return number;
        }
        for (let i = 0; i < this.available.length; i++) {
            if (this.available[i]) {
                this.available[i] = false;
                return i;
            }
        }
        return -1;
    }

    check(number) {
        return this.available[number];
    }

    release(number) {
        if (!this.available[number]) {
            this.available[number] = true;
            this.released.push(number);
        }
    }
}

