#include <unordered_map>
#include <vector>
#include <random>

class RandomizedSet {
    std::unordered_map<int, int> index_map;
    std::vector<int> nums;
public:
    bool insert(int val) {
        if (index_map.count(val)) return false;

        index_map[val] = nums.size();
        nums.push_back(val);
        return true;
    }

    bool remove(int val) {
        if (!index_map.count(val)) return false;

        int last = nums.back();
        index_map[last] = index_map[val];
        nums[index_map[val]] = last;

        nums.pop_back();
        index_map.erase(val);
        return true;
    }

    int getRandom() {
        return nums[rand() % nums.size()];
    }
};

