#include <cstdlib>
#include <ctime>

struct ListNode {
    int val;
    ListNode *next;
    ListNode(int x) : val(x), next(NULL) {}
};

class Solution {
public:
    ListNode* head;

    Solution(ListNode* _head) {
        head = _head;
        srand(time(0));
    }

    int getRandom() {
        int result;
        ListNode* current = head;
        for (int i = 1; current; ++i) {
            if (rand() % i == 0) {
                result = current->val;
            }
            current = current->next;
        }
        return result;
    }
};

