#include <algorithm>
#include <vector>
#include <ctime>

class Solution {
public:
    Solution(std::vector<int>& nums) {
        original = nums;
        srand(time(0));
    }

    std::vector<int> reset() {
        return original;
    }

    std::vector<int> shuffle() {
        std::vector<int> shuffled = original;
        for (int i = shuffled.size() - 1; i > 0; i--) {
            int j = rand() % (i + 1);
            std::swap(shuffled[i], shuffled[j]);
        }
        return shuffled;
    }
private:
    std::vector<int> original;
};

