class Solution {
    constructor(nums) {
        this.original = nums;
    }

    reset() {
        return this.original;
    }

    shuffle() {
        let shuffled = [...this.original];
        for (let i = shuffled.length - 1; i > 0; i--) {
            let j = Math.floor(Math.random() * (i + 1));
            [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
        }
        return shuffled;
    }
}

