#include <string>
#include <sstream>
using namespace std;

class NestedInteger {
public:
    NestedInteger() {}
    NestedInteger(int value) {}
    void add(const NestedInteger& ni) {}
};

NestedInteger deserialize(string s);

NestedInteger deserializeHelper(istringstream& ss) {
    int num;
    if (ss >> num)
        return NestedInteger(num);

    ss.clear();
    ss.get();
    NestedInteger list;
    while (ss.peek() != ']') {
        list.add(deserializeHelper(ss));
        if (ss.peek() == ',')
            ss.get();
    }
    ss.get();
    return list;
}

NestedInteger deserialize(string s) {
    istringstream ss(s);
    return deserializeHelper(ss);
}

