        return new NestedInteger(parseInt(s));
    }

    let stack = [];
    let curr = null;
    let start = 0;

    for (let i = 0; i < s.length; i++) {
        let c = s[i];
        if (c === '[') {
            if (curr !== null) {
                stack.push(curr);
            }
            curr = new NestedInteger();
            start = i + 1;
        } else if (c === ',' || c === ']') {
            if (i > start) {
                curr.add(new NestedInteger(parseInt(s.substring(start, i))));
            }
            start = i + 1;

            if (c === ']' && stack.length > 0) {
                let popped = stack.pop();
                popped.add(curr);
                curr = popped;
            }
        }
    }
    return curr;
}

