import java.util.Stack;

public int lengthLongestPath(String input) {
    Stack<Integer> dirLengthStack = new Stack<>();
    String[] lines = input.split("\n");
    int maxFileLength = 0;

    for (String line : lines) {
        int level = line.lastIndexOf('\t') + 1;
        line = line.substring(level);

        while (dirLengthStack.size() > level) {
            dirLengthStack.pop();
        }

        int length = (dirLengthStack.isEmpty()) ? line.length() : dirLengthStack.peek() + line.length() + 1;
        dirLengthStack.push(length);

        if (line.contains(".")) {
            maxFileLength = Math.max(maxFileLength, length);
        }
    }

    return maxFileLength;
}

cpp_code:
#include <string>
#include <sstream>
#include <vector>
#include <algorithm>

int lengthLongestPath(std::string input) {
    std::istringstream ss(input);
    std::vector<int> dir_length_stack;
    std::string line;
    int max_file_length = 0;

    while (std::getline(ss, line, '\n')) {
        int level = 0;
        while (line.find('\t') != std::string::npos) {
            line.erase(0, 1);
            level++;
        }

        while (dir_length_stack.size() > level)
            dir_length_stack.pop_back();

        int length;
        if (dir_length_stack.empty()) {
            length = line.length();
        } else {
            length = dir_length_stack.back() + line.length() + 1;
        }
        dir_length_stack.push_back(length);

        if (line.find('.') != std::string::npos) {
            max_file_length = std::max(max_file_length, length);
        }
    }

    return max_file_length;
}

python_code:
def length_longest_path(input: str) -> int:
    dir_length_stack = []
    max_file_length = 0
    lines = input.split('\n')

    for line in lines:
        level = line.count('\t')
        line = line.lstrip('\t')

        while len(dir_length_stack) > level:
            dir_length_stack.pop()

        if dir_length_stack:
            length = dir_length_stack[-1] + len(line) + 1
        else:
            length = len(line)
        dir_length_stack.append(length)

        if '.' in line:
            max_file_length = max(max_file_length, length)

    return max_file_length

javascript_code:
function lengthLongestPath(input) {
    const dirLengthStack = [];
    const lines = input.split('\n');
    let maxFileLength = 0;

    for (const line of lines) {
        const level = (line.match(/\t/g) || []).length;
        const lineText = line.replace(/\t/g, '');

        while (dirLengthStack.length > level)
            dirLengthStack.pop();

        const length = (dirLengthStack.length === 0) ? lineText.length : (dirLengthStack[dirLengthStack.length - 1] + lineText.length + 1);
        dirLengthStack.push(length);

        if (lineText.includes('.')) {
            maxFileLength = Math.max(maxFileLength, length);
        }
    }

    return maxFileLength;
}

