        else points.add(p1);
        if (points.has(p2)) points.delete(p2);
        else points.add(p2);
        if (points.has(p3)) points.delete(p3);
        else points.add(p3);
        if (points.has(p4)) points.delete(p4);
        else points.add(p4);
    }

    return points.size === 4 &&
           points.has(lx + "," + ly) && points.has(lx + "," + ry) &&
           points.has(rx + "," + ly) && points.has(rx + "," + ry) &&
           area === (rx - lx) * (ry - ly);
}

