    while (ptr < s.size()) {
        if (isdigit(s[ptr])) {
            int count = 0;
            while (isdigit(s[ptr])) {
                count = count * 10 + (s[ptr] - '0');
                ptr++;
            }
            counts.push(count);
        } else if (s[ptr] == '[') {
            results.push(current);
            current = "";
            ptr++;
        } else if (s[ptr] == ']') {
            std::string prev = results.top();
            results.pop();
            int count = counts.top();
            counts.pop();
            for (int i = 0; i < count; i++) {
                prev += current;
            }
            current = prev;
            ptr++;
        } else {
            current += s[ptr];
            ptr++;
        }
    }

    return current;
}

