java_code:
import java.util.*;

public int longestSubstring(String s, int k) {
    if (s == null || s.length() == 0 || k <= 0) return 0;

    Map<Character, Integer> charCount = new HashMap<>();
    for (char ch : s.toCharArray())
        charCount.put(ch, charCount.getOrDefault(ch, 0) + 1);

    for (Map.Entry<Character, Integer> entry : charCount.entrySet()) {
        if (entry.getValue() < k) {
            int res = 0;
            for (String str : s.split(Character.toString(entry.getKey())))
                res = Math.max(res, longestSubstring(str, k));
            return res;
        }
    }
    return s.length();
}

cpp_code:
#include <string>
#include <unordered_map>
#include <algorithm>

int longestSubstring(const std::string& s, int k) {
    if (s.empty() || k <= 0) return 0;

    std::unordered_map<char, int> char_count;
    for (char ch : s)
        char_count[ch]++;

    for (const auto& item : char_count) {
        if (item.second < k) {
            int res = 0;
            for (const std::string& str : split(s, item.first))
                res = std::max(res, longestSubstring(str, k));
            return res;
        }
    }
    return s.length();
}

std::vector<std::string> split(const std::string& s, char delimiter) {
    std::vector<std::string> subs;
    size_t start = 0;
    size_t end = s.find(delimiter);
    while (end != std::string::npos) {
        subs.push_back(s.substr(start, end - start));
        start = end + 1;
        end = s.find(delimiter, start);
    }
    subs.push_back(s.substr(start));
    return subs;
}

python_code:
def longestSubstring(s: str, k: int) -> int:
    if not s or k <= 0:
        return 0

    char_count = {}
    for ch in s:
        char_count[ch] = char_count.get(ch, 0) + 1

    for char, count in char_count.items():
        if count < k:
            return max(longestSubstring(sub_s, k) for sub_s in s.split(char))
    return len(s)

