from collections import defaultdict

def dfs(s1, s2, graph):
    if s1 not in graph or s2 not in graph:
        return -1.0
    if s1 == s2:
        return 1.0

    for neighbor, weight in graph[s1]:
        if neighbor not in visited:
            visited.add(neighbor)
            temp = dfs(neighbor, s2, graph)
            if temp > 0:
                return weight * temp
    return -1.0

def calcEquation(equations, values, queries):
    graph = defaultdict(list)
    for (s1, s2), value in zip(equations, values):
        graph[s1].append((s2, value))
        graph[s2].append((s1, 1 / value))

    ans = []
    for s1, s2 in queries:
        visited = set()
        ans.append(dfs(s1, s2, graph))
    return ans

javascript_code:
function dfs(s1, s2, graph) {
  if (!graph[s1] || !graph[s2]) return -1.0;
  if (s1 === s2) return 1.0;

  for (const [neighbor, weight] of graph[s1]) {
    if (!visited.has(neighbor)) {
      visited.add(neighbor);
      const temp = dfs(neighbor, s2, graph);
      if (temp > 0) return weight * temp;
    }
  }
  return -1.0;
}

function calcEquation(equations, values, queries) {
  const graph = {};
  for (let i = 0; i < equations.length; i++) {
    const [s1, s2] = equations[i];
    const value = values[i];

    if (!graph[s1]) graph[s1] = [];
    if (!graph[s2]) graph[s2] = [];
    graph[s1].push([s2, value]);
    graph[s2].push([s1, 1 / value]);
  }

  const ans = [];
  for (const [s1, s2] of queries) {
    const visited = new Set();
    ans.push(dfs(s1, s2, graph));
  }
  return ans;
}

