public String removeKDigits(String num, int k) {
    StringBuilder result = new StringBuilder();
    for (char c : num.toCharArray()) {
        while (k > 0 && result.length() > 0 && result.charAt(result.length() - 1) > c) {
            result.setLength(result.length() - 1);
            k--;
        }
        result.append(c);
    }
    result.setLength(result.length() - k);
    while (result.length() > 0 && result.charAt(0) == '0') {
        result.deleteCharAt(0);
    }
    return result.length() == 0 ? "0" : result.toString();
}

cpp_code:
#include <string>
using namespace std;

string removeKDigits(string num, int k) {
    string result = "";
    for (char c : num) {
        while (k > 0 && !result.empty() && result.back() > c) {
            result.pop_back();
            k--;
        }
        result.push_back(c);
    }
    result.resize(result.length() - k);
    while (!result.empty() && result[0] == '0') {
        result.erase(result.begin());
    }
    return result.empty() ? "0" : result;
}

python_code:
def remove_k_digits(num, k):
    stack = []
    for c in num:
        while k > 0 and stack and stack[-1] > c:
            stack.pop()
            k -= 1
        stack.append(c)
    while k > 0:
        stack.pop()
        k -= 1
    return ''.join(stack).lstrip('0') or '0'

javascript_code:
function removeKDigits(num, k) {
    let stack = [];
    for (let i = 0; i < num.length; i++) {
        let c = num[i];
        while (k > 0 && stack.length > 0 && stack[stack.length - 1] > c) {
            stack.pop();
            k--;
        }
        stack.push(c);
    }
    while (k > 0) {
        stack.pop();
        k--;
    }
    let result = stack.join('').replace(/^0+/, '');
    return result || '0';
}

