        for (int k : dp[stone]) {
            for (int jump : {k - 1, k, k + 1}) {
                if (jump > 0 && dp.count(stone + jump))
                    dp[stone + jump].insert(jump);
            }
        }
    }
    return !dp[stones.back()].empty();
}

