#include <queue>
#include <vector>

using namespace std;

int trapRainWater(vector<vector<int>>& heightMap) {
    int m = heightMap.size(), n = heightMap[0].size();
    priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> pq;
    vector<vector<int>> visited(m, vector<int>(n, 0));

    for (int i = 0; i < m; i++) {
        pq.push({heightMap[i][0], i * n});
        pq.push({heightMap[i][n - 1], i * n + n - 1});
        visited[i][0] = visited[i][n - 1] = 1;
    }

    for (int i = 1; i < n - 1; i++) {
        pq.push({heightMap[0][i], i});
        pq.push({heightMap[m - 1][i], (m - 1) * n + i});
        visited[0][i] = visited[m - 1][i] = 1;
    }

    int water = 0, maxHeight = 0;
    vector<vector<int>> dirs = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

    while (!pq.empty()) {
        auto t = pq.top(); pq.pop();
        int h = t.first, r = t.second / n, c = t.second % n;
        maxHeight = max(maxHeight, h);
        for (auto dir : dirs) {
            int x = r + dir[0], y = c + dir[1];
            if (x < 0 || x >= m || y < 0 || y >= n || visited[x][y]) continue;
            if (heightMap[x][y] < maxHeight) water += maxHeight - heightMap[x][y];
            pq.push({heightMap[x][y], x * n + y});
            visited[x][y] = 1;
        }
    }

    return water;
}

javascript_code:
function trapRainWater(heightMap) {
    const m = heightMap.length;
    const n = heightMap[0].length;
    const pq = [];
    const visited = Array.from({ length: m }, () => Array(n).fill(false));

    const comparator = (a, b) => a[0] - b[0];

    for (let i = 0; i < m; i++) {
        pq.push([heightMap[i][0], i, 0], [heightMap[i][n - 1], i, n - 1]);
        visited[i][0] = visited[i][n - 1] = true;
    }

    for (let i = 1; i < n - 1; i++) {
        pq.push([heightMap[0][i], 0, i], [heightMap[m - 1][i], m - 1, i]);
        visited[0][i] = visited[m - 1][i] = true;
    }

    pq.sort(comparator);

    let water = 0;
    let maxHeight = 0;
    const dirs = [[0, 1], [0, -1], [1, 0], [-1, 0]];

    while (pq.length) {
        const [h, r, c] = pq.shift();
        maxHeight = Math.max(maxHeight, h);
        for (const [dx, dy] of dirs) {
            const x = r + dx;
            const y = c + dy;
            if (x < 0 || x >= m || y < 0 || y >= n || visited[x][y]) continue;
            if (heightMap[x][y] < maxHeight) water += maxHeight - heightMap[x][y];
            pq.push([heightMap[x][y], x, y]);
            pq.sort(comparator);
            visited[x][y] = true;
        }
    }

    return water;
}

