function validWordAbbreviation(word, abbr) {
    let i = 0, j = 0;
    while (i < word.length && j < abbr.length) {
        if (!isNaN(abbr[j])) {
            if (abbr[j] === '0') return false; // leading zero
            let num = 0;
            while (j < abbr.length && !isNaN(abbr[j])) {
                num = num * 10 + parseInt(abbr[j]);
                j++;
            }
            i += num;
