#include <string>
#include <vector>

std::string abbreviate(const std::string& s, int k, int i) {
    if (i == s.length()) {
        return (k > 0) ? std::to_string(k) : "";
    }
    if (k == 0) {
        return s.substr(i) + (i + 1 < s.length() ? abbreviate(s, 1, i + 1) : "");
    }
    return std::to_string(k) + s[i] + (i + 1 < s.length() ? abbreviate(s, 1, i + 1) : "");
}

bool isAbbreviation(const std::string& target, const std::string& word) {
    int i = 0, j = 0;
    while (i < target.length() && j < word.length()) {
        if (target[i] == word[j]) {
            i++; j++;
        } else if (isdigit(target[i])) {
            int k = 0;
            while (i < target.length() && isdigit(target[i])) {
                k = k * 10 + target[i++] - '0';
            }
            j += k;
        } else {
            return false;
        }
    }
    return (i == target.length() && j == word.length());
}

std::string minAbbreviation(std::string target, std::vector<std::string>& dictionary) {
    std::string ans = target;
    for (int k = 0; k <= target.length(); k++) {
        for (int i = 0; i <= target.length() - k; i++) {
            std::string current = abbreviate(target, k, i);
            if (current.length() < ans.length()) {
                bool valid = true;
                for (const std::string& word : dictionary) {
                    if (isAbbreviation(current, word)) {
                        valid = false;
                        break;
                    }
                }
                if (valid) {
                    ans = current;
                }
            }
        }
    }
    return ans;
}

python_code:
def abbreviate(s, k, i):
    if i == len(s):
        return str(k) if k > 0 else ""
    if k == 0:
        return s[i:] + (abbreviate(s, 1, i + 1) if i + 1 < len(s) else "")
    return str(k) + s[i] + (abbreviate(s, 1, i + 1) if i + 1 < len(s) else "")

def is_abbreviation(target, word):
    i, j = 0, 0
    while i < len(target) and j < len(word):
        if target[i] == word[j]:
            i, j = i + 1, j + 1
        elif target[i].isdigit():
            k = 0
            while i < len(target) and target[i].isdigit():
                k = k * 10 + int(target[i])
                i += 1
            j += k
        else:
            return False
    return i == len(target) and j == len(word)

def min_abbreviation(target, dictionary):
    ans = target
    for k in range(0, len(target) + 1):
        for i in range(0, len(target) - k + 1):
            current = abbreviate(target, k, i)
            if len(current) < len(ans):
                valid = True
                for word in dictionary:
                    if is_abbreviation(current, word):
                        valid = False
                        break
                if valid:
                    ans = current
    return ans

javascript_code:
function abbreviate(s, k, i) {
    if (i === s.length) {
        return (k > 0) ? String(k) : "";
    }
    if (k === 0) {
        return s.slice(i) + (i + 1 < s.length ? abbreviate(s, 1, i + 1) : "");
    }
    return String(k) + s[i] + (i + 1 < s.length ? abbreviate(s, 1, i + 1) : "");
}

function isAbbreviation(target, word) {
    let i = 0, j = 0;
    while (i < target.length && j < word.length) {
        if (target[i] === word[j]) {
            i++; j++;
        } else if (target[i] >= '0' && target[i] <= '9') {
            let k = 0;
            while (i < target.length && target[i] >= '0' && target[i] <= '9') {
                k = k * 10 + parseInt(target[i++]);
            }
            j += k;
        } else {
            return false;
        }
    }
    return (i === target.length && j === word.length);
}

function minAbbreviation(target, dictionary) {
    let ans = target;
    for (let k = 0; k <= target.length; k++) {
        for (let i = 0; i <= target.length - k; i++) {
            let current = abbreviate(target, k, i);
            if (current.length < ans.length) {
                let valid = true;
                for (const word of dictionary) {
                    if (isAbbreviation(current, word)) {
                        valid = false;
                        break;
                    }
                }
                if (valid) {
                    ans = current;
                }
            }
        }
    }
    return ans;
}

