        if (i >= 0) {
            sum += parseInt(num1[i]);
            --i;
        }
        if (j >= 0) {
            sum += parseInt(num2[j]);
            --j;
        }

        carry = Math.floor(sum / 10);
        result.push(sum % 10);
    }

    return result.reverse().join('');
}

java_code:
public boolean canPartition(int[] nums) {
    int sum = 0;
    for (int num : nums) sum += num;

    if (sum % 2 != 0) return false;

    int target = sum / 2;
    boolean[] dp = new boolean[target + 1];
    dp[0] = true;

    for (int num : nums) {
        for (int i = target; i >= num; i--) {
            dp[i] = dp[i] || dp[i - num];
        }
    }
    return dp[target];
}

