        if (c.match(/[A-Z]/)) missingUpper = 0;
        if (c.match(/[0-9]/)) missingDigit = 0;
    }
    let missing = missingLower + missingUpper + missingDigit;
    if (total < 6) return Math.max(missing, 6 - total);
    if (total > 20) return missing + total - 20;
    return missing;
}

java_code:
public int findMaximumXOR(int[] nums) {
    int max_xor = 0, mask = 0;

    for (int i = 31; i >= 0; i--) {
        mask |= (1 << i);
        HashSet<Integer> prefixes = new HashSet<>();

        for (int num : nums) {
            prefixes.add(num & mask);
        }

        int possible_max = max_xor | (1 << i);

        for (int prefix : prefixes) {
            if (prefixes.contains(prefix ^ possible_max)) {
                max_xor = possible_max;
                break;
            }
        }
    }

    return max_xor;
}

cpp_code:
int findMaximumXOR(vector<int>& nums) {
    int max_xor = 0;
    int mask = 0;

    for (int i = 31; i >= 0; i--) {
        mask |= (1 << i);
        unordered_set<int> prefixes;

        for (int num : nums) {
            prefixes.insert(num & mask);
        }

        int possible_max = max_xor | (1 << i);

        for (int prefix : prefixes) {
            if (prefixes.count(prefix ^ possible_max)) {
                max_xor = possible_max;
                break;
            }
        }
    }

    return max_xor;
}

