    for (const c of s) {
        if (c === 'z') count[0]++;
        if (c === 'w') count[2]++;
        if (c === 'u') count[4]++;
        if (c === 'x') count[6]++;
        if (c === 'g') count[8]++;
        if (c === 'o') count[1]++;
        if (c === 'h') count[3]++;
        if (c === 'f') count[5]++;
        if (c === 's') count[7]++;
        if (c === 'i') count[9]++;
    }
