from collections import defaultdict

def wordSquares(words):
    def build(row, squares, word_lens):
        if row == word_lens:
            res.append(list(squares))
            return
        prefix = ''.join(squares[i][row] for i in range(row))
        for w in prefixes[prefix]:
            squares[row] = w
            build(row+1, squares, word_lens)

    if not words: return []
    res = []
    word_lens = len(words[0])

    prefixes = defaultdict(list)
    for word in words:
        for i in range(word_lens+1):
            prefixes[word[:i]].append(word)

    for word in words:
        build(1, [word] + [None]*(word_lens-1), word_lens)

    return res

javascript_code:
function wordSquares(words) {
    const buildPrefixMap = words => {
        const prefixMap = new Map();
        for (const word of words) {
            for (let i = 0; i <= word.length; i++) {
                const prefix = word.slice(0, i);
                if (!prefixMap.has(prefix)) {
                    prefixMap.set(prefix, []);
                }
                prefixMap.get(prefix).push(word);
            }
        }
        return prefixMap;
    };

    const search = (row, square, prefixMap, res) => {
        if (row === square.length) {
            res.push(square.slice());
            return;
        }
        const prefix = square.slice(0, row).map((word, i) => word[row]).join('');
        for (const word of prefixMap.get(prefix) || []) {
            square[row] = word;
            search(row + 1, square, prefixMap, res);
        }
    };

    const prefixMap = buildPrefixMap(words);
    const res = [];
    for (const word of words) {
        search(1, [word], prefixMap, res);
    }
    return res;
}

