class Solution {
    private static class Node {
        int val;
        Node left;
        Node right;

        Node(int val, Node left, Node right) {
            this.val = val;
            this.left = left;
            this.right = right;
        }
    }

    private Node first = null;
    private Node last = null;

    public Node treeToDoublyList(Node root) {
        if (root == null) {
            return null;
        }

        inOrder(root);

        last.right = first;
        first.left = last;

        return first;
    }

    private void inOrder(Node root) {
        if (root == null) {
            return;
        }

        inOrder(root.left);

        if (last != null) {
            last.right = root;
            root.left = last;
        } else {
            first = root;
        }

        last = root;

        inOrder(root.right);
    }
}

