class Node {
public:
    int val;
    Node* left;
    Node* right;

    Node() {}

    Node(int _val) {
        val = _val;
        left = NULL;
        right = NULL;
    }

    Node(int _val, Node* _left, Node* _right) {
        val = _val;
        left = _left;
        right = _right;
    }
};

class Solution {
public:
    Node* treeToDoublyList(Node* root) {
        if (!root) return nullptr;
        Node *first = nullptr, *last = nullptr;
        inorder(root, first, last);
        first->left = last;
        last->right = first;
        return first;
    }

    void inorder(Node* root, Node*& first, Node*& last) {
        if (!root) return;
        inorder(root->left, first, last);

        if (last) {
            last->right = root;
            root->left = last;
        } else {
            first = root;
        }
        last = root;

        inorder(root->right, first, last);
    }
};

