class Solution:
    def treeToDoublyList(self, root: 'Node') -> 'Node':
        if not root:
            return None

        first = None
        last = None

        def inOrder(node):
            nonlocal first, last

            if not node:
                return

            inOrder(node.left)

            if last:
                last.right = node
                node.left = last
            else:
                first = node

            last = node

            inOrder(node.right)

        inOrder(root)

        first.left = last
        last.right = first

        return first

