#include <vector>
#include <string>
#include <sstream>
using namespace std;

class Node {
public:
    int val;
    vector<Node*> children;

    Node() {}

    Node(int _val) {
        val = _val;
    }

    Node(int _val, vector<Node*> _children) {
        val = _val;
        children = _children;
    }
};

class Codec {
public:

    string serialize(Node* root) {
        if (!root) return "";
        string data = to_string(root->val) + " ";
        for (Node* child : root->children) {
            data += serialize(child);
        }
        data += "# ";
        return data;
    }

    Node* deserialize(string data) {
        istringstream iss(data);
        return deserialize(iss);
    }

private:
    Node* deserialize(istringstream& iss) {
        string val;
        iss >> val;
        if (val == "#") return nullptr;
        Node* node = new Node(stoi(val));
        while (true) {
            Node* child = deserialize(iss);
            if (!child) break;
            node->children.push_back(child);
        }
        return node;
    }
};

