public class Node {
    public int val;
    public Node prev;
    public Node next;
    public Node child;
}

public Node flatten(Node head) {
    if (head == null) return null;

    Node cur = head, prev = null, next;

    while (cur != null) {
        next = cur.next;

        if (cur.child != null) {
            cur.next = flatten(cur.child);
            cur.child.prev = cur;
            cur.child = null;

            if (next != null) {
                prev = cur;
                while (cur.next != null) {
                    cur = cur.next;
                    prev = prev.next;
                }
                cur.next = next;
                next.prev = prev;
            }
        }
        cur = next;
    }

    return head;
}

