def flatten(head: Node) -> Node:
    if not head:
        return None

    cur, prev, next_node = head, None, None

    while cur:
        next_node = cur.next

        if cur.child:
            cur.next = flatten(cur.child)
            cur.child.prev = cur
            cur.child = None

            if next_node:
