        this.val = val;
        this.left = left;
        this.right = right;
    }
}

function encode(root) {
    if (!root) return null;
    const binaryRoot = new BinaryTreeNode(root.val);
    if (root.children.length > 0) {
        binaryRoot.left = encode(root.children[0]);
    }
    let sibling = binaryRoot.left;
    for (let i = 1; i < root.children.length; ++i) {
        sibling.right = encode(root.children[i]);
        sibling = sibling.right;
    }
    return binaryRoot;
}

function decode(root) {
    if (!root) return null;
    const naryRoot = new NaryTreeNode(root.val);
    let sibling = root.left;
    while (sibling) {
        naryRoot.children.push(decode(sibling));
        sibling = sibling.right;
    }
    return naryRoot;
}

