class AllOne {
    constructor() {
        this.data = new Map();
    }

    inc(key) {
        this.data.set(key, (this.data.get(key) || 0) + 1);
    }

    dec(key) {
        if (this.data.has(key)) {
            if (this.data.get(key) === 1) {
                this.data.delete(key);
            } else {
                this.data.set(key, this.data.get(key) - 1);
            }
        }
    }

    getMaxKey() {
        if (this.data.size === 0) return "";
        return [...this.data.entries()].reduce((a, b) => (a[1] > b[1] ? a : b))[0];
    }

    getMinKey() {
        if (this.data.size === 0) return "";
        return [...this.data.entries()].reduce((a, b) => (a[1] < b[1] ? a : b))[0];
    }
}

