public boolean isShortestAndUniqueSupersequence(int[] nums, int[][] sequences) {
    Map<Integer, Integer> pos = new HashMap<>();
    for (int i = 0; i < nums.length; i++) {
        pos.put(nums[i], i);
    }

    for (int[] seq : sequences) {
        if (pos.get(seq[0]) > pos.get(seq[seq.length - 1])) {
            return false;
        }
    }
    return true;
}

