bool isShortestAndUniqueSupersequence(vector<int>& nums, vector<vector<int>>& sequences) {
    unordered_map<int, int> pos;
    for (int i = 0; i < nums.size(); ++i) {
        pos[nums[i]] = i;
    }

    for (const auto& seq : sequences) {
        if (pos[seq[0]] > pos[seq.back()]) {
            return false;
        }
    }
    return true;
}

