#include <vector>
#include <unordered_map>

int numberOfArithmeticSlices(std::vector<int>& nums) {
    int res = 0;
    int n = nums.size();
    std::vector<std::unordered_map<int, int>> dp(n);

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < i; ++j) {
            long diff = (long)nums[i] - (long)nums[j];
            if (diff <= INT_MIN || diff > INT_MAX) continue;

            int delta = (int)diff;
            dp[i][delta] += 1;

            if (dp[j].count(delta)) {
                res += dp[j][delta];
                dp[i][delta] += dp[j][delta];
            }
        }
    }
    return res;
}

python_code:
def numberOfArithmeticSlices(nums):
    res = 0
    n = len(nums)
    dp = [dict() for _ in range(n)]

    for i in range(n):
        for j in range(i):
            diff = nums[i] - nums[j]
            if diff <= -2**31 or diff > 2**31:
                continue

            dp[i][diff] = dp[i].get(diff, 0) + 1

            if diff in dp[j]:
                res += dp[j][diff]
                dp[i][diff] += dp[j][diff]

    return res

javascript_code:
function numberOfArithmeticSlices(nums) {
    let res = 0;
    const n = nums.length;
    const dp = new Array(n).fill(0).map(() => new Map());

    for (let i = 0; i < n; ++i) {
        for (let j = 0; j < i; ++j) {
            const diff = nums[i] - nums[j];
            if (diff <= Number.MIN_SAFE_INTEGER || diff > Number.MAX_SAFE_INTEGER) continue;

            if (!dp[i].has(diff)) {
                dp[i].set(diff, 0);
            }

            dp[i].set(diff, dp[i].get(diff) + 1);

            if (dp[j].has(diff)) {
                res += dp[j].get(diff);
                dp[i].set(diff, dp[i].get(diff) + dp[j].get(diff));
            }
        }
    }
    return res;
}

