import java.util.HashMap;

public int numberOfBoomerangs(int[][] points) {
    int count = 0;

    for (int[] i : points) {
        HashMap<Integer, Integer> group_count = new HashMap<>();
        for (int[] j : points) {
            int dx = i[0] - j[0], dy = i[1] - j[1];
            int dist = dx * dx + dy * dy;

            group_count.put(dist, group_count.getOrDefault(dist, 0) + 1);
        }

        for (int g : group_count.values()) {
            count += g * (g - 1);
        }
    }

    return count;
}

cpp_code:
#include <unordered_map>

int numberOfBoomerangs(vector<vector<int>>& points) {
    int count = 0;

    for (auto& i : points) {
        unordered_map<int, int> group_count;
        for (auto& j : points) {
            int dx = i[0] - j[0], dy = i[1] - j[1];
            int dist = dx * dx + dy * dy;
            group_count[dist]++;
        }

        for (auto& g : group_count) {
            count += g.second * (g.second - 1);
        }
    }

    return count;
}

