#include <sstream>
#include <string>
#include <iostream>

struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

std::string serialize(TreeNode* root) {
    if (!root) return "#";
    return std::to_string(root->val) + ',' + serialize(root->left) + ',' + serialize(root->right);
}

TreeNode* deserialize(std::string data) {
    std::istringstream data_stream(data);
    return deserialize_helper(data_stream);
}

TreeNode* deserialize_helper(std::istringstream& data_stream) {
    std::string val;
    std::getline(data_stream, val, ',');

    if (val == "#") return nullptr;
    TreeNode* node = new TreeNode(std::stoi(val));
    node->left = deserialize_helper(data_stream);
    node->right = deserialize_helper(data_stream);
    return node;
}

