java_code:
import java.util.HashMap;
import java.util.LinkedHashSet;
import java.util.Map;

class LFUCache {
    private int minFreq;
    private int capacity;
    private Map<Integer, Integer> keyValue;
    private Map<Integer, Integer> keyFreq;
    private Map<Integer, LinkedHashSet<Integer>> freqList;

    public LFUCache(int capacity) {
        this.capacity = capacity;
        this.minFreq = 0;
        this.keyValue = new HashMap<>();
        this.keyFreq = new HashMap<>();
        this.freqList = new HashMap<>();
        freqList.put(1, new LinkedHashSet<>());
    }

    public int get(int key) {
        if (!keyValue.containsKey(key)) return -1;
        int count = keyFreq.get(key);
        keyFreq.put(key, count + 1);
        freqList.get(count).remove(key);

        if (count == minFreq && freqList.get(count).size() == 0) minFreq++;

        freqList.computeIfAbsent(count + 1, k -> new LinkedHashSet<>());
        freqList.get(count + 1).add(key);

        return keyValue.get(key);
    }

    public void put(int key, int value) {
        if (capacity <= 0) return;
        if (keyValue.containsKey(key)) {
            keyValue.put(key, value);
            get(key);
            return;
        }
        if (keyValue.size() >= capacity) {
            int evict = freqList.get(minFreq).iterator().next();
            freqList.get(minFreq).remove(evict);
            keyValue.remove(evict);
        }
        keyValue.put(key, value);
        keyFreq.put(key, 1);
        minFreq = 1;
        freqList.get(1).add(key);
    }
}

cpp_code:
#include <list>
#include <unordered_map>

class LFUCache {
public:
    LFUCache(int capacity) : capacity(capacity), minFreq(0) {}

    int get(int key) {
        if (cache.count(key) == 0) return -1;
        auto& node = cache[key];
        freqList[node.freq].erase(node.iter);
        if (freqList[minFreq].size() == 0) minFreq++;
        node.freq++;
        freqList[node.freq].push_back(key);
        node.iter = prev(freqList[node.freq].end());
        return node.value;
    }

    void put(int key, int value) {
        if (capacity == 0) return;
        if (get(key) != -1) {
            cache[key].value = value;
            return;
        }
        if (cache.size() >= capacity) {
            int toRemove = freqList[minFreq].front();
            freqList[minFreq].pop_front();
            cache.erase(toRemove);
        }
        minFreq = 1;
        freqList[minFreq].push_back(key);
        cache[key] = {1, value, prev(freqList[minFreq].end())};
    }

private:
    struct Node {
        int freq, value;
        std::list<int>::iterator iter;
    };

    int capacity;
    int minFreq;
    std::unordered_map<int, Node> cache;
    std::unordered_map<int, std::list<int>> freqList;
};

python_code:
class LFUCache:
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.min_freq = 0
        self.key_value = {}
        self.key_freq = {}
        self.freq_list = {1: []}

    def get(self, key: int) -> int:
        if key not in self.key_value:
            return -1
        count = self.key_freq[key]
        self.key_freq[key] += 1
        self.freq_list[count].remove(key)

        if count == self.min_freq and not self.freq_list[count]:
            self.min_freq += 1

        if count + 1 not in self.freq_list:
            self.freq_list[count + 1] = []
        self.freq_list[count + 1].append(key)

        return self.key_value[key]

    def put(self, key: int, value: int) -> None:
        if self.capacity <= 0:
            return
        if key in self.key_value:
            self.key_value[key] = value
            self.get(key)
            return

        if len(self.key_value) >= self.capacity:
            evict = self.freq_list[self.min_freq][0]
            self.freq_list[self.min_freq].pop(0)
            del self.key_value[evict]

        self.key_value[key] = value
        self.key_freq[key] = 1
        self.min_freq = 1
        self.freq_list[1].append(key)

