from collections import Counter

def find_min_step(board: str, hand: str) -> int:
    def find_min_step_helper(board, memo, hand):
        if not board:
            return 0
        if board in memo:
            return memo[board]

        result = float('inf')
        i = 0
        while i < len(board):
            j = i
            while j < len(board) and board[i] == board[j]:
                j += 1            

            color = board[i]
            required = 3 - (j - i)
            if hand[color] >= required:
                hand[color] -= required
                next_board = board[:i] + board[j:]
                tmp = find_min_step_helper(next_board, memo, hand)
                if tmp != -1:
                    result = min(result, tmp + required)
                hand[color] += required
            i = j

        memo[board] = -1 if result == float('inf') else result
        return memo[board]

    hand_count = Counter(hand)
    memo = {}
    return find_min_step_helper(board, memo, hand_count)

javascript_code:
function findMinStep(board, hand) {
    function findMinStepHelper(board, memo, hand) {
        if (board.length === 0) return 0;
        if (memo.has(board)) return memo.get(board);

        let result = Infinity;
        let i = 0;
        while (i < board.length) {
            let j = i;
            while (j < board.length && board[i] === board[j]) j++;

            let color = board[i];
            let required = 3 - (j - i);
            if (hand[color] >= required) {
                hand[color] -= required;
                let nextBoard = board.slice(0, i) + board.slice(j);
                let tmp = findMinStepHelper(nextBoard, memo, hand);
                if (tmp !== -1) result = Math.min(result, tmp + required);
                hand[color] += required;
            }
            i = j;
        }

        let res = (result === Infinity) ? -1 : result;
        memo.set(board, res);
        return res;
    }

    let handMap = {};
    for (let c of hand) handMap[c] = (handMap[c] || 0) + 1;

    return findMinStepHelper(board, new Map(), handMap);
}

java_code:
public class Solution {
    private int comb(int n, int r) {
        if(r > n - r) r = n - r;
        long res = 1;
        for(int i = 1; i <= r; i++) {
            res *= n - r + i;
            res /= i;
        }
        return (int)res;
    }

    public String kthSmallestPath(int[] destination, int k) {
        int row = destination[0];
        int col = destination[1];
        StringBuilder ans = new StringBuilder();

        for(int i = 0; i < row + col; i++) {
            if(row == 0) {
                ans.append('H');
                col--;
            } else if(col == 0) {
                ans.append('V');
                row--;
            } else if(k <= comb(row + col - 1, row - 1)) {
                ans.append('H');
                col--;
            } else {
                ans.append('V');
                k -= comb(row + col - 1, row - 1);
                row--;
            }
        }

        return ans.toString();
    }
}

