def reversePairs(nums):
    def mergeSort(l, r):
        if l >= r:
            return 0

        mid = (l + r) // 2
        count = mergeSort(l, mid) + mergeSort(mid + 1, r)
        j = mid + 1
        for i in range(l, mid + 1):
            while j <= r and nums[i] > 2 * nums[j]:
                j += 1
            count += j - (mid + 1)

        nums[l:r + 1] = sorted(nums[l:r + 1])

        return count

    return mergeSort(0, len(nums) - 1)

javascript_code:
function reversePairs(nums) {
    function mergeSort(l, r) {
        if (l >= r) {
            return 0;
        }

        const mid = Math.floor((l + r) / 2);
        let count = mergeSort(l, mid) + mergeSort(mid + 1, r);
        let j = mid + 1;
        for (let i = l; i <= mid; i++) {
            while (j <= r && nums[i] > 2 * nums[j]) {
                j++;
            }
            count += j - (mid + 1);
        }

        const merged = nums.slice(l, r + 1).sort((a, b) => a - b);
        nums.splice(l, merged.length, ...merged);

        return count;
    }

    return mergeSort(0, nums.length - 1);
}

java_code:
public int findTargetSumWays(int[] nums, int target) {
    int sum = 0;
    for (int num : nums) sum += num;
    if (sum < target || (sum + target) % 2 != 0) return 0;
    int target_sum = (sum + target) / 2;
    int[] dp = new int[target_sum + 1];
    dp[0] = 1;
    for (int num : nums) {
        for (int j = target_sum; j >= num; j--) {
            dp[j] += dp[j - num];
        }
    }
    return dp[target_sum];
}

