        {'a','s','d','f','g','h','j','k','l'},
        {'z','x','c','v','b','n','m'}
    };
    vector<string> result;

    for (const auto& word : words) {
        int row = -1;
        for (int i = 0; i < 3; ++i) {
            if (rows[i].count(tolower(word[0])) > 0) {
                row = i;
                break;
            }
        }

        bool isOneRow = true;
        for (const auto& letter : word) {
            if (rows[row].count(tolower(letter)) == 0) {
                isOneRow = false;
                break;
            }
        }

        if (isOneRow) {
            result.push_back(word);
        }
    }

    return result;
}

