public List<Integer> findMode(TreeNode root) {
    List<Integer> modes = new ArrayList<>();
    if (root == null) return modes;

    Map<Integer, Integer> frequencyMap = new HashMap<>();
    Stack<TreeNode> stack = new Stack<>();
    TreeNode currentNode = root;
    int maxFrequency = 0;

    while (currentNode != null || !stack.isEmpty()) {
        while (currentNode != null) {
            stack.add(currentNode);
            currentNode = currentNode.left;
        }
        currentNode = stack.pop();
        frequencyMap.put(currentNode.val, frequencyMap.getOrDefault(currentNode.val, 0) + 1);
        maxFrequency = Math.max(maxFrequency, frequencyMap.get(currentNode.val));
        currentNode = currentNode.right;
    }

    for (Map.Entry<Integer, Integer> entry : frequencyMap.entrySet()) {
        if (entry.getValue() == maxFrequency) modes.add(entry.getKey());
    }

    return modes;
}

cpp_code:
void InOrder(TreeNode* root, unordered_map<int, int>& frequencies, int& max_frequency) {
    if (!root) return;
    InOrder(root->left, frequencies, max_frequency);
    frequencies[root->val]++;
    max_frequency = max(max_frequency, frequencies[root->val]);
    InOrder(root->right, frequencies, max_frequency);
}

vector<int> findMode(TreeNode* root) {
    unordered_map<int, int> frequencies;
    int max_frequency = 0;
    InOrder(root, frequencies, max_frequency);
    vector<int> modes;

    for (const auto& freq : frequencies) {
        if (freq.second == max_frequency) modes.push_back(freq.first);
    }

    return modes;
}

