    for (int i = 0; i < nums.size() * 2; ++i) {
        int index = i % nums.size();
        while (!s.empty() && nums[s.top()] < nums[index]) {
            result[s.top()] = nums[index];
            s.pop();
        }
        if (i < nums.size()) {
            s.push(index);
        }
    }
    return result;
}

