#include <string>
#include <vector>
#include <algorithm>

int findRotateSteps(std::string ring, std::string key) {
    int n = ring.size(), m = key.size();
    std::vector<std::vector<int>> dp(m + 1, std::vector<int>(n, 0));

    for (int i = m - 1; i >= 0; --i) {
        for (int j = 0; j < n; ++j) {
            dp[i][j] = INT_MAX;
            for (int k = 0; k < n; ++k) {
                if (ring[k] == key[i]) {
                    int diff = abs(j - k);
                    int step = std::min(diff, n - diff);
                    dp[i][j] = std::min(dp[i][j], step + dp[i + 1][k]);
                }
            }
        }
    }

    return dp[0][0] + m;
}

