public boolean detectCapitalUse(String word) {
    int numCapital = 0;
    for (char c : word.toCharArray()) {
        if (Character.isUpperCase(c)) numCapital++;
    }
    return numCapital == 0 || numCapital == word.length() || (numCapital == 1 && Character.isUpperCase(word.charAt(0)));
}

