        let i = 0, j = 0;
        while (i < s.length && j < word.length) {
            if (s[i] === word[j]) {
                j++;
            }
            i++;
        }
        return j === word.length;
    }

    dictionary.sort();
    let longest = '';
    for (let word of dictionary) {
        if (isSubsequence(s, word)) {
            if (word.length > longest.length) {
                longest = word;
            }
        }
    }
    return longest;
}

