java_code:
int countArrangement(int n) {
    int[] res = new int[]{0};
    boolean[] visited = new boolean[n+1];
    helper(n, 1, visited, res);
    return res[0];
}

void helper(int n, int idx, boolean[] visited, int[] res) {
    if (idx > n) {
        res[0]++;
    }

    for(int i=1; i<=n; i++){
        if (!visited[i] && (idx % i == 0 || i % idx == 0)) {
            visited[i] = true;
            helper(n, idx+1, visited, res);
            visited[i] = false;
        }
    }
}

cpp_code:
int countArrangement(int n) {
    int res=0;
    vector<bool> visited(n+1,false); 
    helper(n,1,visited,res); 
    return res;
}

void helper(int n, int idx, vector<bool>& visited, int& res) {
    if (idx > n) {
        ++res;
    }

    for(int i=1; i<=n; i++){
        if (!visited[i] && (idx % i == 0 || i % idx == 0)) { 
            visited[i] = true; 
            helper(n, idx+1, visited, res); 
            visited[i] = false; 
        }
    }
}

python_code:
def countArrangement(n: int) -> int:
    def helper(idx: int, visited: List[bool], n: int) -> int:
        if idx > n:
            return 1

        count = 0
        for i in range(1, n+1):
            if not visited[i] and (idx % i == 0 or i % idx == 0):
                visited[i] = True
                count += helper(idx+1, visited, n)
                visited[i] = False

        return count

    visited = [False] * (n+1)
    return helper(1, visited, n)

