    helper(n,1,visited); 
    return res;

    function helper(n, idx, visited) {
        if (idx > n) {
            ++res;
        }

        for(let i=1; i<=n; i++){
            if (!visited[i] && (idx % i === 0 || i % idx === 0)) { 
                visited[i] = true; 
                helper(n, idx+1, visited); 
                visited[i] = false; 
            }
        }
    }
}

