public class ListNode {
    int val;
    ListNode next;
    ListNode(int x) { val = x; }
}

public ListNode swapNodes(ListNode head, int k) {
    ListNode first = head, second = head, temp = head;
    for (int i = 0; i < k - 1; i++) {
        temp = temp.next;
    }
    first = temp;
    temp = temp.next;
    while (temp != null) {
        temp = temp.next;
        second = second.next;
    }
    int tmp = first.val;
    first.val = second.val;
    second.val = tmp;

    return head;
}

