ListNode* swapNodes(ListNode* head, int k) {
    ListNode *first = head, *second = head, *temp = head;
    for (int i = 0; i < k - 1; i++) {
        temp = temp->next;
    }
    first = temp;
    temp = temp->next;
    while (temp) {
        temp = temp->next;
        second = second->next;
    }
    std::swap(first->val, second->val);
    return head;
}

