    unordered_map<int, int> occurrences;
    for (int num : nums) {
        if (occurrences.count(num + k)) starters.insert(num);
        if (occurrences.count(num - k)) starters.insert(num - k);
        occurrences[num]++;
    }
    return starters.size();
}

