#include <string>

struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode(int x) : val(x), left(NULL), right(NULL) {}
};

class Solution {
public:
    TreeNode* str2tree(std::string s) {
        int idx = 0;
        return str2treeHelper(s, idx);
    }

    TreeNode* str2treeHelper(const std::string& s, int& idx) {
        if (idx >= s.length()) return NULL;

        int sign = 1;
        if (s[idx] == '-') {
            sign = -1;
            idx++;
        }

        int num = 0;
        while (idx < s.length() && isdigit(s[idx])) {
            num = num * 10 + (s[idx] - '0');
            idx++;
        }

        TreeNode* node = new TreeNode(sign * num);

        if (idx < s.length() && s[idx] == '(') {
            idx++;
            node->left = str2treeHelper(s, idx);
            idx++;
        }
        if (idx < s.length() && s[idx] == '(') {
            idx++;
            node->right = str2treeHelper(s, idx);
            idx++;
        }

        return node;
    }
};

