            idx.value++;
            node.left = str2treeHelper(s, idx);
            idx.value++;
        }
        if (idx.value < s.length && s[idx.value] === '(') {
            idx.value++;
            node.right = str2treeHelper(s, idx);
            idx.value++;
        }

        return node;
    };

    const idx = {value: 0};
    return str2treeHelper(s, idx);
};

