class Solution {
    leftBoundary(node, boundary) {
        if (!node || (!node.left && !node.right)) return;
        boundary.push(node.val);
        if (node.left) this.leftBoundary(node.left, boundary);
        else this.leftBoundary(node.right, boundary);
    }

    rightBoundary(node, boundary) {
        if (!node || (!node.left && !node.right)) return;
        if (node.right) this.rightBoundary(node.right, boundary);
        else this.rightBoundary(node.left, boundary);
        boundary.push(node.val);
    }

    leaves(node, boundary) {
        if (!node) return;
        if (!node.left && !node.right) {
            boundary.push(node.val);
        }
        this.leaves(node.left, boundary);
        this.leaves(node.right, boundary);
    }

    boundaryOfBinaryTree(root) {
        let res = [];
        if (!root) return res;

        res.push(root.val);
        this.leftBoundary(root.left, res);
        this.leaves(root, res);
        this.rightBoundary(root.right, res);
        return res;
    }
}

