#include<algorithm>

class TreeNode {
public:
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode() : val(0), left(nullptr), right(nullptr) {}
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
    TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
};

int longestConsecutivePathUtil(TreeNode* root, int& maxLength) {
    if (root == nullptr) return 0;
    int left = longestConsecutivePathUtil(root->left, maxLength) + 1;
    int right = longestConsecutivePathUtil(root->right, maxLength) + 1;
    if (root->left != nullptr && root->left->val != root->val + 1) left = 1;
    if (root->right != nullptr && root->right->val != root->val + 1) right = 1;
    int length = std::max(left, right);
    maxLength = std::max(maxLength, left + right - 1);
    return length;
}

int longestConsecutive(TreeNode* root) {
    int maxLength = 0;
    longestConsecutivePathUtil(root, maxLength);
    return maxLength;
}

