java_code:
import java.util.List;
import java.util.HashMap;

public int leastBricks(List<List<Integer>> wall) {
    HashMap<Integer, Integer> edgeCount = new HashMap<>();
    int maxCount = 0;

    for (List<Integer> row : wall) {
        int edgePosition = 0;
        for (int i = 0; i < row.size() - 1; ++i) {
            edgePosition += row.get(i);
            edgeCount.put(edgePosition, edgeCount.getOrDefault(edgePosition, 0) + 1);
            maxCount = Math.max(maxCount, edgeCount.get(edgePosition));
        }
    }

    return wall.size() - maxCount;
}

cpp_code:
#include <vector>
#include <unordered_map>

int leastBricks(std::vector<std::vector<int>>& wall) {
    std::unordered_map<int, int> edge_count;
    int max_count = 0;

    for (const auto& row : wall) {
        int edge_position = 0;
        for (size_t i = 0; i < row.size() - 1; ++i) {
            edge_position += row[i];
            ++edge_count[edge_position];
            max_count = std::max(max_count, edge_count[edge_position]);
        }
    }

    return wall.size() - max_count;
}

