            edgePosition += row[i];
            edgeCount.set(edgePosition, (edgeCount.get(edgePosition) || 0) + 1);
            maxCount = Math.max(maxCount, edgeCount.get(edgePosition));
        }
    }

    return wall.length - maxCount;
}

