#include <vector>
#include <string>
#include <algorithm>

std::string splitLoopedString(std::vector<std::string>& strs) {
    std::string ans;
    std::string cur;
    for (auto &s : strs) {
        std::string rev(s.rbegin(), s.rend());
        cur += std::max(s, rev);
    }

    for (size_t i = 0, k = 0; i < strs.size(); ++i) {
        std::string rev(strs[i].rbegin(), strs[i].rend());
        for (auto &xstr : {strs[i], rev}) {
            for (size_t j = 0; j < xstr.size(); ++j) {
                std::string t = xstr.substr(j) + cur.substr(k + xstr.size()) + cur.substr(0, k) + xstr.substr(0, j);
                ans = std::max(ans, t);
            }
        }
        k += strs[i].size();
    }
    return ans;
}

python_code:
def splitLoopedString(strs):
    ans = ''
    cur = ''.join(max(s, s[::-1]) for s in strs)

    for i, s in enumerate(strs):
        for xstr in (s, s[::-1]):
            for j in range(len(xstr)):
                t = xstr[j:] + cur[len(xstr):] + cur[:len(xstr)] + xstr[:j]
                ans = max(ans, t)
        cur = cur[len(s):] + cur[:len(s)]

    return ans

javascript_code:
function splitLoopedString(strs) {
    let ans = "", cur = "";
    strs.forEach(s => {
        const rev = s.split('').reverse().join('');
        cur += s > rev ? s : rev;
    });

    for (let i = 0, k = 0; i < strs.length; i++) {
        let rev = strs[i].split('').reverse().join('');
        [strs[i], rev].forEach(xstr => {
            for (let j = 0; j < xstr.length; j++) {
                let t = xstr.slice(j) + cur.slice(k + xstr.length) + cur.slice(0, k) + xstr.slice(0, j);
                ans = ans > t ? ans : t;
            }
        });
        k += strs[i].length;
    }
    return ans;
}

