#include <string>
#include <algorithm>
#include <sstream>

std::string reverseWordsInString(const std::string& s) {
    std::istringstream iss(s);
    std::ostringstream oss;
    std::string word;
    while (iss >> word) {
        std::reverse(word.begin(), word.end());
        oss << word << ' ';
    }
    std::string result = oss.str();
    if (!result.empty()) result.pop_back();
    return result;
}

