class Node {
public:
    bool val;
    bool isLeaf;
    Node* topLeft;
    Node* topRight;
    Node* bottomLeft;
    Node* bottomRight;
};

class Solution {
public:
    Node* intersect(Node* quadTree1, Node* quadTree2) {
        if (quadTree1->isLeaf) {
            return (quadTree1->val) ? quadTree1 : quadTree2;
        } else if (quadTree2->isLeaf) {
            return (quadTree2->val) ? quadTree2 : quadTree1;
        } else {
            Node* topLeft = intersect(quadTree1->topLeft, quadTree2->topLeft);
            Node* topRight = intersect(quadTree1->topRight, quadTree2->topRight);
            Node* bottomLeft = intersect(quadTree1->bottomLeft, quadTree2->bottomLeft);
            Node* bottomRight = intersect(quadTree1->bottomRight, quadTree2->bottomRight);
            if (topLeft->isLeaf && topRight->isLeaf && bottomLeft->isLeaf && bottomRight->isLeaf &&
                topLeft->val == topRight->val && topLeft->val == bottomLeft->val && topLeft->val == bottomRight->val) {
                quadTree1->isLeaf = true;
                quadTree1->val = topLeft->val;
                delete quadTree1->topLeft;
                delete quadTree1->topRight;
                delete quadTree1->bottomLeft;
                delete quadTree1->bottomRight;
            } else {
                quadTree1->topLeft = topLeft;
                quadTree1->topRight = topRight;
                quadTree1->bottomLeft = bottomLeft;
                quadTree1->bottomRight = bottomRight;
            }
            return quadTree1;
        }
    }
};

