    children.get(ppid[i]).push(pid[i]);
  }

  const killed = [];
  function dfs(id) {
    killed.push(id);
    const childList = children.get(id) || [];
    for (const child of childList) {
      dfs(child);
    }
  }
  dfs(kill);

  return killed;
}

