#include <string>
#include <sstream>
#include <algorithm>

class FileSystem {
    struct Node {
        bool is_file = false;
        std::string content;
        std::map<std::string, Node*> children;
    };

    Node* root;

public:
    FileSystem() {
        root = new Node();
    }

    std::vector<std::string> ls(std::string path) {
        Node* node = root;
        std::vector<std::string> path_parts = split_path(path);

        for (const std::string& part : path_parts) {
            node = node->children[part];
        }

        if (node->is_file) {
            return {path_parts.back()};
        } else {
            std::vector<std::string> files;
            for (const auto& child : node->children) {
                files.push_back(child.first);
            }
            std::sort(files.begin(), files.end());
            return files;
        }
    }

    void mkdir(std::string path) {
        Node* node = root;
        std::vector<std::string> path_parts = split_path(path);

        for (const std::string& part : path_parts) {
            if (node->children.find(part) == node->children.end()) {
                node->children[part] = new Node();
            }
            node = node->children[part];
        }
    }

    void addContentToFile(std::string filePath, std::string content) {
        Node* node = root;
        std::vector<std::string> path_parts = split_path(filePath);

        for (const std::string& part : path_parts) {
            if (node->children.find(part) == node->children.end()) {
                node->children[part] = new Node();
            }
            node = node->children[part];
        }

        node->is_file = true;
        node->content += content;
    }

    std::string readContentFromFile(std::string filePath) {
        Node* node = root;
        std::vector<std::string> path_parts = split_path(filePath);

        for (const std::string& part : path_parts) {
            node = node->children[part];
        }

        return node->content;
    }

private:
    std::vector<std::string> split_path(const std::string& path) {
        std::vector<std::string> parts;
        std::istringstream ss(path);
        std::string part;

        while (std::getline(ss, part, '/')) {
            if (!part.empty()) {
                parts.push_back(part);
            }
        }

        return parts;
    }
};

