class FileSystem {
    constructor() {
        this.root = new this.Node();
    }

    ls(path) {
        let node = this.root;
        const pathParts = this.splitPath(path);

        for (const part of pathParts) {
            node = node.children[part];
        }

        if (node.isFile) {
            return [pathParts[pathParts.length - 1]];
        } else {
            return Object.keys(node.children).sort();
        }
    }

    mkdir(path) {
        let node = this.root;
        const pathParts = this.splitPath(path);

        for (const part of pathParts) {
            if (!node.children[part]) {
                node.children[part] = new this.Node();
            }
            node = node.children[part];
        }
    }

    addContentToFile(filePath, content) {
        let node = this.root;
        const pathParts = this.splitPath(filePath);

        for (const part of pathParts) {
            if (!node.children[part]) {
                node.children[part] = new this.Node();
            }
            node = node.children[part];
        }

        node.isFile = true;
        node.content += content;
    }

    readContentFromFile(filePath) {
        let node = this.root;
        const pathParts = this.splitPath(filePath);

        for (const part of pathParts) {
            node = node.children[part];
        }

        return node.content;
    }

    splitPath(path) {
        return path.split('/').filter(part => part);
    }

    Node() {
        this.isFile = false;
        this.content = '';
        this.children = {};
    }
}

