#include <algorithm>
#include <string>
#include <sstream>
using namespace std;

int gcd(int a, int b) {
    return b == 0 ? a : gcd(b, a % b);
}

string fractionAddition(string expression) {
    stringstream ss(expression);
    int num, den, A = 0, B = 1;
    char ch;

    while (ss >> num >> ch >> den) {
        A = A * den + B * num;
        B *= den;
        int GCD = gcd(abs(A), abs(B));
        A /= GCD;
        B /= GCD;
    }

    return to_string(A) + "/" + to_string(B);
}

