class StringIterator {
    constructor(compressedString) {
        this.s = compressedString;
        this.i = 0;
        this.count = 0;
        this.ch = ' ';
    }

    next() {
        if (!this.hasNext()) {
            return ' ';
        }
        if (this.count === 0) {
            this.ch = this.s[this.i++];
            while (this.i < this.s.length && !isNaN(this.s[this.i])) {
                this.count = this.count * 10 + parseInt(this.s[this.i++]);
            }
        }
        this.count--;
        return this.ch;
    }

    hasNext() {
        return this.i < this.s.length || this.count !== 0;
    }
}

