class TreeNode:
    def __init__(self, x):
        self.val = x
        self.left = None
        self.right = None

def tree2str(t):
    if not t:
        return ""
    if not t.left and not t.right:
        return str(t.val)
    if not t.right:
        return "{}({})".format(t.val, tree2str(t.left))
    return "{}({})({})".format(t.val, tree2str(t.left), tree2str(t.right))

