import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;

public List<List<String>> findDuplicate(String[] paths) {
    HashMap<String, List<String>> contentMap = new HashMap<>();
    for (String path : paths) {
        String[] parts = path.split(" ");
        String directory = parts[0];
        for (int i = 1; i < parts.length; i++) {
            int start = parts[i].indexOf('(');
            int end = parts[i].indexOf(')');
            String content = parts[i].substring(start + 1, end);
            String filePath = directory + "/" + parts[i].substring(0, start);
            contentMap.computeIfAbsent(content, k -> new ArrayList<>()).add(filePath);
        }
    }
    List<List<String>> result = new ArrayList<>();
    for (List<String> filePaths : contentMap.values()) {
        if (filePaths.size() > 1) {
            result.add(filePaths);
        }
    }
    return result;
}

cpp_code:
#include <vector>
#include <string>
#include <unordered_map>
#include <sstream>

std::vector<std::vector<std::string>> findDuplicate(std::vector<std::string>& paths) {
    std::unordered_map<std::string, std::vector<std::string>> content_map;
    for (const std::string &path : paths) {
        std::istringstream iss(path);
        std::string directory;
        iss >> directory;
        std::string file;
        while (iss >> file) {
            size_t start = file.find('(');
            size_t end = file.find(')');
            std::string content = file.substr(start + 1, end - start - 1);
            std::string file_path = directory + "/" + file.substr(0, start);
            content_map[content].push_back(file_path);
        }
    }
    std::vector<std::vector<std::string>> result;
    for (const auto &entry : content_map) {
        if (entry.second.size() > 1) {
            result.push_back(entry.second);
        }
    }
    return result;
}

javascript_code:
function findDuplicate(paths) {
    const contentMap = new Map();

    for (const path of paths) {
        const parts = path.split(' ');
        const directory = parts[0];
        for (let i = 1; i < parts.length; i++) {
            const start = parts[i].indexOf('(');
            const end = parts[i].indexOf(')');
            const content = parts[i].substring(start + 1, end);
            const filePath = directory + '/' + parts[i].substring(0, start);

            if (!contentMap.has(content)) {
                contentMap.set(content, []);
            }
            contentMap.get(content).push(filePath);
        }
    }
    const result = [];
    for (const filePaths of contentMap.values()) {
        if (filePaths.length > 1) {
            result.push(filePaths);
        }
    }
    return result;
}

