#include <string>
#include <vector>

std::string addBoldTag(std::string s, std::vector<std::string>& words) {
    int n = s.size();
    std::vector<bool> marked(n, false);
    for (const auto& word : words) {
        int pos = s.find(word, 0);
        while (pos != std::string::npos) {
            std::fill(marked.begin() + pos, marked.begin() + pos + word.size(), true);
            pos = s.find(word, pos + 1);
        }
    }
    std::string result;
    for (int i = 0; i < n; ++i) {
        if (marked[i] && (i == 0 || !marked[i - 1])) {
            result += "<b>";
        }
        result += s[i];
        if (marked[i] && (i == n - 1 || !marked[i + 1])) {
            result += "</b>";
        }
    }
    return result;
}

python_code:
def addBoldTag(s: str, words: list) -> str:
    n = len(s)
    marked = [False] * n
    for word in words:
        pos = s.find(word)
        while pos != -1:
            for i in range(pos, pos + len(word)):
                marked[i] = True
            pos = s.find(word, pos + 1)
    result = []
    i = 0
    while i < n:
        if marked[i]:
            result.append("<b>")
            while i < n and marked[i]:
                result.append(s[i])
                i += 1
            result.append("</b>")
        else:
            result.append(s[i])
            i += 1
    return "".join(result)

