import java.util.HashMap;
import java.util.PriorityQueue;

public int leastInterval(char[] tasks, int n) {
    HashMap<Character, Integer> taskFreq = new HashMap<>();
    for (char task : tasks) {
        taskFreq.put(task, taskFreq.getOrDefault(task, 0) + 1);
    }

    PriorityQueue<Integer> maxHeap = new PriorityQueue<>((a, b) -> b - a);
    maxHeap.addAll(taskFreq.values());

    int cycles = 0;

    while (!maxHeap.isEmpty()) {
        List<Integer> temp = new ArrayList<>();
        for (int i = 0; i < n + 1; i++) {
            if (!maxHeap.isEmpty()) {
                temp.add(maxHeap.remove());
            }
        }

        for (int freq : temp) {
            if (--freq > 0) {
                maxHeap.add(freq);
            }
        }

        cycles += maxHeap.isEmpty() ? temp.size() : n + 1;
    }

    return cycles;
}

cpp_code:
#include <vector>
#include <algorithm>
#include <unordered_map>

int leastInterval(std::vector<char>& tasks, int n) {
    std::unordered_map<char, int> task_freq;
    for (char task : tasks) {
        task_freq[task]++;
    }

    std::vector<int> frequencies;
    for (auto entry : task_freq) {
        frequencies.push_back(entry.second);
    }

    std::sort(frequencies.rbegin(), frequencies.rend());

    int max_f = frequencies[0] - 1;
    int idle_slots = max_f * n;

    for (int i = 1; i < frequencies.size(); i++) {
        idle_slots -= std::min(frequencies[i], max_f);
    }

    return idle_slots > 0 ? idle_slots + tasks.size() : tasks.size();
}

python_code:
from collections import Counter

def least_interval(tasks, n):
    task_freq = Counter(tasks)

    max_f = max(task_freq.values())
    max_count = sum(1 for count in task_freq.values() if count == max_f)

    return max(len(tasks), (max_f - 1) * (n + 1) + max_count)

javascript_code:
function leastInterval(tasks, n) {
    const taskFreq = {};
    tasks.forEach(task => {
        taskFreq[task] = (taskFreq[task] || 0) + 1;
    });

    const frequencies = Object.values(taskFreq).sort((a, b) => b - a);

    const maxF = frequencies[0] - 1;
    let idleSlots = maxF * n;

    for (let i = 1; i < frequencies.length; i++) {
        idleSlots -= Math.min(frequencies[i], maxF);
    }

    return idleSlots > 0 ? idleSlots + tasks.length : tasks.length;
}

