python_code:
class MyCircularQueue:

    def __init__(self, k: int):
        self.size = k
        self.data = [0]*k
        self.front = -1
        self.rear = -1

    def enQueue(self, value: int) -> bool:
        if self.isFull():
            return False
        if self.isEmpty():
            self.front = 0
        self.rear = (self.rear + 1) % self.size
        self.data[self.rear] = value
        return True

    def deQueue(self) -> bool:
        if self.isEmpty():
            return False
        if self.front == self.rear:
            self.front = -1
            self.rear = -1
        else:
            self.front = (self.front + 1) % self.size
        return True

    def Front(self) -> int:
        if self.isEmpty():
            return -1
        return self.data[self.front]

    def Rear(self) -> int:
        if self.isEmpty():
            return -1
        return self.data[self.rear]

    def isEmpty(self) -> bool:
        return self.front == -1

    def isFull(self) -> bool:
        return (self.rear + 1) % self.size == self.front

javascript_code:
class MyCircularQueue {
    constructor(k) {
        this.size = k;
        this.data = new Array(k);
        this.front = -1;
        this.rear = -1;
    }

    enQueue(value) {
        if (this.isFull()) return false;
        if (this.isEmpty()) this.front = 0;
        this.rear = (this.rear + 1) % this.size;
        this.data[this.rear] = value;
        return true;
    }

    deQueue() {
        if (this.isEmpty()) return false;
        if (this.front === this.rear) {
            this.front = -1;
            this.rear = -1;
        } else {
            this.front = (this.front + 1) % this.size;
        }
        return true;
    }

    Front() {
        if (this.isEmpty()) return -1;
        return this.data[this.front];
    }

    Rear() {
        if (this.isEmpty()) return -1;
        return this.data[this.rear];
    }

    isEmpty() {
        return this.front === -1;
    }

    isFull() {
        return (this.rear + 1) % this.size === this.front;
    }
}

java_code:
public void addOneRowHelper(TreeNode node, int val, int depth, int currentDepth) {
    if (node == null) return;
    if (currentDepth == depth - 1) {
        TreeNode left = node.left;
        TreeNode right = node.right;
        node.left = new TreeNode(val);
        node.left.left = left;
        node.right = new TreeNode(val);
        node.right.right = right;
    } else {
        addOneRowHelper(node.left, val, depth, currentDepth + 1);
        addOneRowHelper(node.right, val, depth, currentDepth + 1);
    }
}

public TreeNode addOneRow(TreeNode root, int val, int depth) {
    if (depth == 1) {
        TreeNode newRoot = new TreeNode(val);
        newRoot.left = root;
        return newRoot;
    }
    addOneRowHelper(root, val, depth, 1);
    return root;
}

