    let result = 0, factor = 1;
    for (let i = 9; i > 1; --i) {
        while (num % i === 0) {
            num /= i;
            result += i * factor;
            factor *= 10;
            if (result > (2**31 - 1)) return 0;
        }
    }
    return num === 1 ? result : 0;
}

