}

class PriorityQueue {
    constructor(comparator) {
        this.data = [];
        this.comparator = comparator;
    }

    push(item) {
        this.data.push(item);
        this.data.sort(this.comparator);
    }

    pop() {
        return this.data.shift();
    }

    size() {
        return this.data.length;
    }
}

content:
Design the basic function of **Excel** and implement the function of the sum formula.

Implement the `Excel` class:

*   `Excel(int height, char width)` Initializes the object with the `height` and the `width` of the sheet. The sheet is an integer matrix `mat` of size `height x width` with the row index in the range `[1, height]` and the column index in the range `['A', width]`. All the values should be **zero** initially.
*   `void set(int row, char column, int val)` Changes the value at `mat[row][column]` to be `val`.
*   `int get(int row, char column)` Returns the value at `mat[row][column]`.
*   `int sum(int row, char column, List numbers)` Sets the value at `mat[row][column]` to be the sum of cells represented by `numbers` and returns the value at `mat[row][column]`. This sum formula **should exist** until this cell is overlapped by another value or another sum formula. `numbers[i]` could be on the format:
    *   `"ColRow "` that represents a single cell.
        *   For example, `"F7 "` represents the cell `mat[7]['F']`.
    *   `"ColRow1:ColRow2 "` that represents a range of cells. The range will always be a rectangle where `"ColRow1 "` represent the position of the top-left cell, and `"ColRow2 "` represents the position of the bottom-right cell.
        *   For example, `"B3:F7 "` represents the cells `mat[i][j]` for `3 <= i <= 7` and `'B' <= j <= 'F'`.

**Note:** You could assume that there will not be any circular sum reference.

*   For example, `mat[1]['A'] == sum(1, "B ")` and `mat[1]['B'] == sum(1, "A ")`.

**Example 1:**

**Input**
\[ "Excel ",  "set ",  "sum ",  "set ",  "get "\]
\[\[3,  "C "\], \[1,  "A ", 2\], \[3,  "C ", \[ "A1 ",  "A1:B2 "\]\], \[2,  "B ", 2\], \[3,  "C "\]\]
**Output**
\[null, null, 4, null, 6\]

**Explanation**
Excel excel = new Excel(3,  "C ");
 // construct a 3\*3 2D array with all zero.
 //   A B C
 // 1 0 0 0
 // 2 0 0 0
 // 3 0 0 0
excel.set(1,  "A ", 2);
 // set mat\[1\]\[ "A "\] to be 2.
 //   A B C
 // 1 2 0 0
 // 2 0 0 0
 // 3 0 0 0
excel.sum(3,  "C ", \[ "A1 ",  "A1:B2 "\]); // return 4
 // set mat\[3\]\[ "C "\] to be the sum of value at mat\[1\]\[ "A "\] and the values sum of the rectangle range whose top-left cell is mat\[1\]\[ "A "\] and bottom-right cell is mat\[2\]\[ "B "\].
 //   A B C
 // 1 2 0 0
 // 2 0 0 0
 // 3 0 0 4
excel.set(2,  "B ", 2);
 // set mat\[2\]\[ "B "\] to be 2. Note mat\[3\]\[ "C "\] should also be changed.
 //   A B C
 // 1 2 0 0
 // 2 0 2 0
 // 3 0 0 6
excel.get(3,  "C "); // return 6

**Constraints:**

*   `1 <= height <= 26`
*   `'A' <= width <= 'Z'`
*   `1 <= row <= height`
*   `'A' <= column <= width`
*   `-100 <= val <= 100`
*   `1 <= numbers.length <= 5`
*   `numbers[i]` has the format `"ColRow "` or `"ColRow1:ColRow2 "`.
*   At most `100` calls will be made to `set`, `get`, and `sum`.

java_code:
import java.util.*;

class Excel {

    int[][] mat;
    Map<String, List<String>> formulas;

    public Excel(int height, char width) {
        mat = new int[height][width - 'A' + 1];
        formulas = new HashMap<>();
    }

    public void set(int row, char column, int val) {
        String pos = String.format("%c%d", column, row);
        formulas.remove(pos);
        mat[row - 1][column - 'A'] = val;
    }

    public int get(int row, char column) {
        String pos = String.format("%c%d", column, row);
        if (formulas.containsKey(pos)) {
            return sum(row, column, formulas.get(pos));
        }
        return mat[row - 1][column - 'A'];
    }

    public int sum(int row, char column, List<String> numbers) {
        int total = 0;
        for (String num : numbers) {
            if (num.contains(":")) {
                String[] parts = num.split(":");
                int startRow = Integer.parseInt(parts[0].substring(1));
                int endRow = Integer.parseInt(parts[1].substring(1));
                char startCol = parts[0].charAt(0);
                char endCol = parts[1].charAt(0);
                for (int r = startRow; r <= endRow; r++) {
                    for (char c = startCol; c <= endCol; c++) {
                        total += get(r, c);
                    }
                }
            } else {
                total += get(Integer.parseInt(num.substring(1)), num.charAt(0));
            }
        }
        set(row, column, total);
        formulas.put(String.format("%c%d", column, row), numbers);
        return total;
    }
}

cpp_code:
#include <vector>
#include <string>
#include <unordered_map>

using namespace std;

class Excel {
public:
    vector<vector<int>> mat;
    unordered_map<string, pair<string, vector<string>>> formulas;

    Excel(int height, char width) {
        mat.resize(height, vector<int>(width - 'A' + 1));
    }

    void set(int row, char column, int val) {
        row--; column -= 'A';
        string pos = string(1, column + 'A') + to_string(row + 1);
        formulas.erase(pos);
        mat[row][column] = val;
    }

    int get(int row, char column) {
        row--; column -= 'A';
        string pos = string(1, column + 'A') + to_string(row + 1);
        if (formulas.count(pos)) {
            int sum = 0;
            for (string &r : formulas[pos].second) {
                auto x = r.find(':');
                if (x == string::npos) {
                    int rRow = stoi(r.substr(1)) - 1;
                    int rCol = r[0] - 'A';
                    sum += get(rRow + 1, rCol + 'A');
                } else {
                    int r1Row = stoi(r.substr(1, x - 1)) - 1;
                    int r1Col = r[0] - 'A';
                    int r2Row = stoi(r.substr(x + 2)) - 1;
                    int r2Col = r[x + 1] - 'A';
                    for (int i = r1Row; i <= r2Row; ++i)
                        for (int j = r1Col; j <= r2Col; ++j)
                            sum += get(i + 1, j + 'A');
                }
            }
            return sum;
        }
        return mat[row][column];
    }

    int sum(int row, char column, vector<string> numbers) {
        int total = 0;
        string pos = string(1, column) + to_string(row);
        for (auto &num : numbers) total += get(stoi(num.substr(1)), num[0]);
        formulas[pos] = make_pair(pos, numbers);
        set(row, column, total);
        return total;
    }
};

