class Excel {
    constructor(height, width) {
        this.mat = new Array(height).fill(null).map(() => new Array(width.charCodeAt(0)-'A'.charCodeAt(0)+1).fill(0));
        this.formulas = {};
    }

    set(row, column, val) {
        let pos = column + row.toString();
        delete this.formulas[pos];
        this.mat[row - 1][column.charCodeAt(0) - 'A'.charCodeAt(0)] = val;
    }

    get(row, column) {
        let pos = column + row.toString();
        if (pos in this.formulas) {
            return this.sum(row, column, this.formulas[pos]);
        }
        return this.mat[row - 1][column.charCodeAt(0) - 'A'.charCodeAt(0)];
    }

    sum(row, column, numbers) {
        let total = 0;
        for (let num of numbers) {
            if (num.includes(':')) {
                let parts = num.split(':');
                let startRow = parseInt(parts[0].substring(1));
                let endRow = parseInt(parts[1].substring(1));
                let startCol = parts[0].charAt(0);
                let endCol = parts[1].charAt(0);
                for (let r = startRow; r <= endRow; r++) {
                    for (let c = startCol.charCodeAt(0); c <= endCol.charCodeAt(0); c++) {
                        total += this.get(r, String.fromCharCode(c));
                    }
                }
            } else {
                total += this.get(parseInt(num.substring(1)), num.charAt(0));
            }
        }
        this.set(row, column, total);
        this.formulas[column + row.toString()] = numbers;
        return total;
    }
}

java_code:
import java.util.PriorityQueue;
import java.util.List;
import java.util.ArrayList;
import java.util.Comparator;

public int[] smallestRange(List<List<Integer>> nums) {
    PriorityQueue<int[]> minHeap = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));

    int maxVal = Integer.MIN_VALUE;
    for (int i = 0; i < nums.size(); i++) {
        minHeap.offer(new int[] {nums.get(i).get(0), i});
        maxVal = Math.max(maxVal, nums.get(i).get(0));
    }

    List<Integer> listIndices = new ArrayList<>();
    for (int i = 0; i < nums.size(); i++) {
        listIndices.add(0);
    }
    int minRange = Integer.MAX_VALUE;
    int start = -1, end = -1;

    while (minHeap.size() == nums.size()) {
        int[] entry = minHeap.poll();
        int val = entry[0];
        int listIdx = entry[1];
        int range = maxVal - val;

        if (range < minRange) {
            minRange = range;
            start = val;
            end = maxVal;
        }

        listIndices.set(listIdx, listIndices.get(listIdx) + 1);
        if (listIndices.get(listIdx) < nums.get(listIdx).size()) {
            int newVal = nums.get(listIdx).get(listIndices.get(listIdx));
            minHeap.offer(new int[] {newVal, listIdx});
            maxVal = Math.max(maxVal, newVal);
        }
    }

    return new int[] {start, end};
}

cpp_code:
#include <vector>
#include <queue>
#include <limits>
#include <utility>

std::pair<int, int> smallestRange(std::vector<std::vector<int>>& nums) {
    auto listComparator = [](const auto& a, const auto& b) {
        return a.first > b.first;
    };

    std::priority_queue<std::pair<int, int>, std::vector<std::pair<int, int>>, decltype(listComparator)> minHeap(listComparator);

    int maxVal = std::numeric_limits<int>::min();
    for (int i = 0; i < nums.size(); i++) {
        minHeap.push({nums[i][0], i});
        maxVal = std::max(maxVal, nums[i][0]);
    }

    std::vector<int> listIndices(nums.size(), 0);
    int minRange = std::numeric_limits<int>::max();
    int start = -1, end = -1;

    while (minHeap.size() == nums.size()) {
        auto entry = minHeap.top();
        minHeap.pop();
        int val = entry.first;
        int listIdx = entry.second;
        int range = maxVal - val;

        if (range < minRange) {
            minRange = range;
            start = val;
            end = maxVal;
        }

        listIndices[listIdx]++;
        if (listIndices[listIdx] < nums[listIdx].size()) {
            int newVal = nums[listIdx][listIndices[listIdx]];
            minHeap.push({newVal, listIdx});
            maxVal = std::max(maxVal, newVal);
        }
    }

    return {start, end};
}

