        }

        listIndices[listIdx]++;
        if (listIndices[listIdx] < nums[listIdx].length) {
            const newVal = nums[listIdx][listIndices[listIdx]];
            minHeap.push([newVal, listIdx]);
            minHeap.sort(([a], [b]) => a - b);
            maxVal = Math.max(maxVal, newVal);
        }
    }

    return [start, end];
}

