content:
You are given several logs, where each log contains a unique ID and timestamp. Timestamp is a string that has the following format: `Year:Month:Day:Hour:Minute:Second`, for example, `2017:01:01:23:59:59`. All domains are zero-padded decimal numbers.

Implement the `LogSystem` class:

*   `LogSystem()` Initializes the `LogSystem` object.
*   `void put(int id, string timestamp)` Stores the given log `(id, timestamp)` in your storage system.
*   `int[] retrieve(string start, string end, string granularity)` Returns the IDs of the logs whose timestamps are within the range from `start` to `end` inclusive. `start` and `end` all have the same format as `timestamp`, and `granularity` means how precise the range should be (i.e. to the exact `Day`, `Minute`, etc.). For example, `start = "2017:01:01:23:59:59 "`, `end = "2017:01:02:23:59:59 "`, and `granularity = "Day "` means that we need to find the logs within the inclusive range from **Jan. 1st 2017** to **Jan. 2nd 2017**, and the `Hour`, `Minute`, and `Second` for each log entry can be ignored.

**Example 1:**

**Input**
\[ "LogSystem ",  "put ",  "put ",  "put ",  "retrieve ",  "retrieve "\]
\[\[\], \[1,  "2017:01:01:23:59:59 "\], \[2,  "2017:01:01:22:59:59 "\], \[3,  "2016:01:01:00:00:00 "\], \[ "2016:01:01:01:01:01 ",  "2017:01:01:23:00:00 ",  "Year "\], \[ "2016:01:01:01:01:01 ",  "2017:01:01:23:00:00 ",  "Hour "\]\]
**Output**
\[null, null, null, null, \[3, 2, 1\], \[2, 1\]\]

**Explanation**
LogSystem logSystem = new LogSystem();
logSystem.put(1,  "2017:01:01:23:59:59 ");
logSystem.put(2,  "2017:01:01:22:59:59 ");
logSystem.put(3,  "2016:01:01:00:00:00 ");

// return \[3,2,1\], because you need to return all logs between 2016 and 2017.
logSystem.retrieve( "2016:01:01:01:01:01 ",  "2017:01:01:23:00:00 ",  "Year ");

// return \[2,1\], because you need to return all logs between Jan. 1, 2016 01:XX:XX and Jan. 1, 2017 23:XX:XX.
// Log 3 is not returned because Jan. 1, 2016 00:00:00 comes before the start of the range.
logSystem.retrieve( "2016:01:01:01:01:01 ",  "2017:01:01:23:00:00 ",  "Hour ");

**Constraints:**

*   `1 <= id <= 500`
*   `2000 <= Year <= 2017`
*   `1 <= Month <= 12`
*   `1 <= Day <= 31`
*   `0 <= Hour <= 23`
*   `0 <= Minute, Second <= 59`
*   `granularity` is one of the values `[ "Year ", "Month ", "Day ", "Hour ", "Minute ", "Second "]`.
*   At most `500` calls will be made to `put` and `retrieve`.

java_code:
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

class LogSystem {
    Map<String, Integer> logs;
    Map<String, Integer> timeGranularity;

    public LogSystem() {
        logs = new HashMap<>();
        timeGranularity = new HashMap<>();
        String[] granularities = {"Year", "Month", "Day", "Hour", "Minute", "Second"};
        for (int i = 0; i < granularities.length; i++) {
            timeGranularity.put(granularities[i], i);
        }
    }

    public void put(int id, String timestamp) {
        logs.put(timestamp, id);
    }

    public List<Integer> retrieve(String start, String end, String granularity) {
        List<Integer> res = new ArrayList<>();
        int sizeSubstring = new int[]{4, 7, 10, 13, 16, 19}[timeGranularity.get(granularity)];

        for (Map.Entry<String, Integer> entry : logs.entrySet()) {
            String key = entry.getKey();
            if (start.substring(0, sizeSubstring).compareTo(key.substring(0, sizeSubstring)) <= 0
                    && end.substring(0, sizeSubstring).compareTo(key.substring(0, sizeSubstring)) >= 0) {
                res.add(entry.getValue());
            }
        }
        return res;
    }
}

cpp_code:
#include <vector>
#include <string>
#include <map>

class LogSystem {
public:
    LogSystem() {
    }

    void put(int id, std::string timestamp) {
        logs[timestamp] = id;
    }

    std::vector<int> retrieve(std::string start, std::string end, std::string granularity) {
        std::vector<int> res;
        std::string min_timestamp, max_timestamp;
        int size_map[] = {4, 7, 10, 13, 16, 19};
        std::map<std::string, int> time_granularity = {{"Year", 0}, {"Month", 1}, {"Day", 2}, {"Hour", 3}, {"Minute", 4}, {"Second", 5}};
        int size_substring = size_map[time_granularity[granularity]];

        min_timestamp = start.substr(0, size_substring);
        max_timestamp = end.substr(0, size_substring);

        for (const auto &x : logs) {
            if (min_timestamp <= x.first.substr(0, size_substring) && max_timestamp >= x.first.substr(0, size_substring)) {
                res.push_back(x.second);
            }
        }
        return res;
    }

private:
    std::map<std::string, int> logs;
};

