java_code:
import java.util.List;
import java.util.Stack;

public int[] exclusiveTime(int n, List<String> logs) {
    int[] res = new int[n];
    Stack<Integer> stack = new Stack<>();
    int prevTime = 0;

    for (String log : logs) {
        String[] parts = log.split(":");
        int id = Integer.parseInt(parts[0]);
        String type = parts[1];
        int time = Integer.parseInt(parts[2]);

        if (type.equals("start")) {
            if (!stack.isEmpty()) {
                res[stack.peek()] += time - prevTime;
            }
            stack.push(id);
            prevTime = time;
        } else {
            res[stack.pop()] += time - prevTime + 1;
            prevTime = time + 1;
        }
    }

    return res;
}

cpp_code:
#include <vector>
#include <string>
#include <stack>

std::vector<int> exclusiveTime(int n, std::vector<std::string>& logs) {
    std::vector<int> res(n, 0);
    std::stack<int> s;
    int prev_time = 0;

    for (const auto& log : logs) {
        auto colon1 = log.find(':');
        auto colon2 = log.rfind(':');

        int id = std::stoi(log.substr(0, colon1));
        std::string type = log.substr(colon1 + 1, colon2 - colon1 - 1);
        int time = std::stoi(log.substr(colon2 + 1));

        if (type == "start") {
            if (!s.empty()) {
                res[s.top()] += time - prev_time;
            }
            s.push(id);
            prev_time = time;
        } else {
            res[s.top()] += time - prev_time + 1;
            s.pop();
            prev_time = time + 1;
        }
    }

    return res;
}

