};

vector<double> averageOfLevels(TreeNode* root) {
    vector<double> result;
    queue<TreeNode*> q;
    q.push(root);

    while (!q.empty()) {
        long long sum = 0;
        int count = 0;
        queue<TreeNode*> temp;
        while (!q.empty()) {
            TreeNode* n = q.front();
            q.pop();
            sum += n->val;
            count++;
            if (n->left) temp.push(n->left);
            if (n->right) temp.push(n->right);
        }
        q = temp;
        result.push_back(static_cast<double>(sum) / count);
    }

    return result;
}

