#include <string>
#include <sstream>
using namespace std;

string solveEquation(string equation) {
    int coef = 0, val = 0, left = 1, operate = 1;
    istringstream in(equation + "+");
    char op;
    int n;
    string s;
    while (in >> op) {
        if (op == '=') {
            left = -1;
            operate = 1;
        } else {
            in >> n >> s;
            (s.size() == 0 ? val : coef) += (op == '+' ? 1 : -1) * left * operate * n;
            operate = s.size();
        }
    }

    if (coef == 0) {
        return val == 0 ? "Infinite solutions" : "No solution";
    } else {
        return "x=" + to_string(-val / coef);
    }
}

python_code:
def solve_equation(equation: str) -> str:
    coef = val = left = operate = 0
    equation += '+'
    parts = [s.strip()+c for c in equation if c in '+-' for s in equation.split(c)]
    for part in parts:
        if part == '=':
            left = -1
            operate = 1
        else:
            n, x = part.split('x')
            value_to_change = 1 if n else int(n)
            if x:
                coef += (1 if part[0] == '+' else -1) * left * operate * value_to_change
            else:
                val += (1 if part[0] == '+' else -1) * left * operate * value_to_change
            operate = 1 - x.find('x')

    if coef == 0:
        return "Infinite solutions" if val == 0 else "No solution"
    return "x=" + str(-val // coef)

javascript_code:
function solveEquation(equation) {
    let coef = 0, val = 0, left = 1, operate = 1;
    let parts = equation.replace(/([+-])/g, ' $1').split('=');
    let leftPart = parts[0].split(' ');
    let rightPart = parts[1].split(' ');

    for (let part of leftPart.concat(rightPart)) {
        if (part === '+') {
            operate = 1;
        } else if (part === '-') {
            operate = -1;
        } else if (part.includes('x')) {
            coef += parseInt(part.replace('x', '') || '1', 10) * operate * left;
        } else {
            val += parseInt(part, 10) * operate * left;
        }
    }

    if (coef === 0) {
        return val === 0 ? "Infinite solutions" : "No solution";
    } else {
        return "x=" + (-val / coef).toString();
    }
}

