#include <vector>
#include <string>
#include <unordered_map>
#include <queue>

class AutocompleteSystem {
    struct TrieNode {
        std::unordered_map<char, TrieNode*> children;
        std::string sentence;
        int times;
        TrieNode() : times(0) {}
    };

    void insert(const std::string &sentence, int times) {
        TrieNode *curr = root;
        for (char c : sentence) {
            if (!curr->children[c]) {
                curr->children[c] = new TrieNode();
            }
            curr = curr->children[c];
        }
        curr->times += times;
        curr->sentence = sentence;
    }

    struct cmp {
        bool operator()(const TrieNode* a, const TrieNode* b) const {
            if (a->times == b->times) {
                return a->sentence > b->sentence;
            }
            return a->times < b->times;
        }
    };

    TrieNode *root;
    TrieNode *current;
    std::string search;

public:
    AutocompleteSystem(std::vector<std::string>& sentences, std::vector<int>& times) {
        root = new TrieNode();
        for (int i = 0; i < sentences.size(); ++i) {
            insert(sentences[i], times[i]);
        }
        current = root;
    }

    std::vector<std::string> input(char c) {
        if (c == '#') {
            insert(search, 1);
            search = "";
            current = root;
            return {};
        }
        search += c;
        if (!current) {
            return {};
        }
        current = current->children[c];
        if (!current) {
            return {};
        }
        std::priority_queue<TrieNode*, std::vector<TrieNode*>, cmp> pq;
        for (auto &[char_, node] : current->children) {
            if (node->times) {
                pq.push(node);
            }
        }

        std::vector<std::string> res;
        while (!pq.empty() && res.size() < 3) {
            res.push_back(pq.top()->sentence);
            pq.pop();
        }
        return res;
    }
};

