import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode(int x) { val = x; }
}

public List<TreeNode> findDuplicateSubtrees(TreeNode root) {
    Map<String, Integer> treeCount = new HashMap<>();
    List<TreeNode> result = new ArrayList<>();
    findDuplicateSubtreesHelper(root, treeCount, result);
    return result;
}

private String findDuplicateSubtreesHelper(TreeNode root, Map<String, Integer> treeCount, List<TreeNode> result) {
    if (root == null) return "";
    String subtree = root.val + "," + findDuplicateSubtreesHelper(root.left, treeCount, result) + "," + findDuplicateSubtreesHelper(root.right, treeCount, result);
    treeCount.put(subtree, treeCount.getOrDefault(subtree, 0) + 1);
    if (treeCount.get(subtree) == 2) {
        result.add(root);
    }
    return subtree;
}

