    queue<TreeNode*> q;
    q.push(root);
    while (!q.empty()) {
        int size = q.size();
        depth++;
        for (int i = 0; i < size; i++) {
            TreeNode* node = q.front(); q.pop();
            if (node->left) q.push(node->left);
            if (node->right) q.push(node->right);
        }
    }

    // Initialize matrix
    vector<vector<string>> res(depth, vector<string>((1 << depth) - 1, ""));

    // Fill in matrix
    q.push(root);
    int level = 0;
    int step = (1 << (depth - 1));
    while (!q.empty()) {
        int size = q.size();
        int curPos = step - 1;
        for (int i = 0; i < size; i++) {
            TreeNode* node = q.front(); q.pop();
            res[level][curPos] = to_string(node->val);
            curPos += (step << 1);
            if (node->left) q.push(node->left);
            if (node->right) q.push(node->right);
        }
        step >>= 1;
        level++;
    }

    return res;
}

