#include <vector>
#include <queue>
#include <utility>
using namespace std;

vector<int> cheapestJump(vector<int>& coins, int maxJump) {
    int n = coins.size();
    vector<int> dp(n, 1e9), parent(n, -1);
    dp[0] = coins[0];
    for (int i = 0; i < n; ++i) {
        if (coins[i] == -1) continue;
        for (int j = 1; j <= maxJump && i + j < n; ++j) {
            int next = i + j;
            int cost = coins[next] + dp[i];
            if (cost < dp[next]) {
                dp[next] = cost;
                parent[next] = i;
            }
        }
    }
    vector<int> ans;
    if (dp[n - 1] == 1e9) return ans;
    int cur = n - 1;
    while (cur != -1) {
        ans.push_back(cur + 1);
        cur = parent[cur];
    }
    reverse(ans.begin(), ans.end());
    return ans;
}

