#include <queue>
#include <utility>

int widthOfBinaryTree(TreeNode* root) {
    if (!root) return 0;
    int maxWidth = 0;
    std::queue<std::pair<TreeNode*, int>> q;
    q.push(std::make_pair(root, 1));

    while (!q.empty()) {
        int levelSize = q.size();
        int left = q.front().second;
        int right = left;
        for (int i = 0; i < levelSize; i++) {
            TreeNode* node = q.front().first;
            right = q.front().second;
            q.pop();

            if (node->left) {
                q.push(std::make_pair(node->left, 2 * right));
            }
            if (node->right) {
                q.push(std::make_pair(node->right, 2 * right + 1));
            }
        }
        maxWidth = std::max(maxWidth, right - left + 1);
    }
    return maxWidth;
}

python_code:
from collections import deque

def widthOfBinaryTree(root):
    if not root:
        return 0

    maxWidth = 0
    q = deque([(root, 1)])

    while q:
        levelSize = len(q)
        left, _ = q[0]
        right = left
        for _ in range(levelSize):
            node, pos = q.popleft()
            right = pos

            if node.left:
                q.append((node.left, 2 * pos))
            if node.right:
                q.append((node.right, 2 * pos + 1))

        maxWidth = max(maxWidth, right - left + 1)

    return maxWidth

