};

class Solution {
public:
    bool checkEqualTree(TreeNode* root) {
        unordered_set<int> seen;
        int total = sum(root, seen);
        if(total % 2 == 0) {
            seen.erase(total);
            return seen.count(total / 2);
        }
        return false;
    }
    int sum(TreeNode* node, unordered_set<int>& seen) {
        if (!node) return 0;
        int s = node->val + sum(node->left, seen) + sum(node->right, seen);
        seen.insert(s);
        return s;
    }
};

