public int findLengthOfLCIS(int[] nums) {
    if (nums.length == 0) return 0;
    int result = 1, current = 1;
    for (int i = 1; i < nums.length; ++i) {
        current = nums[i] > nums[i - 1] ? current + 1 : 1;
        result = Math.max(result, current);
    }
    return result;
}

