from heapq import heappush, heappop
from collections import deque

def cutOffTree(forest: List[List[int]]) -> int:
    if not forest or not forest[0]: return 0
    m, n = len(forest), len(forest[0])
    trees = []

    for i in range(m):
        for j in range(n):
            if forest[i][j] > 1:
                heappush(trees, (forest[i][j], i, j))

    startX, startY = 0, 0
    totalSteps = 0
    while trees:
        tree, endX, endY = heappop(trees)
        steps = bfs(forest, startX, startY, endX, endY)
        if steps == -1:
            return -1
        totalSteps += steps
        startX, startY = endX, endY

    return totalSteps

def bfs(forest, startX, startY, endX, endY):
    if startX == endX and startY == endY:
        return 0

    m, n = len(forest), len(forest[0])
    visited = [[False] * n for _ in range(m)]
    q = deque([(startX, startY, 0)])
    visited[startX][startY] = True
    dirs = [-1, 0, 1, 0, -1]

    while q:
        x, y, steps = q.popleft()
        for k in range(4):
            newX, newY = x + dirs[k], y + dirs[k+1]
            if 0 <= newX < m and 0 <= newY < n and not visited[newX][newY] and forest[newX][newY] != 0:
                if newX == endX and newY == endY:
                    return steps + 1
                q.append((newX, newY, steps + 1))
                visited[newX][newY] = True

    return -1

javascript_code:
function cutOffTree(forest) {
    if(!forest || !forest[0]) return 0;
    let m = forest.length, n = forest[0].length;
    let trees = [];

    for(let i = 0; i < m; i++)
        for(let j = 0; j < n; j++)
            if(forest[i][j] > 1)
                trees.push([forest[i][j], i, j]);

    trees.sort((a, b) => a[0] - b[0]);

    let startX = 0, startY = 0;
    let totalSteps = 0;
    for(let tree of trees){
        let [, x, y] = tree;
        let steps = bfs(forest, startX, startY, x, y);
        if(steps === -1) return -1;
        totalSteps += steps;
        startX = x;
        startY = y;
    }

    return totalSteps;
}

function bfs(forest, startX, startY, endX, endY) {
    let m = forest.length, n = forest[0].length;
    let visited = Array.from({ length: m }, () => Array(n).fill(false));
    let q = [[startX, startY, 0]];
    visited[startX][startY] = true;
    let dirs = [-1, 0, 1, 0, -1];

    while(q.length !== 0) {
        let [x, y, steps] = q.shift();
        for(let k = 0; k < 4; k++) {
            let newX = x + dirs[k], newY = y + dirs[k+1];
            if(0 <= newX && newX < m && 0 <= newY && newY < n && !visited[newX][newY] && forest[newX][newY] !== 0) {
                if(newX === endX && newY === endY)
                    return steps + 1;
                q.push([newX, newY, steps + 1]);
                visited[newX][newY] = true;
            }
        }
    }

    return -1;
}

