        if (word_list.count(searchWord.size())) {
            for (string word : word_list[searchWord.size()]) {
                int diff = 0;
                for (int i = 0; i < searchWord.size(); i++) {
                    if (searchWord[i] != word[i]) diff++;
                }
                if (diff == 1) return true;
            }
        }
