class MagicDictionary {
    constructor() {
        this.word_list = {};
    }

    buildDict(dictionary) {
        for (let word of dictionary) {
            let length = word.length;
            if (!(length in this.word_list)) {
                this.word_list[length] = [];
            }
            this.word_list[length].push(word);
        }
    }

    search(searchWord) {
        let length = searchWord.length;
        if (length in this.word_list) {
            for (let word of this.word_list[length]) {
                let diff = 0;
                for (let i = 0; i < length; i++) {
                    if (searchWord[i] !== word[i]) diff++;
                }
                if (diff === 1) return true;
            }
        }
        return false;
    }
}

