class MapSum {
    unordered_map<string, int> map;
public:
    MapSum() {}

    void insert(string key, int val) {
        map[key] = val;
    }

    int sum(string prefix) {
        int total = 0;
        for (auto& element : map)
            if (element.first.compare(0, prefix.size(), prefix) == 0)
                total += element.second;
        return total;
    }
};

