import java.util.*;

class Solution {
    public int calPoints(String[] ops) {
        LinkedList<Integer> record = new LinkedList<>();
        for (String op : ops) {
            if (op.equals("+")) {
                record.add(record.getLast() + record.get(record.size() - 2));
            } else if (op.equals("D")) {
                record.add(record.getLast() * 2);
            } else if (op.equals("C")) {
                record.removeLast();
            } else {
                record.add(Integer.parseInt(op));
            }
        }
        return record.stream().mapToInt(Integer::intValue).sum();
    }
}

cpp_code:
#include <vector>
#include <string>

int calPoints(std::vector<std::string>& ops) {
    std::vector<int> record;
    for (const std::string& op : ops) {
        if (op == "+") {
            record.push_back(record[record.size() - 1] + record[record.size() - 2]);
        } else if (op == "D") {
            record.push_back(2 * record.back());
        } else if (op == "C") {
            record.pop_back();
        } else {
            record.push_back(stoi(op));
        }
    }
    return std::accumulate(record.begin(), record.end(), 0);
}

