        int u = edge[0], v = edge[1];
        if (parent[v] > 0) {
            candidateA = {parent[v], v};
            candidateB = edge;
        } else {
            parent[v] = u;
        }
    }

    for (int i = 1; i <= edges.size(); ++i) {
        int cycle = i, steps = edges.size();
        while (parent[cycle] != 0 && steps-- > 0) {
            cycle = parent[cycle];
        }
        if (steps == -1) {
            if (candidateA.empty()) return {parent[i], i};
            else return candidateA;
        }
    }

    return candidateB;
}

