int minRepeatsToSubstring(const std::string& a, const std::string& b) {
    int times = (b.length() + a.length() - 1) / a.length();

    for(int i = 0; i < 2; i++){
        std::string repeated_a = "";
        for(int j = 0; j < times + i; j++){
            repeated_a += a;
        }

        if(repeated_a.find(b) != std::string::npos) return times + i;
    }

    return -1;
}

