import java.util.*;

public class Solution {
    public List<String> kFrequentWords(String[] words, int k) {
        Map<String, Integer> wordCount = new HashMap<>();
        for (String word : words) {
            wordCount.put(word, wordCount.getOrDefault(word, 0) + 1);
        }

        PriorityQueue<Map.Entry<String, Integer>> pq = new PriorityQueue<>(
                (a, b) -> a.getValue() == b.getValue()
                        ? a.getKey().compareTo(b.getKey())
                        : b.getValue() - a.getValue()
        );
        pq.addAll(wordCount.entrySet());

        List<String> result = new ArrayList<>();
        for (int i = 0; i < k; i++) {
            result.add(pq.poll().getKey());
        }
        return result;
    }
}

cpp_code:
#include <vector>
#include <string>
#include <unordered_map>
#include <queue>
using namespace std;

vector<string> kFrequentWords(vector<string>& words, int k) {
    unordered_map<string, int> wordCount;
    for (const auto& word : words) {
        wordCount[word]++;
    }

    auto comp = [](const pair<string, int>& a, const pair<string, int>& b) {
        if (a.second == b.second) {
            return a.first > b.first;
        }
        return a.second < b.second;
    };
    priority_queue<pair<string, int>, vector<pair<string, int>>, decltype(comp)> pq(comp);

    for (const auto& wc : wordCount) {
        pq.push(wc);
    }

    vector<string> result;
    for (int i = 0; i < k; ++i) {
        result.push_back(pq.top().first);
        pq.pop();
    }

    return result;
}

javascript_code:
function kFrequentWords(words, k) {
    const wordCount = new Map();
    for (const word of words) {
        wordCount.set(word, (wordCount.get(word) || 0) + 1);
    }

    const pq = Array.from(wordCount.entries()).sort((a, b) => {
        if (a[1] === b[1]) {
            return a[0].localeCompare(b[0]);
        }
        return b[1] - a[1];
    });

    const result = [];
    for (let i = 0; i < k; i++) {
        result.push(pq[i][0]);
    }
    return result;
}

