        if (index < 0 || index > size) return;
        if (index == 0) {
            addAtHead(val);
        } else {
            Node* cur = head;
            for (int i = 0; i < index - 1; ++i) {
                cur = cur->next;
            }
            Node* newNode = new Node(val);
            newNode->next = cur->next;
            cur->next = newNode;
            size++;
        }
    }

    void deleteAtIndex(int index) {
        if (index < 0 || index >= size) return;
        if (index == 0) {
            Node* tmp = head;
            head = head->next;
            delete tmp;
        } else {
            Node* cur = head;
            for (int i = 0; i < index - 1; ++i) {
                cur = cur->next;
            }
            Node* tmp = cur->next;
            cur->next = tmp->next;
            delete tmp;
        }
        size--;
    }

private:
