    if (index < 0 || index >= this.size) return -1;
    let cur = this.head;
    for (let i = 0; i < index; i++) {
      cur = cur.next;
    }
    return cur.val;
  }

  addAtHead(val) {
    this.head = new Node(val, this.head);
    this.size++;
