      this.addAtHead(val);
    } else {
      let cur = this.head;
      while (cur.next) {
        cur = cur.next;
      }
      cur.next = new Node(val);
      this.size++;
    }
  }

  addAtIndex(index, val) {
    if (index < 0 || index > this.size) return;
    if (index === 0) {
      this.addAtHead(val);
    } else {
      let cur = this.head;
      for (let i = 0; i < index - 1; i++) {
        cur = cur.next;
      }
      cur.next = new Node(val, cur.next);
      this.size++;
    }
  }

  deleteAtIndex(index) {
    if (index < 0 || index >= this.size) return;
    if (index === 0) {
      this.head = this.head.next;
