        if (r >= 0 && c >= 0 && r < grid.size() && c < grid[r].size() && grid[r][c] == 1) {
            grid[r][c] = 0;
            island.push_back({r - r0, c - c0});
            dfs(r + 1, c, r0, c0, grid, island);
            dfs(r - 1, c, r0, c0, grid, island);
            dfs(r, c + 1, r0, c0, grid, island);
            dfs(r, c - 1, r0, c0, grid, island);
        }
    }

    std::vector<std::pair<int, int>> normalize(std::vector<std::pair<int, int>>& island) {
        std::vector<std::vector<std::pair<int, int>>> ret(8);
        for (const auto& p : island) {
            int x = p.first;
            int y = p.second;
            ret[0].push_back({x, y});
            ret[1].push_back({x, -y});
            ret[2].push_back({-x, y});
            ret[3].push_back({-x, -y});
            ret[4].push_back({y, x});
            ret[5].push_back({y, -x});
            ret[6].push_back({-y, x});
            ret[7].push_back({-y, -x});
        }
        for (auto& list : ret) {
            std::sort(list.begin(), list.end());
        }
        std::sort(ret.begin(), ret.end());
        return ret[0];
    }

public:
    int numDistinctIslands(std::vector<std::vector<int>>& grid) {
        std::unordered_set<std::string> distinctIslands;
        for (int r = 0; r < grid.size(); ++r) {
            for (int c = 0; c < grid[r].size(); ++c) {
                if (grid[r][c] == 1) {
                    std::vector<std::pair<int, int>> island;
                    dfs(r, c, r, c, grid, island);
                    distinctIslands.insert(normalize(island));
                }
            }
        }
        return distinctIslands.size();
    }
};

python_code:
class Solution:
    def numDistinctIslands(self, grid: List[List[int]]) -> int:
        def dfs(r, c, r0, c0):
            if 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c]:
                grid[r][c] = 0
                island.append((r - r0, c - c0))
                dfs(r + 1, c, r0, c0)
                dfs(r - 1, c, r0, c0)
                dfs(r, c + 1, r0, c0)
                dfs(r, c - 1, r0, c0)

        def normalize(island):
            ret = []
            for p in island:
                x, y = p
                ret += [(x, y), (x, -y), (-x, y), (-x, -y), (y, x), (y, -x), (-y, x), (-y, -x)]
            ret.sort()
            return tuple(ret)

        distinctIslands = set()
        for r in range(len(grid)):
            for c in range(len(grid[0])):
                if grid[r][c]:
                    island = []
                    dfs(r, c, r, c)
                    distinctIslands.add(normalize(island))
        return len(distinctIslands)

