class Solution {
    numDistinctIslands(grid) {
        let distinctIslands = new Set();

        const dfs = (r, c, r0, c0) => {
            if (r >= 0 && c >= 0 && r < grid.length && c < grid[0].length && grid[r][c] === 1) {
                grid[r][c] = 0;
                island.push([r - r0, c - c0]);
                dfs(r + 1, c, r0, c0);
                dfs(r - 1, c, r0, c0);
                dfs(r, c + 1, r0, c0);
                dfs(r, c - 1, r0, c0);
            }
        };

        const normalize = (island) => {
            let ret = [];
            island.forEach(p => {
                let [x, y] = p;
                ret.push(...[[x, y], [x, -y], [-x, y], [-x, -y], [y, x], [y, -x], [-y, x], [-y, -x]]);
            });
            ret.sort((a, b) => a[0] - b[0] || a[1] - b[1]);
            return JSON.stringify(ret);
        };

        for (let r = 0; r < grid.length; ++r) {
            for (let c = 0; c < grid[r].length; ++c) {
                if (grid[r][c] === 1) {
                    let island = [];
                    dfs(r, c, r, c);
                    distinctIslands.add(normalize(island));
                }
            }
        }
        return distinctIslands.size;
    }
}

