public int maxProfit(int[] prices, int fee) {
    int cash = 0, hold = -prices[0];
    for (int price : prices) {
        int temp = cash;
        cash = Math.max(cash, hold + price - fee);
        hold = Math.max(hold, temp - price);
    }
    return cash;
}

