java_code:
import java.util.Arrays;

public int smallestDistancePair(int[] nums, int k) {
    Arrays.sort(nums);
    int low = 0, high = nums[nums.length - 1] - nums[0];

    while (low < high) {
        int mid = (low + high) / 2;
        int count = 0, left = 0;

        for (int right = 0; right < nums.length; ++right) {
            while (nums[right] - nums[left] > mid) {
                ++left;
            }
            count += (right - left);
        }

        if (count < k) {
            low = mid + 1;
        } else {
            high = mid;
        }
    }

    return low;
}

