from collections import defaultdict

def accountsMerge(accounts):
    def dfs(id, visited, merged_emails):
        if id in visited:
            return
        visited.add(id)
        for email in accounts[id][1:]:
            merged_emails.add(email)
            dfs(email_to_id[email], visited, merged_emails)

    email_to_id = {}
    for i, account in enumerate(accounts):
        for email in account[1:]:
            email_to_id[email] = i

    result = []
    visited = set()
    for i, account in enumerate(accounts):
        if i not in visited:
            merged_emails = set()
            dfs(i, visited, merged_emails)
            result.append([account[0]] + sorted(merged_emails))
    return result

javascript_code:
var accountsMerge = function(accounts) {
    function dfs(id, visited, mergedEmails) {
        if (visited.has(id)) return;
        visited.add(id);
        for (let j = 1; j < accounts[id].length; j++) {
            const email = accounts[id][j];
            mergedEmails.add(email);
            const nextId = emailToId[email];
            dfs(nextId, visited, mergedEmails);
        }
    }

    const emailToId = {};
    accounts.forEach((account, i) => {
        account.slice(1).forEach(email => {
            emailToId[email] = i;
        });
    });

    const result = [];
    const visited = new Set();
    accounts.forEach((account, i) => {
        if (!visited.has(i)) {
            const mergedEmails = new Set();
            dfs(i, visited, mergedEmails);
            result.push([account[0], ...Array.from(mergedEmails).sort()]);
        }
    });
    return result;
};

