using namespace std;

map<string, int> parse(const string &formula, int &i) {
    map<string, int> counts;
    while (i < formula.size()) {
        if (formula[i] == '(') {
            map<string, int> temp = parse(formula, ++i);
            int count = 0;
            while (isdigit(formula[i])) {
                count = count * 10 + (formula[i++] - '0');
            }
            if (count == 0) count = 1;
            for (const auto &e : temp) {
                counts[e.first] += e.second * count;
            }
        } else if (formula[i] == ')') {
            ++i;
            return counts;
        } else {
            string name;
            name += formula[i++];
            while (islower(formula[i])) {
                name += formula[i++];
            }
            int count = 0;
            while (isdigit(formula[i])) {
                count = count * 10 + (formula[i++] - '0');
            }
            if (count == 0) count = 1;
            counts[name] += count;
        }
    }
    return counts;
}

string countOfAtoms(string formula) {
    int i = 0;
    map<string, int> counts = parse(formula, i);
    string ans;
    for (const auto &e : counts) {
        ans += e.first;
        if (e.second > 1) ans += to_string(e.second);
    }
    return ans;
}

