        n = Math.floor(n / 10);
    }
    return true;
}

function selfDividingNumbers(left, right) {
    const result = [];
    for (let i = left; i <= right; ++i) {
        if (isSelfDividing(i))
            result.push(i);
    }
    return result;
}

