class MyCalendar {
    constructor() {
        this.calendar = new Map();
    }

    book(start, end) {
        if (this.calendar.size === 0) {
            this.calendar.set(start, end);
            return true;
        }

        let booked = false;
        for (let [s, e] of this.calendar) {
            if (Math.max(s, start) < Math.min(e, end)) {
                booked = true;
                break;
            }
        }

        if (!booked) {
            this.calendar.set(start, end);
            return true;
        }

        return false;
    }
}

