function floodFill(image, sr, sc, newColor) {
    let startColor = image[sr][sc];
    function fill(sr, sc) {
        if (sr < 0 || sc < 0 || sr >= image.length || sc >= image[0].length || image[sr][sc] !== startColor || image[sr][sc] === newColor) return;
        image[sr][sc] = newColor;
        fill(sr - 1, sc);
        fill(sr + 1, sc);
        fill(sr, sc - 1);
        fill(sr, sc + 1);
    }
    fill(sr, sc);
    return image;
}

