                second = first
                value1 = calculate(s, first, end, variables)
                second = s.index(' ', second) + 1
                value2 = calculate(s, second, end, variables)
                return value1 + value2
            elif s[start + 1:start + 5] == "mult":
                first = start + 6
                second = first
                value1 = calculate(s, first, end, variables)
                second = s.index(' ', second) + 1
                value2 = calculate(s, second, end, variables)
                return value1 * value2
            else:
