                idx = start + 5
                while idx < end - 1 and s[idx] != '(':
                    temp = idx
                    idx = s.index(' ', idx + 1)
                    var = s[temp:idx]
                    temp = idx + 1
                    if s[temp] == '(':
                        idx += 1
                    else:
                        idx = s.index(' ', idx + 1)
                    result = calculate(s, temp, idx, variables)
                    inner[var] = result
                    variables = inner
                return calculate(s, end - 1, end, variables)
        else:
