from collections import defaultdict

def areSentencesSimilar(sentence1, sentence2, pairs):
    if len(sentence1) != len(sentence2):
        return False

    graph = defaultdict(set)
    for a, b in pairs:
        graph[a].add(b)
        graph[b].add(a)

    for a, b in zip(sentence1, sentence2):
        if a == b:
            continue
        if b not in graph[a]:
            return False

    return True

javascript_code:
function areSentencesSimilar(sentence1, sentence2, pairs) {
    if (sentence1.length !== sentence2.length) return false;

    const graph = new Map();
    for (const [a, b] of pairs) {
        if (!graph.has(a)) graph.set(a, new Set());
        if (!graph.has(b)) graph.set(b, new Set());

        graph.get(a).add(b);
        graph.get(b).add(a);
    }

    for (let i = 0; i < sentence1.length; ++i) {
        if (sentence1[i] === sentence2[i]) continue;

        const neighbors = graph.get(sentence1[i]);
        if (!neighbors || !neighbors.has(sentence2[i])) return false;
    }

    return true;
}

