public int maxPoints(int[] nums) {
    int[] dp = new int[100001];
    int max_points = 0;
    for (int num : nums) {
        dp[num]++;
    }
    for (int i = 2; i < dp.length; i++) {
        dp[i] = Math.max(dp[i - 1], dp[i - 2] + i * dp[i]);
        max_points = Math.max(max_points, dp[i]);
    }
    return max_points;
}

