function networkDelayTime(times, n, k) {
    const graph = new Map();
    for (const [u, v, w] of times) {
        if (!graph.has(u)) graph.set(u, []);
        graph.get(u).push([v, w]);
    }

    const dist = new Array(n + 1).fill(Infinity);
    dist[k] = 0;

    const pq = [[0, k]];

    while (pq.length) {
        pq.sort((a, b) => b[0] - a[0]);
        const [currDist, u] = pq.pop();

        if (graph.has(u)) {
            for (const [v, weight] of graph.get(u)) {
                const newDist = currDist + weight;
                if (newDist < dist[v]) {
                    dist[v] = newDist;
                    pq.push([dist[v], v]);
                }
            }
        }
    }

    const maxTime = Math.max(...dist.slice(1));
    return maxTime === Infinity ? -1 : maxTime;
}

java_code:
import java.util.*;

class Solution {
    public int networkDelayTime(int[][] times, int n, int k) {
        List<List<int[]>> graph = new ArrayList<>();
        for (int i = 0; i <= n; i++)
            graph.add(new ArrayList<>());
        for (int[] edge : times)
            graph.get(edge[0]).add(new int[]{edge[1], edge[2]});

        int[] dist = new int[n + 1];
        Arrays.fill(dist, Integer.MAX_VALUE);
        dist[k] = 0;

        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[0] - b[0]);
        pq.add(new int[]{0, k});

        while (!pq.isEmpty()) {
            int[] curr = pq.poll();
            int time = curr[0], node = curr[1];

            if (time > dist[node]) continue;
            for (int[] neighbour : graph.get(node)) {
                int neighbourNode = neighbour[0], neighbourTime = neighbour[1];
                if (time + neighbourTime < dist[neighbourNode]) {
                    dist[neighbourNode] = time + neighbourTime;
                    pq.add(new int[]{dist[neighbourNode], neighbourNode});
                }
            }
        }

        int maxTime = Arrays.stream(dist).skip(1).max().getAsInt();
        return maxTime == Integer.MAX_VALUE ? -1 : maxTime;
    }
}

