class WordFilter:

    def __init__(self, words):
        self.dict = {}
        for i, word in enumerate(words):
            for j in range(len(word) + 1):
                self.dict[word[:j] + "#" + word[j:]] = i

    def f(self, prefix, suffix):
        return self.dict.get(prefix + "#" + suffix, -1)

