        this.dict = {};
        for (let i = 0; i < words.length; i++) {
            for (let j = 0; j <= words[i].length; j++) {
                this.dict[words[i].slice(0, j) + "#" + words[i].slice(j)] = i;
            }
        }
    }

    f(prefix, suffix) {
        if (this.dict.hasOwnProperty(prefix + "#" + suffix)) {
            return this.dict[prefix + "#" + suffix];
        }
        return -1;
    }
}

