public int countCornerRectangles(int[][] grid) {
    int count = 0;
    int m = grid.length;
    int n = grid[0].length;

    for (int i = 0; i < m - 1; i++) {
        for (int j = 0; j < n - 1; j++) {
            if (grid[i][j] == 1) {
                for (int k = i + 1; k < m; k++) {
                    for (int l = j + 1; l < n; l++) {
                        if (grid[k][l] == 1 && grid[i][l] == 1 && grid[k][j] == 1) {
                            count++;
                        }
                    }
                }
            }
        }
    }
    return count;
}

