import java.util.ArrayList;
import java.util.List;

public List<String> ipToCIDR(String ip, int n) {
    String[] parts = ip.split("\\.");
    int start = (Integer.parseInt(parts[0]) << 24) + (Integer.parseInt(parts[1]) << 16) + (Integer.parseInt(parts[2]) << 8) + Integer.parseInt(parts[3]);
    int end = start + n - 1;

    List<String> ans = new ArrayList<>();
    while (start <= end) {
        int samePrefixBits = Integer.numberOfTrailingZeros(~(start & -start));
        while (((end - start) >> samePrefixBits) < 1)
            --samePrefixBits;
        int range = 1 << samePrefixBits;
        ans.add((start >> 24) + "." + ((start >> 16) & 255) + "." + ((start >> 8) & 255) + "." + (start & 255) + "/" + (32 - samePrefixBits));
        start += range;
    }

    return ans;
}

cpp_code:
#include <bitset>
#include <vector>
#include <string>
#include <sstream>
using namespace std;

vector<string> ipToCIDR(string ip, int n) {
    stringstream ss(ip);
    int a, b, c, d;
    char ch;
    ss >> a >> ch >> b >> ch >> c >> ch >> d;
    unsigned mask = 0xFFFFFFFF;
    unsigned start = (a << 24) + (b << 16) + (c << 8) + d;
    unsigned end = start + n - 1;

    vector<string> ans;
    while (start <= end) {
        int samePrefixBits = __builtin_ctz(~(start & -start));
        while ((mask >> samePrefixBits) & 1)
            ++samePrefixBits;
        while (((end - start) >> samePrefixBits) < 1)
            --samePrefixBits;
        unsigned range = 1 << samePrefixBits;
        stringstream res;
        res << (start >> 24) << "." << ((start >> 16) & 255) << "." << ((start >> 8) & 255) << "." << (start & 255) << "/" << (32 - samePrefixBits);
        ans.push_back(res.str());
        start += range;
    }

    return ans;
}

javascript_code:
function ipToCIDR(ip, n) {
    const [a, b, c, d] = ip.split('.').map(Number);
    let start = (a << 24) + (b << 16) + (c << 8) + d;
    const end = start + n - 1;

    const ans = [];
    while (start <= end) {
        let samePrefixBits = Math.clz32(~(start & -start));
        while (((end - start) >> samePrefixBits) < 1)
            --samePrefixBits;
        const range = 1 << samePrefixBits;
        ans.push(`${(start >> 24)}.${((start >> 16) & 255)}.${((start >> 8) & 255)}.${(start & 255)}/${32 - samePrefixBits}`);
        start += range;
    }

    return ans;
}

