#include <string>
#include <vector>
#include <algorithm>

std::string makeLargestSpecial(std::string s) {
    int count = 0, i = 0;
    std::vector<std::string> subs;

    for (int j = 0; j < s.size(); j++) {
        if (s[j] == '1') count++;
        else count--;

        if (count == 0) {
            subs.push_back('1' + makeLargestSpecial(s.substr(i+1, j-i-1)) + '0');
            i = j + 1;
        }
    }

    std::sort(subs.rbegin(), subs.rend());
    std::string res;
    for (const auto& sub : subs) {
        res += sub;
    }
    return res;
}

