        else count--;

        if (count === 0) {
            subs.push("1" + makeLargestSpecial(s.slice(i+1, j)) + "0");
            i = j + 1;
        }
    }

    subs.sort((a, b) => b.localeCompare(a));
    return subs.join('');
}

