        int partner = row[i] % 2 == 0 ? row[i] + 1 : row[i] - 1;
        if (row[i + 1] != partner) {
            swap(row[position[partner]], row[i + 1]);
            swap(position[row[i + 1]], position[partner]);
            swaps++;
        }
    }
    return swaps;
}

