public class Node {
    public int val;
    public Node prev;
    public Node next;
    public Node child;
}

public Node flatten(Node head) {
    if(head == null) return null;

    Node curr = head;
    while(curr != null) {
        if(curr.child != null) {
            Node insert = curr.child;
            Node next = curr.next;

            insert.prev = curr;
            curr.next = insert;
            curr.child = null;

            while(insert.next != null) insert = insert.next;

            if(next != null) {
                next.prev = insert;
                insert.next = next;
            }
        }
        curr = curr.next;
    }

    return head;
}

