            next_node = curr.next

            insert.prev = curr
            curr.next = insert
            curr.child = None

            while insert.next:
                insert = insert.next

            if next_node:
                next_node.prev = insert
                insert.next = next_node

        curr = curr.next

    return head

javascript_code:
class Node {
    constructor(val, prev, next, child) {
        this.val = val;
        this.prev = prev || null;
        this.next = next || null;
        this.child = child || null;
    }
}

function flatten(head) {
    if (!head) return null;

    let curr = head;
    while (curr) {
        if (curr.child) {
            let insert = curr.child;
            let next = curr.next;

            insert.prev = curr;
            curr.next = insert;
            curr.child = null;

            while (insert.next) insert = insert.next;

            if (next) {
                next.prev = insert;
                insert.next = next;
            }
        }
        curr = curr.next;
    }

    return head;
}

