        if (length === 1) {
            return new Node(grid[x][y] === 1, true, null, null, null, null);
        }

        const tl = helper(x, y, length >> 1);
        const tr = helper(x, y + (length >> 1), length >> 1);
        const bl = helper(x + (length >> 1), y, length >> 1);
        const br = helper(x + (length >> 1), y + (length >> 1), length >> 1);

        if (tl.isLeaf && tr.isLeaf && bl.isLeaf && br.isLeaf && tl.val === tr.val && tr.val === bl.val && bl.val === br.val) {
            return new Node(tl.val, true, null, null, null, null);
        } else {
            return new Node(false, false, tl, tr, bl, br);
        }
    }

    return helper(0, 0, grid.length);
}

