std::vector<int> postorder(Node* root) {
    std::vector<int> result;
    if(root == nullptr) return result;

    std::stack<Node*> s;
    s.push(root);
    while(!s.empty()) {
        Node* curr = s.top();
        s.pop();

        result.push_back(curr->val);
        for(Node* child : curr->children) {
            s.push(child);
        }
    }
    std::reverse(result.begin(), result.end());
    return result;
}

