import java.util.PriorityQueue;
import java.util.HashMap;

public String rearrangeString(String s) {
    HashMap<Character, Integer> counts = new HashMap<>();
    for (char c : s.toCharArray()) {
        counts.put(c, counts.getOrDefault(c, 0) + 1);
    }

    PriorityQueue<Character> pq = new PriorityQueue<>((a, b) -> counts.get(b) - counts.get(a));
    pq.addAll(counts.keySet());

    StringBuilder result = new StringBuilder();
    Character previous = null;

    while (!pq.isEmpty()) {
        char current = pq.remove();
        result.append(current);

        if (previous != null && counts.get(previous) > 0) {
            pq.add(previous);
        }

        counts.put(current, counts.get(current) - 1);
        previous = current;
    }

    return result.length() == s.length() ? result.toString() : "";
}

cpp_code:
#include <queue>

std::string rearrangeString(std::string s) {
    std::unordered_map<char, int> counts;
    for (char c : s) {
        counts[c]++;
    }

    auto cmp = [](const auto& a, const auto& b) {
        return a.second < b.second;
    };

    std::priority_queue<std::pair<char, int>, std::vector<std::pair<char, int>>, decltype(cmp)> pq(cmp);

    for (auto& count : counts) {
        pq.push(count);
    }

    std::string result;
    std::pair<char, int> previous = {-1, 0};

    while (!pq.empty()) {
        auto current = pq.top();
        pq.pop();
        result += current.first;

        if (previous.second > 0) {
            pq.push(previous);
        }

        current.second--;
        previous = current;
    }

    return result.size() == s.size() ? result : "";
}

javascript_code:
function rearrangeString(s) {
    const counts = new Map();
    for (const c of s) {
        counts.set(c, (counts.get(c) || 0) + 1);
    }

    const pq = Array.from(counts.entries()).sort((a, b) => b[1] - a[1]);

    const result = [];
    let previous = [-1, null];

    while (pq.length) {
        const current = pq.shift();
        result.push(current[0]);

        if (previous[0] > 0) {
            pq.push(previous);
        }

        current[1]--;
        previous = current;
        pq.sort((a, b) => b[1] - a[1]);
    }

    const resultStr = result.join('');
    return resultStr.length === s.length ? resultStr : "";
}

