using namespace std;

int numRabbits(vector<int>& answers) {
    unordered_map<int, int> count;
    int rabbits = 0;
    for (int ans : answers) {
        count[ans]++;
    }
    for (auto& [ans, cnt] : count) {
        rabbits += (ans + cnt) / (ans + 1) * (ans + 1);
    }
    return rabbits;
}

