import java.util.PriorityQueue;

public int[] kthSmallestPrimeFraction(int[] arr, int k) {
    PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> arr[a[0]] * arr[b[1]] - arr[a[1]] * arr[b[0]]);
    for (int i = 0; i < arr.length - 1; i++) {
        pq.offer(new int[]{i, arr.length - 1});
    }
    while (--k > 0) {
        int[] tmp = pq.poll();
        if (--tmp[1] > tmp[0]) {
            pq.offer(tmp);
        }
    }
    return new int[]{arr[pq.peek()[0]], arr[pq.peek()[1]]};
}

cpp_code:
#include <vector>
#include <queue>
using namespace std;

vector<int> kthSmallestPrimeFraction(vector<int>& arr, int k) {
    auto compare = [&](pair<int, int>& a, pair<int, int>& b) {
        return arr[a.first] * arr[b.second] > arr[a.second] * arr[b.first];
    };
    priority_queue<pair<int, int>, vector<pair<int, int>>, decltype(compare)> pq(compare);
    for (int i = 0; i < arr.size() - 1; ++i) {
        pq.push({i, arr.size() - 1});
    }
    for (int i = 0; i < k - 1; ++i) {
        auto [row, col] = pq.top();
        pq.pop();
        if (--col > row) {
            pq.push({row, col});
        }
    }
    return {arr[pq.top().first], arr[pq.top().second]};
}

python_code:
import heapq
from typing import List

def kthSmallestPrimeFraction(arr: List[int], k: int) -> List[int]:
    pq = [(arr[i] / arr[j], i, j) for j in range(len(arr) - 1, 0, -1)]
    heapq.heapify(pq)
    for _ in range(k - 1):
        _, i, j = heapq.heappop(pq)
        if j != i + 1:
            heapq.heappush(pq, (arr[i] / arr[j - 1], i, j - 1))
    return [arr[pq[0][1]], arr[pq[0][2]]]

