#include <vector>
#include <queue>
#include <string>

using namespace std;

int slidingPuzzle(vector<vector<int>>& board) {
    int m = 2, n = 3;
    string target = "123450";
    string start = "";
    for (int i = 0; i < m; ++i)
        for (int j = 0; j < n; ++j)
            start += to_string(board[i][j]);
    vector<vector<int>> dirs{{1, 3}, {0, 2, 4}, {1, 5}, {0, 4}, {1, 3, 5}, {2, 4}};
    queue<string> q{{start}};
    int res = 0;
    unordered_set<string> visited{start};
    while (!q.empty()) {
        for (int k = q.size(); k > 0; --k) {
            string cur = q.front(); q.pop();
            if (cur == target) return res;
            int zero_idx = cur.find("0");
            for (int dir : dirs[zero_idx]) {
                string neighbor = cur;
                swap(neighbor[zero_idx], neighbor[dir]);
                if (!visited.count(neighbor)) {
                    visited.insert(neighbor);
                    q.push(neighbor);
                }
            }
        }
        ++res;
    }
    return -1;
}

javascript_code:
function slidingPuzzle(board) {
    const m = 2, n = 3;
    const target = "123450";
    let start = "";
    for (const row of board) {
        for (const num of row) {
            start += num;
        }
    }
    const dirs = [[1, 3], [0, 2, 4], [1, 5], [0, 4], [1, 3, 5], [2, 4]];
    const q = [start];
    let res = 0;
    const visited = new Set(q);
    while (q.length > 0) {
        for (let k = q.length; k > 0; --k) {
            const cur = q.shift();
            if (cur === target) return res;
            const zero_idx = cur.indexOf('0');
            for (const dir of dirs[zero_idx]) {
                let neighbor = cur.slice(0, zero_idx) + cur[dir] + cur.slice(zero_idx + 1);
                neighbor = neighbor.slice(0, dir) + '0' + neighbor.slice(dir + 1);
                if (!visited.has(neighbor)) {
                    visited.add(neighbor);
                    q.push(neighbor);
                }
            }
        }
        ++res;
    }
    return -1;
}

