class KthLargest {
    constructor(k, nums) {
        this.minHeap = new MinHeap();
        this.k = k;
        for (let num of nums) {
            this.add(num);
        }
    }

    add(val) {
        this.minHeap.offer(val);
        if (this.minHeap.size() > this.k) {
            this.minHeap.poll();
        }
        return this.minHeap.peek();
    }
}

class MinHeap {
    constructor() {
        this.heap = [];
    }

    offer(val) {
        this.heap.push(val);
        this.heap.sort((a, b) => a - b);
    }

    poll() {
        return this.heap.shift();
    }

    peek() {
        return this.heap[0];
    }

    size() {
        return this.heap.length;
    }
}

