import java.util.HashMap;

public String customSortString(String order, String s) {
    HashMap<Character, Integer> priority = new HashMap<>();
    for (int i = 0; i < order.length(); i++) {
        priority.put(order.charAt(i), i);
    }

    Character[] sChars = s.chars().mapToObj(c -> (char) c).toArray(Character[]::new);
    Arrays.sort(sChars, (a, b) -> priority.getOrDefault(a, 0) - priority.getOrDefault(b, 0));
    return Arrays.stream(sChars).map(String::valueOf).collect(Collectors.joining());
}

cpp_code:
#include <algorithm>
#include <string>
#include <unordered_map>

std::string customSortString(const std::string& order, std::string& s) {
    std::unordered_map<char, int> priority;
    for (int i = 0; i < order.size(); i++) {
        priority[order[i]] = i;
    }

    std::sort(s.begin(), s.end(), [&](char a, char b) {
        return priority[a] < priority[b];
    });

    return s;
}

python_code:
def customSortString(order, s):
    priority = {char: idx for idx, char in enumerate(order)}
    return "".join(sorted(s, key=lambda x: priority.get(x, 0)))

javascript_code:
function customSortString(order, s) {
    const priority = new Map();
    for (let i = 0; i < order.length; i++) {
        priority.set(order[i], i);
    }

    const sArr = Array.from(s);
    sArr.sort((a, b) => (priority.has(a) ? priority.get(a) : 0) - (priority.has(b) ? priority.get(b) : 0));
    return sArr.join('');
}

