        while (i < n && start[i] == 'X') i++;
        while (j < n && end[j] == 'X') j++;

        if (start[i] != end[j]) return false;

        if ((start[i] == 'R' && i > j) || (start[i] == 'L' && i < j)) return false;

        i++; j++;
    }
    return true;
}

