import heapq

def swim(n, grid):
    pq = [(grid[0][0], 0, 0)]
    visited = [[False] * n for _ in range(n)]

    dr = [-1, 0, 1, 0]
    dc = [0, 1, 0, -1]

    while pq:
        curT, curR, curC = heapq.heappop(pq)

        if curR == n - 1 and curC == n - 1:
            return curT

        for d in range(4):
            newRow, newCol = curR + dr[d], curC + dc[d]
            if 0 <= newRow < n and 0 <= newCol < n and not visited[newRow][newCol]:
                visited[newRow][newCol] = True
                heapq.heappush(pq, (max(curT, grid[newRow][newCol]), newRow, newCol))

    return -1

javascript_code:
function swim(n, grid) {
    const pq = [[grid[0][0], 0, 0]];
    const visited = Array.from({ length: n }, () => Array(n).fill(false));

    const dr = [-1, 0, 1, 0];
    const dc = [0, 1, 0, -1];

    while (pq.length) {
        pq.sort((a, b) => a[0] - b[0]);
        const [curT, curR, curC] = pq.shift();

        if (curR === n - 1 && curC === n - 1) return curT;

        for (let d = 0; d < 4; d++) {
            const newRow = curR + dr[d];
            const newCol = curC + dc[d];
            if (0 <= newRow && newRow < n && 0 <= newCol && newCol < n && !visited[newRow][newCol]) {
                visited[newRow][newCol] = true;
                pq.push([Math.max(curT, grid[newRow][newCol]), newRow, newCol]);
            }
        }
    }
    return -1;
}

