#include <unordered_map>
int numRabbits(vector<int>& answers) {
    unordered_map<int, int> count;
    int res = 0;
    for (int a : answers) {
        ++count[a];
        if (count[a] == 1) {
            res += (a + 1);
        } else if (count[a] > a + 1) {
            count[a] = 1;
            res += (a + 1);
        }
    }
    return res;
}

