public int movesToChessboard(int[][] board) {
    int N = board.length;
    int row = 0, col = 0, rowCount = 0, colCount = 0;

    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            if (((board[0][0] ^ board[i][0] ^ board[0][j]) ^ board[i][j]) != 0) return -1;
        }
    }

    for (int i = 0; i < N; i++) {
        row ^= board[0][i];
        col ^= board[i][0];
        rowCount += board[0][i] == 1 ? 1 : 0;
        colCount += board[i][0] == 1 ? 1 : 0;
    }

    if (row != 0 && rowCount * 2 != N) return -1;
    if (col != 0 && colCount * 2 != N) return -1;

    if (N % 2 == 1) {
        if (rowCount % 2 == 1) rowCount = N - rowCount;
        if (colCount % 2 == 1) colCount = N - colCount;
    } else {
        rowCount = Math.min(rowCount, N - rowCount);
        colCount = Math.min(colCount, N - colCount);
    }

    return (rowCount + colCount) / 2;
}

cpp_code:
#include <bitset>
#include <vector>

int movesToChessboard(std::vector<std::vector<int>>& board) {
  int N = board.size();
  std::bitset<30> row, col;

  for (int i = 0; i < N; ++i)
    for (int j = 0; j < N; ++j)
      if (board[0][0] ^ board[i][0] ^ board[0][j] ^ board[i][j])
        return -1;

  for (int i = 0; i < N; ++i) {
    row.flip(i);
    col.flip(i);
  }

  int c = board[0] & col;
  int d = row.count() - row.count() & col;
  int max_count = max(c, d);

  if (max_count == N) return 0;

  if (N & 1) return max_count & 1 ? max_count / 2 : max_count / 2 + 1;
  else return max_count / 2;
}

