#include <vector>
#include <string>

void backtrack(std::string s, int index, std::vector<std::string>& result) {
    if (index == s.length()) {
        result.push_back(s);
        return;
    }
    backtrack(s, index + 1, result);
    if (isalpha(s[index])) {
        s[index] ^= (1 << 5);
        backtrack(s, index + 1, result);
    }
}

std::vector<std::string> letterCasePermutation(std::string s) {
    std::vector<std::string> result;
    backtrack(s, 0, result);
    return result;
}

javascript_code:
function letterCasePermutation(s) {
    const result = [];
    function backtrack(index) {
        if (index === s.length) {
            result.push(s.join(''));
            return;
        }
        backtrack(index + 1);
        if (s[index] !== s[index].toUpperCase() || s[index] !== s[index].toLowerCase()) {
            s[index] = flipCase(s[index]);
            backtrack(index + 1);
            s[index] = flipCase(s[index]);
        }
    }
    s = s.split('');
    backtrack(0);
    return result;
}

function flipCase(c) {
    return c === c.toUpperCase() ? c.toLowerCase() : c.toUpperCase();
}

