import java.util.PriorityQueue;

public int[] kthSmallestPrimeFraction(int[] arr, int k) {
    PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> arr[a[0]] * arr[b[1]] - arr[a[1]] * arr[b[0]]);

    for (int i = 0; i < arr.length - 1; i++) {
        pq.offer(new int[]{i, arr.length - 1});
    }

    for (int i = 1; i < k; i++) {
        int[] curr = pq.poll();
        curr[1]--;
        if (curr[0] < curr[1]) {
            pq.offer(curr);
        }
    }

    return new int[]{arr[pq.peek()[0]], arr[pq.peek()[1]]};
}

cpp_code:
#include <vector>
#include <queue>

std::vector<int> kthSmallestPrimeFraction(std::vector<int>& arr, int k) {
    auto compare = [&](const std::pair<int, int>& a, const std::pair<int, int>& b) {
        return (long long)arr[a.first] * arr[b.second] > (long long)arr[a.second] * arr[b.first];
    };

    std::priority_queue<std::pair<int, int>, std::vector<std::pair<int, int>>, decltype(compare)> pq(compare);

    for (int i = 0; i < arr.size() - 1; ++i) {
        pq.push({i, arr.size() - 1});
    }

    for (int i = 1; i < k; ++i) {
        auto curr = pq.top();
        pq.pop();
        curr.second--;
        if (curr.first < curr.second) {
            pq.push(curr);
        }
    }

    return {arr[pq.top().first], arr[pq.top().second]};
}

