import heapq

def findCheapestPrice(n, flights, src, dst, k):
    graph = [[] for _ in range(n)]
    for flight in flights:
        graph[flight[0]].append((flight[1], flight[2]))

    pq = [(0, src, k + 1)]
    while pq:
        price, city, stops = heapq.heappop(pq)

        if city == dst:
            return price

        if stops > 0:
            for nei, prc in graph[city]:
                heapq.heappush(pq, (price + prc, nei, stops - 1))

    return -1

javascript_code:
function findCheapestPrice(n, flights, src, dst, k) {
    const graph = Array.from({ length: n }, () => []);
    for (const flight of flights) {
        graph[flight[0]].push([flight[1], flight[2]]);
    }

    const pq = [[0, src, k + 1]];
    while (pq.length) {
        pq.sort((a, b) => a[0] - b[0]);
        const [price, city, stops] = pq.shift();

        if (city === dst) {
            return price;
        }

        if (stops > 0) {
            for (const [nei, prc] of graph[city]) {
                pq.push([price + prc, nei, stops - 1]);
            }
        }
    }

    return -1;
}

