#include <string>
#include <vector>

int numMatchingSubseq(const std::string& s, const std::vector<std::string>& words) {
    std::vector<std::vector<int>> positions(26);

    for (int i = 0; i < s.size(); ++i) {
        positions[s[i] - 'a'].push_back(i);
    }

    int count = 0;

    for (const auto& word : words) {
        int index = -1;
        bool isSubsequence = true;

        for (const char& c : word) {
            auto it = std::upper_bound(positions[c - 'a'].begin(), positions[c - 'a'].end(), index);
            if (it == positions[c - 'a'].end()) {
                isSubsequence = false;
                break;
            }
            index = *it;
        }

        if (isSubsequence) {
            ++count;
        }
    }

    return count;
}

python_code:
from bisect import bisect_left
from collections import defaultdict

def numMatchingSubseq(s, words):
    positions = defaultdict(list)

    for i, c in enumerate(s):
        positions[c].append(i)

    count = 0

    for word in words:
        index = -1
        isSubsequence = True

        for c in word:
            position_list = positions.get(c, [])
            i = bisect_left(position_list, index + 1)
            if (i == len(position_list)):
                isSubsequence = False
                break
            index = position_list[i]

        if isSubsequence:
            count += 1

    return count

