    if board[0][2] == board[1][1] == board[2][0] != ' ':
        x_win, o_win = (True, o_win) if board[0][2] == 'X' else (x_win, True)

    if x_win and o_win: return False
    if x_win and x_count == o_count: return False
    if o_win and x_count > o_count: return False

