int numSubarrayBoundedMax(int[] nums, int left, int right) {
    int result = 0, prev = 0, start = -1;
    for (int i = 0; i < nums.length; ++i) {
        if (nums[i] >= left && nums[i] <= right) {
            prev = i - start;
            result += prev;
        } else if (nums[i] < left) {
            result += prev;
        } else {
            start = i;
            prev = 0;
        }
    }
    return result;
}

