import java.util.*;

public int numBusesToDestination(int[][] routes, int source, int target) {
    if (source == target) return 0;

    Map<Integer, Set<Integer>> stopRouteMap = new HashMap<>();
    for (int i = 0; i < routes.length; i++) {
        for (int stop : routes[i]) {
            stopRouteMap.computeIfAbsent(stop, x -> new HashSet<>()).add(i);
        }
    }

    Queue<Integer> queue = new LinkedList<>();
    Set<Integer> visitedSources = new HashSet<>();

    queue.offer(source);
    visitedSources.add(source);
    int transfers = 0;

    while (!queue.isEmpty()) {
        int size = queue.size();
        while (size-- > 0) {
            int curr = queue.poll(); // Pop from the queue.
            if (curr == target) return transfers;

            for (int route : stopRouteMap.get(curr)) {
                for (int stop : routes[route]) {
                    if (!visitedSources.contains(stop)) {
                        queue.offer(stop);
                        visitedSources.add(stop);
                    }
                }
                // Remove the route from the stop.
                stopRouteMap.get(curr).remove(route);
            }
        }
        transfers++;
    }
    return -1;
}

cpp_code:
#include <unordered_map>
#include <unordered_set>
#include <vector>
#include <queue>

int numBusesToDestination(std::vector<std::vector<int>>& routes, int source, int target) {
    if (source == target) return 0;

    std::unordered_map<int, std::unordered_set<int>> stop_route_map;
    for (int i = 0; i < routes.size(); ++i) {
        for (int stop : routes[i]) {
            stop_route_map[stop].insert(i);
        }
    }

    std::queue<int> q;
    std::unordered_set<int> visited_sources;

    q.push(source);
    visited_sources.insert(source);
    int transfers = 0;

    while (!q.empty()) {
        int size = q.size();
        while (size--) {
            int curr = q.front();
            q.pop();
            if (curr == target) return transfers;

            for (int route : stop_route_map[curr]) {
                for (int stop : routes[route]) {
                    if (visited_sources.count(stop) == 0) {
                        q.push(stop);
                        visited_sources.insert(stop);
                    }
                }
                stop_route_map[curr].erase(route);
            }
        }
        transfers++;
    }
    return -1;
}

