java_code:
public int racecar(int target) {
    return dp(0, 1, target, new HashMap<>());
}

private int dp(int position, int speed, int target, Map<String, Integer> memo) {
    if (Math.abs(position) > 2 * target) {
        return target + 1;
    }
    if (position == target) {
        return speed == 1 ? 0 : 1;
    }
    String key = position + "," + speed;
    if (memo.containsKey(key)) {
        return memo.get(key);
    }
    int result = (speed > 0 ? dp(position + speed / 2, -speed / 2, target, memo) : dp(position - speed / 2, -speed / 2, target, memo)) + 1;
    result = Math.min(result, dp(position + speed, speed * 2, target, memo) + 1);
    memo.put(key, result);
    return result;
}

cpp_code:
int racecar(int target) {
    unordered_map<int, unordered_map<int, int>> memo;
    function<int(int, int)> dp = [&](int pos, int speed) {
        if (abs(pos) > 2 * target) return target + 1;
        if (pos == target) return speed == 1 ? 0 : 1;
        if (memo[pos][speed]) return memo[pos][speed];
        int ans = (speed > 0 ? dp(pos + speed / 2, -speed / 2) : dp(pos - speed / 2, -speed / 2)) + 1;
        ans = min(ans, dp(pos + speed, speed * 2) + 1);
        return memo[pos][speed] = ans;
    };
    return dp(0, 1);
}

python_code:
def racecar(target: int) -> int:
    memo = {}
    def dp(position, speed):
        if abs(position) > 2 * target:
            return target + 1
        if position == target:
            return 0 if speed == 1 else 1
        if (position, speed) in memo:
            return memo[(position, speed)]

        ans = dp(position + speed // 2, -speed // 2) + 1 if speed > 0 else dp(position - speed // 2, -speed // 2) + 1
        ans = min(ans, dp(position + speed, speed * 2) + 1)
        memo[(position, speed)] = ans
        return ans

    return dp(0, 1)

javascript_code:
function racecar(target) {
    const memo = new Map();

    function dp(pos, speed) {
        if (Math.abs(pos) > 2 * target) {
            return target + 1;
        }
        if (pos === target) {
            return speed === 1 ? 0 : 1;
        }
        const key = pos + "," + speed;
        if (memo.has(key)) {
            return memo.get(key);
        }

        let result = ((speed > 0)
            ? dp(pos + Math.floor(speed / 2), -Math.floor(speed / 2))
            : dp(pos - Math.floor(speed / 2), -Math.floor(speed / 2))) + 1;

        result = Math.min(result, dp(pos + speed, speed * 2) + 1);
        memo.set(key, result);
        return result;
    }

    return dp(0, 1);
}

