        for (const auto& d : directions) {
            sum += dfs(x + d[0], y + d[1]);
        }
        return sum;
    };

    for (int i = 0; i < n; ++i) {
        if (grid[0][i] == 1) {
            dfs(0, i);
        }
    }

    for (const auto& hit : hits) {
        grid[hit[0]][hit[1]]++;
        if (grid[hit[0]][hit[1]] != 1) {
            result.push_back(0);
            continue;
        }
        for (const auto& d : directions) {
            if (dfs(hit[0] + d[0], hit[1] + d[1])) {
                result.push_back(dfs(hit[0], hit[1]) - 1);
                break;
            }
        }
    }

    return result;
