}

python_code:
class Solution:
    def largestSumOfAverages(self, nums: List[int], k: int) -> float:
        memo = {}

        def max_partition_sum(start: int, k: int) -> float:
            if k == 1:
                return sum(nums[start:]) / (len(nums) - start)
            if (start, k) in memo:
                return memo[start, k]

            ans, curr_sum = 0, 0
            for i in range(start, len(nums) - k + 1):
                curr_sum += nums[i]
                ans = max(ans, curr_sum / (i - start + 1) + max_partition_sum(i + 1, k - 1))

            memo[start, k] = ans
            return ans

        return max_partition_sum(0, k)

javascript_code:
function largestSumOfAverages(nums, k) {
    const memo = Array.from(Array(nums.length), () => Array(k + 1).fill(-1));
    return maxPartitionSum(0, k, nums, memo);
}

function maxPartitionSum(start, k, nums, memo) {
    if (k === 1) {
        return nums.slice(start).reduce((sum, n) => sum + n) / (nums.length - start);
    }
    if (memo[start][k] !== -1) {
        return memo[start][k];
    }
    let sum = 0, ans = 0;
    for (let i = start; i < nums.length - k + 1; ++i) {
        sum += nums[i];
        ans = Math.max(ans, sum / (i - start + 1) + maxPartitionSum(i + 1, k - 1, nums, memo));
    }
    memo[start][k] = ans;
    return ans;
}

