def mostCommonWord(paragraph: str, banned: List[str]):
    word_count = {}
    banned_set = {ban.lower() for ban in banned}

    for word in paragraph.lower().split():
        cleaned_word = ''.join(c for c in word if c.isalpha())
        if cleaned_word not in banned_set:
            word_count[cleaned_word] = word_count.get(cleaned_word, 0) + 1

    return max(word_count, key=word_count.get)

javascript_code:
function mostCommonWord(paragraph, banned) {
    const wordCount = new Map();
    const bannedSet = new Set(banned.map(x => x.toLowerCase()));
    const words = paragraph.toLowerCase().split(/\W+/);

    words.forEach(word => {
        if (!bannedSet.has(word)) {
            wordCount.set(word, (wordCount.get(word) || 0) + 1);
        }
    });

    let maxCount = -1;
    let result = '';
    wordCount.forEach((count, word) => {
        if (count > maxCount) {
            maxCount = count;
            result = word;
        }
    });

    return result;
}

java_code:
public String pushDominoes(String dominoes) {
    int n = dominoes.length();
    int[] forces = new int[n];

    int force = 0;
    for (int i = 0; i < n; ++i) {
        if (dominoes.charAt(i) == 'R') force = n;
        else if (dominoes.charAt(i) == 'L') force = 0;
        else force = Math.max(force - 1, 0);
        forces[i] += force;
    }

    force = 0;
    for (int i = n - 1; i >= 0; --i) {
        if (dominoes.charAt(i) == 'L') force = n;
        else if (dominoes.charAt(i) == 'R') force = 0;
        else force = Math.max(force - 1, 0);
        forces[i] -= force;
    }

    StringBuilder result = new StringBuilder();
    for (int f : forces) {
        if (f > 0) result.append('R');
        else if (f < 0) result.append('L');
        else result.append('.');
    }

    return result.toString();
}

