#include <vector>
#include <map>

bool isPossibleDivide(std::vector<int>& hand, int groupSize) {
    std::map<int, int> cardCount;
    for (int card : hand) {
        cardCount[card]++;
    }

    for (auto it = cardCount.begin(); it != cardCount.end(); ++it) {
        if (it->second > 0) {
            int count = it->second;
            for (int i = 1; i < groupSize; ++i) {
                cardCount[it->first + i] -= count;
                if (cardCount[it->first + i] < 0) {
                    return false;
                }
            }
        }
    }

    return true;
}

python_code:
from collections import Counter

def is_possible_divide(hand, group_size):
    card_count = Counter(hand)

    for card in sorted(card_count):
        if card_count[card] > 0:
            count = card_count[card]
            for i in range(1, group_size):
                if card_count[card + i] < count:
                    return False
                card_count[card + i] -= count

    return True

javascript_code:
function isPossibleDivide(hand, groupSize) {
    const cardCount = new Map();
    for (const card of hand) {
        cardCount.set(card, (cardCount.get(card) || 0) + 1);
    }

    for (const [card, count] of Array.from(cardCount.entries()).sort((a, b) => a[0] - b[0])) {
        if (count > 0) {
            for (let i = 1; i < groupSize; ++i) {
                const tmp = (cardCount.get(card + i) || 0) - count;
                if (tmp < 0) {
                    return false;
                }
                cardCount.set(card + i, tmp);
            }
        }
    }

    return true;
}

