#include <queue>
#include <vector>

int shortestPathLength(const std::vector<std::vector<int>>& graph) {
    int n = graph.size();
    std::queue<std::tuple<int, int, int>> q;
    std::vector<std::vector<bool>> visited(n, std::vector<bool>(1 << n, false));

    for (int i = 0; i < n; ++i) {
        q.push({i, 1 << i, 0});
        visited[i][1 << i] = true;
    }

    while (!q.empty()) {
        auto [node, bitmask, length] = q.front();
        q.pop();

        if (bitmask == (1 << n) - 1) return length;

        for (int nei : graph[node]) {
            int next_bitmask = bitmask | (1 << nei);
            if (!visited[nei][next_bitmask]) {
                visited[nei][next_bitmask] = true;
                q.push({nei, next_bitmask, length + 1});
            }
        }
    }

    return 0;
}

python_code:
from collections import deque

def shortestPathLength(graph):
    n = len(graph)
    queue = deque([(i, 1 << i, 0) for i in range(n)])
    visited = [[False] * (1 << n) for _ in range(n)]

    for i in range(n):
        visited[i][1 << i] = True

    while queue:
        node, bitmask, length = queue.popleft()

        if bitmask == (1 << n) - 1:
            return length

        for nei in graph[node]:
            next_bitmask = bitmask | (1 << nei)
            if not visited[nei][next_bitmask]:
                visited[nei][next_bitmask] = True
                queue.append((nei, next_bitmask, length + 1))

    return 0

javascript_code:
function shortestPathLength(graph) {
    const n = graph.length;
    const queue = [];
    const visited = Array.from({length: n}, () => Array(1 << n).fill(false));

    for (let i = 0; i < n; i++) {
        queue.push([i, 1 << i, 0]);
        visited[i][1 << i] = true;
    }

    while (queue.length) {
        const [node, bitmask, length] = queue.shift();

        if (bitmask === (1 << n) - 1) return length;

        for (const nei of graph[node]) {
            const next_bitmask = bitmask | (1 << nei);
            if (!visited[nei][next_bitmask]) {
                visited[nei][next_bitmask] = true;
                queue.push([nei, next_bitmask, length + 1]);
            }
        }
    }

    return 0;
}

