#include<string>
#include<vector>
using namespace std;

string shiftingLetters(string s, vector<int>& shifts) {
    for (int i = shifts.size() - 2; i >= 0; i--) {
        shifts[i] += shifts[i + 1] % 26;
    }

    for (int i = 0; i < s.size(); i++) {
        s[i] = (s[i] - 'a' + shifts[i] % 26) % 26 + 'a';
    }

    return s;
}

python_code:
def shiftingLetters(s: str, shifts) -> str:
    for i in range(len(shifts) - 2, -1, -1):
        shifts[i] += shifts[i + 1] % 26

    result = list(s)
    for i in range(len(s)):
        result[i] = chr((ord(result[i]) - ord('a') + shifts[i] % 26) % 26 + ord('a'))

    return "".join(result)

javascript_code:
function shiftingLetters(s, shifts) {
    for (let i = shifts.length - 2; i >= 0; i--) {
        shifts[i] = (shifts[i] + shifts[i + 1] % 26) % 26;
    }

    let result = s.split('');
    for (let i = 0; i < s.length; i++) {
        result[i] = String.fromCharCode((result[i].charCodeAt(0) - 'a'.charCodeAt(0) + shifts[i] % 26) % 26 + 'a'.charCodeAt(0));
    }

    return result.join('');
}

