cpp_code:
#include <vector>
#include <set>
using namespace std;

int rectangleArea(vector<vector<int>>& rectangles) {
    const int64_t mod = 1e9 + 7;
    int n = rectangles.size();
    vector<int> X, Y;
    for (const auto &rect : rectangles) {
        X.push_back(rect[0]);
        X.push_back(rect[2]);
        Y.push_back(rect[1]);
        Y.push_back(rect[3]);
    }
    sort(X.begin(), X.end());
    sort(Y.begin(), Y.end());

    X.erase(unique(X.begin(), X.end()), X.end());
    Y.erase(unique(Y.begin(), Y.end()), Y.end());

    vector<vector<int>> cnt(X.size() - 1, vector<int>(Y.size() - 1));

    for (const auto &rect : rectangles) {
        int x1_idx = lower_bound(X.begin(), X.end(), rect[0]) - X.begin();
        int x2_idx = lower_bound(X.begin(), X.end(), rect[2]) - X.begin() - 1;
        int y1_idx = lower_bound(Y.begin(), Y.end(), rect[1]) - Y.begin();
        int y2_idx = lower_bound(Y.begin(), Y.end(), rect[3]) - Y.begin() - 1;
        for (int i = x1_idx; i <= x2_idx; ++i) {
            for (int j = y1_idx; j <= y2_idx; ++j) {
                cnt[i][j] = 1;
            }
        }
    }
    int64_t total_area = 0;
    for (int i = 0; i < X.size() - 1; ++i) {
        for (int j = 0; j < Y.size() - 1; ++j) {
            if (cnt[i][j]) {
                total_area += (int64_t)(X[i + 1] - X[i]) * (Y[j + 1] - Y[j]);
                total_area %= mod;
            }
        }
    }
    return total_area;
}

javascript_code:
function rectangleArea(rectangles) {
    const mod = 1e9 + 7;
    let n = rectangles.length;
    let X = new Set(), Y = new Set();
    for (const rect of rectangles) {
        X.add(rect[0]);
        X.add(rect[2]);
        Y.add(rect[1]);
        Y.add(rect[3]);
    }
    let sortedX = Array.from(X).sort((a, b) => a - b);
    let sortedY = Array.from(Y).sort((a, b) => a - b);

    let cnt = Array.from({ length: X.size - 1 }, () => Array.from({ length: Y.size - 1 }, () => 0));

    for (const rect of rectangles) {
        let x1_idx = sortedX.indexOf(rect[0]);
        let x2_idx = sortedX.indexOf(rect[2]) - 1;
        let y1_idx = sortedY.indexOf(rect[1]);
        let y2_idx = sortedY.indexOf(rect[3]) - 1;
        for (let i = x1_idx; i <= x2_idx; i++) {
            for (let j = y1_idx; j <= y2_idx; j++) {
                cnt[i][j] = 1;
            }
        }
    }

    let total_area = 0;
    for (let i = 0; i < X.size - 1; i++) {
        for (let j = 0; j < Y.size - 1; j++) {
            if (cnt[i][j]) {
                total_area += (sortedX[i + 1] - sortedX[i]) * (sortedY[j + 1] - sortedY[j]);
                total_area %= mod;
            }
        }
    }

    return total_area;
}

java_code:
import java.util.Set;
import java.util.HashSet;
import java.util.StringJoiner;

public String toGoatLatin(String sentence) {
    String[] words = sentence.split(" ");
    String vowels = "AEIOUaeiou";
    Set<Character> vowelSet = new HashSet<>();

    for (char c : vowels.toCharArray()) {
        vowelSet.add(c);
    }

    StringJoiner result = new StringJoiner(" ");
    StringBuilder suffix = new StringBuilder("a");

    for (String word : words) {
        if (!vowelSet.contains(word.charAt(0))) {
            word = word.substring(1) + word.charAt(0);
        }
        result.add(word + "ma" + suffix);
        suffix.append("a");
    }

    return result.toString();
}

cpp_code:
#include <sstream>

std::string toGoatLatin(std::string sentence) {
    std::istringstream ss(sentence);
    std::string word, result, suffix = "a";
    const std::string vowels = "AEIOUaeiou";

    while (ss >> word) {
        if (vowels.find(word[0]) == std::string::npos) {
            word = word.substr(1) + word[0];
        }
        result += word + "ma" + suffix + " ";
        suffix += "a";
    }

    result.pop_back();
    return result;
}

python_code:
def to_goat_latin(sentence: str) -> str:
    words = sentence.split()
    vowels = set("AEIOUaeiou")
    result = []

    for i, word in enumerate(words):
        if word[0] not in vowels:
            word = word[1:] + word[0]
        result.append(word + "ma" + "a" * (i + 1))

    return ' '.join(result)

javascript_code:
function toGoatLatin(sentence) {
    const words = sentence.split(" ");
    const vowels = new Set("AEIOUaeiou");
    let result = [];
    let suffix = "a";

    words.forEach(word => {
        if (!vowels.has(word[0])) {
            word = word.slice(1) + word[0];
        }
        result.push(word + "ma" + suffix);
        suffix += "a";
    });

    return result.join(" ");
}

