#include <vector>
#include <algorithm>

int maxProfitAssignment(std::vector<int>& difficulty, std::vector<int>& profit, std::vector<int>& worker) {
    std::vector<std::pair<int, int>> jobs;
    for (int i = 0; i < difficulty.size(); ++i)
        jobs.push_back({difficulty[i], profit[i]});
    std::sort(jobs.begin(), jobs.end());
    std::sort(worker.begin(), worker.end());

    int i = 0, max_profit = 0, total_profit = 0;
    for (int& ability : worker) {
        while (i < difficulty.size() && ability >= jobs[i].first) {
            max_profit = std::max(max_profit, jobs[i].second);
            ++i;
        }
        total_profit += max_profit;
    }
    return total_profit;
}

python_code:
def max_profit_assignment(difficulty, profit, worker):
    jobs = sorted(zip(difficulty, profit))
    worker.sort()

    i, max_profit, total_profit = 0, 0, 0
    for ability in worker:
        while i < len(difficulty) and ability >= jobs[i][0]:
            max_profit = max(max_profit, jobs[i][1])
            i += 1
        total_profit += max_profit
    return total_profit

