            maxProfit = Math.max(maxProfit, jobs[i][1]);
            i++;
        }
        totalProfit += maxProfit;
    }
    return totalProfit;
}

java_code:
int kSimilarity(String s1, String s2) {
    int k = 0;
    StringBuilder sb = new StringBuilder(s1);

    for (int i = 0; i < sb.length(); i++) {
        if (sb.charAt(i) != s2.charAt(i)) {
            int j = i + 1;
            while (sb.charAt(j) != s2.charAt(i) || s2.charAt(j) == sb.charAt(j)) {
                j++;
            }
            sb.setCharAt(j, sb.charAt(i));
            sb.setCharAt(i, s2.charAt(i));
            k++;
        }
    }
    return k;
}

cpp_code:
int kSimilarity(const std::string& s1, const std::string& s2) {
    int k = 0;
    std::string temp = s1;

    for (int i = 0; i < temp.length(); ++i) {
        if (temp[i] != s2[i]) {
            int j = i + 1;
            while (temp[j] != s2[i] || s2[j] == temp[j]) {
                ++j;
            }
            std::swap(temp[i], temp[j]);
            k++;
        }
    }
    return k;
}

python_code:
def kSimilarity(s1: str, s2: str) -> int:
    k = 0
    temp = list(s1)

    for i in range(len(temp)):
        if temp[i] != s2[i]:
            j = i + 1
            while temp[j] != s2[i] or s2[j] == temp[j]:
                j += 1
            temp[i], temp[j] = temp[j], temp[i]
            k += 1

    return k

javascript_code:
function kSimilarity(s1, s2) {
    let k = 0;
    let temp = s1.split('');

    for (let i = 0; i < temp.length; i++) {
        if (temp[i] !== s2[i]) {
            let j = i + 1;
            while (temp[j] !== s2[i] || s2[j] === temp[j]) {
                j++;
            }
            [temp[i], temp[j]] = [temp[j], temp[i]];
            k++;
        }
    }
    return k;
}

java_code:
import java.util.HashSet;

public int countUniqueChars(String s) {
    HashSet<Character> uniqueChars = new HashSet<>();
    for (char c : s.toCharArray()) {
        uniqueChars.add(c);
    }
    return uniqueChars.size();
}

public int sumCountUniqueChars(String s) {
    int sum = 0;
    for (int i = 0; i < s.length(); ++i) {
        for (int j = i + 1; j <= s.length(); ++j) {
            sum += countUniqueChars(s.substring(i, j));
        }
    }
    return sum;
}

cpp_code:
#include <unordered_set>

int countUniqueChars(const std::string &s) {
    std::unordered_set<char> uniqueChars(s.begin(), s.end());
    return uniqueChars.size();
}

int sumCountUniqueChars(const std::string &s) {
    int sum = 0;
    for (int i = 0; i < s.size(); ++i) {
        for (int j = i + 1; j <= s.size(); ++j) {
            sum += countUniqueChars(s.substr(i, j - i));
        }
    }
    return sum;
}

