public int consecutiveNumbersSum(int n) {
    int count = 0;
    for (int i = 1; i * (i - 1) / 2 < n; i++) {
        if ((n - i * (i - 1) / 2) % i == 0) {
            count++;
        }
    }
    return count;
}

