#include <utility>

struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode(int x) : val(x), left(NULL), right(NULL) {}
};

class Solution {
public:
    TreeNode* subtreeWithAllDeepest(TreeNode* root) {
        return findDeepest(root).first;
    }

private:
    std::pair<TreeNode*, int> findDeepest(TreeNode* node) {
        if (node == nullptr) return {nullptr, 0};
        auto left = findDeepest(node->left);
        auto right = findDeepest(node->right);
        if (left.second == right.second) {
            return {node, left.second + 1};
        }
        return left.second > right.second ? std::make_pair(left.first, left.second + 1) : std::make_pair(right.first, right.second + 1);
    }
};

