var subtreeWithAllDeepest = function(root) {
    const findDeepest = (node) => {
        if (node === null) return {node: null, height: 0};
        const left = findDeepest(node.left);
        const right = findDeepest(node.right);
        if (left.height === right.height) {
            return {node: node, height: left.height + 1};
        }
        return left.height > right.height ? {node: left.node, height: left.height + 1} : {node: right.node, height: right.height + 1};
    };

    return findDeepest(root).node;
