#include <vector>
#include <set>

std::vector<int> advantageCount(std::vector<int>& nums1, std::vector<int>& nums2) {
    std::multiset<int> s(nums1.begin(), nums1.end());
    std::vector<int> res;
    for (int i : nums2) {
        auto it = s.upper_bound(i);
        if (it == s.end()) it = s.begin();
        res.push_back(*it);
        s.erase(it);
    }
    return res;
}

