java_code:
import java.util.ArrayList;
import java.util.List;

public List<Integer> splitIntoFibonacci(String num) {
    List<Integer> ans = new ArrayList<>();
    backtrack(num, ans, 0, 0, 0);
    return ans;
}

private boolean backtrack(String num, List<Integer> ans, int index, int prev1, int prev2) {
    if (index == num.length()) {
        return ans.size() >= 3;
    }
    long curr = 0;
    for (int i = index; i < num.length(); ++i) {
        if (i > index && num.charAt(index) == '0') {
            break;
        }
        curr = curr * 10 + num.charAt(i) - '0';
        if (curr > Integer.MAX_VALUE) {
            break;
        }

        if (ans.size() >= 2) {
            long sum = (long) prev1 + prev2;
            if (curr < sum) {
                continue;
            } else if (curr > sum) {
                break;
            }
        }

        ans.add((int) curr);
        if (backtrack(num, ans, i + 1, prev2, (int) curr)) {
            return true;
        }
        ans.remove(ans.size() - 1);
    }
    return false;
}

python_code:
def splitIntoFibonacci(num):
    ans = []
    def backtrack(index, prev1, prev2):
        if index == len(num):
            return len(ans) >= 3
        curr = 0
        for i in range(index, len(num)):
            if i > index and num[index] == '0':
                break
            curr = curr * 10 + ord(num[i]) - ord('0')
            if curr > 2**31 - 1:
                break
            if len(ans) >= 2:
                if curr < prev1 + prev2:
                    continue
                elif curr > prev1 + prev2:
                    break
            ans.append(curr)
            if backtrack(i + 1, prev2, curr):
                return True
            ans.pop()
        return False

    backtrack(0, 0, 0)
    return ans

