function splitIntoFibonacci(num) {
    const ans = [];
    const backtrack = (index, prev1, prev2) => {
        if (index === num.length) {
            return ans.length >= 3;
        }
        let curr = 0;
        for (let i = index; i < num.length; ++i) {
            if (i > index && num[index] === '0') {
                break;
            }
            curr = curr * 10 + num.charCodeAt(i) - 48;
            if (curr > 2**31 - 1) {
                break;
            }

            if (ans.length >= 2) {
                const sum = prev1 + prev2;
                if (curr < sum) {
                    continue;
                } else if (curr > sum) {
                    break;
                }
            }

            ans.push(curr);
            if (backtrack(i + 1, prev2, curr)) {
                return true;
            }
            ans.pop();
        }
        return false;
    }

    backtrack(0, 0, 0);
    return ans;
}

