        if (c != '#') {
            sStack.push(c);
        } else if (!sStack.empty()) {
            sStack.pop();
        }
    }

    for (char c : t) {
        if (c != '#') {
            tStack.push(c);
        } else if (!tStack.empty()) {
            tStack.pop();
        }
    }

    return sStack == tStack;
}

