    for (let key of [...counts.keys()].sort((a, b) => a - b)) {
        if (counts.get(key) > 0) {
            for (let i = groupSize - 1; i >= 0; --i) {
                if ((counts.get(key + i) || 0) < counts.get(key)) {
                    return false;
                }
                counts.set(key + i, counts.get(key + i) - counts.get(key));
            }
        }
    }

    return true;
}

