public int maxDistToClosest(int[] seats) {
    int maxDist = 0, lastPerson = -1;
    for (int i = 0; i < seats.length; ++i) {
        if (seats[i] == 1) {
            maxDist = lastPerson < 0 ? i : Math.max(maxDist, (i - lastPerson) / 2);
            lastPerson = i;
        }
    }
    return Math.max(maxDist, seats.length - 1 - lastPerson);
}

