class ExamRoom {
public:
    set<int> students;
    int n;

    ExamRoom(int n) {
        this->n = n;
    }

    int seat() {
        if (students.empty()) {
            students.insert(0);
            return 0;
        }

        int distance = *students.begin(), seat_index = 0;

        for (auto itr = next(students.begin()); itr != students.end(); ++itr) {
            auto prev = prev(itr);
            int d = (*itr - *prev) / 2;

            if (d > distance) {
                distance = d;
                seat_index = *prev + d;
            }
        }

        if (n - 1 - *students.rbegin() > distance)
            seat_index = n - 1;

        students.insert(seat_index);
        return seat_index;
    }

    void leave(int p) {
        students.erase(p);
    }
};

