class ExamRoom {
    constructor(n) {
        this.n = n;
        this.students = new Set();
    }

    seat() {
        if (this.students.size === 0) {
            this.students.add(0);
            return 0;
        }

        let distance = [...this.students][0], seatIndex = 0;

        for (let i = 0, prev = distance; i < this.students.size - 1; i++) {
            let srcArr = [...this.students.values()];
            let curr = srcArr[i + 1];
            let d = Math.floor((curr - prev) / 2);

            if (d > distance) {
                distance = d;
                seatIndex = prev + d;
            }
            prev = curr;
        }

        if (this.n - 1 - Array.from(this.students).pop() > distance)
            seatIndex = this.n - 1;

        this.students.add(seatIndex);
        return seatIndex;
    }

    leave(p) {
        this.students.delete(p);
    }
}

java_code:
int scoreOfParentheses(String s) {
    int score = 0, depth = 0;
    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) == '(')
            depth++;
        else {
            depth--;
            if (s.charAt(i - 1) == '(')
                score += 1 << depth;
        }
    }
    return score;
}

