public int matrixScore(int[][] grid) {
    int m = grid.length, n = grid[0].length;
    for (int i = 0; i < m; i++) {
        if (grid[i][0] == 0) {
            for (int j = 0; j < n; j++) {
                grid[i][j] = 1 - grid[i][j];
            }
        }
    }
    for (int j = 1; j < n; j++) {
        int count = 0;
        for (int i = 0; i < m; i++) {
            count += grid[i][j];
        }
        if (count <= m / 2) {
            for (int i = 0; i < m; i++) {
                grid[i][j] = 1 - grid[i][j];
            }
        }
    }
    int sum = 0;
    for (int i = 0; i < m; i++) {
        int num = 0;
        for (int j = 0; j < n; j++) {
            num = num * 2 + grid[i][j];
        }
        sum += num;
    }
    return sum;
}

