#include <deque>
#include <vector>
using namespace std;

int shortestSubarray(vector<int>& nums, int k) {
    int n = nums.size();
    vector<int> prefix_sum(n + 1, 0);
    for (int i = 0; i < n; i++) prefix_sum[i + 1] = prefix_sum[i] + nums[i];

    int res = n + 1;
    deque<int> dq;
    for (int i = 0; i < n + 1; i++) {
        while (!dq.empty() && prefix_sum[i] - prefix_sum[dq.front()] >= k) {
            res = min(res, i - dq.front());
            dq.pop_front();
        }
        while (!dq.empty() && prefix_sum[i] <= prefix_sum[dq.back()]) {
            dq.pop_back();
        }
        dq.push_back(i);
    }
    return res <= n ? res : -1;
}

python_code:
from collections import deque

def shortest_subarray(nums, k):
    n = len(nums)
    prefix_sum = [0] * (n + 1)
    for i in range(n):
        prefix_sum[i + 1] = prefix_sum[i] + nums[i]

    res = n + 1
    dq = deque()
    for i in range(n + 1):
        while dq and prefix_sum[i] - prefix_sum[dq[0]] >= k:
            res = min(res, i - dq.popleft())
        while dq and prefix_sum[i] <= prefix_sum[dq[-1]]:
            dq.pop()
        dq.append(i)

    return res if res <= n else -1

javascript_code:
function shortestSubarray(nums, k) {
    const n = nums.length;
    const prefixSum = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) prefixSum[i + 1] = prefixSum[i] + nums[i];

    let res = n + 1;
    const dq = [];
    for (let i = 0; i < n + 1; i++) {
        while (dq.length > 0 && prefixSum[i] - prefixSum[dq[0]] >= k) {
            res = Math.min(res, i - dq.shift());
        }
        while (dq.length > 0 && prefixSum[i] <= prefixSum[dq[dq.length - 1]]) {
            dq.pop();
        }
        dq.push(i);
    }
    return res <= n ? res : -1;
}

