int longestDistance(int n) {
    int last = -1, longest = 0;
    for (int i = 0; n > 0; n >>= 1, i++) {
        if ((n & 1) == 1) {
            if (last >= 0)
                longest = Math.max(longest, i - last);
            last = i;
        }
    }
    return longest;
}

