#include <vector>
#include <algorithm>
using namespace std;

vector<int> advantageCount(vector<int>& nums1, vector<int>& nums2) {
    multiset<int> s(nums1.begin(), nums1.end());
    vector<int> res;
    for (int num : nums2) {
        auto it = s.upper_bound(num);
        if (it == s.end())
            it = s.begin();
        res.push_back(*it);
        s.erase(it);
    }
    return res;
}

javascript_code:
function advantageCount(nums1, nums2) {
    const sortedNums1 = [...nums1].sort((a, b) => a - b);
    const res = [];

    for (const num of nums2) {
        let idx = binarySearch(sortedNums1, num);
        if (idx === sortedNums1.length) {
            idx = 0;
        }
        res.push(sortedNums1.splice(idx, 1)[0]);
    }

    return res;
}

function binarySearch(arr, target) {
    let left = 0, right = arr.length;
    while (left < right) {
        const mid = Math.floor((left + right) / 2);
        if (arr[mid] <= target) {
            left = mid + 1;
        } else {
            right = mid;
        }
    }
    return left;
}

