            if (i >= 0 && i < j) {
                longest.set(j * arr.length + k, (longest.get(i * arr.length + j) || 1) + 1);
                ans = Math.max(ans, longest.get(j * arr.length + k) + 1);
            }
        }
    }

    return ans >= 3 ? ans : 0;
}

