    def robotSim(self, commands: List[int], obstacles: List[List[int]]) -> int:
        dx = [0, 1, 0, -1]
        dy = [1, 0, -1, 0]
        x = y = di = 0
        obstacleSet = set(map(tuple, obstacles))

        ans = 0
        for cmd in commands:
            if cmd == -2:
                di = (di - 1) % 4
            elif cmd == -1:
                di = (di + 1) % 4
            else:
                for k in range(cmd):
                    nx = x + dx[di]
                    ny = y + dy[di]
                    if (nx, ny) not in obstacleSet:
                        x = nx
                        y = ny
                        ans = max(ans, x * x + y * y)

        return ans

