function minEatingSpeed(piles, h) {
  let left = 1, right = Math.max(...piles);
  while (left < right) {
    let mid = left + Math.floor((right - left) / 2);
    let totalHours = 0;
    for (let pile of piles)
      totalHours += Math.ceil(pile / mid);
    if (totalHours > h)
      left = mid + 1;
    else
      right = mid;
  }
  return left;
}

