public int nthMagicalNumber(int n, int a, int b) {
    long mod = 1000000007;
    long lcm = a * b / gcd(a, b);
    long left = 1, right = (long)1e14, mid;
    while(left < right) {
        mid = left + (right - left) / 2;
        if ((mid / a + mid / b - mid / lcm) < n) {
            left = mid + 1;
        } else {
            right = mid;
        }
    }
    return (int)(left % mod);
}

public int gcd(int a, int b) {
    return b == 0 ? a : gcd(b, a % b);
}

