    const mod = 1e9 + 7;
    const lcm = a * b / gcd(a, b);
    let left = 1, right = 1e14, mid;
    while(left < right) {
        mid = left + Math.trunc((right - left) / 2);
        if (Math.trunc(mid / a + mid / b - mid / lcm) < n) {
            left = mid + 1;
        } else {
            right = mid;
        }
    }
    return left % mod;
}

