import java.util.Random;

class Solution {
    private int[] prefixSum;
    private Random random;

    public Solution(int[] w) {
        prefixSum = new int[w.length];
        prefixSum[0] = w[0];
        for (int i = 1; i < w.length; i++) {
            prefixSum[i] = prefixSum[i - 1] + w[i];
        }
        random = new Random();
    }

    public int pickIndex() {
        int num = random.nextInt(prefixSum[prefixSum.length - 1]) + 1;
        int idx = 0;
        while (num > prefixSum[idx]) {
            idx++;
        }
        return idx;
    }
}

cpp_code:
#include <vector>
#include <random>

class Solution {
public:
    std::vector<int> prefixSum;
    std::default_random_engine generator;
    std::uniform_real_distribution<double> distribution;

    Solution(std::vector<int>& w) {
        prefixSum.push_back(w[0]);
        for (size_t i = 1; i < w.size(); ++i) {
            prefixSum.push_back(prefixSum.back() + w[i]);
        }
        distribution = std::uniform_real_distribution<double>(0, prefixSum.back());
    }

    int pickIndex() {
        double num = distribution(generator);
        return std::lower_bound(prefixSum.begin(), prefixSum.end(), num) - prefixSum.begin();
    }
};

