            this.prefixSum[i] = this.prefixSum[i - 1] + w[i];
        }
    }

    pickIndex() {
        const num = Math.random() * this.prefixSum[this.prefixSum.length - 1];
        let idx = 0;
        while (num >= this.prefixSum[idx]) {
            idx++;
        }
        return idx;
    }
}

