class Solution {
    constructor(m, n) {
        this.grid = new Array(m).fill(0).map(() => new Array(n).fill(0));
        this.zeroCount = m * n;
    }

    pick() {
        let index = Math.floor(Math.random() * this.zeroCount);

        for (let i = 0; i < this.grid.length; i++) {
            for (let j = 0; j < this.grid[0].length; j++) {
                if (this.grid[i][j] === 0) {
                    if (index === 0) {
                        this.grid[i][j] = 1;
                        this.zeroCount--;
                        return [i, j];
                    }
                    index--;
                }
            }
        }
        return [-1, -1];  // Should not happen
    }
}

