public int projectionArea(int[][] grid) {
    int n = grid.length;
    int top = 0, front = 0, side = 0;
    for (int i = 0; i < n; i++) {
        int maxFront = 0, maxSide = 0;
        for (int j = 0; j < n; j++) {
            if (grid[i][j] > 0) {
                top++;
            }
            maxFront = Math.max(maxFront, grid[i][j]);
            maxSide = Math.max(maxSide, grid[j][i]);
        }
        front += maxFront;
        side += maxSide;
    }
    return top + front + side;
}

