import java.util.*;

class FreqStack {
    private Map<Integer, Integer> freq;
    private Map<Integer, Stack<Integer>> group;

    public FreqStack() {
        freq = new HashMap<>();
        group = new TreeMap<>(Collections.reverseOrder());
    }

    public void push(int x) {
        int f = freq.getOrDefault(x, 0) + 1;
        freq.put(x, f);
        group.computeIfAbsent(f, k -> new Stack<>()).push(x);
    }

    public int pop() {
        int x = group.get(group.keySet().iterator().next()).pop();
        int f = freq.get(x) - 1;
        freq.put(x, f);

        if (group.get(f + 1).empty()) {
            group.remove(f + 1);
        }

        return x;
    }
}

cpp_code:
#include <unordered_map>
#include <map>
#include <stack>

class FreqStack {
    std::unordered_map<int, int> freq;
    std::map<int, std::stack<int>> group;

public:
    FreqStack() {}

    void push(int x) {
        int f = ++freq[x];
        group[f].push(x);
    }

    int pop() {
        auto& st = group.rbegin()->second;
        int x = st.top();
        st.pop();
        if (st.empty()) {
            group.erase(group.rbegin()->first);
        }
        --freq[x];
        return x;
    }
};

python_code:
from collections import defaultdict, deque

class FreqStack:
    def __init__(self):
        self.freq = defaultdict(int)
        self.group = defaultdict(list)

    def push(self, x: int):
        freq = self.freq[x] = self.freq[x] + 1
        self.group[freq].append(x)

    def pop(self) -> int:
        max_freq = max(self.group)
        x = self.group[max_freq].pop()
        self.freq[x] -= 1
        if not self.group[max_freq]:
            del self.group[max_freq]
        return x

javascript_code:
class FreqStack {
    constructor() {
        this.freq = new Map();
        this.group = new Map();
    }

    push(x) {
        let f = (this.freq.get(x) || 0) + 1;
        this.freq.set(x, f);
        let stack = this.group.get(f) || [];
        stack.push(x);
        this.group.set(f, stack);
    }

    pop() {
        let maxFreq = Math.max(...this.group.keys());
        let stack = this.group.get(maxFreq);
        let x = stack.pop();
        this.freq.set(x, this.freq.get(x) - 1);
        if (stack.length === 0) {
            this.group.delete(maxFreq);
        } else {
            this.group.set(maxFreq, stack);
        }
        return x;
    }
}

