#include <set>
#include <vector>

int subarrayBitwiseORs(std::vector<int>& arr) {
    std::set<int> result, current, temp;
    for (int num : arr) {
        temp = {num};
        for (int c : current) {
            temp.insert(num | c);
        }
        current = std::move(temp);
        result.insert(current.begin(), current.end());
    }
    return result.size();
}

