#include <vector>
#include <stack>

class StockSpanner {
public:
    std::vector<int> prices;
    std::stack<int> index_stack;

    StockSpanner() {}

    int next(int price) {
        while (!index_stack.empty() && prices[index_stack.top()] <= price) {
            index_stack.pop();
        }
        int span = index_stack.empty() ? prices.size() + 1 : prices.size() - index_stack.top();
        index_stack.push(prices.size());
        prices.push_back(price);
        return span;
    }
};

