        while (this.indexStack.length > 0 && this.prices[this.indexStack[this.indexStack.length - 1]] <= price) {
            this.indexStack.pop();
        }
        const span = this.indexStack.length === 0 ? this.prices.length + 1 : this.prices.length - this.indexStack[this.indexStack.length - 1];
        this.indexStack.push(this.prices.length);
        this.prices.push(price);
        return span;
    }
}

