#include <vector>
#include <string>
using namespace std;

int num_digits_less_than_n(vector<int>& digits, int n) {
    int ans = 0, factor = 1;
    string n_str = to_string(n);
    for (int i = n_str.size() - 1; i >= 0; --i) {
        ans += (upper_bound(digits.begin(), digits.end(), n_str[i] - '0') - digits.begin()) * factor;
        factor *= digits.size();
    }
    return ans;
}

javascript_code:
function numDigitsLessThanN(digits, n) {
    let ans = 0, factor = 1;
    let nStr = String(n);
    for (let i = nStr.length - 1; i >= 0; --i) {
        ans += (upperBound(digits, nStr.charCodeAt(i) - 48)) * factor;
        factor *= digits.length;
    }
    return ans;
}

function upperBound(arr, target) {
    let low = 0, high = arr.length;
    while (low < high) {
        let mid = Math.floor((low + high) / 2);
        if (arr[mid] > target) high = mid;
        else low = mid + 1;
    }
    return low;
}

