public int findValidPermutations(String s) {
    int n = s.length();
    long[] dp = new long[n + 2];
    dp[0] = 1;
    int MOD = 1000000007;

    for (char c : s.toCharArray()) {
        long[] new_dp = new long[n + 2];
        if (c == 'I') {
            for (int i = 0; i < n; ++i) {
                new_dp[i + 1] = (new_dp[i + 1] + dp[i]) % MOD;
            }
        } else {
            for (int i = n - 1; i >= 0; --i) {
                new_dp[i] = (new_dp[i + 1] + dp[i + 1]) % MOD;
            }
        }
        dp = new_dp;
    }
    return (int) dp[0];
}

