void moveEvenOdd(vector<int>& nums) {
    int evenIndex = 0;
    int oddIndex = nums.size() - 1;

    while (evenIndex < oddIndex) {
        if (nums[evenIndex] % 2 == 0) {
            evenIndex++;
        } else {
            swap(nums[evenIndex], nums[oddIndex]);
            oddIndex--;
        }
    }
}

