    }
    return ans;
}

java_code:
public int minDifference(int[] nums, int k) {
    if(nums.length <= 1) return 0;
    Arrays.sort(nums);
    int min_diff = nums[nums.length - 1] - nums[0];
    for(int i = 1; i < nums.length; i++) {
        int high = Math.max(nums[i - 1] + k, nums[nums.length - 1] - k);
        int low = Math.min(nums[i] - k, nums[0] + k);
        min_diff = Math.min(min_diff, high - low);
    }
    return min_diff;
}

cpp_code:
int minDifference(vector<int>& nums, int k) {
    if(nums.size() <= 1) return 0;
    sort(nums.begin(), nums.end());
    int min_diff = nums.back() - nums.front();
    for(int i=1; i<nums.size(); i++) {
        int high = max(nums[i-1] + k, nums.back() - k);
        int low = min(nums[i] - k, nums.front() + k);
        min_diff = min(min_diff, high - low);
    }
    return min_diff;
}

