    nums.sort((a, b) => a - b);
    let min_diff = nums[nums.length - 1] - nums[0];
    for(let i = 1; i < nums.length; i++) {
        let high = Math.max(nums[i - 1] + k, nums[nums.length - 1] - k);
        let low = Math.min(nums[i] - k, nums[0] + k);
        min_diff = Math.min(min_diff, high - low);
    }
    return min_diff;
}

java_code:
public int snakesAndLadders(int[][] board) {
    int n = board.length;
    int[] flattenedBoard = new int[n * n + 1];
    boolean isRight = true;
    int idx = 1;
    for (int i = n - 1; i >= 0; i--) {
        if (isRight) {
            for (int j = 0; j < n; j++) {
                flattenedBoard[idx++] = board[i][j];
            }
        } else {
            for (int j = n - 1; j >= 0; j--) {
                flattenedBoard[idx++] = board[i][j];
            }
        }
        isRight = !isRight;
    }

    int[] moves = new int[n * n + 1];
    Arrays.fill(moves, -1);
    moves[1] = 0;
    for (int i = 0; i < moves.length; i++) {
        if (moves[i] != -1) {
            for (int j = 1; j <= 6 && i + j < moves.length; j++) {
                int nextPos = i + j;
                int value = flattenedBoard[nextPos];
                if (value == -1) {
                    value = nextPos;
                }
                if (moves[value] == -1) {
                    moves[value] = moves[i] + 1;
                }
            }
        }
    }
    return moves[n * n];
}

cpp_code:
int snakesAndLadders(vector<vector<int>> &board) {
    int n = board.size();
    auto getRowCol = [&](int x) {
        int r = (x - 1) / n, c = (x - 1) % n;
        if (r % 2) c = n - 1 - c;
        return make_pair(n - 1 - r, c);
    };

    vector<bool> visited(n * n + 1, false);
    queue<pair<int, int>> q;
    q.push({1, 0});
    visited[1] = true;

    while (!q.empty()) {
        auto cur = q.front(); q.pop();
        int x = cur.first;
        int steps = cur.second;
        for (int jump = 1; jump <= 6; jump++) {
            int next_x = x + jump;
            if (next_x > n * n) break;
            auto nextRC = getRowCol(next_x);
            if (board[nextRC.first][nextRC.second] != -1) {
                next_x = board[nextRC.first][nextRC.second];
            }
            if (next_x == n * n) return steps + 1;
            if (!visited[next_x]) {
                visited[next_x] = true;
                q.push({next_x, steps + 1});
            }
        }
    }
    return -1;
}

python_code:
def snakesAndLadders(board):
    n = len(board)
    visited = [False] * (n*n + 1)
    queue = [(1, 0)]  # starting at position 1
    visited[1] = True

    def get_position(pos):
        r = (pos - 1) // n
        c = (pos - 1) % n
        if r % 2 == 1:
            c = n - 1 - c
        r = n - r - 1
        return r, c

    while queue:
        pos, steps = queue.pop(0)
        for jump in range(1, 7):
            next_pos = pos + jump
            if next_pos > n*n:
                break
            r, c = get_position(next_pos)
            if board[r][c] != -1:
                next_pos = board[r][c]
            if next_pos == n*n:
                return steps + 1
            if not visited[next_pos]:
                visited[next_pos] = True
                queue.append((next_pos, steps + 1))

    return -1

javascript_code:
function snakesAndLadders(board) {
  const n = board.length;
  const visited = new Array(n * n + 1).fill(false);
  const queue = [{ pos: 1, steps: 0 }];
  visited[1] = true;

  function getPosition(pos) {
    const row = Math.ceil(pos / n);
    let col = ((row % 2) === 0) ? n - (pos % n) : (pos % n) + 1;
    if (col === n + 1) {
      col = 1;
    }
    return [n - row, col - 1];
  }

  while (queue.length) {
    const { pos, steps } = queue.shift();

    for (let jump = 1; jump <= 6; jump++) {
      let nextPos = pos + jump;
      if (nextPos > n * n) break;
      const [r, c] = getPosition(nextPos);
      if (board[r][c] !== -1) {
        nextPos = board[r][c];
      }
      if (nextPos === n * n) return steps + 1;
      if (!visited[nextPos]) {
        visited[nextPos] = true;
        queue.push({ pos: nextPos, steps: steps + 1 });
      }
    }
  }
  return -1;
}

