bool canReorderDoubled(vector<int>& arr) {
    map<int, int> count;
    for (int a : arr) {
        count[a]++;
    }

    for (const auto& [a, c] : count) {
        if (c > 0) {
            int target = a < 0 ? a / 2 : a * 2;
            if (count[target] < c) return false;
            count[target] -= c;
        }
    }

    return true;
}

