var canReorderDoubled = function(arr) {
    const count = new Map();
    arr.sort((a, b) => Math.abs(a) - Math.abs(b));

    for (const a of arr) {
        if (!count.has(a)) {
            count.set(a, 0);
        }
        count.set(a, count.get(a) + 1);
    }

    for (const a of count.keys()) {
        if (count.get(a) > 0) {
            const target = a < 0 ? a / 2 : a * 2;
            if (!count.has(target) || count.get(target) < count.get(a)) {
                return false;
            }
            count.set(target, count.get(target) - count.get(a));
        }
    }

    return true;
};

java_code:
import java.util.LinkedList;
import java.util.Queue;

class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode(int x) { val = x; }
}

class CBTInserter {
    TreeNode root;
    Queue<TreeNode> q;

    public CBTInserter(TreeNode root) {
        this.root = root;
        q = new LinkedList<>();
        q.add(root);
        while (true) {
            TreeNode node = q.peek();
            if (node.left == null || node.right == null) break;
            q.add(node.left);
            q.add(node.right);
            q.poll();
        }
    }

    public int insert(int v) {
        TreeNode newNode = new TreeNode(v);
        TreeNode parentNode = q.peek();
        if (parentNode.left == null) {
            parentNode.left = newNode;
        } else {
            parentNode.right = newNode;
            q.add(parentNode.left);
            q.add(parentNode.right);
            q.poll();
        }
        return parentNode.val;
    }

    public TreeNode get_root() {
        return root;
    }
}

