        TreeNode* newNode = new TreeNode(v);
        TreeNode* parentNode = q.front();
        if (!parentNode->left) {
            parentNode->left = newNode;
        } else {
            parentNode->right = newNode;
            q.push(parentNode->left);
            q.push(parentNode->right);
            q.pop();
        }
        return parentNode->val;
    }

    TreeNode* get_root() {
        return root;
    }
};

