    const int mod = 1e9 + 7;
    vector<vector<int>> moves = {
        {4, 6}, {6, 8}, {7, 9}, {4, 8}, {0, 3, 9},
        {}, {1, 7, 0}, {2, 6}, {1, 3}, {2, 4}
    };
    vector<int> dp(10, 1);
    for (int i = 2; i <= n; ++i) {
        vector<int> new_dp(10, 0);
        for (int j = 0; j < 10; ++j)
            for (const auto& move : moves[j])
                new_dp[j] = (new_dp[j] + dp[move]) % mod;
        dp = std::move(new_dp);
    }
    return accumulate(dp.begin(), dp.end(), 0, [&](int a, int b) { return (a + b) % mod; });
}

