java_code:
public int subarraysDivByK(int[] nums, int k) {
    int[] prefixSumsModK = new int[k];
    prefixSumsModK[0] = 1;
    int runningSum = 0;
    int count = 0;

    for (int i = 0; i < nums.length; ++i) {
        runningSum += nums[i];
        int mod = (runningSum % k + k) % k;
        count += prefixSumsModK[mod]++;
    }

    return count;
}

