public int[] decode_permutation(String s) {
    int n = s.length();
    int[] perm = new int[n + 1];
    int next_zero = 0, next_one = n;

    for (char c : s.toCharArray()) {
        if (c == '0') {
            perm[next_zero++] = next_one--;
        } else {
            perm[next_one--] = next_zero++;
        }
    }
    perm[next_zero] = next_one;
    return perm;
}

