java_code:
import java.util.*;

class Solution {
    public int removeStones(int[][] stones) {
        int n = stones.length;
        Map<Integer, Integer> row_groups = new HashMap<>();
        Map<Integer, Integer> col_groups = new HashMap<>();
        int group_count = 0;

        int[][] groups = new int[n * 2][n];
        int[] group_sizes = new int[n * 2];

        for (int i = 0; i < n; i++) {
            int x = stones[i][0], y = stones[i][1];
            int groupId_x = row_groups.computeIfAbsent(x, (key) -> group_count++);
            int groupId_y = col_groups.computeIfAbsent(y + 10001, (key) -> group_count++); // Offset by max row index

            groups[groupId_x][group_sizes[groupId_x]++] = groupId_y;
            groups[groupId_y][group_sizes[groupId_y]++] = groupId_x;
        }

        boolean[] visited = new boolean[group_count];

        int max_stones = 0;
        for (int groupId = 0; groupId < group_count; groupId++) {
            if (!visited[groupId]) {
                Stack<Integer> stack = new Stack<>();
                stack.push(groupId);
                visited[groupId] = true;
                int size = 0;

                while (!stack.isEmpty()) {
                    int curr = stack.pop();
                    size++;
                    for (int i = 0; i < group_sizes[curr]; i++) {
                        int neighbor = groups[curr][i];
                        if (!visited[neighbor]) {
                            stack.push(neighbor);
                            visited[neighbor] = true;
                        }
                    }
                }

                max_stones += size - 1;
            }
        }

        return max_stones;
    }
}

cpp_code:
#include <unordered_map>
#include <vector>

int removeStones(std::vector<std::vector<int>>& stones) {
    std::unordered_map<int, int> row_groups, col_groups;
    int group_count = 0;

    std::function<int(int, bool)> getGroupId = [&](int idx, bool isRow) -> int {
        auto& groups = isRow ? row_groups : col_groups;
        if (!groups.count(idx)) {
            groups[idx] = group_count++;
        }
        return groups[idx];
    };

    std::vector<std::vector<int>> groups(group_count);
    for (auto& [x, y] : stones) {
        int group_x = getGroupId(x, true);
        int group_y = getGroupId(10001 + y, false); // Offset by max row index
        groups[group_x].push_back(group_y);
        groups[group_y].push_back(group_x);
    }

    int max_stones = 0;
    std::vector<bool> visited(group_count);

    auto dfs = [&](int groupId, auto& dfs_ref) -> int {
        if (visited[groupId]) return 0;
        visited[groupId] = true;
        int size = 1;
        for (int neighbor : groups[groupId]) {
            size += dfs_ref(neighbor, dfs_ref);
        }
        return size;
    };

    for (int groupId = 0; groupId < group_count; groupId++) {
        max_stones += dfs(groupId, dfs) - 1;
    }

    return max_stones;
}

javascript_code:
function removeStones(stones) {
    let row_groups = new Map(),
        col_groups = new Map(),
        groups = new Map(),
        group_count = 0;

    for (const [x, y] of stones) {
        if (!row_groups.has(x)) {
            row_groups.set(x, group_count++);
        }
        if (!col_groups.has(y + 10001)) { // Offset by max row index
            col_groups.set(y + 10001, group_count++);
        }
        let group_x = row_groups.get(x),
            group_y = col_groups.get(y + 10001);

        if (!groups.has(group_x)) {
            groups.set(group_x, []);
        }
        if (!groups.has(group_y)) {
            groups.set(group_y, []);
        }
        groups.get(group_x).push(group_y);
        groups.get(group_y).push(group_x);
    }

    let visited = new Array(group_count).fill(false);

    function dfs(groupId) {
        if (visited[groupId]) {
            return 0;
        }
        visited[groupId] = true;
        let size = 1;

        for (const neighbor of groups.get(groupId)) {
            size += dfs(neighbor);
        }

        return size;
    }

    let max_stones = 0;
    for (let groupId = 0; groupId < group_count; groupId++) {
        max_stones += dfs(groupId) - 1;
    }

    return max_stones;
}

