from itertools import permutations

def largestTimeFromDigits(arr):
    max_time = -1
    for h, i, j, k in permutations(arr):
        hour = h * 10 + i
        minute = j * 10 + k
        time = hour * 60 + minute
        if hour < 24 and minute < 60 and time > max_time:
            max_time = time

    if max_time == -1:
        return ""
    else:
        return "{:02d}:{:02d}".format(max_time // 60, max_time % 60)

javascript_code:
function largestTimeFromDigits(arr) {
    let maxTime = -1;
    for (let i = 0; i < 4; i++) {
        if (arr[i] > 2) continue;
        for (let j = 0; j < 4; j++) {
            if (j === i || (arr[i] === 2 && arr[j] > 3)) continue;
            for (let k = 0; k < 4; k++) {
                if (k === i || k === j || arr[k] > 5) continue;
                let l = 6 - i - j - k;
                let time = 60 * (10 * arr[i] + arr[j]) + 10 * arr[k] + arr[l];
                maxTime = Math.max(maxTime, time);
            }
        }
    }
    if (maxTime === -1) return "";
    else return `${String(Math.trunc(maxTime / 60)).padStart(2, '0')}:${String(maxTime % 60).padStart(2, '0')}`;
}

