import java.util.*;

public int[] deckRevealedIncreasing(int[] deck) {
    int n = deck.length;
    Queue<Integer> index = new LinkedList<>();
    for (int i = 0; i < n; i++)
        index.add(i);

    int[] ans = new int[n];
    Arrays.sort(deck);
    for (int card : deck) {
        ans[index.poll()] = card;
        if (!index.isEmpty()) {
            index.add(index.poll());
        }
    }
    return ans;
}

cpp_code:
#include <vector>
#include <deque>
#include <algorithm>

std::vector<int> deckRevealedIncreasing(std::vector<int>& deck) {
    int n = deck.size();
    std::deque<int> index;
    for (int i = 0; i < n; ++i)
        index.push_back(i);

    std::vector<int> ans(n);
    std::sort(deck.begin(), deck.end());

    for (int card : deck) {
        ans[index.front()] = card;
        index.pop_front();
        if (!index.empty()) {
            index.push_back(index.front());
            index.pop_front();
        }
    }

    return ans;
}

javascript_code:
function deckRevealedIncreasing(deck) {
    const n = deck.length;
    const index = [];
    for (let i = 0; i < n; i++) {
        index.push(i);
    }

    const ans = new Array(n);
    deck.sort((a, b) => a - b);

    for (const card of deck) {
        ans[index.shift()] = card;
        if (index.length) {
            index.push(index.shift());
        }
    }
    return ans;
}

