from collections import defaultdict

def largestComponentSize(nums):
    def primes(n):
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return i
        return n

    def dfs(node, visited, graph):
        if node in visited:
            return 0
        visited.add(node)
        size = 1
        for neighbor in graph[node]:
            size += dfs(neighbor, visited, graph)
        return size

    graph = defaultdict(set)
    visited = set()

    for num in nums:
        prime = primes(num)
        graph[prime].add(num)
        if num != prime:
            graph[num].add(prime)

    count = 0
    for num in nums:
        count = max(count, dfs(num, visited, graph))

    return count

javascript_code:
function largestComponentSize(nums) {
    function primes(n) {
        for (let i = 2; i * i <= n; ++i) {
            if (n % i === 0) return i;
        }
        return n;
    }

    function dfs(node, visited, graph) {
        if (visited.has(node)) return 0;
        visited.add(node);
        let size = 1;
        for (let neighbor of graph[node]) {
            size += dfs(neighbor, visited, graph);
        }
        return size;
    }

    const graph = new Map();
    const visited = new Set();

    for (const num of nums) {
        const prime = primes(num);
        if (!graph.has(prime)) graph.set(prime, new Set());
        graph.get(prime).add(num);
        if (num !== prime) {
            if (!graph.has(num)) graph.set(num, new Set());
            graph.get(num).add(prime);
        }
    }

    let count = 0;
    for (const num of nums) {
        count = Math.max(count, dfs(num, visited, graph));
    }

    return count;
}

