#include <vector>
#include <unordered_map>
#include <algorithm>

bool canReorderArray(std::vector<int>& arr) {
    std::unordered_map<int, int> count;
    for (int n : arr) {
        count[n]++;
    }
    sort(arr.begin(), arr.end());
    for (int x : arr) {
        if (count[x] == 0) {
            continue;
        }
        if (count[2 * x] > 0) {
            count[x]--;
            count[2 * x]--;
        } else {
            return false;
        }
    }
    return true;
}

