#include <vector>
#include <string>
using namespace std;

int minDeletionSize(vector<string>& strs) {
    int n = strs.size();
    int m = strs[0].length();
    vector<int> dp(m, 1);

    for (int j = 0; j < m; ++j)
        for (int i = 0; i < j; ++i) {
            bool flag = true;
            for (int k = 0; k < n - 1; ++k)
                flag = flag && (strs[k][i] <= strs[k][j]);
            dp[j] = flag ? max(dp[j], dp[i] + 1) : dp[j];
        }

    return m - *max_element(dp.begin(), dp.end());
}

python_code:
class Solution:
    def minDeletionSize(self, strs: List[str]) -> int:
        n = len(strs)
        m = len(strs[0])
        dp = [1] * m

        for j in range(m):
            for i in range(j):
                flag = all(strs[k][i] <= strs[k][j] for k in range(n - 1))
                dp[j] = max(dp[j], dp[i] + 1) if flag else dp[j]

        return m - max(dp)

