var minDeletionSize = function (strs) {
  let n = strs.length;
  let m = strs[0].length;
  let dp = new Array(m).fill(1);

  for (let j = 0; j < m; ++j) {
    for (let i = 0; i < j; ++i) {
      let flag = true;
      for (let k = 0; k < n - 1; ++k)
        flag = flag && (strs[k][i] <= strs[k][j]);
      dp[j] = flag ? Math.max(dp[j], dp[i] + 1) : dp[j];
    }
  }

  return m - Math.max(...dp);
};

