public int minKBitFlips(int[] nums, int k) {
    int n = nums.length;
    int[] flipped = new int[n];
    int flips = 0, ans = 0;
    for (int i = 0; i < n; ++i) {
        if (i >= k) flips -= flipped[i - k];
        if ((flips + nums[i]) % 2 == 0) {
            if (i + k > n) return -1;
            flipped[i] = 1;
            flips++;
            ans++;
        }
    }
    return ans;
}

cpp_code:
int minKBitFlips(vector<int>& nums, int k) {
    int n = nums.size();
    vector<int> flipped(n, 0);
    int flips = 0, ans = 0;
    for (int i = 0; i < n; ++i) {
        if (i >= k) flips = (flips - flipped[i - k]) % 2;
        if ((flips + nums[i]) % 2 == 0) {
            if (i + k > n) return -1;
            flipped[i] = 1;
            flips = (flips + 1) % 2;
            ans++;
        }
    }
    return ans;
}

