java_code:
import java.util.HashMap;
import java.util.Map;

public int numSquarefulPerms(int[] nums) {
    Map<Integer, Integer> counter = new HashMap<>();
    for (int num : nums)
        counter.put(num, counter.getOrDefault(num, 0) + 1);

    return dfs(nums, 0, counter);
}

private boolean isSquare(int n) {
    int root = (int) Math.sqrt(n);
    return root * root == n;
}

private int dfs(int[] nums, int idx, Map<Integer, Integer> counter) {
    if (idx == nums.length)
        return 1;

    int count = 0;
    for (int key : counter.keySet()) {
        if (counter.get(key) != 0 && (idx == 0 || isSquare(nums[idx - 1] + key))) {
            counter.put(key, counter.get(key) - 1);
            nums[idx] = key;
            count += dfs(nums, idx + 1, counter);
            counter.put(key, counter.get(key) + 1);
        }
    }

    return count;
}

cpp_code:
#include <vector>
#include <unordered_map>

bool isSquare(int n) {
    int root = sqrt(n);
    return root * root == n;
}

void dfs(std::vector<int>& nums, int idx, int& count,
         std::unordered_map<int, int>& counter) {
    if (idx == nums.size()) {
        count++;
        return;
    }

    for (auto it : counter) {
        if (it.second && (idx == 0 || isSquare(nums[idx - 1] + it.first))) {
            counter[it.first]--;
            nums[idx] = it.first;
            dfs(nums, idx + 1, count, counter);
            counter[it.first]++;
        }
    }
}

int numSquarefulPerms(std::vector<int>& nums) {
    std::unordered_map<int, int> counter;
    for (int num : nums)
        counter[num]++;

    int count = 0;
    dfs(nums, 0, count, counter);
    return count;
}

python_code:
from collections import Counter

def numSquarefulPerms(nums):
    def is_square(n):
        return int(n ** 0.5) ** 2 == n

    def dfs(idx):
        if idx == len(nums):
            return 1

        count = 0
        for key in counter.keys():
            if counter[key] and (idx == 0 or is_square(nums[idx - 1] + key)):
                counter[key] -= 1
                nums[idx] = key
                count += dfs(idx + 1)
                counter[key] += 1

        return count

    key_set, counter = set(nums), Counter(nums)
    return dfs(0)

javascript_code:
function numSquarefulPerms(nums) {
    const counter = new Map();
    nums.forEach(num => counter.set(num, (counter.get(num) || 0) + 1));

    const isSquare = n => {
        const root = Math.sqrt(n);
        return Math.floor(root) * Math.floor(root) === n;
    };

    const dfs = (idx) => {
        if (idx === nums.length)
            return 1;

        let count = 0;
        for (let key of counter.keys()) {
            if (counter.get(key) !== 0 && (idx === 0 || isSquare(nums[idx - 1] + key))) {
                counter.set(key, counter.get(key) - 1);
                nums[idx] = key;
                count += dfs(idx + 1);
                counter.set(key, counter.get(key) + 1);
            }
        }

        return count;
    };

    return dfs(0);
}

