    def __init__(self, x):
        self.val = x
        self.left = None
        self.right = None

def is_complete_tree(root: TreeNode) -> bool:
    if not root:
        return True

    queue = [root]
    while queue[0]:
        node = queue.pop(0)
        queue.append(node.left)
        queue.append(node.right)
    while queue and not queue[0]:
        queue.pop(0)
    return not queue

