function isCompleteTree(root) {
    if (!root) return true;

    let queue = [root];
    let hasGap = false;
    while (queue.length) {
        let node = queue.shift();
        if (node.left) {
            if (hasGap) return false;
            queue.push(node.left);
        } else {
            hasGap = true;
        }
        if (node.right) {
            if (hasGap) return false;
            queue.push(node.right);
        } else {
            hasGap = true;
        }
    }
    return true;
}

