                for (int y2 : ys2) {
                    if (ys1.find(y2) != ys1.end() && ys2.find(y1) != ys2.end()) {
                        double area = sqrt(pow(x1 - x2, 2) + pow(y1 - y2, 2)) * sqrt(pow(x1 - x2, 2) + pow(y1 - y1, 2));
                        minArea = min(minArea, area);
                    }
                }
            }
        }
    }

    return minArea == numeric_limits<double>::infinity() ? 0 : minArea;
}

