        } else if (wordMapLowerCase[lowerQuery]) {
            result.push(wordMapLowerCase[lowerQuery]);
        } else if (wordMapVowelReplaced[vowelReplacedQuery]) {
            result.push(wordMapVowelReplaced[vowelReplacedQuery]);
        } else {
            result.push("");
        }
    }

    return result;
}

