std::vector<int> powerful_integers(int x, int y, int bound) {
    std::set<int> result;
    for (int i = 0; pow(x, i) <= bound; ++i) {
        for (int j = 0; pow(x, i) + pow(y, j) <= bound; ++j) {
            result.insert(pow(x, i) + pow(y, j));
        }
    }
    return std::vector<int>(result.begin(), result.end());
}

