#include <vector>
#include <queue>
using namespace std;

void flipRecur(TreeNode* node, vector<int>& voyage, int& idx, vector<int>& flipped)
{
    if (node == nullptr) return;
    if (node->val != voyage[idx++])
    {
        flipped = {-1};
        return;
    }
    if (idx < voyage.size() && node->left != nullptr && node->left->val != voyage[idx])
    {
        flipped.push_back(node->val);
        flipRecur(node->right, voyage, idx, flipped);
        flipRecur(node->left, voyage, idx, flipped);
    }
    else
    {
        flipRecur(node->left, voyage, idx, flipped);
        flipRecur(node->right, voyage, idx, flipped);
    }
}

vector<int> flipMatchVoyage(TreeNode* root, vector<int>& voyage) {
    vector<int> flipped;
    int idx = 0;
    flipRecur(root, voyage, idx, flipped);
    return flipped;
}

javascript_code:
function flipRecur(node, voyage, flipped, idx) {
    if (!node) return idx;
    if (node.val !== voyage[idx]) {
        flipped[0] = -1;
        return idx;
    }
    idx++;
    if (idx < voyage.length && node.left !== null && node.left.val !== voyage[idx]) {
        flipped.push(node.val);
        idx = flipRecur(node.right, voyage, flipped, idx);
        idx = flipRecur(node.left, voyage, flipped, idx);
    } else {
        idx = flipRecur(node.left, voyage, flipped, idx);
        idx = flipRecur(node.right, voyage, flipped, idx);
    }
    return idx;
}

function flipMatchVoyage(root, voyage) {
    let flipped = [];
    flipRecur(root, voyage, flipped, 0);
    if (flipped.length > 0 && flipped[0] === -1) return [-1];
    return flipped;
}

