public boolean isRationalEqual(String s, String t) {
    Double num1 = evaluateString(s);
    Double num2 = evaluateString(t);
    return Math.abs(num1 - num2) < 1e-12;
}

private double evaluateString(String s) {
    int i = s.indexOf('(');
    if (i != -1) {
        String base = s.substring(0, i);
        String rep = s.substring(i + 1, s.length() - 1);
        for (int k = 0; k < 20; ++k) {
            base += rep;
        }
        return Double.parseDouble(base);
    }
    return Double.parseDouble(s);
}

cpp_code:
bool isRationalEqual(std::string s, std::string t) {
    auto eval = [](std::string s) {
        int i = s.find('(');
        if (i != std::string::npos) {
            std::string base = s.substr(0, i);
            std::string rep = s.substr(i + 1, s.length() - i - 2);
            for (int k = 0; k < 20; ++k) base += rep;
            return stod(base);
        }
        return stod(s);
    };
    return fabs(eval(s) - eval(t)) < 1e-12;
}

python_code:
def isRationalEqual(s: str, t: str) -> bool:
    def evaluate(s: str) -> float:
        i = s.find('(')
        if i != -1:
            base = s[:i]
            rep = s[i + 1:-1]
            return float(base + rep * 20)
        return float(s)

    return abs(evaluate(s) - evaluate(t)) < 1e-12

