function isRationalEqual(s, t) {
    const evaluate = (s) => {
        let i = s.indexOf('(');
        if (i !== -1) {
            let base = s.substring(0, i);
            let rep = s.substring(i + 1, s.length - 1);
            for (let k = 0; k < 20; ++k) {
                base += rep;
            }
            return parseFloat(base);
        }
        return parseFloat(s);
    };
    return Math.abs(evaluate(s) - evaluate(t)) < 1e-12;
}

