int subarraysDivByK(vector<int>& nums, int k) {
    unordered_map<int, int> counts;
    counts[0] = 1;
    int sum = 0, result = 0;

    for (int num : nums) {
        sum += num;
        int mod = ((sum % k) + k) % k;
        result += counts[mod];
        counts[mod]++;
    }

    return result;
}

