import java.util.TreeMap;

public int oddEvenJumps(int[] arr) {
    int n = arr.length;
    boolean[] canReachOdd = new boolean[n], canReachEven = new boolean[n];
    canReachOdd[n - 1] = canReachEven[n - 1] = true;
    TreeMap<Integer, Integer> indexMap = new TreeMap<>();
    indexMap.put(arr[n - 1], n - 1);

    int goodIndices = 1;
    for (int i = n - 2; i >= 0; --i) {
        Integer oddJump = indexMap.ceilingKey(arr[i]);
        Integer evenJump = indexMap.floorKey(arr[i]);

        if (oddJump != null) canReachOdd[i] = canReachEven[indexMap.get(oddJump)];
        if (evenJump != null) canReachEven[i] = canReachOdd[indexMap.get(evenJump)];

        if (canReachOdd[i]) ++goodIndices;

        indexMap.put(arr[i], i);
    }

    return goodIndices;
}

cpp_code:
#include <vector>
#include <map>

int oddEvenJumps(std::vector<int>& arr) {
    int n = arr.size();
    std::vector<bool> canReachOdd(n, false), canReachEven(n, false);
    canReachOdd[n - 1] = canReachEven[n - 1] = true;
    std::map<int, int> indexMap;
    indexMap[arr[n - 1]] = n - 1;

    int goodIndices = 1;
    for (int i = n - 2; i >= 0; --i) {
        auto oddJump = indexMap.lower_bound(arr[i]);
        auto evenJump = indexMap.upper_bound(arr[i]);

        if (oddJump != indexMap.end())
            canReachOdd[i] = canReachEven[oddJump->second];
        if (evenJump != indexMap.begin())
            canReachEven[i] = canReachOdd[(--evenJump)->second];

        if (canReachOdd[i]) ++goodIndices;

        indexMap[arr[i]] = i;
    }

    return goodIndices;
}

python_code:
def odd_even_jumps(arr):
    n = len(arr)
    can_reach_odd = [False] * n
    can_reach_even = [False] * n
    can_reach_odd[-1] = can_reach_even[-1] = True

    index_map = {}
    index_map[arr[-1]] = n - 1

    good_indices = 1
    for i in range(n - 2, -1, -1):
        odd_jump = next(iter([value for value in index_map if value >= arr[i]]), None)
        even_jump = next(iter([value for value in index_map if value <= arr[i]]), None)

        if odd_jump is not None:
            can_reach_odd[i] = can_reach_even[index_map[odd_jump]]
        if even_jump is not None:
            can_reach_even[i] = can_reach_odd[index_map[even_jump]]

        if can_reach_odd[i]:
            good_indices += 1

        index_map[arr[i]] = i

    return good_indices

javascript_code:
function oddEvenJumps(arr) {
    const n = arr.length;
    const canReachOdd = new Array(n).fill(false);
    const canReachEven = new Array(n).fill(false);
    canReachOdd[n - 1] = canReachEven[n - 1] = true;

    const indexMap = new Map();
    indexMap.set(arr[n - 1], n - 1);

    let goodIndices = 1;
    for (let i = n - 2; i >= 0; --i) {
        const oddJump = [...indexMap.keys()].find((value) => value >= arr[i]);
        const evenJump = [...indexMap.keys()].find((value) => value <= arr[i]);

        if (oddJump !== undefined)
            canReachOdd[i] = canReachEven[indexMap.get(oddJump)];
        if (evenJump !== undefined)
            canReachEven[i] = canReachOdd[indexMap.get(evenJump)];

        if (canReachOdd[i]) ++goodIndices;

        indexMap.set(arr[i], i);
    }

    return goodIndices;
}

