from collections import defaultdict
import bisect

class TimeMap:

    def __init__(self):
        self.data = defaultdict(list)

    def set(self, key, value, timestamp):
        self.data[key].append((timestamp, value))

    def get(self, key, timestamp):
        if key not in self.data: return ""
        index = bisect.bisect(self.data[key], (timestamp + 1,))
        return self.data[key][index-1][1] if index else ""

javascript_code:
class TimeMap {
    constructor() {
        this.data = new Map();
    }

    set(key, value, timestamp) {
        if (!this.data.has(key)) {
            this.data.set(key, []);
        }
        this.data.get(key).push({ timestamp, value });
    }

    get(key, timestamp) {
        if (!this.data.has(key)) return "";
        const values = this.data.get(key);
        let left = 0, right = values.length - 1;
        while (left < right) {
            let mid = Math.floor((left + right + 1) / 2);
            if (values[mid].timestamp > timestamp) {
                right = mid - 1;
            } else {
                left = mid;
            }
        }
        return values[left].timestamp <= timestamp ? values[left].value : "";
    }
}

