import java.util.*;

public List<Integer> addToArrayForm(int[] num, int k) {
    List<Integer> result = new ArrayList<>();
    int carry = k, i = num.length - 1;
    while (i >= 0 || carry > 0) {
        if (i >= 0) {
            carry += num[i--];
        }
        result.add(carry % 10);
        carry /= 10;
    }
    Collections.reverse(result);
    return result;
}

cpp_code:
#include <vector>
#include <algorithm>
using namespace std;

vector<int> addToArrayForm(vector<int>& num, int k) {
    // add k to the least significant digit of the integer represented by num
    num.back() += k;
    // sum digits from least to most significant digit
    for (int i = num.size() - 1; i > 0 && num[i]; --i) {
        num[i - 1] += num[i] / 10;
        num[i] %= 10;
    }
    // handle possible remaining carry
    while (num[0] >= 10) {
        num.insert(num.begin(), num[0] / 10);
        num[1] %= 10;
    }
    return num;
}

