def add_to_array_form(num, k):
    for i in range(len(num) - 1, -1, -1):
        k, num[i] = divmod(num[i] + k, 10)
        if k == 0:
            break
    while k:
        k, digit = divmod(k, 10)
        num.insert(0, digit)
    return num

javascript_code:
function addToArrayForm(num, k) {
    for (let i = num.length - 1; i >= 0; --i) {
        let sum = num[i] + k % 10;
        k = Math.floor(k / 10);
        if (sum >= 10) {
            sum -= 10;
            k++;
        }
        num[i] = sum;
        if (k === 0)
            break;
    }
    while (k !== 0) {
        num.unshift(k % 10);
        k = Math.floor(k / 10);
    }
    return num;
}

