        if (!node || (!node->left && !node->right)) return nullptr;
        if ((node->left && node->left->val == search_val) || (node->right && node->right->val == search_val)) return node;
        TreeNode* left_parent = findParent(node->left, search_val);
        if (left_parent) return left_parent;
        return findParent(node->right, search_val);
    }
};

