        if (node.val === searchVal) return depth;
        let leftDepth = findDepth(node.left, searchVal, depth + 1);
        if (leftDepth !== -1) return leftDepth;
        return findDepth(node.right, searchVal, depth + 1);
    }

    function findParent(node, searchVal) {
        if (!node || (!node.left && !node.right)) return null;
        if ((node.left && node.left.val === searchVal) || (node.right && node.right.val === searchVal)) return node;
        let leftParent = findParent(node.left, searchVal);
        if (leftParent) return leftParent;
        return findParent(node.right, search_val);
    }

    let xDepth = findDepth(root, x, 0);
    let yDepth = findDepth(root, y, 0);
    let xParent = findParent(root, x);
    let yParent = findParent(root, y);
    return (xDepth === yDepth) && (xParent !== yParent);
}

java_code:
import java.util.LinkedList;
import java.util.Queue;

public int orangesRotting(int[][] grid) {
    int m = grid.length;
    int n = grid[0].length;
    int freshOranges = 0;
    Queue<int[]> rotten = new LinkedList<>();

    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            if (grid[i][j] == 1)
                freshOranges++;
            else if (grid[i][j] == 2)
                rotten.offer(new int[]{i, j});
        }
    }

    int minutes = 0;
    int[][] directions = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};

    while (!rotten.isEmpty() && freshOranges != 0) {
        int size = rotten.size();
        for (int i = 0; i < size; ++i) {
            int[] current = rotten.poll();

            for (int[] direction : directions) {
                int x = current[0] + direction[0];
                int y = current[1] + direction[1];

                if (x < 0 || y < 0 || x >= m || y >= n || grid[x][y] != 1)
                    continue;

                grid[x][y] = 2;
                freshOranges--;
                rotten.offer(new int[]{x, y});
            }
        }
        minutes++;
    }

    return freshOranges == 0 ? minutes : -1;
}

