java_code:
public int minKBitFlips(int[] nums, int k) {
    int n = nums.length, res = 0, flipped = 0;
    int[] change = new int[n];
    for (int i = 0; i <= n - k; i++) {
        flipped ^= change[i];
        if (nums[i] == flipped) {
            res++;
            flipped ^= 1;
            if (i + k < n) change[i + k] ^= 1;
        }
    }
    for (int i = n - k + 1; i < n; i++) {
        flipped ^= change[i];
        if (nums[i] == flipped) return -1;
    }
    return res;
}

