public int numRookCaptures(char[][] board) {
    int x = 0, y = 0, captures = 0;
    outer: for (x = 0; x < 8; x++) {
        for (y = 0; y < 8; y++) {
            if (board[x][y] == 'R') {
                break outer;
            }
        }
    }

    int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
    for (int[] dir : dirs) {
        int nx = x + dir[0];
        int ny = y + dir[1];
        while (nx >= 0 && nx < 8 && ny >= 0 && ny < 8) {
            if (board[nx][ny] == 'p') {
                captures++;
                break;
            } else if (board[nx][ny] == 'B') {
                break;
            }
            nx += dir[0];
            ny += dir[1];
        }
    }

    return captures;
}

