#include <vector>
#include <string>

int numRookCaptures(std::vector<std::string>& board) {
    int x = 0, y = 0, captures = 0;
    for (x = 0; x < 8; ++x) {
        for (y = 0; y < 8; ++y) {
            if (board[x][y] == 'R') {
                break;
            }
        }
        if (y < 8) break;
    }

    std::vector<std::pair<int, int>> dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
    for (auto& dir : dirs) {
        int nx = x + dir.first;
        int ny = y + dir.second;
        while (nx >= 0 && nx < 8 && ny >= 0 && ny < 8) {
            if (board[nx][ny] == 'p') {
                captures++;
                break;
            } else if (board[nx][ny] == 'B') {
                break;
            }
            nx += dir.first;
            ny += dir.second;
        }
    }

    return captures;
}

