import java.util.*;

public List<Character> commonChars(String[] words) {
    Map<Character, Integer> merged = new HashMap<>();

    for (String word : words) {
        Map<Character, Integer> wordMap = new HashMap<>();
        for (char c : word.toCharArray()) {
            wordMap.put(c, wordMap.getOrDefault(c, 0) + 1);
        }
        if (merged.isEmpty()) {
            merged = wordMap;
        } else {
            for (char c : merged.keySet()) {
                merged.put(c, Math.min(merged.get(c), wordMap.getOrDefault(c, 0)));
            }
        }
    }

    List<Character> result = new ArrayList<>();
    for (Map.Entry<Character, Integer> entry : merged.entrySet()) {
        for (int i = 0; i < entry.getValue(); i++) {
            result.add(entry.getKey());
        }
    }
    return result;
}

cpp_code:
#include <vector>
#include <string>
#include <unordered_map>

std::vector<char> commonChars(std::vector<std::string>& words) {
    std::unordered_map<char, int> merged;
    for (const auto& word : words) {
        std::unordered_map<char, int> word_map;
        for (char c : word) {
            ++word_map[c];
        }
        if (merged.empty()) {
            merged = word_map;
        }
        else {
            for (auto& entry : merged) {
                entry.second = std::min(entry.second, word_map[entry.first]);
            }
        }
    }

    std::vector<char> result;
    for (const auto& entry : merged) {
        for (int i = 0; i < entry.second; ++i) {
            result.push_back(entry.first);
        }
    }
    return result;
}

