            wordMap[char] = (wordMap[char] || 0) + 1;
        }
        if (Object.keys(merged).length === 0) {
            merged = wordMap;
        } else {
            for (const char in merged) {
                merged[char] = Math.min(merged[char], wordMap[char] || 0);
            }
        }
    }

    let result = [];
    for (const char in merged) {
        for (let i = 0; i < merged[char]; i++) {
            result.push(char);
        }
    }
    return result;
}

