    let left = 0, right = nums.length;
    while (left < right) {
        let mid = Math.floor(left + (right - left) / 2);
        if (nums[mid] - mid - 1 < k) {
            left = mid + 1;
        } else {
            right = mid;
        }
    }
    return left + k;
}

