function addNegabinary(arr1, arr2) {
    const res = [];
    let carry = 0, i = arr1.length - 1, j = arr2.length - 1;
    while (i >= 0 || j >= 0 || carry) {
        if (i >= 0) carry += arr1[i--];
        if (j >= 0) carry += arr2[j--];
        res.unshift(carry & 1);
        carry = -(carry >> 1);
    }
    while (res.length > 1 && res[0] == 0) res.shift();
    return res;
}

