                cur_sum += matrix[row][col2] - (col1 > 0 ? matrix[row][col1-1] : 0);
                count += (counter.get(cur_sum - target) || 0);
                counter.set(cur_sum, (counter.get(cur_sum) || 0) + 1);
            }
        }
    }
    return count;
};

