int findConfusingNumbers(int num, int& n, unordered_map<int, int>& mp) {
    if (num > n) return 0;
    int rotated = 0, src = num, newNum;
    while (src > 0) {
        rotated = rotated * 10 + mp[src % 10];
        src /= 10;
    }
    return (num != rotated) + findConfusingNumbers(num * 10 + 6, n, mp)
           + findConfusingNumbers(num * 10 + 9, n, mp)
           + findConfusingNumbers(num * 10 + 0, n, mp)
           + findConfusingNumbers(num * 10 + 1, n, mp)
           + findConfusingNumbers(num * 10 + 8, n, mp);
}

int confusingNumberII(int n) {
    unordered_map<int, int> mp = {{0,0},{1,1},{6,9},{8,8},{9,6}};
    return findConfusingNumbers(6, n, mp) + findConfusingNumbers(9, n, mp) +
           findConfusingNumbers(1, n, mp) + findConfusingNumbers(8, n, mp) + findConfusingNumbers(0, n, mp);
}

python_code:
def confusingNumberII(n):
    def helper(current):
        nonlocal count, validNums
        for num in validNums:
            next_num = current * 10 + num
            if next_num > n:
                break
            if current != 0 or next_num != 0:
                if next_num != rotate(next_num):
                    count += 1
                count = helper(next_num)
        return count

    def rotate(num):
        rotated = 0
        original = num
        while num > 0:
            digit = num % 10
            if digit in (2, 3, 4, 5, 7):
                return original
            revd = {0: 0, 1: 1, 6: 9, 8: 8, 9: 6}
            rotated = rotated * 10 + revd[digit]
            num //= 10
        return rotated

    count = 0
    validNums = [0, 1, 6, 8, 9]
    return helper(0)

javascript_code:
var confusingNumberII = function(n) {
    const validNums = [0, 1, 6, 8, 9];

    function helper(current) {
        let count = 0;
        for (const num of validNums) {
            const nextNum = current * 10 + num;
            if (nextNum > n) break;
            if (current !== 0 || nextNum !== 0) {
                if (nextNum !== rotate(nextNum)) count += 1;
                count += helper(nextNum);
            }
        }
        return count;
    }

    function rotate(num) {
        let rotated = 0;
        while (num > 0) {
            const digit = num % 10;
            if ([2, 3, 4, 5, 7].includes(digit)) return -1;
            rotated = rotated * 10 + (digit === 6 ? 9 : (digit === 9 ? 6 : digit));
            num = Math.floor(num / 10);
        }
        return rotated;
    }

    return helper(0);
};

