struct TreeNode {
    int val;
    TreeNode* left;
    TreeNode* right;
    TreeNode(int _val) : val(_val), left(nullptr), right(nullptr) {}
};

int dfs(TreeNode* node, int& mn, int& mx) {
    if (!node) return 0;
    int left_min = node->val, right_min = node->val;
    int left_max = node->val, right_max = node->val;
    int left_diff = dfs(node->left, left_min, left_max);
    int right_diff = dfs(node->right, right_min, right_max);
    mn = min(node->val, min(left_min, right_min));
    mx = max(node->val, max(left_max, right_max));
    return max(max(left_diff, right_diff), max(abs(node->val - left_min), abs(node->val - right_max)));
}
int maxAncestorDiff(TreeNode* root) {
    int mn = root->val, mx = root->val;
    return dfs(root, mn, mx);
}

