class TreeNode {
    constructor(val, left = null, right = null) {
        this.val = val;
        this.left = left;
        this.right = right;
    }
}

function dfs(node) {
    if (!node) return [0, Infinity, -Infinity];
    const [leftDiff, leftMin, leftMax] = dfs(node.left);
    const [rightDiff, rightMin, rightMax] = dfs(node.right);
    const mn = Math.min(node.val, leftMin, rightMin);
    const mx = Math.max(node.val, leftMax, rightMax);
    return [Math.max(Math.max(leftDiff, rightDiff), Math.max(Math.abs(node.val - leftMin), Math.abs(node.val - rightMax))), mn, mx];
}

function maxAncestorDiff(root) {
    const [diff, _, _] = dfs(root);
    return diff;
}

