class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode(int x) { val = x; }
}

public TreeNode recoverFromPreorder(String S) {
    return helper(new java.util.Scanner(S), 0);
}

public TreeNode helper(java.util.Scanner scanner, int depth) {
    int numDashes = 0;
    while (scanner.hasNext("-")) {
        numDashes++;
        scanner.next("-");
    }

    if (numDashes != depth) {
        while (numDashes-- > 0) {
            scanner.next("-");
        }
        return null;
    }

    int val = scanner.nextInt();
    TreeNode node = new TreeNode(val);
    node.left = helper(scanner, depth + 1);
    node.right = helper(scanner, depth + 1);
    return node;
}

cpp_code:
#include <sstream>
#include <string>

using namespace std;

struct TreeNode {
    int val;
    TreeNode* left;
    TreeNode* right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

void helper(istringstream &iss, TreeNode* &node, int depth) {
    int d = 0;
    while (iss.peek() == '-') {
        iss.get();
        d++;
    }
    if (d != depth) {
        iss.putback('-');
        return;
    }
    int val;
    iss >> val;
    node = new TreeNode(val);
    helper(iss, node->left, depth + 1);
    helper(iss, node->right, depth + 1);
}

TreeNode* recoverFromPreorder(string S) {
    istringstream iss(S);
    TreeNode* root = nullptr;
    helper(iss, root, 0);
    return root;
}

javascript_code:
class TreeNode {
    constructor(val) {
        this.val = val;
        this.left = this.right = null;
    }
}

function recoverFromPreorder(S) {
    return helper(S, 0);
}

function helper(S, depth) {
    if (!S.length) return null;

    let numDashes = 0;
    let start = 0;
    while (S.charAt(start) === '-') {
        numDashes++;
        start++;
    }

    if (numDashes < depth) return null;

    S = S.substring(start - depth);
    let end = 0;
    while (S.charAt(end) !== '-' && end < S.length) end++;
    const val = parseInt(S.substring(0, end));

    const node = new TreeNode(val);
    S = S.substring(end);

    node.left = helper(S, depth + 1);
    node.right = helper(S, depth + 1);

    return node;
}

