#include <string>
#include <set>
#include <vector>
using namespace std;

class Solution {
public:
    vector<string> braceExpansionII(string expression) {
        int i = 0;
        return vector<string>(parse(expression, i).begin(), parse(expression, i).end());
    }

    set<string> parse(string& expresion, int& i) {
        set<string> current;
        current.insert("");
        set<string> result;

        for (; i < expresion.size(); ++i) {
            char c = expresion[i];
            if (c == '{') {
                set<string> update;
                for (string postfix : parse(expresion, ++i)) {
                    for (string prefix : current) {
                        update.insert(prefix + postfix);
                    }
                }
                current = update;
            } else if (c == ',') {
                result.insert(current.begin(), current.end());
                current.clear();
                current.insert("");
            } else if (c == '}') {
                break;
            } else { 
                set<string> update;
                for (string element : current) {
                    update.insert(element + c);
                }
                current = update;
            }
        }

        result.insert(current.begin(), current.end());
        return result;
    }
};

python_code:
class Solution:
    def braceExpansionII(self, expression: str) -> List[str]:
        def parse(expr: str, i: int) -> Set[str]:
            result, current = set(), {""}
            while i < len(expr):
                if expr[i] == '{':
                    update = set()
                    for postfix in parse(expr, i + 1):
                        for prefix in current:
                            update.add(prefix + postfix)
                    current = update
                    i = expr.index('}', i)
                elif expr[i] == '}':
                    break
                elif expr[i] == ',':
                    result |= current
                    current = {""}
                else:
                    current = {s + expr[i] for s in current}
                i += 1
            return result | current

        return sorted(parse(expression, 0))

javascript_code:
/**
 * @param {string} expression
 * @return {string[]}
 */
var braceExpansionII = function(expression) {
    function parse(expresion, i) {
        let current = new Set();
        current.add("");
        let result = new Set();

        while (i[0] < expresion.length) {
            let c = expresion[i[0]++];
            if (c === '{') {
                let update = new Set();
                for(let postfix of parse(expresion, i)) {
                    for(let prefix of current) {
                        update.add(prefix + postfix);
                    }
                }
                current = update;
            } else if (c === '}') {
                break;
            } else if (c === ',') {
                for(let cur of current) {
                    result.add(cur);
                }
                current.clear();
                current.add("");
            } else {
                let update = new Set();
                for(let element of current) {
                    update.add(element + c);
                }
                current = update;
            }
        }

        for(let cur of current) {
            result.add(cur);
        }
        return result;
    }

    const i = [0];
    return Array.from(parse(expression, i)).sort();
};

