    std::sort(logs.begin(), logs.end());

    int groupCount = n;
    for (const auto& log : logs) {
        int rootX = parent(log[1], parents);
        int rootY = parent(log[2], parents);
        if (rootX != rootY) {
            parents[rootX] = rootY;
            groupCount--;
        }
        if (groupCount == 1) {
            return log[0];
        }
    }
    return -1;
}

