        if (x !== parents[x]) {
            parents[x] = find(parents[x]);
        }
        return parents[x];
    }

    let group_count = n;
    for (const [timestamp, x, y] of logs) {
        const root_x = find(x);
        const root_y = find(y);
        if (root_x !== root_y) {
            parents[root_x] = root_y;
            group_count--;
        }
        if (group_count === 1) {
            return timestamp;
        }
    }

    return -1;
}

