public int[] distributeCandies(int candies, int num_people) {
    int[] result = new int[num_people];
    int i = 0, count = 1;

    while (candies > 0) {
        result[i % num_people] += Math.min(candies, count);
        candies -= count;
        count++;
        i++;
    }

    return result;
}

