public String defangIPaddr(String address) {
    StringBuilder defanged = new StringBuilder();
    for (char c : address.toCharArray()) {
        if (c == '.')
            defanged.append("[.]");
        else
            defanged.append(c);
    }
    return defanged.toString();
}

