using namespace std;

struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode(int x) : val(x), left(NULL), right(NULL) {}
};

vector<TreeNode*> delNodes(TreeNode* root, vector<int>& to_delete) {
    set<int> to_delete_set(to_delete.begin(), to_delete.end());
    vector<TreeNode*> remaining_trees;

    function<TreeNode*(TreeNode*)> removeNodes = [&](TreeNode* node) -> TreeNode* {
        if (node == nullptr) return nullptr;
        node->left = removeNodes(node->left);
        node->right = removeNodes(node->right);
        if (to_delete_set.count(node->val)) {
            if (node->left) remaining_trees.push_back(node->left);
            if (node->right) remaining_trees.push_back(node->right);
            return nullptr;
        }
        return node;
    };

    if (removeNodes(root)) remaining_trees.push_back(root);
    return remaining_trees;
}

