    for (let length = n - 1; length > 0; --length) {
        for (let i = 0; i <= n - length; ++i) {
            const substring = s.substring(i, i + length);
            if (s.indexOf(substring, i + 1) !== -1) {
                longest_duplicate = substring;
                return longest_duplicate;
            }
        }
    }
    return longest_duplicate;
}

