import java.util.*;

public List<Integer> smallestSufficientTeam(String[] req_skills, List<List<String>> people) {
    Map<String, Integer> skillToId = new HashMap<>();
    int idx = 0;
    for (String skill : req_skills) {
        skillToId.put(skill, idx++);
    }

    int n = people.size(), m = req_skills.length;
    int[] dp = new int[1 << m];
    int[] pre = new int[1 << m];
    int[] skillSet = new int[1 << m];

    Arrays.fill(dp, Integer.MAX_VALUE / 2);
    dp[0] = 0;

    for (int i = 0; i < n; ++i) {
        int skillMask = 0;
        for (String skill : people.get(i)) {
            skillMask |= 1 << skillToId.get(skill);
        }
        for (int j = (1 << m) - 1; j >= 0; --j) {
            if (dp[j | skillMask] > dp[j] + 1) {
                dp[j | skillMask] = dp[j] + 1;
                pre[j | skillMask] = j;
                skillSet[j | skillMask] = i;
            }
        }
    }

    List<Integer> res = new ArrayList<>();
    int mask = (1 << m) - 1;
    while (mask != 0) {
        res.add(skillSet[mask]);
        mask = pre[mask];
    }

    return res;
}

cpp_code:
#include <unordered_map>
#include <vector>
#include <bitset>
using namespace std;

vector<int> smallestSufficientTeam(vector<string>& req_skills, vector<vector<string>>& people) {
    unordered_map<int, string> id_to_skill;
    unordered_map<string, int> skill_to_id;
    int idx = 0;
    for (const auto& skill : req_skills) {
        skill_to_id[skill] = idx++;
        id_to_skill[idx - 1] = skill;
    }

    vector<int> res;
    vector<bitset<16>> dp(1 << idx, bitset<16>());
    vector<int> pre(1 << idx, -1);
    dp[0].set(31);

    int people_size = people.size();
    for (int i = 0; i < people_size; ++i) {
        int skill_mask = 0;
        for (const auto& skill : people[i]) {
            skill_mask |= 1 << skill_to_id[skill];
        }
        for (int j = (1 << idx) - 1; j >= 0; --j) {
            int next_mask = j | skill_mask;
            if (dp[next_mask].count() > dp[j].count() + 1) {
                dp[next_mask] = dp[j];
                dp[next_mask].set(i);
                pre[next_mask] = j;
            }
        }
    }

    int current_mask = (1 << idx) - 1;
    while (current_mask != 0) {
        int previous_mask = pre[current_mask];
        int mask = current_mask ^ previous_mask;
        int id = log2(mask);
        res.push_back(id);
        current_mask = previous_mask;
    }

    return res;
}

