            let pre = word.slice(0, i) + word.slice(i + 1);
            dp.set(word, Math.max(dp.get(word) || 0, (dp.get(pre) || 0) + 1));
        }
        maxLen = Math.max(maxLen, dp.get(word));
    }

    return maxLen;
}

