function lastStoneWeight(stones) {
    const pq = new MinPriorityQueue({ priority: x => -x });
    stones.forEach(stone => pq.enqueue(stone));
    while (pq.size() > 1) {
        const x = pq.dequeue().element;
        const y = pq.dequeue().element;
        if (x !== y) {
            pq.enqueue(y - x);
        }
    }
    return pq.isEmpty() ? 0 : pq.front().element;
}

