            }
        }
    }

    return n == 0 ? semesters : -1;
}

python_code:
def minimum_semesters(n: int, relations: List[List[int]]) -> int:
    in_degree = [0] * (n + 1)
    graph = [[] for _ in range(n + 1)]

    for prev, next in relations:
        graph[prev].append(next)
        in_degree[next] += 1

    q = [i for i in range(1, n + 1) if in_degree[i] == 0]
    semesters = 0

    while q:
        next_q = []
        semesters += 1
        for course in q:
            n -= 1
            for next_course in graph[course]:
                in_degree[next_course] -= 1
                if in_degree[next_course] == 0:
                    next_q.append(next_course)
        q = next_q

    return semesters if n == 0 else -1

javascript_code:
function minimumSemesters(n, relations) {
    const in_degree = new Array(n + 1).fill(0);
    const graph = new Array(n + 1).fill(null).map(() => []);

    for (let [prev, next] of relations) {
        graph[prev].push(next);
        in_degree[next]++;
    }

    const q = [];
    for (let i = 1; i <= n; i++) {
        if (in_degree[i] === 0) {
            q.push(i);
        }
    }

    let semesters = 0;
    while (q.length) {
        const size = q.length;
        semesters++;
        for (let i = 0; i < size; i++) {
            const course = q.shift();
            n--;

            for (let next of graph[course]) {
                in_degree[next]--;
                if (in_degree[next] === 0) {
                    q.push(next);
                }
            }
        }
    }

    return n === 0 ? semesters : -1;
}

