std::vector<int> prevPermOpt1(std::vector<int>& arr) {
    int n = arr.size();
    for(int i = n - 2; i >= 0; i--){
        if(arr[i] > arr[i + 1]){
            int j = i + 1;
            while(j < n && arr[j] < arr[i]) j++;
            std::swap(arr[i], arr[j - 1]);
            return arr;
        }
    }
    return arr;
}

