import java.util.*;

public int[] rearrangeBarcodes(int[] barcodes) {
    int n = barcodes.length;
    int[] count = new int[10001];
    for (int i = 0; i < n; i++) {
        count[barcodes[i]]++;
    }

    PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> b[1] - a[1]);
    for (int i = 1; i <= 10000; i++) {
        if (count[i] > 0) {
            pq.offer(new int[]{i, count[i]});
        }
    }

    int index = 0;
    while (!pq.isEmpty()) {
        int[] curr = pq.poll();
        while (curr[1] > 0) {
            barcodes[index] = curr[0];
            curr[1]--;
            index += 2;
            if (index >= n) {
                index = 1;
            }
        }
    }
    return barcodes;
}

cpp_code:
#include<vector>
#include<queue>
using namespace std;

vector<int> rearrangeBarcodes(vector<int> &barcodes) {
    int n = barcodes.size();
    vector<int> count(10001, 0);
    for (int i = 0; i < n; ++i) {
        ++count[barcodes[i]];
    }

    auto comp = [](const pair<int, int>& a, const pair<int, int>& b) { return a.second < b.second; };
    priority_queue<pair<int, int>, vector<pair<int, int>>, decltype(comp)> pq(comp);
    for (int i = 1; i <= 10000; ++i) {
        if (count[i] > 0) {
            pq.push({i, count[i]});
        }
    }

    int idx = 0;
    while (!pq.empty()) {
        auto curr = pq.top();
        pq.pop();
        while (curr.second > 0) {
            barcodes[idx] = curr.first;
            curr.second--;
            idx += 2;
            if (idx >= n) {
                idx = 1;
            }
        }
    }
    return barcodes;
}

python_code:
from heapq import heappush, heappop

def rearrange_barcodes(barcodes):
    count = {}
    for barcode in barcodes:
        if barcode not in count:
            count[barcode] = 0
        count[barcode] += 1

    pq = []
    for key, value in count.items():
        heappush(pq, (-value, key))

    idx = 0
    while pq:
        curr = heappop(pq)
        while curr[0] < 0:
            barcodes[idx] = curr[1]
            curr = (curr[0] + 1, curr[1])
            idx += 2
            if idx >= len(barcodes):
                idx = 1
    return barcodes

