class TreeNode {
    constructor(val, left = null, right = null) {
        this.val = val;
        this.left = left;
        this.right = right;
    }
}

function btreeGameWinningMove(root, n, x) {
    function countNodes(node) {
        if (!node) return 0;
        return countNodes(node.left) + countNodes(node.right) + 1;
    }

    function findNode(node, x) {
        if (!node) return null;
        if (node.val === x) return node;
        let leftSearch = findNode(node.left, x);
        if (leftSearch) return leftSearch;
        return findNode(node.right, x);
    }

    let xNode = findNode(root, x);
    let leftNodes = countNodes(xNode.left);
    let rightNodes = countNodes(xNode.right);
    let parentNodes = n - leftNodes - rightNodes - 1;

    return Math.max(Math.max(leftNodes, rightNodes), parentNodes) > Math.floor(n / 2);
}

