from typing import List
from collections import defaultdict
from itertools import combinations

class Solution:
    def mostVisitedPattern(self, username: List[str], timestamp: List[int], website: List[str]) -> List[str]:
        n = len(username)
        visits = defaultdict(list)

        # user_visits: {user: [(timestamp, website),...]}
        for i in range(n):
            visits[username[i]].append((timestamp[i], website[i]))


        for user in visits:
            visits[user].sort()

        patterns = defaultdict(int)

        for user in visits:
            websites = [web for _, web in visits[user]]
            patterns_set = set(combinations(websites, 3))

            for pattern in patterns_set:
                patterns[pattern] += 1

        patterns = sorted(patterns.items(), key=lambda x: (-x[1], x[0]))

        return list(patterns[0][0])

javascript_code:
var mostVisitedPattern = function(username, timestamp, website) {
    let n = username.length;
    let visitingOrder = [];
    let userVisits = new Map();

    for (let i = 0; i < n; i++) {
        if (!userVisits.has(username[i])) {
            userVisits.set(username[i], []);
        }
        userVisits.get(username[i]).push({time: timestamp[i], index: i});
    }

    for (let visits of userVisits.values()) {
        visits.sort((a, b) => a.time - b.time);
        let m = visits.length;
        for (let i = 0; i < m; i++) {
            for (let j = i + 1; j < m; j++) {
                for (let k = j + 1; k < m; k++) {
                    visitingOrder.push([website[visits[i].index], website[visits[j].index], website[visits[k].index]]);
                }
            }
        }
    }

    visitingOrder.sort();

    let ans = visitingOrder[0];
    let maxScore = 0, score = 1;

    for (let i = 1; i < visitingOrder.length; i++) {
        if (visitingOrder[i].toString() === visitingOrder[i-1].toString()) {
            score++;
        } else {
            score = 1;
        }

        if (score > maxScore) {
            maxScore = score;
            ans = visitingOrder[i];
        }
    }

    return ans;
};

