struct TreeNode {
  int val;
  TreeNode* left;
  TreeNode* right;
};

bool isInsufficient(TreeNode* node, int limit, int sum) {
  if (!node) {
    return true;
  }

  sum += node->val;
  if (!node->left && !node->right) {
    return sum < limit;
  }

  bool leftInsufficient = isInsufficient(node->left, limit, sum);
  bool rightInsufficient = isInsufficient(node->right, limit, sum);

  if (leftInsufficient) {
    delete(node->left);
    node->left = nullptr;
  }
  if (rightInsufficient) {
    delete(node->right);
    node->right = nullptr;
  }

  return leftInsufficient && rightInsufficient;
}

TreeNode* sufficientSubset(TreeNode* root, int limit) {
  if (isInsufficient(root, limit, 0)) {
    delete(root);
    return nullptr;
  }
  return root;
}

