    for (char c : tiles) {
        freq[c - 'A']++;
    }

    int result = 0;
    for (int i = 0; i < 26; i++) {
        if (freq[i]) {
            freq[i]--;
            result += 1 + numTilePossibilities(tiles);
            freq[i]++;
