#include <queue>

class TreeNode {
public:
    int val;
    TreeNode* left;
    TreeNode* right;
    TreeNode(int x) : val(x), left(NULL), right(NULL) {}
};

int maxLevelSum(TreeNode* root) {
    if (!root) return 0;

    std::queue<TreeNode*> q;
    q.push(root);
    int level = 0, max_sum = INT_MIN, result_level;

    while (!q.empty()) {
        int count = q.size();
        int sum = 0;
        level++;

        while (count--) {
            TreeNode* temp = q.front(); q.pop();
            sum += temp->val;

            if (temp->left) q.push(temp->left);
            if (temp->right) q.push(temp->right);
        }

        if (sum > max_sum) {
            max_sum = sum;
            result_level = level;
        }
    }

    return result_level;
}

