class FileSystem {
public:
    unordered_map<string, int> pathMap;

    bool createPath(string path, int value) {
        if (pathMap.count(path) != 0) return false;
        string parentPath = path.substr(0, path.find_last_of('/'));
        if (!parentPath.empty() && pathMap.count(parentPath) == 0) return false;
        pathMap[path] = value;
        return true;
    }

    int get(string path) {
        if (pathMap.count(path) == 0) return -1;
        return pathMap[path];
    }
};

