    for (let i = 2; i <= n; i++) {
        if (isPrime(i)) primeCount++;
    }
    let compositeCount = n - primeCount;

    const MOD = 10**9 + 7;
    let res = 1;
    for (let i = 1; i <= primeCount; i++) {
        res = res * i % MOD;
    }
    for (let i = 1; i <= compositeCount; i++) {
        res = res * i % MOD;
    }

    return res;
}

