public int dietPlanPerformance(int[] calories, int k, int lower, int upper) {
    int points = 0;
    int T = 0;

    for(int i = 0; i < calories.length; i++) {
        T += calories[i];
        if(i >= k) {
            T -= calories[i-k];
        }
        if(i >= k-1) {
            if(T < lower) points--;
            if(T > upper) points++;
        }
    }

    return points;
}

