function canMakePaliQueries(s, queries) {
    const answer = [];
    const prefixSum = new Array(s.length + 1).fill(0);

    for (let i = 0; i < s.length; ++i) {
        prefixSum[i + 1] = prefixSum[i] ^ (1 << (s.charCodeAt(i) - 'a'.charCodeAt(0)));
    }

