        if (count[i] > 0) {
            if (minVal == -1) minVal = i;
            maxVal = i;
            sum += static_cast<double>(i) * count[i];
            totalCount += count[i];
            if (count[i] > modeCount) {
                modeCount = count[i];
                mode = i;
            }
        }
    }

    mean = sum / totalCount;
    bool isEven = (totalCount % 2 == 0);
    long long mid1 = totalCount / 2, mid2 = mid1 - 1;
    if (isEven) mid2++;

    for (int i = 0; i <= 255; i++) {
        curCount += count[i];
        if (isEven && curCount >= mid2) {
            median += i;
            mid2 = totalCount;
            isEven = false;
        }

        if (curCount >= mid1) {
            median += i;
            break;
        }
    }

    if (!isEven) median /= 2;
    return {minVal, maxVal, mean, median, mode};
}

