        if (c === 'a') letter_count[1]++;
        if (c === 'l') letter_count[2]++;
        if (c === 'o') letter_count[3]++;
        if (c === 'n') letter_count[4]++;
    }
    letter_count[2] = Math.floor(letter_count[2] / 2);
    letter_count[3] = Math.floor(letter_count[3] / 2);
    return Math.min(...letter_count);
}

