                st.push(i);
            else if(s[i] == ')'){
                reverse(s.begin() + st.top() + 1,  s.begin() + i);
                st.pop();
            }
        }
        string result = "";
        for(int i = 0 ; i < s.length(); ++i){

            if(s[i] != '(' && s[i] != ')')
                result += s[i];
        }
        return result;
}

python_code:
def reverseParentheses(s: str) -> str:
    stack = []
    for i, c in enumerate(s):
        if c == '(':
            stack.append(i)
        elif c == ')':
            start, end = stack.pop(), i
            # reversal of the substring
            s = s[:start] + s[start+1:end][::-1] + s[end+1:]
    return ''.join(c for c in s if c.isalpha())

javascript_code:
function reverseParentheses(s) {
    const stack = [];
    for (let i = 0; i < s.length; i++) {
        if (s[i] === '(') {
            stack.push(i);
        } else if (s[i] === ')') {
            const start = stack.pop();
            const end = i;
            const substring = s.slice(start + 1, end).split('').reverse().join('');
            s = s.slice(0, start) + substring + s.slice(end + 1);
        }
    }
    let result = '';
    for (let i = 0; i < s.length; i++) {
        if (s[i] !== '(' && s[i] !== ')') {
            result += s[i];
        }
    }
    return result;
}

