bool parseBoolExpr(string expression, int &pos) {
    switch (expression[pos++]) {
        case 't': return true;
        case 'f': return false;
        case '!': return !parseBoolExpr(expression, ++pos);
        case '&': {
            pos++; 
            bool result = true;
            while (expression[pos] != ')') {
                result &= parseBoolExpr(expression, pos);
                if(expression[pos] == ',') pos++;
            }
            pos++;
            return result;
        }
        case '|': {
            pos++;
            bool result = false;
            while (expression[pos] != ')') {
                result |= parseBoolExpr(expression, pos);
                if(expression[pos] == ',') pos++;
            }
            pos++;
            return result;
        }
    }
}

