int minBuildTime(std::vector<int>& blocks, int split) {
    std::priority_queue<int, std::vector<int>, greater<int>> pq(blocks.begin(), blocks.end());

    while (pq.size() > 1) {
        int a = pq.top();
        pq.pop();
        int b = pq.top();
        pq.pop();
        pq.push(b + split);
    }

    return pq.top();
}

