#include <vector>
#include <string>
#include <algorithm>
using namespace std;

class Solution {
public:
    string smallestStringWithSwaps(string s, vector<vector<int>>& pairs) {
        int n = s.size();
        vector<int> p(n, 0);
        for (int i = 0; i < n; ++i) {
            p[i] = i;
        }

        // find the parent for each index
        function<int(int)> find = [&](int x) {
            if (p[x] != x) {
                p[x] = find(p[x]);
            }
            return p[x];
        };

        // union-find and create the connected groups
        for (const auto& pair : pairs) {
            int root1 = find(pair[0]);
            int root2 = find(pair[1]);
            if (root1 != root2) {
                p[root2] = root1;
            }
        }

        vector<string> groups(n);
        for (int i = 0; i < n; ++i) {
            groups[find(i)].push_back(s[i]);
        }

        // Sort each group
        for (string& group : groups) {
            sort(group.begin(), group.end(), greater<char>());
        }

        // Build the result string
        string res;
        for (int i = 0; i < n; ++i) {
            char smallest_char = groups[find(i)].back(); 
            res += smallest_char;
            groups[find(i)].pop_back();
        }

        return res;
    }
};

python_code:
from collections import defaultdict

class Solution:
    def smallestStringWithSwaps(self, s: str, pairs: List[List[int]]) -> str:
        n = len(s)

        # Initialize the parents array
        p = list(range(n))

        # Helper function to find the parent of an index
        def find(x):
            if p[x] != x:
                p[x] = find(p[x])
            return p[x]

        # Union-find, grouping connected indices together
        for pair in pairs:
            root1 = find(pair[0])
            root2 = find(pair[1])
            if root1 != root2:
                p[root2] = root1

        # Group all the characters together according to their representatives (parent)
        groups = defaultdict(list)
        for i in range(n):
            root = find(i)
            groups[root].append(s[i])

        # Sort each group
        for group in groups.values():
            group.sort(reverse=True)

        # Build the result string
        res = []
        for i in range(n):
            root = find(i)
            res.append(groups[root].pop())

        return "".join(res)

javascript_code:
/**
 * @param {string} s
 * @param {number[][]} pairs
 * @return {string}
 */
const smallestStringWithSwaps = (s, pairs) => {
    const n = s.length;
    const p = Array.from({length: n}, (_, i) => i);

    const find = x => {
        if (p[x] !== x) p[x] = find(p[x]);
        return p[x];
    };

    for (const [x, y] of pairs) {
        p[find(y)] = find(x);
    }

    const groups = Array.from({length: n}, () => []);
    for (let i = 0; i < n; i++) {
        const root = find(i);
        groups[root].push(s[i]);
    }

    for (const group of groups) {
        group.sort((a, b) => a.charCodeAt(0) - b.charCodeAt(0));
    }

    let result = '';
    for (let i = 0; i < n; i++) {
        const root = find(i);
        result += groups[root].pop();
    }

    return result;
};

