public void sortArray(int[] arr1, int[] arr2) {
    HashMap<Integer, Integer> counts = new HashMap<>();

    for (int num : arr1) {
        counts.put(num, counts.getOrDefault(num, 0) + 1);
    }

    int index = 0;
    for (int num : arr2) {
        while (counts.get(num) > 0) {
            arr1[index++] = num;
            counts.put(num, counts.get(num) - 1);
        }
    }

    Arrays.sort(arr1, index, arr1.length);
}

cpp_code:
#include <vector>
#include <map>
#include <algorithm>

void sortArray(vector<int>& arr1, vector<int>& arr2) {
    map<int, int> counts;

    for (int num : arr1) {
        counts[num]++;
    }
    int index = 0;
    for (int num : arr2) {
        while (counts[num]--) {
            arr1[index++] = num;
        }
    }
    for (auto &pair : counts) {
        while (pair.second--) {
            arr1[index++] = pair.first;
        }
    }
}

