class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

class Solution:
    def lcaDeepestLeaves(self, root: TreeNode) -> TreeNode:
        def dfs(node):
            if not node:
                return (None, 0)
            left, right = dfs(node.left), dfs(node.right)
            if left[1] > right[1]:
                return (left[0], left[1] + 1)
            elif left[1] < right[1]:
                return (right[0], right[1] + 1)
            else:
                return (node, left[1] + 1)

        return dfs(root)[0]

