function lcaDeepestLeaves(root) {
    function dfs(node) {
        if (!node) return {node: null, depth: 0};
        const left = dfs(node.left);
        const right = dfs(node.right);
        if (left.depth > right.depth) {
            return {node: left.node, depth: left.depth + 1};
        } else if (left.depth < right.depth) {
            return {node: right.node, depth: right.depth + 1};
        } else {
            return {node, depth: left.depth + 1};
        }
    }

    return dfs(root).node;
}

java_code:
import java.util.HashMap;

public int longestWPI(int[] hours) {
    int score = 0;
    int maxLength = 0;
    HashMap<Integer, Integer> firstOccurrence = new HashMap<>();

    for (int i = 0; i < hours.length; ++i) {
        score += hours[i] > 8 ? 1 : -1;
        if (score > 0) maxLength = i + 1;
        else {
            firstOccurrence.putIfAbsent(score, i);
            if (firstOccurrence.containsKey(score - 1))
                maxLength = Math.max(maxLength, i - firstOccurrence.get(score - 1));
        }
    }
    return maxLength;
}

