public int[] replaceElements(int[] arr) {
    int n = arr.length;
    int maxElement = -1;
    for (int i = n - 1; i >= 0; i--) {
        int temp = arr[i];
        arr[i] = maxElement;
        maxElement = Math.max(maxElement, temp);
    }
    return arr;
}

