java_code:
public String alphabetBoardPath(String target) {
    int x = 0, y = 0;
    StringBuilder sb = new StringBuilder();

    for (char c : target.toCharArray()) {
        int dx = (c - 'a') / 5;
        int dy = (c - 'a') % 5;
        while (x > dx) {
            sb.append('U');
            x--;
        }
        while (y > dy) {
            sb.append('L');
            y--;
        }
        while (x < dx) {
            sb.append('D');
            x++;
        }
        while (y < dy) {
            sb.append('R');
            y++;
        }
        sb.append('!');
    }
    return sb.toString();
}

cpp_code:
#include <string>
#include <utility>

std::string alphabetBoardPath(const std::string& target) {
    std::string result;
    std::pair<int, int> startPosition(0, 0);

    for (char t : target) {
        int r = (t - 'a') / 5;
        int c = (t - 'a') % 5;
        while (startPosition.first > r) {
            result.push_back('U');
            --startPosition.first;
        }
        while (startPosition.second > c) {
            result.push_back('L');
            --startPosition.second;
        }
        while (startPosition.first < r) {
            result.push_back('D');
            ++startPosition.first;
        }
        while (startPosition.second < c) {
            result.push_back('R');
            ++startPosition.second;
        }
        result.push_back('!');
    }
    return result;
}

python_code:
def alphabet_board_path(target: str) -> str:
    startX, startY = 0, 0
    result = []

    for t in target:
        targetX, targetY = divmod(ord(t) - ord('a'), 5)
        while startX > targetX:
            result.append('U')
            startX -= 1
        while startY > targetY:
            result.append('L')
            startY -= 1
        while startX < targetX:
            result.append('D')
            startX += 1
        while startY < targetY:
            result.append('R')
            startY += 1
        result.append('!')

    return ''.join(result)

