from collections import deque, defaultdict

def tree_diameter(edges):
    tree = defaultdict(list)
    for edge in edges:
        tree[edge[0]].append(edge[1])
        tree[edge[1]].append(edge[0])

    queue = deque([(0, 0)])
    furthest, max_distance = 0, 0
    while queue:
        node, distance = queue.popleft()
        if distance > max_distance:
            max_distance = distance
            furthest = node
        for neighbor in tree[node]:
            tree[neighbor].remove(node)
            queue.append((neighbor, distance + 1))

    queue.append((furthest, 0))
    max_distance = 0
    while queue:
        node, distance = queue.popleft()
        if distance > max_distance:
            max_distance = distance
        for neighbor in tree[node]:
            tree[neighbor].remove(node)
            queue.append((neighbor, distance + 1))

    return max_distance

javascript_code:
/**
 * @param {number[][]} edges
 * @return {number}
 */
var treeDiameter = function(edges) {
    const tree = new Map();

    for (const edge of edges) {
        if (!tree.has(edge[0])) tree.set(edge[0], []);
        if (!tree.has(edge[1])) tree.set(edge[1], []);

        tree.get(edge[0]).push(edge[1]);
        tree.get(edge[1]).push(edge[0]);
    }

    const queue = [[0, 0]];
    let furthest = 0;
    let maxDistance = 0;

    while (queue.length > 0) {
        const [node, distance] = queue.shift();
        if (distance > maxDistance) {
            maxDistance = distance;
            furthest = node;
        }

        for (const neighbor of tree.get(node)) {
            tree.get(neighbor).splice(tree.get(neighbor).indexOf(node), 1);
            queue.push([neighbor, distance + 1]);
        }
    }

    queue.push([furthest, 0]);
    maxDistance = 0;

    while (queue.length > 0) {
        const [node, distance] = queue.shift();
        if (distance > maxDistance) {
            maxDistance = distance;
        }

        for (const neighbor of tree.get(node)) {
            tree.get(neighbor).splice(tree.get(neighbor).indexOf(node), 1);
            queue.push([neighbor, distance + 1]);
        }
    }

    return maxDistance;
};

