public class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode(int x) { val = x; }
}

public boolean canWin(TreeNode root, int x) {
    if (root == null) return false;
    if (root.val == x) {
        int leftNodes = 0, rightNodes = 0;
        if (root.left != null) leftNodes = 1 + canWin(root.left, x);
        if (root.right != null) rightNodes = 1 + canWin(root.right, x);
        return leftNodes % 2 != 0 || rightNodes % 2 != 0;
    }
    return canWin(root.left, x) || canWin(root.right, x);
}

