import java.util.*;

class Solution {
    public int[][] diagonalSort(int[][] mat) {
        int m = mat.length, n = mat[0].length;
        for (int i = 0; i < m; ++i) {
            PriorityQueue<Integer> pq = new PriorityQueue<>();
            int row = i, col = 0;
            while (row < m && col < n) {
                pq.offer(mat[row++][col++]);
            }
            row = i; col = 0;
            while (row < m && col < n) {
                mat[row++][col++] = pq.poll();
            }
        }
        for (int i = 1; i < n; ++i) {
            PriorityQueue<Integer> pq = new PriorityQueue<>();
            int row = 0, col = i;
            while (row < m && col < n) {
                pq.offer(mat[row++][col++]);
            }
            row = 0; col = i;
            while (row < m && col < n) {
                mat[row++][col++] = pq.poll();
            }
        }
        return mat;
    }
}

