vector<vector<int>> diagonalSort(vector<vector<int>>& mat) {
    int m = mat.size(), n = mat[0].size();
    for (int i = 0; i < m; ++i) {
        priority_queue<int, vector<int>, greater<>> pq;
        int row = i, col = 0;
        while (row < m && col < n) {
            pq.push(mat[row++][col++]);
        }
        row = i, col = 0;
        while (row < m && col < n) {
            mat[row++][col++] = pq.top();
            pq.pop();
        }
    }
    for (int i = 1; i < n; ++i) {
        priority_queue<int, vector<int>, greater<>> pq;
        int row = 0, col = i;
        while (row < m && col < n) {
            pq.push(mat[row++][col++]);
        }
        row = 0, col = i;
        while (row < m && col < n) {
            mat[row++][col++] = pq.top();
            pq.pop();
        }
    }
    return mat;
}

javascript_code:
function diagonalSort(mat) {
    const m = mat.length, n = mat[0].length;
    for (let i = 0; i < m; ++i) {
        let pq = [];
        let [row, col] = [i, 0];
        while (row < m && col < n) {
            pq.push(mat[row++][col++]);
        }
        pq.sort((a, b) => a - b);
        [row, col] = [i, 0];
        while (row < m && col < n) {
            mat[row++][col++] = pq.shift();
        }
    }
    for (let i = 1; i < n; ++i) {
        let pq = [];
        let [row, col] = [0, i];
        while (row < m && col < n) {
            pq.push(mat[row++][col++]);
        }
        pq.sort((a, b) => a - b);
        [row, col] = [0, i];
        while (row < m && col < n) {
            mat[row++][col++] = pq.shift();
        }
    }
    return mat;
}

