from collections import deque
from itertools import chain

def matrix_rank_transform(matrix):
    def neighbours(r, c):
        for i in range(m):
            if i != r:
                yield i, c
        for i in range(n):
            if i != c:
                yield r, i

    m, n = len(matrix), len(matrix[0])
    rank = [[0] * n for _ in range(m)]
    sorted_row = [0] * m
    sorted_col = [0] * n

    for bound in range(200001):
        q = deque((r, c) for r in range(m) for c in range(n) if matrix[r][c] == bound and rank[r][c] == 0)
        if not q:
            break
        while q:
            r, c = rc = q.popleft()
            potential_rank = sorted_row[r] + 1
            for row, col in neighbours(r, c):
                if matrix[row][col] <= matrix[r][c]:
                    potential_rank = max(potential_rank, rank[row][col] + (matrix[row][col] < matrix[r][c]))
            if potential_rank == sorted_col[c] + 1:
                rank[r][c] = sorted_row[r] = sorted_col[c] = potential_rank
            else:
                q.append(rc)
    return rank

javascript_code:
function matrixRankTransform(matrix) {
    function* neighbours(r, c) {
        for (let i = 0; i < m; ++i) if (i != r) yield [i, c];
        for (let i = 0; i < n; ++i) if (i != c) yield [r, i];
    }

    const m = matrix.length, n = matrix[0].length;
    const rank = Array.from({length: m}, () => Array(n).fill(0));
    const sorted_row = new Array(m).fill(0);
    const sorted_col = new Array(n).fill(0);

    for (let bound = 0; bound <= 200000; bound++) {
        const q = [];
        for (let i = 0; i < m; ++i) {
            for (let j = 0; j < n; ++j) {
                if (matrix[i][j] == bound && rank[i][j] == 0) {
                    q.push([i, j]);
                }
            }
        }
        if (q.length === 0) break;
        while (q.length > 0) {
            const [r, c] = rc = q.shift();
            let potential_rank = sorted_row[r] + 1;
            for (const [row, col] of neighbours(r, c)) {
                if (matrix[row][col] <= matrix[r][c]) {
                    potential_rank = Math.max(potential_rank, rank[row][col] + (matrix[row][col] < matrix[r][c] ? 0 : 1));
                }
            }
            if (potential_rank === (sorted_col[c] + 1)) {
                rank[r][c] = sorted_row[r] = sorted_col[c] = potential_rank;
            } else {
                q.push(rc);
            }
        }
    }
    return rank;
}

