#include <vector>
#include <string>
#include <set>
#include <map>

using namespace std;

void generateSentencesHelper(int index, vector<string>& words, map<string, set<string>>& synonyms, vector<string>& result, string curSentence) {
    if (index == words.size()) {
        result.push_back(curSentence);
    } else {
        set<string>& synSet = synonyms[words[index]];
        for (const auto& syn : synSet) {
            generateSentencesHelper(index + 1, words, synonyms, result, curSentence + (curSentence.empty() ? "" : " ") + syn);
        }
    }
}

vector<string> generateSentences(vector<vector<string>>& synonyms, string text) {
    map<string, set<string>> synonymMap;

    for (const auto& synPair : synonyms) {
        synonymMap[synPair[0]].insert(synPair[0]);
        synonymMap[synPair[0]].insert(synPair[1]);
        synonymMap[synPair[1]].insert(synPair[0]);
        synonymMap[synPair[1]].insert(synPair[1]);
    }

    vector<string> words;
    size_t start = 0, end = text.find(' ');

    while (end != string::npos) {
        words.push_back(text.substr(start, end - start));
        start = end + 1;
        end = text.find(' ', start);
    }

    words.push_back(text.substr(start));

    vector<string> result;
    generateSentencesHelper(0, words, synonymMap, result, "");

    return result;
}

python_code:
from typing import List


def generateSentences(synonyms: List[List[str]], text: str) -> List[str]:
    synonym_map = {}

    for s, t in synonyms:
        if s not in synonym_map:
            synonym_map[s] = {s}
        if t not in synonym_map:
            synonym_map[t] = {t}
        synonym_map[s].add(t)
        synonym_map[t].add(s)

    words = text.split()
    results = []

    def helper(index: int, cur_sentence: List[str]) -> None:
        if index == len(words):
            results.append(" ".join(cur_sentence))
            return
        for w in synonym_map.get(words[index], {words[index]}):
            cur_sentence.append(w)
            helper(index + 1, cur_sentence)
            cur_sentence.pop()

    helper(0, [])

    return sorted(results)

javascript_code:
function generateSentences(synonyms, text) {
    const synonymMap = new Map();

    for (const [s, t] of synonyms) {
        if (!synonymMap.has(s)) {
            synonymMap.set(s, new Set([s]));
        }
        if (!synonymMap.has(t)) {
            synonymMap.set(t, new Set([t]));
        }
        synonymMap.get(s).add(t);
        synonymMap.get(t).add(s);
    }

    const words = text.split(" ");
    const results = [];

    function helper(index, curSentence) {
        if (index === words.length) {
            results.push(curSentence.join(" "));
        } else {
            const synSet = synonymMap.get(words[index]) || new Set([words[index]]);

            for (const w of synSet) {
                curSentence.push(w);
                helper(index + 1, curSentence);
                curSentence.pop();
            }
        }
    }

    helper(0, []);

    return results.sort();
}

