            int randomIndex = rand() % (right - left + 1) + left;
            int num = positions[arr[randomIndex]].size();
            if (num >= threshold) {
                auto lb = lower_bound(positions[arr[randomIndex]].begin(), positions[arr[randomIndex]].end(), left);
                auto ub = upper_bound(positions[arr[randomIndex]].begin(), positions[arr[randomIndex]].end(), right);
                if(ub - lb >= threshold) return arr[randomIndex];
            }
        }
        return -1;
    }
private:
    unordered_map<int, vector<int>> positions;
};

python_code:
from collections import defaultdict
from random import randint

class MajorityChecker:
    def __init__(self, arr: List[int]):
        self.arr = arr
        self.positions = defaultdict(list)
        for i, num in enumerate(arr):
            self.positions[num].append(i)

    def query(self, left: int, right: int, threshold: int) -> int:
        for _ in range(20):
            randomIndex = randint(left, right)
            num = self.arr[randomIndex]
            lb = self.lower_bound(self.positions[num], left)
            ub = self.upper_bound(self.positions[num], right)
            if ub - lb >= threshold:
                return num
        return -1

    def lower_bound(self, nums, target):
        l, r = 0, len(nums)
        while l < r:
            mid = (l + r) // 2
            if nums[mid] < target:
                l = mid + 1
            else:
                r = mid
        return l

    def upper_bound(self, nums, target):
        l, r = 0, len(nums)
        while l < r:
            mid = (l + r) // 2
            if nums[mid] <= target:
                l = mid + 1
            else:
                r = mid
        return l

javascript_code:
class MajorityChecker {
    constructor(arr) {
        this.arr = arr;
        this.positions = new Map();
        for(let i = 0; i < arr.length; i++) {
            if (!this.positions.has(arr[i])) this.positions.set(arr[i], []);
            this.positions.get(arr[i]).push(i);
        }
    }

    query(left, right, threshold) {
        for(let i = 0; i < 20; i++) {
            let randomIndex = Math.floor(Math.random() * (right - left + 1)) + left;
            let num = this.positions.get(this.arr[randomIndex]).length;
            if (num >= threshold) {
                let lb = this.lower_bound(this.positions.get(this.arr[randomIndex]), left);
                let ub = this.upper_bound(this.positions.get(this.arr[randomIndex]), right);
                if(ub - lb >= threshold) return this.arr[randomIndex];
            }
        }
        return -1;
    }

    lower_bound(nums, target) {
        let l = 0, r = nums.length;
        while (l < r) {
            let mid = Math.floor((l + r) / 2);
            if (nums[mid] < target) l = mid + 1;
            else r = mid;
        }
        return l;
    }

    upper_bound(nums, target) {
        let l = 0, r = nums.length;
        while (l < r) {
            let mid = Math.floor((l + r) / 2);
            if (nums[mid] <= target) l = mid + 1;
            else r = mid;
        }
        return l;
    }
}

