public ListNode removeZeroSumSublists(ListNode head) {
    ListNode dummy = new ListNode(0);
    dummy.next = head;
    ListNode current = dummy;

    while (current != null) {
        int sum = 0;
        while (head != null) {
            sum += head.val;
            if (sum == 0) {
                current.next = head.next;
            }
            head = head.next;
        }
        current = current.next;
        if (current != null) {
            head = current.next;
        }
    }

    return dummy.next;
}

