java_code:
final int mod = 1000000007;

public int numOfWays(int steps, int arrLen) {
  int maxPos = Math.min(steps / 2, arrLen - 1);
  int[][] dp = new int[2][maxPos + 1];
  dp[0][0] = 1;
  for (int s = 1; s <= steps; ++s) {
    for (int p = 0; p <= maxPos; ++p) {
      dp[s % 2][p] = dp[(s - 1) % 2][p];
      if (p > 0)
        dp[s % 2][p] += dp[(s - 1) % 2][p - 1];
      if (p < maxPos)
        dp[s % 2][p] += dp[(s - 1) % 2][p + 1];
      dp[s % 2][p] %= mod;
    }
  }
  return dp[steps % 2][0];
}

