#include <string>

std::string toHexspeak(std::string num) {
    long n = std::stol(num);
    std::string hex = "";
    while (n) {
        int rem = n % 16;
        if (rem == 1) hex = "I" + hex;
        else if (rem == 0) hex = "O" + hex;
        else if (rem > 9) hex = (char)(rem - 10 + 'A') + hex;
        else return "ERROR";
        n /= 16;
    }
    return hex;
}

