    if (sum % 3 == 1) {
        if (count[1] >= 1) count[1]--; 
        else count[2] -= 2;
    }
    else if (sum % 3 == 2) {
        if (count[2] >= 1) count[2]--;
        else count[1] -= 2;
    }

    std::string res = "";
    for (int i = 0; i <= 9; ++i) {
        int n = count[i % 3];
        while (n--) res += std::to_string(i);
    }

    if (!res.empty() && res.back() == '0') return "0";
    std::reverse(res.begin(), res.end());
    return res;
}

