    std::vector<std::vector<int>> dp(n, std::vector<int>(n, 0));

    for (int len = 2; len <= n; ++len) {
        for (int i = 0; i <= n - len; ++i) {
            int j = i + len - 1;
            dp[i][j] = dp[i + 1][j - 1] + (s[i] != s[j]);
        }
    }

    std::vector<int> memo(n, 1e9);
    for (int i = 0; i < n; ++i) {
        if (dp[0][i] == 0) {
            memo[i] = 0;
        } else {
            for (int j = 0; j < i; ++j) {
                memo[i] = std::min(memo[i], memo[j] + dp[j + 1][i]);
            }
        }
    }

    return memo.back() + k;
}

