    for (let len = 2; len <= n; ++len) {
        for (let i = 0; i <= n - len; ++i) {
            const j = i + len - 1;
            dp[i][j] = dp[i + 1][j - 1] + (s[i] !== s[j] ? 1 : 0);
        }
    }

    const memo = Array(n).fill(1e9);
    for (let i = 0; i < n; ++i) {
        if (dp[0][i] === 0) {
            memo[i] = 0;
        } else {
            for (let j = 0; j < i; ++j) {
                memo[i] = Math.min(memo[i], memo[j] + dp[j + 1][i]);
            }
        }
    }

    return memo[memo.length - 1] + k;
}

