public int sumOfDivisorsWithFourDivisors(int[] nums) {
    int sum = 0;
    for (int num : nums) {
        int divCount = 0;
        int divSum = 0;

        for (int i = 1; i * i <= num; ++i) {
            if (num % i == 0) {
                divSum += i;
                ++divCount;

                if (num / i != i) {
                    divSum += (num / i);
                    ++divCount;
                }
            }

            if (divCount > 4) {
                break;
            }
        }

        if (divCount == 4) {
            sum += divSum;
        }
    }

    return sum;
}

