                div_count += 1

                if num // i != i:
                    div_sum += num // i
                    div_count += 1

            if div_count > 4:
                break

        if div_count == 4:
            total_sum += div_sum

    return total_sum

javascript_code:
function sumOfDivisorsWithFourDivisors(nums) {
    let sum = 0;
    for (let num of nums) {
        let divCount = 0;
        let divSum = 0;

        for (let i = 1; i * i <= num; ++i) {
            if (num % i === 0) {
                divSum += i;
                ++divCount;

                if (num / i !== i) {
                    divSum += (num / i);
                    ++divCount;
                }
            }

            if (divCount > 4) {
                break;
            }
        }

        if (divCount === 4) {
            sum += divSum;
        }
    }

    return sum;
}

