class TreeAncestor:

    def __init__(self, n: int, parent: List[int]):
        self.dp = [[0] * 20 for _ in range(n)]
        for i in range(n):
            self.dp[i][0] = parent[i]
        for k in range(1, 20):
            for i in range(n):
                if self.dp[i][k - 1] != -1:
                    self.dp[i][k] = self.dp[self.dp[i][k - 1]][k - 1]
                else:
                    self.dp[i][k] = -1

    def getKthAncestor(self, node: int, k: int) -> int:
        for i in range(20):
            if k & (1 << i):
                node = self.dp[node][i]
                if node == -1:
                    return -1
        return node

