class TreeAncestor {
    constructor(n, parent) {
        this.dp = new Array(n).fill(0).map(() => new Array(20).fill(0));
        for (let i = 0; i < n; i++) this.dp[i][0] = parent[i];
        for (let k = 1; k < 20; k++)
            for (let i = 0; i < n; i++)
                this.dp[i][k] = this.dp[i][k - 1] === -1 ? -1 : this.dp[this.dp[i][k - 1]][k - 1];
    }

    getKthAncestor(node, k) {
        for (let i = 0; i < 20; i++) {
            if (k & (1 << i)) {
                node = this.dp[node][i];
                if (node === -1) return -1;
            }
        }
        return node;
    }
}

