std::string reverseParentheses(std::string s) {
    std::stack<char> st;
    std::string result = "";

    for (char c : s) {
        if (c != ')') {
            st.push(c);
        } else {
            std::string temp = "";
            while (!st.empty() && st.top() != '(') {
                temp += st.top();
                st.pop();
            }
            if (!st.empty()) st.pop(); // Remove '('
            for (char t : temp) {
                st.push(t);
            }
        }
    }

    while (!st.empty()) {
        result = st.top() + result;
        st.pop();
    }

    return result;
}

