    result = []

    for c in s:
        if c != ')':
            st.append(c)
        else:
            temp = []
            while st and st[-1] != '(':
                temp.append(st.pop())
            if st: st.pop()  # Remove '('
            st.extend(temp)

    result = "".join(st)
    return result

