function reverseParentheses(s) {
    const st = [];
    let result = "";

    for (const c of s) {
        if (c !== ')') {
            st.push(c);
        } else {
            let temp = "";
            while (st.length > 0 && st[st.length - 1] !== '(') {
                temp += st.pop();
            }
            if (st.length > 0) st.pop(); // Remove '('
            for (const t of temp) {
                st.push(t);
            }
        }
    }

    result = st.join("");
    return result;
}

