from heapq import heappush, heappop

def longestHappyString(a, b, c):
    res = ""
    pq = []
    if a: heappush(pq, (-a, 'a'))
    if b: heappush(pq, (-b, 'b'))
    if c: heappush(pq, (-c, 'c'))

    while pq:
        curr = heappop(pq)
        if len(res) >= 2 and res[-1] == curr[1] and res[-2] == curr[1]:
            if not pq: break
            next = heappop(pq)
            res += next[1]
            if next[0] < -1: heappush(pq, (next[0] + 1, next[1]))
            heappush(pq, curr)
        else:
            res += curr[1]
            if curr[0] < -1: heappush(pq, (curr[0] + 1, curr[1]))

    return res

javascript_code:
function longestHappyString(a, b, c) {
    let res = "";
    let pq = [];

    if (a) pq.push([-a, 'a']);
    if (b) pq.push([-b, 'b']);
    if (c) pq.push([-c, 'c']);

    pq.sort((x, y) => x[0] - y[0]);

    while (pq.length) {
        let curr = pq.pop();
        if (res.length >= 2 && res[res.length - 1] === curr[1] && res[res.length - 2] === curr[1]) {
            if (!pq.length) break;
            let next = pq.pop();
            res += next[1];
            if (next[0] < -1) pq.push([next[0] + 1, next[1]]);
            pq.push(curr);
        } else {
            res += curr[1];
            if (curr[0] < -1) pq.push([curr[0] + 1, curr[1]]);
        }
        pq.sort((x, y) => x[0] - y[0]);
    }

    return res;
}

