import java.util.Stack;

public int[] peopleCanSee(int[] heights) {
    int n = heights.length;
    int[] ans = new int[n];
    Stack<Integer> st = new Stack<>();

    for (int i = n - 1; i >= 0; --i) {
        while (!st.isEmpty() && heights[st.peek()] < heights[i]) {
            int idx = st.pop();
            ans[i]++;
            ans[i] += ans[idx];
        }
        st.push(i);
    }

    return ans;
}

