                    col[i + k][j + t] - col[i][j + t] == _sum for t in range(1, k))

                if not ok: continue

                diag1 = sum(grid[i + t][j + t] for t in range(k))
                diag2 = sum(grid[i + t][j + k - 1 - t] for t in range(k))

                if diag1 == _sum and diag2 == _sum: return k

