public int sumEvenGrandparent(TreeNode root, TreeNode parent, TreeNode grandparent) {
    if (root == null) return 0;
    int sum = (grandparent != null && grandparent.val % 2 == 0) ? root.val : 0;
    return sum + sumEvenGrandparent(root.left, root, parent) + sumEvenGrandparent(root.right, root, parent);
}

