public int[] findBall(int[][] grid) {
    int m = grid.length;
    int n = grid[0].length;
    int[] result = new int[n];

    for (int i = 0; i < n; i++) {
        int x = 0, y = i;
        result[i] = -1;

        while (x < m) {
            int nx = x + 1, ny = y + grid[x][y];
            if (ny < 0 || ny >= n || grid[x][ny] != grid[x][y]) break;
            x = nx;
            y = ny;
        }

        if (x == m) {
            result[i] = y;
        }
    }

    return result;
}

