#include <vector>
#include <queue>
using namespace std;

double maxProbability(int n, vector<vector<int>>& edges, vector<double>& succProb, int start, int end) {
    vector<vector<pair<int, double>>> graph(n);
    for (int i = 0; i < edges.size(); ++i) {
        graph[edges[i][0]].emplace_back(edges[i][1], succProb[i]);
        graph[edges[i][1]].emplace_back(edges[i][0], succProb[i]);
    }

    vector<double> maxProb(n, 0);
    maxProb[start] = 1;

    priority_queue<pair<double, int>> pq;
    pq.emplace(1, start);

    while (!pq.empty()) {
        double prob = pq.top().first;
        int node = pq.top().second;
        pq.pop();

        if (node == end) {
            return prob;
        }

        if (prob < maxProb[node]) {
            continue;
        }

        for (auto& edge : graph[node]) {
            double newProb = prob * edge.second;
            if (newProb > maxProb[edge.first]) {
                maxProb[edge.first] = newProb;
                pq.emplace(newProb, edge.first);
            }
        }
    }

    return 0;
}

python_code:
from heapq import heappush, heappop

def maxProbability(n, edges, succProb, start, end):
    graph = [[] for _ in range(n)]
    for i in range(len(edges)):
        a, b = edges[i]
        graph[a].append((b, succProb[i]))
        graph[b].append((a, succProb[i]))

    max_prob = [0] * n
    max_prob[start] = 1

    pq = [(-1, start)]

    while pq:
        prob, node = heappop(pq)

        if node == end:
            return -prob

        if -prob < max_prob[node]:
            continue

        for neighbor, edge_prob in graph[node]:
            new_prob = -prob * edge_prob
            if new_prob > max_prob[neighbor]:
                max_prob[neighbor] = new_prob
                heappush(pq, (-new_prob, neighbor))

    return 0

javascript_code:
function maxProbability(n, edges, succProb, start, end) {
  const graph = new Array(n).fill(null).map(() => []);
  for (let i = 0; i < edges.length; i++) {
    const [a, b] = edges[i];
    graph[a].push([b, succProb[i]]);
    graph[b].push([a, succProb[i]]);
  }

  const maxProb = new Array(n).fill(0);
  maxProb[start] = 1;

  const pq = [[1, start]];

  while (pq.length) {
    const [prob, node] = pq.pop();

    if (node === end) {
      return prob;
    }

    if (prob < maxProb[node]) {
      continue;
    }

    for (const [neighbor, edgeProb] of graph[node]) {
      const newProb = prob * edgeProb;
      if (newProb > maxProb[neighbor]) {
        maxProb[neighbor] = newProb;
        pq.push([newProb, neighbor]);

        // Re-sort the queue, so it stays a max heap.
        pq.sort(([a], [b]) => b - a);
      }
    }
  }

  return 0;
}

java_code:
public int sumOfFlooredPairs(int[] nums) {
    int mod = 1000000007;
    int maxVal = Integer.MIN_VALUE;
    for (int num : nums) {
        maxVal = Math.max(maxVal, num);
    }
    int[] count = new int[maxVal + 1];
    long[] prefSum = new long[maxVal + 1];

    for (int num : nums) {
        count[num]++;
    }

    for (int i = 1; i <= maxVal; i++) {
        prefSum[i] = (prefSum[i - 1] + count[i]) % mod;
    }

    long res = 0;
    for (int x = 1; x <= maxVal; x++) {
        for (int k = 1, nx = x; nx <= maxVal; k++, nx += x) {
            res = (res + ((prefSum[nx] - prefSum[nx - x] + mod) % mod) * k % mod * count[x] % mod) % mod;
        }
    }
    return (int) res;
}

