public int longestSubsequence(int[] arr, int difference) {
    HashMap<Integer, Integer> dp = new HashMap<>();
    int maxLength = 0;
    for (int num : arr) {
        dp.put(num, dp.getOrDefault(num - difference, 0) + 1);
        maxLength = Math.max(maxLength, dp.get(num));
    }
    return maxLength;
}

