#include <vector>
#include <unordered_map>
#include <queue>
using namespace std;

int minSetSize(vector<int>& arr) {
    unordered_map<int, int> freq_map;
    priority_queue<int> max_heap;
    for (int x : arr)
        freq_map[x]++;
    for (auto &[_, cnt] : freq_map)
        max_heap.push(cnt);
    int half = arr.size() / 2;
    int cnt = 0;
    int size = 0;
    while (size < half) {
        size += max_heap.top();
        max_heap.pop();
        cnt++;
    }
    return cnt;
}

