java_code:
import java.util.concurrent.locks.*;

class DiningPhilosophers {
    private final ReentrantLock[] locks = new ReentrantLock[5];
    private final Condition[] notBusy = new Condition[5];

    public DiningPhilosophers() {
        for (int i = 0; i < 5; i++) {
            locks[i] = new ReentrantLock();
            notBusy[i] = locks[i].newCondition();
        }
    }

    public void wantsToEat(int philosopher,
                            Runnable pickLeftFork,
                            Runnable pickRightFork,
                            Runnable eat,
                            Runnable putLeftFork,
                            Runnable putRightFork) throws InterruptedException {
        int leftFork = philosopher;
        int rightFork = (philosopher + 1) % 5;

        locks[leftFork].lock();
        try {
            while (!locks[rightFork].tryLock()) {
                notBusy[leftFork].await();
            }
            pickLeftFork.run();

            try {
                pickRightFork.run();
                eat.run();
                putRightFork.run();
            } finally {
                locks[rightFork].unlock();
            }
            notBusy[rightFork].signalAll();

            putLeftFork.run();
        } finally {
            locks[leftFork].unlock();
        }
        notBusy[leftFork].signalAll();
    }
}

cpp_code:
#include <mutex>
#include <condition_variable>

class DiningPhilosophers {
    std::mutex forks[5];
    std::condition_variable not_busy[5];

public:
    void wantsToEat(int philosopher,
                    std::function<void()> pickLeftFork,
                    std::function<void()> pickRightFork,
                    std::function<void()> eat,
                    std::function<void()> putLeftFork,
                    std::function<void()> putRightFork) {
        int left_fork = philosopher;
        int right_fork = (philosopher + 1) % 5;

        {
            std::unique_lock<std::mutex> lock(forks[left_fork]);
            not_busy[left_fork].wait(lock, [&] { return !forks[right_fork].try_lock(); });
            pickLeftFork();

            std::unique_lock<std::mutex> right_lock(forks[right_fork], std::adopt_lock);
            pickRightFork();
            eat();

            putRightFork();
            right_lock.unlock();
            not_busy[right_fork].notify_all();
        }

        putLeftFork();
        not_busy[left_fork].notify_all();
    }
};

javascript_code:
class DiningPhilosophers {
    constructor() {
        this.forks = Array.from({ length: 5 }, () => new Mutex());
        this.notBusy = Array.from({ length: 5 }, (_, i) => new ConditionVariable(this.forks[i]));
    }

    async wantsToEat(philosopher, pickLeftFork, pickRightFork, eat, putLeftFork, putRightFork) {
        const leftFork = philosopher;
        const rightFork = (philosopher + 1) % 5;

        await this.forks[leftFork].lock();
        try {
            await this.notBusy[leftFork].wait(async () => !(await this.forks[rightFork].tryLock()));
            pickLeftFork();

            try {
                await this.forks[rightFork].lock();
                pickRightFork();
                eat();
                putRightFork();
                this.forks[rightFork].unlock();
                this.notBusy[rightFork].signalAll();

                putLeftFork();
            } finally {
                this.forks[leftFork].unlock();
            }
        } finally {
            this.notBusy[leftFork].signalAll();
        }
    }
}

