function minJumps(arr) {
  const n = arr.length;
  if (n <= 1) return 0;

  const valueIndices = new Map();

  for (let i = 0; i < n; ++i) {
    if (!valueIndices.has(arr[i])) valueIndices.set(arr[i], []);
    valueIndices.get(arr[i]).push(i);
  }

  const q = [0];
  const visited = new Array(n).fill(false);
  visited[0] = true;
  let steps = 0;

  while (q.length) {
    const size = q.length;

    for (let i = 0; i < size; ++i) {
      const index = q.shift();

      if (index === n - 1) return steps;

      if (index > 0 && !visited[index - 1]) {
        q.push(index - 1);
        visited[index - 1] = true;
      }

      if (index < n - 1 && !visited[index + 1]) {
        q.push(index + 1);
        visited[index + 1] = true;
      }

      for (const neighbor of valueIndices.get(arr[index])) {
        if (!visited[neighbor]) {
          q.push(neighbor);
          visited[neighbor] = true;
        }
      }

      valueIndices.set(arr[index], []);
    }

    ++steps;
  }

  return -1;
}

