public int minMovesToPalindrome(String s) {
    char[] chars = s.toCharArray();
    int moves = 0;
    int left = 0, right = s.length() - 1;

    while (left < right) {
        if (chars[left] != chars[right]) {
            int temp_right = right;

            while (chars[left] != chars[temp_right]) {
                temp_right--;
            }
            char temp = chars[temp_right];
            System.arraycopy(chars, temp_right + 1, chars, temp_right, right - temp_right);
            chars[right] = temp;
            moves += right - temp_right;
        }
        left++;
        right--;
    }

    return moves;
}

cpp_code:
#include <string>
using namespace std;

int min_moves_to_palindrome(string s) {
    int moves = 0;
    int left = 0, right = s.length() - 1;

    while (left < right) {
        if (s[left] != s[right]) {
            int temp_right = right;

            while (s[left] != s[temp_right]) {
                temp_right--;
            }
            s.erase(s.begin() + temp_right);
            s.insert(s.begin() + right, s[left]);
            moves += right - temp_right;
        }
        left++;
        right--;
    }

    return moves;
}

