function minMovesToPalindrome(s) {
    let moves = 0;
    s = s.split('');
    let left = 0, right = s.length - 1;

    while (left < right) {
        if (s[left] !== s[right]) {
            let temp_right = right;

            while (s[left] !== s[temp_right]) {
                temp_right--;
            }
            s.splice(right, 0, s.splice(temp_right, 1)[0]);
            moves += right - temp_right;
        }
        left++;
        right--;
    }

    return moves;
}

