        for (int i = dp.size() - 1; i >= 0; --i) {
            std::string tmp = dp[i] + s;
            if (std::unordered_set<char>(tmp.begin(), tmp.end()).size() == tmp.size()) {
                dp.push_back(tmp);
                maxLen = std::max(maxLen, (int)tmp.size());
            }
        }
    }

    return maxLen;
}

