java_code:
public int tilingRectangle(int n, int m) {
    if (n > m) {
        int temp = n;
        n = m;
        m = temp;
    }
    if (n == 1) return m;
    if (n == m) return 1;

    int res = Integer.MAX_VALUE;
    for (int a = 1; a <= n / 2; a++) {
        res = Math.min(res, tilingRectangle(a, m) + tilingRectangle(n - a, m));
    }
    for (int b = 1; b <= m / 2; b++) {
        res = Math.min(res, tilingRectangle(n, b) + tilingRectangle(n, m - b));
    }
    return res;
}

