function findClosestDivisors(num) {
    for (let i = Math.floor(Math.sqrt(num + 2)); i >= 1; i--) {
        if ((num + 1) % i === 0) return [i, (num + 1) / i];
        if ((num + 2) % i === 0) return [i, (num + 2) / i];
    }
    return [];
}

