#include <vector>
#include <string>
#include <algorithm>

std::string largestMultipleOfThree(std::vector<int>& digits) {
    std::sort(digits.rbegin(), digits.rend());
    int sum = 0;
    for (int digit : digits) {
        sum += digit;
    }

    if (sum % 3 == 0) {
        if (digits.back() == 0) return "0";
        std::string result(digits.begin(), digits.end());
        return result;
    }

    std::vector<int> mod[3];
    for (int digit : digits) {
        mod[digit % 3].push_back(digit);
    }

    if (sum % 3 == 1) {
        if (!mod[1].empty()) {
            mod[1].pop_back();
        } else {
            mod[2].pop_back();
            mod[2].pop_back();
        }
    } else {
        if (!mod[2].empty()) {
            mod[2].pop_back();
        } else {
            mod[1].pop_back();
            mod[1].pop_back();
        }
    }

    std::string result;
    for (int i = 0; i < 3; ++i) {
        for (int digit : mod[i]) {
            result += std::to_string(digit);
        }
    }

    std::sort(result.rbegin(), result.rend());
    if (result.empty() || result[0] == '0') {
        return "0";
    }

    return result;
}

