public int numberOfSubarrays(int[] nums, int k) {
    int n = nums.length, result = 0, count = 0;
    int[] oddCount = new int[n + 1];

    oddCount[0] = 1;
    for (int i = 0; i < n; i++) {
        count += nums[i] % 2;
        if (count >= k) result += oddCount[count - k];
        oddCount[count]++;
    }

    return result;
}

