#include <string>
#include <stack>

std::string minRemoveToMakeValid(const std::string &s) {
    std::stack<int> stk;
    std::string result = s;

    for (int i = 0; i < s.size(); i++) {
        if (s[i] == '(') {
            stk.push(i);
        } else if (s[i] == ')') {
            if (!stk.empty()) {
                stk.pop();
            } else {
                result[i] = '-';
            }
        }
    }

    while (!stk.empty()) {
        result[stk.top()] = '-';
        stk.pop();
    }

    result.erase(std::remove(result.begin(), result.end(), '-'), result.end());
    return result;
}

