public class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode(int x) { val = x; }
}

class Solution {
    int maxSum = 0;

    public int maxSumBST(TreeNode root) {
        dfs(root);
        return maxSum;
    }

    private int[] dfs(TreeNode node) {
        if (node == null) 
            return new int[]{1, 0, Integer.MAX_VALUE, Integer.MIN_VALUE};

        int[] l = dfs(node.left);
        int[] r = dfs(node.right);

        if (l[0] == 0 || r[0] == 0 || node.val <= l[3] || node.val >= r[2]) 
            return new int[4];

        int currSum = node.val + l[1] + r[1];
        maxSum = Math.max(maxSum, currSum);

        return new int[]{1, currSum, Math.min(node.val, l[2]), Math.max(node.val, r[3])};
    }
}

cpp_code:
struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode(int x) : val(x), left(NULL), right(NULL) {}
};

class Solution {
public:
    int maxSumBST(TreeNode* root) {
        int maxSum = 0;
        dfs(root, maxSum);
        return maxSum;
    }

private:
    array<int, 4> dfs(TreeNode* node, int &maxSum) {
        if (!node) 
            return {1, 0, 1e5, -1e5};

        auto l = dfs(node->left, maxSum);
        auto r = dfs(node->right, maxSum);

        if (l[0] == 0 || r[0] == 0 || node->val <= l[3] || node->val >= r[2]) 
            return {0, 0, 0, 0};

        int currSum = node->val + l[1] + r[1];
        maxSum = max(maxSum, currSum);

        return {1, currSum, min(node->val, l[2]), max(node->val, r[3])};
    }
};

