function maxSumBST(root) {
    let maxSum = 0;

    function dfs(node) {
        if (node === null) 
            return [1, 0, Number.MAX_VALUE, Number.MIN_VALUE];

        const l = dfs(node.left);
        const r = dfs(node.right);

        if (l[0] === 0 || r[0] === 0 || node.val <= l[3] || node.val >= r[2]) 
            return new Array(4).fill(0);

        const currSum = node.val + l[1] + r[1];
        maxSum = Math.max(maxSum, currSum);

        return [1, currSum, Math.min(node.val, l[2]), Math.max(node.val, r[3])];
    }

    dfs(root);
    return maxSum;
}

