    for (let neighbor of graph[node]) {
        if (neighbor !== parent) {
            hasChild = true;
            dfs(neighbor, node, t - 1, target, graph, prob / (graph[node].length - (node !== 1 ? 1 : 0)), ans);
        }
    }

    if (!hasChild && node === target) ans[0] += prob;
}

