import java.util.ArrayList;
import java.util.List;

public int[][] reconstructMatrix(int upper, int lower, int[] colsum) {
    int[][] result = new int[2][colsum.length];

    for (int i = 0; i < colsum.length; i++) {
        if (colsum[i] == 2) {
            result[0][i] = 1;
            result[1][i] = 1;
            upper--;
            lower--;
        } else if (colsum[i] == 1) {
            if (upper > lower) {
                result[0][i] = 1;
                upper--;
            } else {
                result[1][i] = 1;
                lower--;
            }
        }

        if (upper < 0 || lower < 0) {
            return new int[][]{};
        }
    }

    if (upper > 0 || lower > 0) {
        return new int[][]{};
    }

    return result;
}

