java_code:
public class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode() {}
    TreeNode(int val) { this.val = val; }
    TreeNode(int val, TreeNode left, TreeNode right) {
        this.val = val;
        this.left = left;
        this.right = right;
    }
}

class Solution {
    public TreeNode balanceBST(TreeNode root) {
        List<TreeNode> sortedNodes = new ArrayList<>();
        inorderTraversal(root, sortedNodes);
        return sortedArrayToBST(sortedNodes, 0, sortedNodes.size() - 1);
    }

    private void inorderTraversal(TreeNode node, List<TreeNode> sortedNodes) {
        if (node == null) return;
        inorderTraversal(node.left, sortedNodes);
        sortedNodes.add(node);
        inorderTraversal(node.right, sortedNodes);
    }

    private TreeNode sortedArrayToBST(List<TreeNode> sortedNodes, int start, int end) {
        if (start > end) return null;
        int mid = start + (end - start) / 2;
        TreeNode newNode = sortedNodes.get(mid);
        newNode.left = sortedArrayToBST(sortedNodes, start, mid - 1);
        newNode.right = sortedArrayToBST(sortedNodes, mid + 1, end);
        return newNode;
    }
}

cpp_code:
struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode() : val(0), left(nullptr), right(nullptr) {}
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
    TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
};

class Solution {
public:
    TreeNode* balanceBST(TreeNode* root) {
        vector<TreeNode*> sortedNodes;
        inorderTraversal(root, sortedNodes);
        return sortedArrayToBST(sortedNodes, 0, sortedNodes.size() - 1);
    }

    void inorderTraversal(TreeNode* node, vector<TreeNode*>& sortedNodes) {
        if (node == nullptr) return;
        inorderTraversal(node->left, sortedNodes);
        sortedNodes.push_back(node);
        inorderTraversal(node->right, sortedNodes);
    }

    TreeNode* sortedArrayToBST(vector<TreeNode*>& sortedNodes, int start, int end) {
        if (start > end) return nullptr;
        int mid = start + (end - start) / 2;
        TreeNode* newNode = sortedNodes[mid];
        newNode->left = sortedArrayToBST(sortedNodes, start, mid - 1);
        newNode->right = sortedArrayToBST(sortedNodes, mid + 1, end);
        return newNode;
    }
};

python_code:
class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

class Solution:
    def balanceBST(self, root: TreeNode) -> TreeNode:
        sortedNodes = []
        self.inorderTraversal(root, sortedNodes)
        return self.sortedArrayToBST(sortedNodes, 0, len(sortedNodes) - 1)

    def inorderTraversal(self, node: TreeNode, sortedNodes: list):
        if node is None: return
        self.inorderTraversal(node.left, sortedNodes)
        sortedNodes.append(node)
        self.inorderTraversal(node.right, sortedNodes)

    def sortedArrayToBST(self, sortedNodes: list, start: int, end: int) -> TreeNode:
        if start > end: return None
        mid = start + (end - start) // 2
        newNode = sortedNodes[mid]
        newNode.left = self.sortedArrayToBST(sortedNodes, start, mid - 1)
        newNode.right = self.sortedArrayToBST(sortedNodes, mid + 1, end)
        return newNode

javascript_code:
class TreeNode {
    constructor(val, left = null, right = null) {
        this.val = val;
        this.left = left;
        this.right = right;
    }
}

function inorderTraversal(node, sortedNodes) {
    if (node === null) return;
    inorderTraversal(node.left, sortedNodes);
    sortedNodes.push(node);
    inorderTraversal(node.right, sortedNodes);
}

function sortedArrayToBST(sortedNodes, start, end) {
    if (start > end) return null;
    let mid = start + Math.floor((end - start) / 2);
    let newNode = sortedNodes[mid];
    newNode.left = sortedArrayToBST(sortedNodes, start, mid - 1);
    newNode.right = sortedArrayToBST(sortedNodes, mid + 1, end);
    return newNode;
}

function balanceBST(root) {
    let sortedNodes = [];
    inorderTraversal(root, sortedNodes);
    return sortedArrayToBST(sortedNodes, 0, sortedNodes.length - 1);
}

