#include <vector>
#include <queue>
#include <algorithm>

int maxPerformance(int n, int k, std::vector<int>& speed, std::vector<int>& efficiency) {
    std::vector<std::pair<int, int>> engineers(n);
    for (int i = 0; i < n; ++i) {
        engineers[i] = {efficiency[i], speed[i]};
    }

    std::sort(engineers.rbegin(), engineers.rend());

    std::priority_queue<int, std::vector<int>, std::greater<int>> min_heap;

    long long speed_sum = 0;
    long long max_performance = 0;

    for (auto& engineer : engineers) {
        speed_sum += engineer.second;
        min_heap.push(engineer.second);

        if (min_heap.size() > k) {
            speed_sum -= min_heap.top();
            min_heap.pop();
        }

        max_performance = std::max(max_performance, speed_sum * engineer.first);
    }

    return max_performance % 1000000007;
}

javascript_code:
function maxPerformance(n, k, speed, efficiency) {
    const engineers = efficiency.map((e, i) => [e, speed[i]]).sort((a, b) => b[0] - a[0]);
    const minHeap = new MinHeap();

    let speedSum = 0;
    let maxPerformance = 0;

    for (const [e, s] of engineers) {
        speedSum += s;
        minHeap.insert(s);

        if (minHeap.size() > k) {
            speedSum -= minHeap.extractMin();
        }

        maxPerformance = Math.max(maxPerformance, speedSum * e);
    }

    return maxPerformance % (10**9 + 7);
}

class MinHeap {
    constructor() {
        this.heap = [];
    }
    insert(value) {
        this.heap.push(value);
        this.bubbleUp(this.heap.length - 1);
    }
    extractMin() {
        const min = this.heap[0];
        this.heap[0] = this.heap.pop();
        this.bubbleDown(0);
        return min;
    }
    size() {
        return this.heap.length;
    }
    bubbleUp(index) {
        while (index > 0) {
            const parentIndex = Math.floor((index - 1) / 2);
            if (this.heap[index] >= this.heap[parentIndex]) {
                break;
            }
            [this.heap[index], this.heap[parentIndex]] = [this.heap[parentIndex], this.heap[index]];
            index = parentIndex;
        }
    }
    bubbleDown(index) {
        while (true) {
            let minIndex = index;
            const leftChildIndex = 2 * index + 1;
            const rightChildIndex = 2 * index + 2;
            if (leftChildIndex < this.heap.length && this.heap[leftChildIndex] < this.heap[minIndex]) {
                minIndex = leftChildIndex;
            }
            if (rightChildIndex < this.heap.length && this.heap[rightChildIndex] < this.heap[minIndex]) {
                minIndex = rightChildIndex;
            }
            if (minIndex === index) {
                break;
            }
            [this.heap[index], this.heap[minIndex]] = [this.heap[minIndex], this.heap[index]];
            index = minIndex;
        }
    }
}

