public int findTheDistanceValue(int[] arr1, int[] arr2, int d) {
    int distance = 0;
    for (int a : arr1) {
        boolean found = true;
        for (int b : arr2) {
            if (Math.abs(a - b) <= d) {
                found = false;
                break;
            }
        }
        if (found) distance++;
    }
    return distance;
}

