import java.util.*;

public List<List<String>> suggestedProducts(String[] products, String searchWord) {
    Arrays.sort(products);

    List<List<String>> result = new ArrayList<>();
    String currentPrefix = "";

    for (char letter : searchWord.toCharArray()) {
        currentPrefix += letter;

        int index = Arrays.binarySearch(products, currentPrefix);
        if (index < 0) {
            index = -index - 1;
        }

        List<String> suggestions = new ArrayList<>();
        for (int i = 0; i < 3 && index < products.length && products[index].startsWith(currentPrefix); i++) {
            suggestions.add(products[index]);
            index++;
        }

        result.add(suggestions);
    }

    return result;
}

cpp_code:
#include <vector>
#include <string>
#include <algorithm>

std::vector<std::vector<std::string>> suggestedProducts(std::vector<std::string>& products, std::string searchWord) {
    std::sort(products.begin(), products.end());

    std::vector<std::vector<std::string>> result;
    std::string currentPrefix;

    for (char letter : searchWord) {
        currentPrefix += letter;

        auto it = std::lower_bound(products.begin(), products.end(), currentPrefix);
        std::vector<std::string> suggestions;

        for (int i = 0; i < 3 && it != products.end() && it->substr(0, currentPrefix.size()) == currentPrefix; ++i) {
            suggestions.push_back(*it);
            ++it;
        }

        result.push_back(suggestions);
    }

    return result;
}

