    let res = 0;
    for (let i = 0; i < k; ++i) {
        let counts = new Array(26).fill(0);
        for (let j = i; j < n; j += k) {
            ++counts[s.charCodeAt(j) - 'a'.charCodeAt(0)];
        }
        let maxCount = Math.max(...counts);
        res += chunkCount - maxCount;
    }
    return res;
}

