java_code:
import java.util.*;

class Solution {
    public String longestDiverseString(int a, int b, int c) {
        StringBuilder result = new StringBuilder();
        PriorityQueue<int[]> pq = new PriorityQueue<>((a1, a2) -> a2[0] - a1[0]);
        if (a != 0) pq.offer(new int[]{a, 'a'});
        if (b != 0) pq.offer(new int[]{b, 'b'});
        if (c != 0) pq.offer(new int[]{c, 'c'});

        while (!pq.isEmpty()) {
            int[] first = pq.poll();
            if (result.length() != 0 && result.charAt(result.length()-1) == first[1]) {
                if (pq.isEmpty()) break;
                int[] second = pq.poll();
                result.append((char)second[1]);
                second[0]--;
                if (second[0] != 0) pq.offer(second);
                pq.offer(first);
            } else {
                result.append((char)first[1]);
                first[0]--;
                if (first[0] != 0) pq.offer(first);
            }
        }
        return result.toString();
    }
}

cpp_code:
#include <algorithm>
#include <queue>
using namespace std;

string longestDiverseString(int a, int b, int c) {
    string result = "";
    using T = pair<int, char>;
    priority_queue<T> pq;
    if (a) pq.push({a, 'a'});
    if (b) pq.push({b, 'b'});
    if (c) pq.push({c, 'c'});

    while (!pq.empty()) {
        T first = pq.top(); pq.pop();
        if (!result.empty() && result.back() == first.second) {
            if (pq.empty()) break;
            T second = pq.top(); pq.pop();
            result += second.second;
            second.first--;
            if (second.first) pq.push(second);
            pq.push(first);
        } else {
            result += first.second;
            first.first--;
            if (first.first) pq.push(first);
        }
    }
    return result;
}

python_code:
import heapq

def longest_diverse_string(a: int, b: int, c: int) -> str:
    result = ""
    pq = [(-a, 'a'), (-b, 'b'), (-c, 'c')]
    heapq.heapify(pq)

    while pq:
        first = heapq.heappop(pq)
        if not result or result[-1] != first[1]:
            result += first[1]
            first = (first[0] + 1, first[1])
            if first[0] < 0:
                heapq.heappush(pq, first)
        elif pq:
            second = heapq.heappop(pq)
            result += second[1]
            second = (second[0] + 1, second[1])
            if second[0] < 0:
                heapq.heappush(pq, second)
            if first[0] < 0:
                heapq.heappush(pq, first)
        else:
            break

    return result

javascript_code:
var longestDiverseString = function(a, b, c) {
    let result = "";
    let pq = new PriorityQueue(([cnt1, _], [cnt2, __]) => cnt1 > cnt2);
    if (a !== 0) pq.enqueue([a, 'a']);
    if (b !== 0) pq.enqueue([b, 'b']);
    if (c !== 0) pq.enqueue([c, 'c']);

    while (!pq.isEmpty()) {
        let [firstCnt, firstChar] = pq.dequeue();
        if (result.length === 0 || result[result.length - 1] !== firstChar) {
            result += firstChar;
            firstCnt--;
            if (firstCnt !== 0) pq.enqueue([firstCnt, firstChar]);
        } else if (!pq.isEmpty()) {
            let [secondCnt, secondChar] = pq.dequeue();
            result += secondChar;
            secondCnt--;
            if (secondCnt !== 0) pq.enqueue([secondCnt, secondChar]);
            pq.enqueue([firstCnt, firstChar]);
        } else {
            break;
        }
    }
    return result;
};

java_code:
public String stoneGameIII(int[] stoneValue) {
    int n = stoneValue.length;
    int[] dp = new int[n + 1];
    dp[n] = 0;

    for (int i = n - 1; i >= 0; --i) {
        dp[i] = Integer.MIN_VALUE;
        int curr = 0;
        for (int j = 0; j < 3 && i + j < n; ++j) {
            curr += stoneValue[i + j];
            dp[i] = Math.max(dp[i], curr - dp[i + j + 1]);
        }
    }

    return dp[0] == 0 ? "Tie " : dp[0] > 0 ? "Alice " : "Bob ";
}

