import java.lang.Math;

public int smallestDivisor(int[] nums, int threshold) {
    int left = 1, right = 1000000;
    while (left < right) {
        int mid = (left + right) / 2;
        int sum = 0;
        for (int n : nums) {
            sum += Math.ceil(1.0 * n / mid);
        }
        if (sum > threshold) {
            left = mid + 1;
        } else {
            right = mid;
        }
    }
    return left;
}

