function minNumberOfFlips(mat) {
    const m = mat.length, n = mat[0].length;
    let steps = 0;
    const dirs = [[0, 1], [0, -1], [1, 0], [-1, 0], [0, 0]];

    function encode(i, j) {
        return i * n + j;
    }

    while (true) {
        let flipped = 0;
        const que = [];

        for (let i = 0; i < m; ++i) {
            for (let j = 0; j < n; ++j) {
                if (mat[i][j] === 1) {
                    que.push(encode(i, j));
                }
            }
        }

        while (que.length > 0) {
            const cur = que.shift();
            const cur_i = Math.floor(cur / n), cur_j = cur % n;

            for (const dir of dirs) {
                const ni = cur_i + dir[0], nj = cur_j + dir[1];
                if (ni >= 0 && ni < m && nj >= 0 && nj < n) {
                    mat[ni][nj] ^= 1;
                    ++flipped;
                }
            }
        }

        if (flipped === 0) {
            break;
        }
        steps += flipped;
    }

    for (const row of mat) {
        for (const cell of row) {
            if (cell === 1) {
                return -1;
            }
        }
    }

    return steps;
}

