function entityParser(text) {
    const entities = {
        "&quot;": "\"",
        "&apos;": "\'",
        "&amp;": "&",
        "&gt;": ">",
        "&lt;": "<",
        "&frasl;": "/",
    };

    let result = '';
    let currentEntity = '';
    let inEntity = false;

    for (const c of text) {
        if (inEntity) {
            currentEntity += c;
            if (c === ';') {
                if (entities.hasOwnProperty(currentEntity)) {
                    result += entities[currentEntity];
                } else {
                    result += currentEntity;
                }
                inEntity = false;
                currentEntity = '';
            }
        } else {
            if (c === '&') {
                inEntity = true;
                currentEntity += c;
            } else {
                result += c;
            }
        }
    }

    return result;
}

