public int maxSideLength(int[][] mat, int threshold) {
    int m = mat.length;
    int n = mat[0].length;
    int[][] dp = new int[m + 1][n + 1];
    int ans = 0;

    for (int i = 1; i <= m; i++) {
        for (int j = 1; j <= n; j++) {
            dp[i][j] = mat[i - 1][j - 1] + dp[i][j - 1] + dp[i - 1][j] - dp[i - 1][j - 1];
            int k = ans + 1;
            if (i >= k && j >= k && dp[i][j] - dp[i][j - k] - dp[i - k][j] + dp[i - k][j - k] <= threshold) {
                ans++;
            }
        }
    }
    return ans;
}

