#include <string>
#include <vector>

using namespace std;

class Solution {
public:
    void generate_strings(int n, string& current, vector<string>& strings) {
        if (n == 0) {
            strings.push_back(current);
            return;
        }
        for (char c = 'a'; c <= 'c'; ++c) {
            if (current.empty() || current.back() != c) {
                current.push_back(c);
                generate_strings(n - 1, current, strings);
                current.pop_back();
            }
        }
    }

    string getHappyString(int n, int k) {
        vector<string> strings;
        string current = "";
        generate_strings(n, current, strings);
        return k <= strings.size() ? strings[k - 1] : "";
    }
};

