            strings.push(current);
            return;
        }
        for (let c of 'abc') {
            if (!current || current[current.length - 1] !== c) {
                this.generateStrings(n - 1, current + c, strings);
            }
        }
    }

    getHappyString(n, k) {
        let strings = [];
        this.generateStrings(n, '', strings);
        return k <= strings.length ? strings[k - 1] : '';
    }
}

