function numDecodings(s, k) {
    const n = s.length;
    const dp = new Array(n + 1).fill(0);
    dp[n] = 1;
    const MOD = 1000000007;

    for (let i = n - 1; i >= 0; i--) {
        let num = 0;
        for (let j = i; j < n && num <= k; j++) {
            num = num * 10 + parseInt(s[j]);
            if (num >= 1 && num <= k) {
                dp[i] = (dp[i] + dp[j + 1]) % MOD;
            }
        }
    }

    return dp[0];
}

