import java.util.*;

public List<List<String>> displayTable(List<List<String>> orders) {
    TreeMap<Integer, TreeMap<String, Integer>> tables = new TreeMap<>();
    TreeSet<String> foodSet = new TreeSet<>();

    for (List<String> order : orders) {
        int tableNumber = Integer.parseInt(order.get(1));
        String foodItem = order.get(2);
        tables.putIfAbsent(tableNumber, new TreeMap<>());
        tables.get(tableNumber).put(foodItem, tables.get(tableNumber).getOrDefault(foodItem, 0) + 1);
        foodSet.add(foodItem);
    }

    List<List<String>> result = new ArrayList<>();
    List<String> header = new ArrayList<>();
    header.add("Table");
    header.addAll(foodSet);
    result.add(header);

    for (Map.Entry<Integer, TreeMap<String, Integer>> table : tables.entrySet()) {
        List<String> row = new ArrayList<>();
        row.add(Integer.toString(table.getKey()));
        for (String foodItem : foodSet) {
            row.add(Integer.toString(table.getValue().getOrDefault(foodItem, 0)));
        }
        result.add(row);
    }

    return result;
}

cpp_code:
#include <vector>
#include <string>
#include <map>
#include <set>
#include <algorithm>

std::vector<std::vector<std::string>> displayTable(std::vector<std::vector<std::string>>& orders) {
    std::map<int, std::map<std::string, int>> tables;
    std::set<std::string> foodSet;

    for (auto& order : orders) {
        int tableNumber = std::stoi(order[1]);
        std::string foodItem = order[2];
        tables[tableNumber][foodItem]++;
        foodSet.insert(foodItem);
    }

    std::vector<std::vector<std::string>> result;
    std::vector<std::string> header = {"Table"};
    header.insert(header.end(), foodSet.begin(), foodSet.end());
    result.push_back(header);

    for (auto& table : tables) {
        std::vector<std::string> row = {std::to_string(table.first)};
        for (const auto& foodItem : foodSet) {
            row.push_back(std::to_string(table.second[foodItem]));
        }
        result.push_back(row);
    }

    return result;
}

javascript_code:
function displayTable(orders) {
    const tables = new Map();
    const foodSet = new Set();

    for (const order of orders) {
        const tableNumber = parseInt(order[1]);
        const foodItem = order[2];
        if (!tables.has(tableNumber)) tables.set(tableNumber, new Map());
        const table = tables.get(tableNumber);
        table.set(foodItem, (table.get(foodItem) || 0) + 1);
        foodSet.add(foodItem);
    }

    const foodList = [...foodSet].sort();
    const result = [["Table", ...foodList]];

    for (const [tableNumber, table] of [...tables.entries()].sort((a, b) => a[0] - b[0])) {
        const row = [tableNumber.toString()];
        row.push(...foodList.map(foodItem => (table.get(foodItem) || 0).toString()));
        result.push(row);
    }

    return result;
}

