    for (int i = 0; i < n; ++i) {
        if (i >= k) pq.pop(); // Maintain the maximum size of k
        pq.push(dp[i] - nums[i]);
        dp[i + 1] = max(dp[i], nums[i] + pq.top());
        sum = max(sum, dp[i + 1]);
    }

    return sum;
}

