public int maxDiff(int num) {
    int a = -1, b = -1;
    String s = Integer.toString(num);
    for (char c : s.toCharArray()) {
        if (a == -1 && c != '9') {
            a = c - '0';
        }
        if (b == -1 && c > '1') {
            b = c - '0';
        }
        if (a != -1 && b != -1) {
            break;
        }
    }
    int result = 0;
    for (char c : s.toCharArray()) {
        if (c - '0' == a) {
            result = result * 10 + 9;
        } else if (c - '0' == b) {
            result = result * 10 + ((c == s.charAt(0)) ? 1 : 0);
        } else {
            result = result * 10 + c - '0';
        }
    }
    return result - num;
}

