#include <vector>

class Encrypter {
public:
    Encrypter(std::vector<char> keys, std::vector<std::string> values, std::vector<std::string> dictionary) {
        for (int i = 0; i < keys.size(); i++) {
            encrypt_map[keys[i]] = values[i];
            decrypt_map[values[i]] = keys[i];
        }
        for (const auto &word : dictionary) {
            this->dictionary.insert(word);
        }
    }

    std::string encrypt(const std::string &original) {
        std::string res = "";
        for (char c : original) {
            if (encrypt_map.find(c) == encrypt_map.end()) {
                return "";
            }
            res += encrypt_map[c];
        }
        return res;
    }

    std::string decrypt(const std::string &encrypted) {
        std::string res = "";
        for (int i = 0; i < encrypted.size(); i += 2) {
            std::string temp = encrypted.substr(i, 2);
            if (decrypt_map.find(temp) == decrypt_map.end()) {
                return "";
            }
            res += decrypt_map[temp];
        }
        if (dictionary.find(res) == dictionary.end()) {
            return "";
        }
        return res;
    }

private:
    std::unordered_map<char, std::string> encrypt_map;
    std::unordered_map<std::string, char> decrypt_map;
    std::unordered_set<std::string> dictionary;
};

