#include<cstring>

int dp(int first, int second, int pos, const std::string& word) {
    if (pos == word.size()) return 0;

    int ans = 1e9;
    for (int i : { first, second }) {
        if (i != -1) {
            int dx = abs(word[pos] - word[i]) % 6, dy = abs(word[pos] - word[i]) / 6;
            ans = std::min(ans, min(dx, dy) * 2 + max(dx, dy));
        }
    }
    ans += dp(first, second, pos + 1, word);

    if (first == -1 || second == -1) {
        ans = std::min(ans, dp(first == -1 ? pos : first, word[pos], pos + 1, word));
    }

    return ans;
}

int minimum_distance(const std::string& word) {
    return dp(-1, -1, 0, word);
}

python_code:
def minimum_distance(word: str) -> int:
    def dp(first: int, second: int, pos: int) -> int:
        if pos == len(word): return 0

        ans = float('inf')
        for i in [first, second]:
            if i != -1:
                dx = abs(ord(word[pos]) - ord(word[i])) % 6
                dy = abs(ord(word[pos]) - ord(word[i])) // 6
                ans = min(ans, min(dx, dy) * 2 + max(dx, dy))
        ans += dp(first, second, pos + 1)

        if first == -1 or second == -1:
            ans = min(ans, dp(pos if first == -1 else first, ord(word[pos]), pos + 1))

        return ans

    return dp(-1, -1, 0)

