    n = len(jobDifficulty)
    if n < d: return -1
    dp = [[float("inf")] * n for _ in range(d)]

    dp[0][0] = jobDifficulty[0]
    for i in range(1, n):
        dp[0][i] = max(dp[0][i-1], jobDifficulty[i])

