int minSetSize(std::vector<int>& arr) {
    std::unordered_map<int, int> count;
    for (auto value : arr)
        count[value]++;

    std::vector<int> freq;
    for (auto& entry : count)
        freq.push_back(entry.second);

    std::sort(freq.rbegin(), freq.rend());

    int removed = 0, setSize = 0;
    for (auto f : freq) {
        removed += f;
        setSize++;
        if (removed * 2 >= arr.size())
            return setSize;
    }

    return 0;
}

