class Solution {
public:
    int maxProduct(TreeNode* root) {
        long total = dfs(root), result = 0;
        dfs2(root, total/2, result, total);
        return result % 1000000007;
    }

    int dfs(TreeNode* root) {
        if (!root) return 0;
        return root->val + dfs(root->left) + dfs(root->right);
    }

    int dfs2(TreeNode* root, double half, long& result, long total) {
        if (!root) return 0;
        int curSum = root->val + dfs2(root->left, half, result, total) + dfs2(root->right, half, result, total);
        result = max(result, (total - curSum) * curSum);
        return curSum;
    }
};

