class TreeNode:
    def __init__(self, x):
        self.val = x
        self.left = None
        self.right = None

class Solution:
    def maxProduct(self, root: TreeNode) -> int:
        def dfs(node):
            if not node:
                return 0
            return node.val + dfs(node.left) + dfs(node.right)

        def dfs2(node, half):
            nonlocal result

            if not node:
                return 0
            cur_sum = node.val + dfs2(node.left, half) + dfs2(node.right, half)
            result = max(result, (total - cur_sum) * cur_sum)
            return cur_sum

        total = dfs(root)
        result = 0
        dfs2(root, total / 2)
        return result % (10**9 + 7)

