        this.left = (left === undefined ? null : left)
        this.right = (right === undefined ? null : right)
    }
}

var maxProduct = function(root) {
    const mod = BigInt(10 ** 9 + 7);
    let total, result = 0n;

    function dfs(node) {
        if (!node) return 0;
        return node.val + dfs(node.left) + dfs(node.right);
    }

    function dfs2(node) {
        if (!node) return 0;
        let curSum = node.val + dfs2(node.left) + dfs2(node.right);
        result = BigInt(Math.max(Number(result), Number((total - curSum) * curSum)));
        return curSum;
    }

    total = BigInt(dfs(root));
    dfs2(root);
    return Number(result % mod);
};

