from collections import OrderedDict

def sortString(s: str) -> str:
    freq_map = OrderedDict(sorted({c: s.count(c) for c in set(s)}.items()))
    result = []

    while freq_map:
        for key in list(freq_map.keys()):
            result.append(key)
            freq_map[key] -= 1

            if freq_map[key] == 0:
                del freq_map[key]

        for key in list(reversed(freq_map.keys())):
            result.append(key)
            freq_map[key] -= 1

            if freq_map[key] == 0:
                del freq_map[key]

    return "".join(result)

javascript_code:
function sortString(s) {
    const freqMap = new Map([...s]
        .sort()
        .reduce((acc, c) => {
            acc.set(c, (acc.get(c) || 0) + 1);
            return acc;
        }, new Map()));
    let result = '';

    while (freqMap.size) {
        for (const [key, val] of freqMap) {
            result += key;
            if (val - 1 === 0) {
                freqMap.delete(key);
            } else {
                freqMap.set(key, val - 1);
            }
        }

        for (const [key, val] of [...freqMap].reverse()) {
            result += key;
            if (val - 1 === 0) {
                freqMap.delete(key);
            } else {
                freqMap.set(key, val - 1);
            }
        }
    }

    return result;
}

