#include <string>
#include <unordered_map>
using namespace std;

int findTheLongestSubstring(string s) {
    unordered_map<int, int> mp;
    mp[0] = -1;
    int res = 0, n = s.length(), i, j = 0;
    for (i = 0; i < n; ++i) {
        if (s[i] == 'a') j ^= 1;
        else if (s[i] == 'e') j ^= 2;
        else if (s[i] == 'i') j ^= 4;
        else if (s[i] == 'o') j ^= 8;
        else if (s[i] == 'u') j ^= 16;
        if(!mp.count(j)) mp[j] = i;
        res = max(res, i - mp[j]);
    }
    return res;
}

