function findLeastNumOfUniqueInts(arr, k) {
    let count = {};
    for (let n of arr) {
        count[n] = (count[n] || 0) + 1;
    }
    let pq = Object.values(count).sort((a, b) => a - b);
    while (k > 0) {
        k -= pq.shift();
    }
    return k === 0 ? pq.length : pq.length + 1;
}

