int getPower(int x) {
    int steps = 0;
    while (x != 1) {
        if (x % 2 == 0) x /= 2;
        else x = 3 * x + 1;
        steps++;
    }
    return steps;
}

int sortByPower(int lo, int hi, int k) {
    List<int[]> nums = new ArrayList<>();
    for (int i = lo; i <= hi; i++) {
        nums.add(new int[]{getPower(i), i});
    }
    nums.sort(Comparator.comparingInt((int[] a) -> a[0]).thenComparingInt(a -> a[1]));
    return nums.get(k - 1)[1];
}

