import heapq

def max_performance(n, k, speed, efficiency):
    engineers = sorted(zip(efficiency, speed), reverse=True)

    result = 0
    sum_speed = 0
    min_heap = []
    for e, s in engineers:
        if len(min_heap) >= k:
            sum_speed -= heapq.heappop(min_heap)

        heapq.heappush(min_heap, s)
        sum_speed += s
        result = max(result, e * sum_speed)

    return result % (10**9 + 7)

javascript_code:
function maxPerformance(n, k, speed, efficiency) {
  const engineers = efficiency.map((e, i) => [e, speed[i]]);
  engineers.sort((a, b) => b[0] - a[0]);

  let sum = 0, result = 0;
  const minHeap = new MinHeap();
  for (const [e, s] of engineers) {
    if (minHeap.size() >= k) {
      sum -= minHeap.poll();
    }
    minHeap.offer(s);
    sum += s;
    result = Math.max(result, e * sum);
  }

  return result % 1000000007;
}

class MinHeap {
  constructor() {
    this.data = [];
  }

  offer(value) {
    this.data.push(value);
    this._bubbleUp(this.data.length - 1);
  }

  poll() {
    if (this.data.length === 0) {
      return null;
    }
    if (this.data.length === 1) {
      return this.data.pop();
    }
    const result = this.data[0];
    this.data[0] = this.data.pop();
    this._sinkDown(0);

    return result;
  }

  size() {
    return this.data.length;
  }

  _bubbleUp(index) {
    while (index > 0) {
      const parentIndex = Math.floor((index - 1) / 2);
      const value = this.data[index];
      const parentValue = this.data[parentIndex];
      if (value >= parentValue) {
        break;
      }
      this.data[parentIndex] = value;
      this.data[index] = parentValue;
      index = parentIndex;
    }
  }

  _sinkDown(index) {
    const last = this.data.length - 1;
    while (true) {
      const leftChildIndex = index * 2 + 1;
      const rightChildIndex = leftChildIndex + 1;
      let swapIndex = index;

      if (leftChildIndex <= last && this.data[leftChildIndex] < this.data[swapIndex]) {
        swapIndex = leftChildIndex;
      }
      if (rightChildIndex <= last && this.data[rightChildIndex] < this.data[swapIndex]) {
        swapIndex = rightChildIndex;
      }
      if (swapIndex === index) {
        break;
      }
      [this.data[index], this.data[swapIndex]] = [this.data[swapIndex], this.data[index]];
      index = swapIndex;
    }
  }
}

