import java.util.Arrays;

public int maxSatisfaction(int[] satisfaction) {
    Arrays.sort(satisfaction);
    int ans = 0, total = 0, sum = 0;
    for (int i = satisfaction.length - 1; i >= 0; i--) {
        total += satisfaction[i];
        if (total > 0) {
            sum += total;
            ans = Math.max(ans, sum);
        }
    }
    return ans;
}

