class UndergroundSystem {
    constructor() {
        this.checkInData = new Map();
        this.travelData = new Map();
    }

    checkIn(id, stationName, t) {
        this.checkInData.set(id, [stationName, t]);
    }

    checkOut(id, stationName, t) {
        const [startStation, startTime] = this.checkInData.get(id);
        const route = `${startStation}_${stationName}`;
        const travelInfo = this.travelData.get(route) || [0, 0];
        this.travelData.set(route, [travelInfo[0] + t - startTime, travelInfo[1] + 1]);
    }

    getAverageTime(startStation, endStation) {
        const route = `${startStation}_${endStation}`;
        const [totalTime, numTrips] = this.travelData.get(route);
        return totalTime / numTrips;
    }
}

java_code:
class Solution {
    private static final int MOD = 1000000007;

    public int countGoodStrings(String s1, String s2, String evil) {
        int n = s1.length();
        int m = evil.length();
        int[][] dp = new int[n + 1][m];

        // Preprocess the KMP prefix function for the evil string
        int[] lps = new int[m];
        int len = 0;
        for (int i = 1; i < m;) {
            if (evil.charAt(i) == evil.charAt(len)) {
                lps[i++] = ++len;
            } else if (len > 0) {
                len = lps[len - 1];
            } else {
                ++i;
            }
        }

        dp[0][0] = 1;
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < m; ++j) {
                for (int k = 0; k < 2; ++k) {
                    for (char c = 'a'; c <= (k == 1 ? s2.charAt(i) : 'z'); ++c) {
                        int e = j;
                        while (e > 0 && (c != evil.charAt(e))) {
                            e = lps[e - 1];
                        }

                        if (c != evil.charAt(e)) {
                            e++;
                        }

                        if (e != m) {
                            dp[i + 1][k | ((c < s2.charAt(i)) ? 1 : 0)] += dp[i][k];
                            dp[i + 1][k | ((c < s2.charAt(i)) ? 1 : 0)] %= MOD;
                        }
                    }
                }
            }
        }

        return (dp[n][1] - dp[n][0] + MOD) % MOD;
    }
}

