const int MOD = 1e9 + 7;

int countGoodStrings(string s1, string s2, string evil) {
    int n = s1.size();
    int m = evil.size();
    vector<vector<int>> dp(n + 1, vector<int>(m, 0));

    // Preprocess the KMP prefix function for the evil string
    vector<int> lps(m);
    int len = 0;
    for (int i = 1; i < m;) {
        if (evil[i] == evil[len]) {
            lps[i++] = ++len;
        } else if (len) {
            len = lps[len - 1];
        } else {
            ++i;
        }
    }

    vector<vector<int>> count(s1.size() + 1, vector<int>(2, 0));
    dp[0][0] = 1;

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            for (int k = 0; k < 2; ++k) {
                for (char c = 'a'; c <= (k ? s2[i] : 'z'); ++c) {
                    int e = j;
                    while (e && (c != evil[e])) {
                        e = lps[e - 1];
                    }

                    if ((c != evil[e])) {
                        e++;
                    }

                    if (e != m) {
                        dp[i + 1][k | (c < s2[i])] += dp[i][k];
                        dp[i + 1][k | (c < s2[i])] %= MOD;
                    }
                }
            }
        }
    }

    return (dp[n][1] - dp[n][0] + MOD) % MOD;
}

