            for k in range(2):
                for c in range(ord('a'), ord(s2[i] if k else 'z') + 1):
                    e = j
                    while e and (chr(c) != evil[e]):
                        e = lps[e - 1]

                    if chr(c) != evil[e]:
                        e += 1

                    if e != m:
                        dp[i + 1][k | (c < ord(s2[i]))] += dp[i][k]
                        dp[i + 1][k | (c < ord(s2[i]))] %= MOD

    return (dp[n][1] - dp[n][0] + MOD) % MOD

