        if (s.length() == n) {
            happyStrings.push_back(s);
            return;
        }
        for (char c = 'a'; c <= 'c'; c++) {
            if (c != prev) {
                dfs(s + c, c);
            }
        }
    };
    dfs("", ' ');
    return k <= happyStrings.size() ? happyStrings[k - 1] : "";
}

