std::vector<int> minSubsequence(std::vector<int>& nums) {
    std::sort(nums.begin(), nums.end(), std::greater<int>());
    int totalSum = 0, currentSum = 0;
    for (int num : nums) {
        totalSum += num;
    }
    std::vector<int> result;
    for (int num : nums) {
        currentSum += num;
        result.push_back(num);
        if (currentSum > totalSum - currentSum) {
            break;
        }
    }
    return result;
}

