int num_steps(const std::string& s) {
    int steps = 0, carry = 0;
    for (int i = s.size() - 1; i > 0; --i) {
        if (s[i] - '0' + carry == 1) {
            steps += 2;
            carry = 1;
        } else {
            steps += carry;
            carry = s[i] - '0';
        }
    }

    return steps + carry;
}

