public int closestToTarget(int[] arr, int target) {
    int minDiff = Integer.MAX_VALUE;
    Set<Integer> prefix = new HashSet<>();

    for (int n : arr) {
        Set<Integer> nextPrefix = new HashSet<>();
        for (int p : prefix) {
            nextPrefix.add(p & n);
        }
        nextPrefix.add(n);

        for (int p : nextPrefix) {
            minDiff = Math.min(minDiff, Math.abs(p - target));
        }
        prefix = nextPrefix;
    }
    return minDiff;
}

cpp_code:
int closestToTarget(vector<int>& arr, int target) {
    int min_diff = INT_MAX;
    unordered_set<int> prefix;

    for (int n : arr) {
        unordered_set<int> next_prefix;
        for (int p : prefix) {
            next_prefix.insert(p & n);
        }
        next_prefix.insert(n);

        for (int p : next_prefix) {
            min_diff = min(min_diff, abs(p - target));
        }
        swap(prefix, next_prefix);
    }
    return min_diff;
}

