java_code:
public String stoneGameIII(int[] stoneValue) {
    int n = stoneValue.length;
    int[] dp = new int[n + 1];
    dp[n - 1] = stoneValue[n - 1];
    for (int i = n - 2; i >= 0; --i) {
        dp[i] = stoneValue[i] - dp[i + 1];
        for (int j = 1; j < 3; ++j) {
            if (i + j < n)
                dp[i] = Math.max(dp[i], stoneValue[i + j] - dp[i + j + 1]);
        }
    }
    if (dp[0] > 0) return "Alice";
    if (dp[0] < 0) return "Bob";
    return "Tie";
}

