import java.util.ArrayList;
import java.util.List;

public List<Integer> processQueries(int[] queries, int m) {
    List<Integer> nums = new ArrayList<>();
    List<Integer> result = new ArrayList<>();
    for (int i = 0; i < m; i++) {
        nums.add(i + 1);
    }
    for (int q : queries) {
        int pos = nums.indexOf(q);
        result.add(pos);
        nums.remove(pos);
        nums.add(0, q);
    }
    return result;
}

cpp_code:
#include <vector>
#include <algorithm>

std::vector<int> processQueries(std::vector<int> &queries, int m) {
    std::vector<int> nums(m), result;
    for (int i = 0; i < m; ++i) {
        nums[i] = i + 1;
    }
    for (int q : queries) {
        int pos = std::find(nums.begin(), nums.end(), q) - nums.begin();
        result.push_back(pos);
        nums.erase(nums.begin() + pos);
        nums.insert(nums.begin(), q);
    }
    return result;
}

javascript_code:
function processQueries(queries, m) {
    const nums = Array.from({ length: m }, (_, i) => i + 1);
    const result = [];
    for (const q of queries) {
        const pos = nums.indexOf(q);
        result.push(pos);
        nums.splice(pos, 1);
        nums.unshift(q);
    }
    return result;
}

