#include <string>
#include <unordered_map>
using namespace std;

string entityParser(string text) {
    unordered_map<string, char> entities{
        {"&quot;", '\"'},
        {"&apos;", '\''},
        {"&amp;", '&'},
        {"&gt;", '>'},
        {"&lt;", '<'},
        {"&frasl;", '/'}
    };
    string result;
    for (int i = 0; i < text.size(); ++i) {
        if (text[i] == '&') {
            string temp;
            for (int j = i; j < text.size() && j < i + 7; ++j) {
                temp.push_back(text[j]);
                if (entities.find(temp) != entities.end()) {
                    result.push_back(entities[temp]);
                    i = j;
                    break;
                }
            }
            if (temp.back() != ';') result.push_back(text[i]);
        } else {
            result.push_back(text[i]);
        }
    }
    return result;
}

python_code:
def entityParser(text: str) -> str:
    entities = {
        "&quot;": '\"',
        "&apos;": '\'',
        "&amp;": '&',
        "&gt;": '>',
        "&lt;": '<',
        "&frasl;": '/'
    }

    result, i = [], 0
    while i < len(text):
        if text[i] == '&':
            temp = ''
            for j in range(i, min(i+7, len(text))):
                temp += text[j]
                if temp in entities:
                    result.append(entities[temp])
                    i = j
                    break
            else:
                result.append(text[i])
        else:
            result.append(text[i])
        i += 1
    return ''.join(result)

javascript_code:
function entityParser(text) {
    const entities = {
        "&quot;": '\"',
        "&apos;": '\'',
        "&amp;": '&',
        "&gt;": '>',
        "&lt;": '<',
        "&frasl;": '/'
    };

    let result = '';
    for (let i = 0; i < text.length; ++i) {
        if (text[i] === '&') {
            let temp = '';
            for (let j = i; j < text.length && j < i + 7; ++j) {
                temp += text[j];
                if (temp in entities) {
                    result += entities[temp];
                    i = j;
                    break;
                }
            }
            if (temp[temp.length - 1] !== ';') result += text[i];
        } else {
            result += text[i];
        }
    }
    return result;
}

