java_code:
import java.util.*;

public List<List<String>> displayTable(List<List<String>> orders) {
    TreeSet<String> foodItems = new TreeSet<>();
    TreeMap<Integer, Map<String, Integer>> tableOrders = new TreeMap<>();

    for (List<String> order : orders) {
        foodItems.add(order.get(2));
        int tableNumber = Integer.parseInt(order.get(1));
        tableOrders.putIfAbsent(tableNumber, new HashMap<>());
        tableOrders.get(tableNumber).put(order.get(2), tableOrders.get(tableNumber).getOrDefault(order.get(2), 0) + 1);
    }

    List<List<String>> result = new ArrayList<>();
    List<String> header = new ArrayList<>();
    header.add("Table");
    header.addAll(foodItems);
    result.add(header);

    for (Map.Entry<Integer, Map<String, Integer>> entry : tableOrders.entrySet()) {
        List<String> row = new ArrayList<>();
        row.add(String.valueOf(entry.getKey()));
        for (String food : foodItems) {
            row.add(String.valueOf(entry.getValue().getOrDefault(food, 0)));
        }
        result.add(row);
    }

    return result;
}

cpp_code:
#include <vector>
#include <string>
#include <map>
#include <set>
#include <algorithm>

using namespace std;

vector<vector<string>> displayTable(vector<vector<string>>& orders) {
    set<string> foodItems;
    map<int, map<string, int>> tableOrders;

    for (const auto& order : orders) {
        foodItems.insert(order[2]);
        tableOrders[stoi(order[1])][order[2]]++;
    }

    vector<vector<string>> result;
    vector<string> header;
    header.push_back("Table");
    header.insert(header.end(), foodItems.begin(), foodItems.end());
    result.push_back(header);

    for (const auto& entry : tableOrders) {
        vector<string> row;
        row.push_back(to_string(entry.first));
        for (const auto& food : foodItems) {
            row.push_back(to_string(entry.second[food]));
        }
        result.push_back(row);
    }

    return result;
}

javascript_code:
function displayTable(orders) {
    const foodItems = new Set();
    const tableOrders = new Map();

    for (const order of orders) {
        foodItems.add(order[2]);
        const tableNumber = parseInt(order[1]);
        if (!tableOrders.has(tableNumber)) {
            tableOrders.set(tableNumber, new Map());
        }
        const table = tableOrders.get(tableNumber);
        table.set(order[2], (table.get(order[2]) || 0) + 1);
    }

    const sortedFoodItems = Array.from(foodItems).sort();
    const header = ['Table', ...sortedFoodItems];
    const result = [header];

    for (const [tableNumber, foodOrder] of [...tableOrders.entries()].sort((a, b) => a[0] - b[0])) {
        const row = [tableNumber.toString(), ...sortedFoodItems.map(food => (foodOrder.get(food) || 0).toString())];
        result.push(row);
    }

    return result;
}

java_code:
int minNumberOfFrogs(String croakOfFrogs) {
    int[] counts = new int[5];
    int max_frogs = 0;

    for (char c : croakOfFrogs.toCharArray()) {
        int index = "croak".indexOf(c);
        if (index == 0) {
            counts[0]++;
            max_frogs = Math.max(max_frogs, counts[0]);
        } else if (counts[index - 1] > 0) {
            counts[index - 1]--;
            counts[index]++;
        } else {
            return -1;
        }
    }

    if (counts[0] == counts[4]) {
        return max_frogs;
    } else {
        return -1;
    }
}

