int numberOfWays(int n, int m, int k, int mod = 1_000_000_007) {
    if (k > 1) {
        long result = 1;
        for (int i = 0; i < n; ++i) {
            result = (result * m) % mod;
        }
        return (int)result;
    }
    return n % 2 == 0 ? 1 : m;
}

