import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;

public List<Integer> findDiagonalOrder(List<List<Integer>> nums) {
    List<Integer> res = new ArrayList<>();
    int m = nums.size();
    HashMap<Integer, List<Integer>> diagonals = new HashMap<>();

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < nums.get(i).size(); j++) {
            int key = i + j;
            if (!diagonals.containsKey(key)) {
                diagonals.put(key, new ArrayList<>());
            }
            diagonals.get(key).add(nums.get(i).get(j));
        }
    }

    for (int key : diagonals.keySet()) {
        List<Integer> diag = diagonals.get(key);
        Collections.reverse(diag);
        res.addAll(diag);
    }

    return res;
}

cpp_code:
#include <vector>

std::vector<int> findDiagonalOrder(std::vector<std::vector<int>>& nums) {
    std::vector<int> res;
    int m = nums.size();
    std::map<int, std::vector<int>> diagonals;

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < nums[i].size(); j++) {
            diagonals[i + j].push_back(nums[i][j]);
        }
    }

    for (auto& diag : diagonals) {
        std::reverse(diag.second.begin(), diag.second.end());
        res.insert(res.end(), diag.second.begin(), diag.second.end());
    }

    return res;
}

