    for (int t = 1; t <= target; ++t) {
        for (int i = 1; i <= 9; ++i) {
            if (t >= cost[i - 1]) {
                std::string temp = dp[t - cost[i - 1]] + char('0' + i);
                if (dp[t].length() <= temp.length()) {
                    dp[t] = temp;
                }
            }
        }
    }

    return dp[target].empty() ? "0" : dp[target];
}

