public boolean kLengthApart(int[] nums, int k) {
    int last_one = -1;
    for (int i = 0; i < nums.length; i++) {
        if (nums[i] == 1) {
            if (last_one != -1 && i - last_one <= k) {
                return false;
            }
            last_one = i;
        }
    }
    return true;
}

