java_code:
import java.util.Comparator;
import java.util.PriorityQueue;

public int kthSmallest(int[][] mat, int k) {
    int m = mat.length, n = mat[0].length;

    PriorityQueue<int[]> minHeap = new PriorityQueue<>(Comparator.comparing(a -> a[0]));
    minHeap.offer(new int[]{mat[0][0], 0, 0});

    boolean[][] visited = new boolean[m][n];
    visited[0][0] = true;

    int res = 0;
    while (k-- > 0) {
        int[] cur = minHeap.poll();
        res = cur[0];
        int i = cur[1], j = cur[2];

        if (i < m - 1 && !visited[i+1][j]) {
            minHeap.offer(new int[]{res - mat[i][j] + mat[i + 1][j], i + 1, j});
            visited[i+1][j] = true;
        }
        if (j < n - 1 && !visited[i][j+1]) {
            minHeap.offer(new int[]{res - mat[i][j] + mat[i][j + 1], i, j + 1});
            visited[i][j+1] = true;
        }
    }

    return res;
}

cpp_code:
#include <vector>
#include <queue>

int kthSmallest(const std::vector<std::vector<int>>& mat, int k) {
    int m = mat.size(), n = mat[0].size();

    auto comp = [&](const std::vector<int>& a, const std::vector<int>& b) {
        return a[0] > b[0];
    };

    std::priority_queue<std::vector<int>, std::vector<std::vector<int>>, decltype(comp)> minHeap(comp);
    minHeap.push({mat[0][0], 0, 0});

    std::vector<std::vector<bool>> visited(m, std::vector<bool>(n, false));
    visited[0][0] = true;

    int res;
    while (k--) {
        auto cur = minHeap.top(); minHeap.pop();
        res = cur[0];
        int i = cur[1], j = cur[2];

        if (i < m - 1 && !visited[i+1][j]) {
            minHeap.push({res - mat[i][j] + mat[i + 1][j], i + 1, j});
            visited[i+1][j] = true;
        }
        if (j < n - 1 && !visited[i][j+1]) {
            minHeap.push({res - mat[i][j] + mat[i][j + 1], i, j + 1});
            visited[i][j+1] = true;
        }
    }

    return res;
}

javascript_code:
function kthSmallest(mat, k) {
    const m = mat.length, n = mat[0].length;

    const minHeap = [[mat[0][0], 0, 0]].sort((a, b) => a[0] - b[0]);
    const visited = Array(m).fill().map(_ => Array(n).fill(false));
    visited[0][0] = true;

    let res = 0;
    while (k-- > 0) {
        const [val, i, j] = minHeap.shift();
        res = val;

        if (i < m - 1 && !visited[i+1][j]) {
            minHeap.push([res - mat[i][j] + mat[i + 1][j], i + 1, j]);
            visited[i+1][j] = true;
        }
        if (j < n - 1 && !visited[i][j+1]) {
            minHeap.push([res - mat[i][j] + mat[i][j + 1], i, j + 1]);
            visited[i][j+1] = true;
        }

        minHeap.sort((a, b) => a[0] - b[0]);
    }

    return res;
}

