function minTime(n, edges, hasApple) {
  const graph = Array.from({ length: n }, () => new Map());

  for (const [a, b] of edges) {
    graph[a].set(b, 0);
    graph[b].set(a, 0);
  }

  function dfs(v, parent) {
    let ans = 0;
    for (const [u, _] of graph[v]) {
      if (u === parent) continue;
      ans += dfs(u, v) * 2;
    }

    return ans + (hasApple[v] || ans > 0 ? 1 : 0);
  }

  return dfs(0, -1);
}

