from collections import defaultdict

def DFS(src, graph, visited, transitive_closure, dest):
    if src == dest:
        transitive_closure[dest] = True
        return
    if visited[src]:
        return
    visited[src] = True
    for neighbor in graph[src]:
        DFS(neighbor, graph, visited, transitive_closure, dest)
        if transitive_closure[dest]:
            return

def checkIfPrerequisite(numCourses, prerequisites, queries):
    graph = defaultdict(list)

    for pre in prerequisites:
        graph[pre[0]].append(pre[1])

    result = []

    for i in range(len(queries)):
        visited = [False] * numCourses
        transitive_closure = [False] * numCourses
        DFS(queries[i][0], graph, visited, transitive_closure, queries[i][1])
        result.append(transitive_closure[queries[i][1]])

    return result

javascript_code:
function DFS(src, graph, visited, transitiveClosure, dest) {
    if (src === dest) {
        transitiveClosure[dest] = true;
        return;
    }
    if (visited[src]) return;
    visited[src] = true;
    for (let neighbor of graph[src]) {
        DFS(neighbor, graph, visited, transitiveClosure, dest);
        if (transitiveClosure[dest]) return;
    }
}

function checkIfPrerequisite(numCourses, prerequisites, queries) {
    const graph = new Map();

    for (let pre of prerequisites) {
        if (!graph.has(pre[0])) {
            graph.set(pre[0], []);
        }
        graph.get(pre[0]).push(pre[1]);
    }

    const result = [];

    for (let i = 0; i < queries.length; ++i) {
        const visited = new Array(numCourses).fill(false);
        const transitiveClosure = new Array(numCourses).fill(false);
        DFS(queries[i][0], graph, visited, transitiveClosure, queries[i][1]);
        result.push(transitiveClosure[queries[i][1]]);
    }

    return result;
}

java_code:
public int cherryPickup(int[][] grid) {
    int rows = grid.length;
    int cols = grid[0].length;
    int[][][] dp = new int[rows][cols][cols];

    for (int row = rows - 1; row >= 0; --row) {
        for (int col1 = 0; col1 < cols; ++col1) {
            for (int col2 = 0; col2 < cols; ++col2) {
                int currentCell = row < rows - 1 ? dp[row + 1][col1][col2] : 0;
                currentCell += grid[row][col1] + (col1 != col2 ? grid[row][col2] : 0);

                int maxVal = 0;
                for (int move1 = -1; move1 <= 1; ++move1) {
                    for (int move2 = -1; move2 <= 1; ++move2) {
                        int newCol1 = col1 + move1;
                        int newCol2 = col2 + move2;
                        if (newCol1 >= 0 && newCol1 < cols && newCol2 >= 0 && newCol2 < cols) {
                            maxVal = Math.max(maxVal, dp[row][newCol1][newCol2]);
                        }
                    }
                }

                dp[row][col1][col2] = currentCell + maxVal;
            }
        }
    }

    return dp[0][0][cols - 1];
}

