            if (i != j && includes(favoriteCompanies[j].begin(), favoriteCompanies[j].end(),
                                   favoriteCompanies[i].begin(), favoriteCompanies[i].end())) {
                isSubset = true;
            }
        }
        if (!isSubset) result.push_back(i);
    }
    return result;
}

