int maxVowels(std::string s, int k) {
    int max_count = 0, count = 0;
    for (int i = 0; i < s.length(); i++) {
        count += (s[i] == 'a' || s[i] == 'e' || s[i] == 'i' || s[i] == 'o' || s[i] == 'u');
        if (i >= k)
            count -= (s[i - k] == 'a' || s[i - k] == 'e' || s[i - k] == 'i' || s[i - k] == 'o' || s[i - k] == 'u');
        max_count = std::max(max_count, count);
    }
    return max_count;
}

