        for(int b : balls) sum+= b;
        vector<int> pre_sum;
        pre_sum.push_back(0);
        for(int b : balls) pre_sum.push_back(pre_sum.back()+b);

        memset(dp, 0, sizeof(dp));
        dp[0][0][0] = 1;
        for(int i = 0; i < k; ++i)
            for(int j = i; j >= 0; --j)
