                    for(int y = pre_sum[i+1] - x; y >= 0; --y)
                        if (x + y <= balls[i])
                            for(int d = max(0, balls[i] - 2 * y); d <= x; ++d){
                                double tmp = 1;
                                for(int z = 1; z <= d; ++z) tmp *= x + y + 1 - z, tmp /= z;
                                for(int z = 1; z <= y; ++z) tmp *= x + y + d + 1 - z, tmp /= z;
                                for(int z = 1; z <= balls[i] - y - y - d; ++z) tmp *= x + y + d + 1 - z, tmp /= z;
                                dp[i+1][j+1][x+d] += dp[i][j][x] * tmp;
                                dp[i+1][j][x+d] += dp[i][j][x] * tmp;
                            }

        return (dp[k][k>>1][sum>>1] - (1e-5 > dp[k][k>>1][sum>>1])) / (sum % 2 ? 1 : (1ll<<(sum>>1)));
    }
};

