#include <vector>
using namespace std;

class UnionFind {
public:
    vector<int> parent;
    int components;

    UnionFind(int size) {
        parent.resize(size);
        components = size;
        for (int i = 0; i < size; ++i) {
            parent[i] = i;
        }
    }

    int find(int x) {
        if (x != parent[x])
            parent[x] = find(parent[x]);
        return parent[x];
    }

    bool unite(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);
        if (rootX != rootY) {
            parent[rootX] = rootY;
            components--;
            return true;
        }
        return false;
    }
};

int maxNumEdgesToRemove(int n, vector<vector<int>> &edges) {
    UnionFind ufA(n + 1), ufB(n + 1);
    int common_edges = 0;

    for (auto &edge : edges) {
        if (edge[0] == 3) {
            if (ufA.unite(edge[1], edge[2])) {
                ufB.unite(edge[1], edge[2]);
                common_edges++;
            }
        }
    }

    int removed_edges = 0;
    for (auto &edge : edges) {
        UnionFind *uf = (edge[0] == 1) ? &ufA : (edge[0] == 2) ? &ufB : nullptr;
        if (uf && !uf->unite(edge[1], edge[2])) {
            removed_edges++;
        }
    }

    if (ufA.components != 2 || ufB.components != 2)
        return -1;
    return removed_edges - common_edges;
}

python_code:
class UnionFind:
    def __init__(self, size):
        self.parent = list(range(size))
        self.components = size

    def find(self, x):
        if x != self.parent[x]:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def unite(self, x, y):
        root_x, root_y = self.find(x), self.find(y)
        if root_x != root_y:
            self.parent[root_x] = root_y
            self.components -= 1
            return True
        return False

def max_num_edges_to_remove(n, edges):
    ufA, ufB = UnionFind(n + 1), UnionFind(n + 1)
    common_edges = 0

    for t, u, v in edges:
        if t == 3:
            if ufA.unite(u, v):
                ufB.unite(u, v)
                common_edges += 1

    removed_edges = 0
    for t, u, v in edges:
        uf = ufA if t == 1 else ufB if t == 2 else None
        if uf and not uf.unite(u, v):
            removed_edges += 1

    return -1 if ufA.components != 2 or ufB.components != 2 else removed_edges - common_edges

