class UnionFind {
    constructor(size) {
        this.parent = Array.from({length: size}, (_, i) => i);
        this.components = size;
    }

    find(x) {
        if (x !== this.parent[x]) {
            this.parent[x] = this.find(this.parent[x]);
        }
        return this.parent[x];
    }

    unite(x, y) {
        const rootX = this.find(x);
        const rootY = this.find(y);
        if (rootX !== rootY) {
            this.parent[rootX] = rootY;
            this.components--;
            return true;
        }
        return false;
    }
}

function maxNumEdgesToRemove(n, edges) {
    const ufA = new UnionFind(n + 1);
    const ufB = new UnionFind(n + 1);
    let common_edges = 0;

    for (const [t, u, v] of edges) {
        if (t === 3) {
            if (ufA.unite(u, v)) {
                ufB.unite(u, v);
                common_edges++;
            }
        }
    }

    let removed_edges = 0;
    for (const [t, u, v] of edges) {
        const uf = (t === 1) ? ufA : (t === 2) ? ufB : null;
        if (uf && !uf.unite(u, v)) {
            removed_edges++;
        }
    }

    return (ufA.components !== 2 || ufB.components !== 2) ? -1 : removed_edges - common_edges;
}

