import java.util.HashSet;

public int maxUniqueSplit(String s) {
    return maxUniqueSplit(s, 0, new HashSet<String>());
}

private int maxUniqueSplit(String s, int start, HashSet<String> seen) {
    if (start == s.length()) {
        return 0;
    }
    int maxUnique = -1;
    for (int i = start + 1; i <= s.length(); ++i) {
        String sub = s.substring(start, i);
        if (!seen.contains(sub)) {
            seen.add(sub);
            int unique = maxUniqueSplit(s, i, seen);
            if (unique != -1) {
                maxUnique = Math.max(maxUnique, unique + 1);
            }
            seen.remove(sub);
        }
    }
    return maxUnique;
}

cpp_code:
#include <string>
#include <unordered_set>

int maxUniqueSplit(const std::string& s, int start = 0, std::unordered_set<std::string>& seen = std::unordered_set<std::string>()) {
    if (start == s.size())
        return 0;
    int maxUnique = -1;
    for (int i = start + 1; i <= s.size(); ++i) {
        std::string sub = s.substr(start, i - start);
        if (seen.find(sub) == seen.end()) {
            seen.insert(sub);
            int unique = maxUniqueSplit(s, i, seen);
            if (unique != -1)
                maxUnique = std::max(maxUnique, unique + 1);
            seen.erase(sub);
        }
    }
    return maxUnique;
}

