class Solution {
public:
    struct TreeNode {
        char val;
        TreeNode* left;
        TreeNode* right;
        TreeNode(char x) : val(x), left(NULL), right(NULL) {}
    };

    TreeNode* expTree(string s) {
        stack<TreeNode*> nodes;
        stack<char> ops;
        for (int i = 0; i < s.size(); ++i) {
            if (isdigit(s[i])) {
                nodes.push(new TreeNode(s[i]));
            } else if (s[i] == '(') {
                ops.push(s[i]);
            } else if (s[i] == ')') {
                while (ops.top() != '(') {
                    process(nodes, ops);
                }
                ops.pop();
            } else {
                while (!ops.empty() && precedence(ops.top(), s[i])) {
                    process(nodes, ops);
                }
                ops.push(s[i]);
            }
        }
        while (!ops.empty()) {
            process(nodes, ops);
        }
        return nodes.top();
    }

    bool precedence(char a, char b) {
        if (a == '(') return false;
        if (b == '(' || b == ')') return true;
        if ((a == '*' || a == '/') && (b == '+' || b == '-')) return true;
        return false;
    }

    void process(stack<TreeNode*>& nodes, stack<char>& ops) {
        TreeNode* right = nodes.top(); nodes.pop();
        TreeNode* left = nodes.top(); nodes.pop();
        TreeNode* oper = new TreeNode(ops.top()); ops.pop();
        oper->left = left;
        oper->right = right;
        nodes.push(oper);
    }
};

python_code:
class Solution:
    def expTree(self, s: str) -> 'Node':
        def precedence(a, b):
            if a == '(':
                return False
            if b == '(' or b == ')':
                return True
            if (a in {'*', '/'}) and (b in {'+', '-'}):
                return True
            return False

        def process(nodes, ops):
            right = nodes.pop()
            left = nodes.pop()
            oper = Node(ops.pop())
            oper.left = left
            oper.right = right
            nodes.append(oper)

        nodes = []
        ops = []
        for i in s:
            if i.isdigit():
                nodes.append(Node(i))
            elif i == '(':
                ops.append(i)
            elif i == ')':
                while ops[-1] != '(':
                    process(nodes, ops)
                ops.pop()
            else:
                while ops and precedence(ops[-1], i):
                    process(nodes, ops)
                ops.append(i)
        while ops:
            process(nodes, ops)
        return nodes[0]

javascript_code:
var expTree = function(s) {
    function precedence(a, b) {
        if (a === '(') return false;
        if (b === '(' || b === ')') return true;
        if (('*/'.includes(a)) && ('+-'.includes(b))) return true;
        return false;
    }

    function process(nodes, ops) {
        const right = nodes.pop();
        const left = nodes.pop();
        const oper = new TreeNode(ops.pop());
        oper.left = left;
        oper.right = right;
        nodes.push(oper);
    }

    const nodes = [];
    const ops = [];
    for (let i = 0; i < s.length; ++i) {
        if (s[i] >= '0' && s[i] <= '9') {
            nodes.push(new TreeNode(s[i]));
        } else if (s[i] === '(') {
            ops.push(s[i]);
        } else if (s[i] === ')') {
            while (ops[ops.length - 1] !== '(') {
                process(nodes, ops);
            }
            ops.pop();
        } else {
            while (ops.length && precedence(ops[ops.length - 1], s[i])) {
                process(nodes, ops);
            }
            ops.push(s[i]);
        }
    }
    while (ops.length) {
        process(nodes, ops);
    }
    return nodes[0];
};

