class ThroneInheritance {
    constructor(kingName) {
        this.king = kingName;
        this.family = new Map();
        this.dead = new Set();
    }

    birth(parentName, childName) {
        if (!this.family.has(parentName)) {
            this.family.set(parentName, []);
        }
        this.family.get(parentName).push(childName);
    }

    death(name) {
        this.dead.add(name);
    }

    getInheritanceOrder() {
        const order = [];
        this.dfs(this.king, order);
        return order;
    }

    dfs(name, order) {
        if (!this.dead.has(name)) {
            order.push(name);
        }
        const children = this.family.get(name);
        if (children) {
            for (const child of children) {
                this.dfs(child, order);
            }
        }
    }
}

