class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def find_nearest_right_node(root, u):
    if not root:
        return None

    q = [root]

    while q:
        n = len(q)

        for i in range(n):
            current = q.pop(0)

            if current == u:
                return q[0] if i < n - 1 else None

            if current.left:
                q.append(current.left)
            if current.right:
                q.append(current.right)

    return None

