        const size = q.length;
        let prevVal = (level % 2 === 0) ? 0 : 1000001;

        for (let i = 0; i < size; ++i) {
            const curr = q.shift();

            if ((level % 2 === 0 && (curr.val % 2 === 0 || curr.val <= prevVal)) || 
                (level % 2 !== 0 && (curr.val % 2 !== 0 || curr.val >= prevVal))) {
                return false;
