    std::vector<std::string> ans;

    for (const auto &name : names) {
        if (nameCount[name] == 0) {
            ans.push_back(name);
            nameCount[name] = 1;
        } else {
            int k = nameCount[name];
            while (nameCount[name + "(" + std::to_string(k) + ")"] != 0) {
                k++;
            }
            ans.push_back(name + "(" + std::to_string(k) + ")");
            nameCount[name + "(" + std::to_string(k) + ")"] = 1;
            nameCount[name] = k + 1;
        }
    }

    return ans;
}

