javascript_code:
function rangeSum(nums, n, left, right) {
    const MOD = 10**9 + 7;
    let sums = [];
    for (let i = 0; i < n; ++i) {
        let sum = 0;
        for (let j = i; j < n; ++j) {
            sum += nums[j];
            sums.push(sum);
        }
    }
    sums.sort((a, b) => a - b);
    let result = 0;
    for (let i = left - 1; i < right; ++i) {
        result = (result + sums[i]) % MOD;
    }
    return result;
}

