function findMaxValueOfEquation(points, k) {
    let res = -Infinity;
    let q = [];

    for (let p of points) {
        while (q.length > 0 && p[0] - q[0][1] > k)
            q.shift();

        if (q.length > 0)
            res = Math.max(res, p[1] + p[0] + q[0][0]);

        while (q.length > 0 && p[1] - p[0] >= q[q.length - 1][0])
            q.pop();

        q.push([p[1] - p[0], p[0]]);
    }

    return res;
}

