    for (int i = 0; i < s.length(); ++i) {
        if (char_map.find(s[i]) == char_map.end()) {
            char_map[s[i]] = i;
        } else {
            result = std::max(result, i - char_map[s[i]] - 1);
        }
    }
    return result;
}

