#include <string>
#include <algorithm>

std::string findLexSmallestString(std::string s, int a, int b) {
    std::string smallest = s;
    int len = s.length();
    std::string rotated;

    for (int i = 0; i < len; i += 2) {
        for (int j = 0; j < 10; ++j) {
            rotated = s.substr(len - b) + s.substr(0, len - b);
            std::string tmp = rotated;

            for (int k = 1; k < len; k += 2)
                tmp[k] = '0' + (tmp[k] - '0' + a) % 10;

            smallest = std::min(smallest, tmp);
            s = rotated;
        }
        s[len - i - 1] = '0' + (s[len - i - 1] - '0' + a) % 10;
    }

    return smallest;
}

python_code:
def findLexSmallestString(s: str, a: int, b: int) -> str:
    def add_odd(s: str, a: int) -> str:
        return ''.join([str((int(ch) + a) % 10) if idx % 2 else ch for idx, ch in enumerate(s)])

    def rotate(s: str, k: int) -> str:
        k %= len(s)
        return s[-k:] + s[:-k]

    smallest = s
    for _ in range(len(s)):
        for _ in range(10):
            rotated = rotate(s, b)
            temp = add_odd(rotated, a)
            smallest = min(smallest, temp)
            s = rotated
        s = add_odd(s, a)
    return smallest

javascript_code:
function findLexSmallestString(s, a, b) {
    function rotate(s, k) {
        k %= s.length;
        return s.slice(s.length - k) + s.slice(0, s.length - k);
    }

    function addAtIndex(s, a, index) {
        const arr = [...s];
        arr[index] = (arr[index] - '0' + a) % 10 + '0';
        return arr.join('');
    }

    function addOdd(s, a) {
        return s.split('').map((ch, idx) => idx % 2 ? (parseInt(ch) + a) % 10 : ch).join('');
    }

    let smallest = s;
    for (let i = 0; i < s.length; i++) {
        for (let j = 0; j < 10; j++) {
            const rotated = rotate(s, b);
            const temp = addOdd(rotated, a);
            smallest = smallest < temp ? smallest : temp;
            s = rotated;
        }
        s = addAtIndex(s, a, s.length - i - 1);
    }
    return smallest;
}

