public int lastMoment(int n, int[] left, int[] right) {
    int max_left = 0;
    int min_right = n;

    for(int position : left) {
        max_left = Math.max(max_left, position);
    }

    for(int position : right) {
        min_right = Math.min(min_right, position);
    }

    return Math.max(max_left, n - min_right);
}

