int numSubmat(vector<vector<int>>& mat) {
    int m = mat.size(), n = mat[0].size();
    vector<vector<int>> dp(m, vector<int>(n));
    int count = 0;

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                dp[i][j] = (j == 0) ? 1 : dp[i][j - 1] + 1;
                int minWidth = dp[i][j];
                for (int k = i; k >= 0; k--) {
                    minWidth = min(minWidth, dp[k][j]);
                    count += minWidth;
                }
            }
        }
    }
    return count;
}

