public int numOfSubarrays(int[] arr) {
    int odd = 0, even = 1, sum = 0, result = 0;
    int mod = 1_000_000_007;
    for (int x : arr) {
        sum = (sum + x) % 2;
        if (sum % 2 == 0) {
            even++;
        } else {
            odd++;
        }
        result = (result + odd) % mod;
    }
    return result;
}

