        left_set.insert(s[i]);
        left[i] = left_set.size();
    }

    for (int i = s.size() - 1; i > 0; --i) {
        right_set.insert(s[i]);
        right[i] = right_set.size();
    }

    for (int i = 0; i < s.size() - 1; ++i) {
        if (left[i] == right[i + 1]) {
            ++count;
        }
    }

    return count;
}

