class PolyNode:
    def __init__(self, c: int, p: int, next: 'PolyNode' = None):
        self.coefficient = c
        self.power = p
        self.next = next

def addPoly(poly1: PolyNode, poly2: PolyNode) -> PolyNode:
    dummy = PolyNode(0, 0)
    current = dummy

    while poly1 and poly2:
        if poly1.power > poly2.power:
            current.next = poly1
            poly1 = poly1.next
        elif poly1.power < poly2.power:
            current.next = poly2
            poly2 = poly2.next
        else:
            sum = poly1.coefficient + poly2.coefficient
            if sum != 0:
                current.next = PolyNode(sum, poly1.power)
                current = current.next
            poly1 = poly1.next
            poly2 = poly2.next
        current = current.next

    current.next = poly1 if poly1 else poly2
    return dummy.next

