                if (s[l] == s[i - 1]) cnt++;
                else cnt = 1;
                int used = i - 2 - l;
                int new_aposition = i - 1 - cnt - used + 1;
                if (cnt >= 100) new_aposition += 4;
                else if (cnt >= 10) new_aposition += 3;
                else if (cnt >= 2) new_aposition += 2;
                else new_aposition++;
                dp[i][j] = std::min(dp[i][j], new_aposition + dp[l][j - used]);
            }
        }
