public double getMinDistSum(int[][] positions) {
    double x = 0;
    double y = 0;
    int n = positions.length;
    for (int i = 0; i < n; i++) {
        x += positions[i][0];
        y += positions[i][1];
    }
    x /= n;
    y /= n;
    return x;
}

