double getMinDistSum(std::vector<std::vector<int>>& positions) {
    double x = 0;
    double y = 0;
    for (const auto& pos : positions) {
        x += pos[0];
        y += pos[1];
    }
    int n = positions.size();
    x /= n;
    y /= n;
    return x;
}

