using namespace std;

int numWays(vector<string>& words, string target) {
    int n = words.size(), m = target.size();
    vector<vector<int>> count(n, vector<int>(26, 0));
    vector<vector<int>> dp(m, vector<int>(n, 0));
    const int mod = 1e9 + 7;

    for(int i = 0; i < n; i++) {
        for(char c : words[i]) {
            count[i][c - 'a']++;
        }
    }

    for(int i = 0; i < n; i++) {
        dp[0][i] = count[i][target[0] - 'a'];
    }

    for(int i = 1; i < m; i++) {
        for(int j = 0; j < n; j++) {
            for(int k = 0; k < n; k++) {
                dp[i][j] = (dp[i][j] + (long long)dp[i-1][k] * count[j][target[i] - 'a']) % mod;
            }
        }
    }

    int res = 0;
    for(int i = 0; i < n; i++) {
        res = (res + dp[m-1][i]) % mod;
    }
    return res;
}

python_code:
def numWays(words, target):
    n = len(words)
    m = len(target)
    count = [[0] * 26 for _ in range(n)]
    dp = [[0] * n for _ in range(m)]
    mod = 1000000007

    for i, word in enumerate(words):
        for c in word:
            count[i][ord(c) - ord('a')] += 1

    for i in range(n):
        dp[0][i] = count[i][ord(target[0]) - ord('a')]

    for i in range(1, m):
        for j in range(n):
            for k in range(n):
                dp[i][j] = (dp[i][j] + dp[i-1][k] * count[j][ord(target[i]) - ord('a')]) % mod

    return sum(dp[m-1]) % mod

javascript_code:
function numWays(words, target) {
    const n = words.length;
    const m = target.length;
    const count = Array.from({length: n}, () => Array(26).fill(0));
    const dp = Array.from({length: m}, () => Array(n).fill(0));
    const mod = 1e9 + 7;

    for (let i = 0; i < n; i++) {
        for (let c of words[i]) {
            count[i][c.charCodeAt(0) - 'a'.charCodeAt(0)]++;
        }
    }

    for (let i = 0; i < n; i++) {
        dp[0][i] = count[i][target.charCodeAt(0) - 'a'.charCodeAt(0)];
    }

    for (let i = 1; i < m; i++) {
        for (let j = 0; j < n; j++) {
            for (let k = 0; k < n; k++) {
                dp[i][j] = (dp[i][j] + dp[i-1][k] * count[j][target.charCodeAt(i) - 'a'.charCodeAt(0)]) % mod;
            }
        }
    }

    return dp[m-1].reduce((acc, val) => (acc + val) % mod, 0);
}

java_code:
import java.util.HashMap;
import java.util.Map;

public boolean canFormArray(int[] arr, int[][] pieces) {
    Map<Integer, int[]> map = new HashMap<>();
    for (int[] piece : pieces) {
        map.put(piece[0], piece);
    }

    int i = 0;
    while (i < arr.length) {
        if (!map.containsKey(arr[i])) {
            return false;
        }
        int[] piece = map.get(arr[i]);
        for (int j = 0; j < piece.length; ++j) {
            if (piece[j] != arr[i]) {
                return false;
            }
            ++i;
        }
    }
    return true;
}

