function canFormArray(arr, pieces) {
    const map = new Map(pieces.map(piece => [piece[0], piece]));

    let i = 0;
    while (i < arr.length) {
        if (!map.has(arr[i])) {
            return false;
        }
        const piece = map.get(arr[i]);
        for (const num of piece) {
            if (num !== arr[i]) {
                return false;
            }
            i++;
        }
    }
    return true;
}

