public List<String> maxNumOfSubstrings(String s) {
    int[] last = new int[26];
    Arrays.fill(last, -1);
    for (int i = 0; i < s.length(); ++i) {
        last[s.charAt(i) - 'a'] = i;
    }

    List<String> res = new ArrayList<>();
    int pre = -1, maxRight = -1;
    for (int i = 0; i < s.length(); ++i) {
        maxRight = Math.max(maxRight, last[s.charAt(i) - 'a']);
        if (maxRight == i) {
            res.add(s.substring(pre + 1, maxRight + 1));
            pre = i;
        }
    }

    return res;
}

