        last[s[i] - 'a'] = i;
    }

    std::vector<std::string> res;
    int pre = -1, maxRight = -1;
    for (int i = 0; i < (int)s.size(); ++i) {
        maxRight = std::max(maxRight, last[s[i] - 'a']);
        if (maxRight == i) {
            res.push_back(s.substr(pre + 1, maxRight - pre));
            pre = i;
        }
    }

    return res;
}

