    let maxRight = -1;
    for (let i = 0; i < s.length; ++i) {
        maxRight = Math.max(maxRight, last[s.charCodeAt(i) - 'a'.charCodeAt(0)]);
        if (maxRight === i) {
            res.push(s.substring(pre + 1, maxRight + 1));
            pre = i;
        }
    }

    return res;
}

