    umap[0] = 1;
    for (int num : nums) {
        sum += num;
        if (umap[sum - target]) {
            count++;
            umap.clear();
            umap[0] = 1;
            sum = 0;
        } else {
            umap[sum]++;
        }
    }
    return count;
}

