function maxNonOverlapping(nums, target) {
    let prefixSum = {};
    let sumSoFar = 0;
    let count = 0;
    prefixSum[0] = 1;
    for (const num of nums) {
        sumSoFar += num;
        if (prefixSum.hasOwnProperty(sumSoFar - target)) {
            count++;
            prefixSum = {};
            prefixSum[0] = 1;
            sumSoFar = 0;
        } else {
            if (!prefixSum.hasOwnProperty(sumSoFar)) {
                prefixSum[sumSoFar] = 0;
            }
            prefixSum[sumSoFar]++;
        }
    }
    return count;
}

