public int getWinner(int[] arr, int k) {
    int winner = arr[0];
    int consecutiveWins = 0;

    for (int i = 1; i < arr.length; i++) {
        if (arr[i] > winner) {
            winner = arr[i];
            consecutiveWins = 0;
        }
        if (++consecutiveWins == k) {
            break;
        }
    }
    return winner;
}

