public int minSwaps(int[][] grid) {
    int n = grid.length;
    int[] row_zeros = new int[n];

    for (int i = 0; i < n; i++) {
        for (int j = n - 1; j >= 0; j--) {
            if (grid[i][j] == 0) {
                row_zeros[i]++;
            } else {
                break;
            }
        }
    }

    int steps = 0;
    for (int i = 0; i < n; i++) {
        int target = n - i - 1;
        int current_row = i;
        while (current_row < n && row_zeros[current_row] < target) {
            current_row++;
        }
        if (current_row == n) {
            return -1;
        }
        steps += current_row - i;
        int temp = row_zeros[current_row];
        System.arraycopy(row_zeros, i, row_zeros, i + 1, current_row - i);
        row_zeros[i] = temp;
    }

    return steps;
}

