    const row_zeros = new Array(n).fill(0);

    for (let i = 0; i < n; i++) {
        for (let j = n - 1; j >= 0; j--) {
            if (grid[i][j] === 0) {
                row_zeros[i]++;
            } else {
                break;
            }
        }
    }

    let steps = 0;
    for (let i = 0; i < n; i++) {
        const target = n - i - 1;
        let current_row = i;
        while (current_row < n && row_zeros[current_row] < target) {
            current_row++;
        }
        if (current_row === n) {
            return -1;
        }
        steps += current_row - i;
        row_zeros.splice(current_row, 1);
        row_zeros.splice(i, 0, target);
    }

    return steps;
}

