        const b = j >= 0 ? dp2[j] + nums2[j] : Number.MIN_SAFE_INTEGER;
        const seen = new Set();
        if (a > b) {
            dp1[i--] = a % mod;
            seen.add(nums1[i + 1]);
        } else {
            dp2[j--] = b % mod;
            seen.add(nums2[j + 1]);
        }
    }
    return Math.max(dp1[0], dp2[0]) % mod;
}

