#include <string>

std::string thousandSeparator(int n) {
    std::string result = std::to_string(n);
    int count = 0;
    for (int i = result.size() - 1; i > 0; --i) {
        count++;
        if (count % 3 == 0) {
            result.insert(i, ".");
        }
    }
    return result;
}

