def count_routes(locations, start, finish, fuel, curr=None, remaining_fuel=None, memo=None):
    if memo is None:
        memo = {}

    if curr is None:
        curr = start
        remaining_fuel = fuel

    if remaining_fuel < 0:
        return 0

    if (curr, remaining_fuel) in memo:
        return memo[(curr, remaining_fuel)]

    ans = 1 if curr == finish else 0
    for next in range(len(locations)):
        if next != curr:
            ans += count_routes(locations, start, finish, fuel, next, remaining_fuel - abs(locations[curr] - locations[next]), memo)
            ans %= 1000000007

    memo[(curr, remaining_fuel)] = ans
    return ans

javascript_code:
function countRoutes(locations, start, finish, fuel, curr = null, remainingFuel = null, memo = {}) {
    if (curr === null) {
        curr = start;
        remainingFuel = fuel;
    }

    if (remainingFuel < 0) {
        return 0;
    }

    const key = `${curr}:${remainingFuel}`;
    if (memo.hasOwnProperty(key)) {
        return memo[key];
    }

    let ans = (curr === finish) ? 1 : 0;
    for (let next = 0; next < locations.length; ++next) {
        if (next !== curr) {
            ans += countRoutes(locations, start, finish, fuel, next, remainingFuel - Math.abs(locations[curr] - locations[next]), memo);
            ans %= 1000000007;
        }
    }
    memo[key] = ans;
    return ans;
}

