function minSubarray(nums, p) {
    const n = nums.length;
    let need = 0, cur = 0, res = n;
    const last_seen = new Map();

    for (const num of nums)
        need = (need + num) % p;

    if (need === 0)
        return 0;

    last_seen.set(cur, -1);
    for (let i = 0; i < n; ++i) {
        cur = (cur + nums[i]) % p;
        last_seen.set(cur, i);
        const want = (cur - need + p) % p;
        if (last_seen.has(want))
            res = Math.min(res, i - last_seen.get(want));
    }

    return res === n ? -1 : res;
}

