            if (!dfs(((i-top[k])*(right[k]-left[k]+1)) + j - left[k])) return false;
        }
        return true;
    };

    for (int color = 1; color <= 60; ++color) {
        for (int i = top[color]; i <= bottom[color]; ++i) {
            for (int j = left[color]; j <= right[color]; ++j) {
                if (!vis[i][j] && !dfs(i * n + j)) return false;
            }
        }
    }

    return true;
}

