def maxNumEdgesToRemove(n, edges):
    def find(u):
        if parent[u] == u:
            return u
        else:
            parent[u] = find(parent[u])
            return parent[u]

    def unite(u, v):
        u = find(u)
        v = find(v)
        if u != v:
            parent[u] = v
            return True
        return False

    parent = list(range(2 * n + 1))
    ct = [0, 0]
    both = n - 1
    edges.sort(reverse=True)
    for edge in edges:
        type, u, v = edge
        if type == 3 and unite(u, v + n):
            both -= 1
        if both == 0:
            break

    for type in range(1, 3):
        for edge in edges:
            a, u, v = edge
            if a == type and unite(u, v + n):
                ct[type - 1] += 1
        if both + ct[type - 1] < n - 1:
            return -1

    return ct[0] + ct[1] - n + 1

javascript_code:
function maxNumEdgesToRemove(n, edges) {
    let parent = new Array(2 * n + 1).fill().map((_, i) => i);

    function find(u) {
        return parent[u] === u ? u : parent[u] = find(parent[u]);
    }

    function unite(u, v) {
        u = find(u);
        v = find(v);
        if (u !== v) {
            parent[u] = v;
            return true;
        }
        return false;
    }

    edges.sort((a, b) => b[0] - a[0]);
    let ct = [0, 0];
    let both = n - 1;
    for (let edge of edges) {
        if (edge[0] === 3 && unite(edge[1], edge[2] + n)) {
            both--;
        }
        if (both === 0) break;
    }

    for (let type = 1; type < 3; type++) {
        for (let edge of edges) {
            if (edge[0] === type && unite(edge[1], edge[2] + n)) {
                ct[type - 1]++;
            }
        }
        if (both + ct[type - 1] < n - 1) {
            return -1;
        }
    }

    return ct[0] + ct[1] - n + 1;
}

java_code:
public String maximumBinaryString(String binary) {
    int zeroCount = 0;
    int oneCount = 0;

    for (char c : binary.toCharArray()) {
        if (c == '0') {
            zeroCount++;
        } else {
            oneCount++;
        }
    }

    if (zeroCount <= 1) {
        return binary;
    }

    StringBuilder result = new StringBuilder();
    for (int i = 0; i < oneCount; ++i) {
        result.append('1');
    }
    for (int i = 0; i < zeroCount - 1; ++i) {
        result.append('0');
    }
    result.append("1####1");
    return result.substring(0, binary.length());
}

