java_code:
public int minMoves(int[] nums, int k) {
    List<Integer> ones_pos = new ArrayList<>();
    for (int i = 0; i < nums.length; i++) {
        if (nums[i] == 1) {
            ones_pos.add(i - ones_pos.size());
        }
    }
    int sum = 0;
    for (int i = 0; i < k; i++) {
        sum += ones_pos.get(i);
    }
    int min_sum = sum;
    for (int i = k; i < ones_pos.size(); i++) {
        sum += ones_pos.get(i) - ones_pos.get(i - k);
        min_sum = Math.min(min_sum, sum);
    }
    return min_sum - (k - 1) * k / 2;
}

cpp_code:
int minMoves(vector<int>& nums, int k) {
    vector<int> ones_pos;
    int moves = 0;
    for (int i = 0; i < nums.size(); i++) {
        if (nums[i] == 1) {
            ones_pos.push_back(i);
        }
    }
    for (int i = 0; i + k <= ones_pos.size(); i++) {
        int pos = ones_pos[i + k / 2];
        for (int j = i; j < i + k; j++) {
            moves += abs(ones_pos[j] - pos);
        }
    }
    return moves;
}

