#include <vector>
#include <queue>

std::vector<int> busiestServers(int k, std::vector<int>& arrival, std::vector<int>& load) {
    std::vector<int> serverRequests(k, 0);
    std::priority_queue<std::pair<int, int>, std::vector<std::pair<int, int>>, std::greater<std::pair<int, int>>> pq;
    std::queue<int> availableServers;

    for (int i = 0; i < k; ++i) {
        availableServers.push(i);
    }

    for (int i = 0; i < arrival.size(); ++i) {
        while (!pq.empty() && pq.top().first <= arrival[i]) {
            availableServers.push(pq.top().second);
            pq.pop();
        }

        if (!availableServers.empty()) {
            int serverId = availableServers.front();
            availableServers.pop();
            serverRequests[serverId]++;
            pq.push({arrival[i] + load[i], serverId});
        }
    }

    int maxRequests = 0;
    for (int requests : serverRequests) {
        maxRequests = std::max(maxRequests, requests);
    }

    std::vector<int> result;
    for (int i = 0; i < k; ++i) {
        if (serverRequests[i] == maxRequests) {
            result.push_back(i);
        }
    }

    return result;
}

javascript_code:
function busiestServers(k, arrival, load) {
    const serverRequests = new Array(k).fill(0);
    const pq = [];
    const availableServers = Array.from({ length: k }, (_, i) => i);

    for (let i = 0; i < arrival.length; i++) {
        while (pq.length && pq[0][0] <= arrival[i]) {
            const [, serverId] = pq.shift();
            availableServers.push(serverId);
        }

        if (availableServers.length) {
            const serverId = availableServers.shift();
            serverRequests[serverId]++;
            pq.push([arrival[i] + load[i], serverId]);
            pq.sort((a, b) => a[0] - b[0]);
        }
    }

    const maxRequests = Math.max(...serverRequests);
    return serverRequests.reduce((result, requests, i) => {
        if (requests === maxRequests) {
            result.push(i);
        }
        return result;
    }, []);
}

