    for (const a of arr) {
        if (pos.has(a)) {
            const idx = dp.findIndex(x => x >= pos.get(a));
            if (idx === -1) {
                dp.push(pos.get(a));
            } else {
                dp[idx] = pos.get(a);
            }
        }
    }
    return target.length - dp.length;
}

