java_code:
public int[] constructDistancedSequence(int n) {
    int[] res = new int[2 * n - 1];
    dfs(res, 0, new boolean[n + 1]);
    return res;
}

private boolean dfs(int[] res, int i, boolean[] used) {
    if (i == res.length) {
        return true;
    }
    if (res[i] != 0) {
        return dfs(res, i + 1, used);
    }
    for (int num = used.length - 1; num > 0; num--) {
        if (!used[num] && (num == 1 || (i + num < res.length && res[i + num] == 0))) {
            res[i] = num;
            if (num > 1) {
                res[i + num] = num;
            }
            used[num] = true;
            if (dfs(res, i + 1, used)) {
                return true;
            }
            res[i] = 0;
            if (num > 1) {
                res[i + num] = 0;
            }
            used[num] = false;
        }
    }
    return false;
}

cpp_code:
vector<int> constructDistancedSequence(int n) {
    vector<int> res(2 * n - 1, 0);
    function<bool(int,int)> dfs = [&](int i, int unused){
        if (i == res.size()) return true;
        if (res[i]) return dfs(i + 1, unused);
        for (int num = n; num > 0; --num) {
            if ((unused >> num) & 1) {
                if (num == 1 || i + num < res.size() && !res[i + num]) {
                    res[i] = num;
                    if (num > 1) res[i + num] = num;
                    if (dfs(i + 1, unused ^ (1 << num))) return true;
                    res[i] = 0;
                    if (num > 1) res[i + num] = 0;
                }
            }
        }
        return false;
    };
    dfs(0, (1 << (n + 1)) - 2);
    return res;
}

python_code:
class Solution:
    def constructDistancedSequence(self, n: int) -> List[int]:
        res = [0] * (2 * n - 1)

        def backtrack(i, unused):
            if i == len(res):
                return True
            if res[i]:
                return backtrack(i + 1, unused)
            for num in range(n, 0, -1):
                if (unused >> num) & 1:
                    if num == 1 or (i + num < len(res) and not res[i + num]):
                        res[i] = num
                        if num > 1:
                            res[i + num] = num
                        if backtrack(i + 1, unused ^ (1 << num)):
                            return True
                        res[i] = 0
                        if num > 1:
                            res[i + num] = 0
            return False

        backtrack(0, (1 << (n + 1)) - 2)
        return res

