        if (res[i]) return dfs(i + 1, unused);
        for (let num = n; num > 0; num--) {
            if ((unused >> num) & 1) {
                if (num === 1 || i + num < res.length && !res[i + num]) {
                    res[i] = num;
                    if (num > 1) res[i + num] = num;
                    if (dfs(i + 1, unused ^ (1 << num))) return true;
                    res[i] = 0;
                    if (num > 1) res[i + num] = 0;
                }
            }
        }
        return false;
    }

    dfs(0, (1 << (n + 1)) - 2);
    return res;
};

