int checkWays(std::vector<std::vector<int>>& pairs) {
    std::unordered_map<int, int> candidates;
    for (const auto& pair : pairs) {
        ++candidates[pair[0]];
        ++candidates[pair[1]];
    }

    int rootCount = 0;
    for (const auto& candidate : candidates) {
        if (candidate.second == 1) {
            ++rootCount;
            if (rootCount > 1) {
                return 2;
            }
        }
    }

    return rootCount;
}

