    unordered_map<string, bool> alive;
    string king;
public:
    ThroneInheritance(string kingName) : king(kingName) {
        alive[kingName] = true;
    }

    void birth(string parentName, string childName) {
        children[parentName].push_back(childName);
        alive[childName] = true;
    }

    void death(string name) {
        alive[name] = false;
    }

    vector<string> getInheritanceOrder() {
        vector<string> order;
        getSuccessor(king, order);
        return order;
    }

    void getSuccessor(string name, vector<string>& order) {
        if (alive[name]) {
            order.push_back(name);
        }
        for (const auto& child : children[name]) {
            getSuccessor(child, order);
        }
    }
};

