class ThroneInheritance {
    constructor(kingName) {
        this.children = {};
        this.alive = {[kingName]: true};
        this.king = kingName;
    }

    birth(parentName, childName) {
        if (!this.children[parentName]) {
            this.children[parentName] = [];
        }
        this.children[parentName].push(childName);
        this.alive[childName] = true;
    }

    death(name) {
        this.alive[name] = false;
    }

    getInheritanceOrder() {
        const order = [];
        this.getSuccessor(this.king, order);
        return order;
    }

    getSuccessor(name, order) {
        if (this.alive[name]) {
            order.push(name);
        }
        if (this.children[name]) {
            for (const child of this.children[name]) {
                this.getSuccessor(child, order);
            }
        }
    }
}

