#include <vector>

int maxAchievableRequests(int n, std::vector<std::vector<int>>& requests, int idx = 0, std::vector<int> counts = {}) {
    if (counts.empty()) {
        counts.resize(n, 0);
    }
    if (idx == requests.size()) {
        for (int count : counts) {
            if (count != 0) return 0;
        }
        return 0;
    }
    int ignored = maxAchievableRequests(n, requests, idx + 1, counts);
    counts[requests[idx][0]]++;
    counts[requests[idx][1]]--;

    int accepted = 1 + maxAchievableRequests(n, requests, idx + 1, counts);

    return std::max(ignored, accepted);
}

python_code:
def max_achievable_requests(n, requests, idx=0, counts=None):
    if counts is None:
        counts = [0] * n
    if idx == len(requests):
        if all(count == 0 for count in counts):
            return 0
        return 0

    ignored = max_achievable_requests(n, requests, idx+1, counts[:])
    counts[requests[idx][0]] += 1
    counts[requests[idx][1]] -= 1

    accepted = 1 + max_achievable_requests(n, requests, idx+1, counts)

    return max(ignored, accepted)

javascript_code:
function maxAchievableRequests(n, requests, idx = 0, counts = null) {
    if (counts === null) {
        counts = new Array(n).fill(0);
    }
    if (idx === requests.length) {
        if (counts.every(count => count === 0)) return 0;
        return 0;
    }
    let ignored = maxAchievableRequests(n, requests, idx + 1, [...counts]);
    counts[requests[idx][0]]++;
    counts[requests[idx][1]]--;

    let accepted = 1 + maxAchievableRequests(n, requests, idx + 1, counts);

    return Math.max(ignored, accepted);
}

