class DistanceLimitedPathsExist {
public:
    DistanceLimitedPathsExist(int n, const std::vector<std::vector<int>>& edgeList) {
        id.resize(n);
        for (int i = 0; i < n; ++i) {
            id[i] = i;
        }
        std::sort(edgeList.begin(), edgeList.end(), [](const auto& a, const auto& b) {
            return a[2] < b[2];
        });
        for (const auto& edge : edgeList) {
            int p = find(edge[0]);
            int q = find(edge[1]);
            if (p != q) {
                id[p] = id[q];
                mst.emplace_back(edge);
            }
        }
    }

    bool query(int p, int q, int limit) {
        for (const auto& edge : mst) {
            if (edge[2] >= limit) break;
            p = union_set(edge[0], p);
            q = union_set(edge[1], q);
            if (p == q) return true;
        }
        return false;
    }

private:
    int find(int x) {
        if (id[x] != x) {
            id[x] = find(id[x]);
        }
        return id[x];
    }

    int union_set(int x, int y) {
        int px = find(x);
        int py = find(y);
        if (px != py) {
            id[px] = py;
        }
        return py;
    }

    std::vector<int> id;
    std::vector<std::vector<int>> mst;
};

