        this.mst = [];
        for (const edge of edgeList) {
            const p = this.find(edge[0]);
            const q = this.find(edge[1]);
            if (p !== q) {
                this.id[p] = this.id[q];
                this.mst.push(edge);
            }
        }
    }

    query(p, q, limit) {
        for (const edge of this.mst) {
            if (edge[2] >= limit) break;
            p = this.union_set(edge[0], p);
            q = this.union_set(edge[1], q);
            if (p === q) return true;
        }
        return false;
    }

    find(x) {
        if (this.id[x] !== x) {
            this.id[x] = this.find(this.id[x]);
        }
        return this.id[x];
    }

    union_set(x, y) {
        const px = this.find(x);
        const py = this.find(y);
        if (px !== py) {
            this.id[px] = py;
        }
        return py;
    }
}

java_code:
public int numberOfSets(int n, int k) {
    long mod = 1000000007;
    long[][] dp = new long[n][k + 1];
    long[] presum = new long[n];
    Arrays.fill(presum, 1);

    for (int j = 1; j <= k; ++j) {
        for (int i = 0; i < n; ++i) {
            dp[i][j] = presum[i];
            if (i > 0) {
                dp[i][j] += dp[i - 1][j];
            }
            dp[i][j] %= mod;
            presum[i] = (presum[i] + dp[i][j - 1]) % mod;
        }
    }

    return (int) dp[n - 1][k];
}

