        for(auto& num : sequence) {
            num += inc;
        }
    }

    void multAll(int m) {
        for(auto& num : sequence) {
            num *= m;
        }
    }

    int getIndex(int idx) {
        if(idx >= sequence.size()) return -1;
        return sequence[idx];
    }
private:
    vector<int> sequence;
};

