        degree[road[0]]++;
        degree[road[1]]++;
        s.insert({min(road[0], road[1]), max(road[0], road[1])});
    }

    int ans = 0;
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            ans = max(ans, degree[i] + degree[j] - (s.count({i, j}) ? 1 : 0));
        }
    }
    return ans;
}

