using std::vector;
using std::pair;
using std::priority_queue;

int minimumEffortPath(vector<vector<int>>& heights) {
    const vector<pair<int, int>> directions = {{1, 0}, {0, 1}, {-1, 0}, {0, -1}};
    int rows = heights.size();
    int cols = heights[0].size();
    vector<vector<int>> efforts(rows, vector<int>(cols, INT_MAX));
    priority_queue<pair<int, pair<int, int>>, vector<pair<int, pair<int, int>>>, std::greater<>> pq;

    efforts[0][0] = 0;
    pq.push({0, {0, 0}});

    while (!pq.empty()) {
        auto [effort, pos] = pq.top();
        pq.pop();
        int x = pos.first, y = pos.second;

        if (x == rows - 1 && y == cols - 1) {
            return effort;
        }

        for (const auto& dir : directions) {
            int nx = x + dir.first;
            int ny = y + dir.second;
            if (nx >= 0 && nx < rows && ny >= 0 && ny < cols) {
                int new_effort = std::max(effort, std::abs(heights[nx][ny] - heights[x][y]));
                if (new_effort < efforts[nx][ny]) {
                    efforts[nx][ny] = new_effort;
                    pq.push({new_effort, {nx, ny}});
                }
            }
        }
    }

    return -1;
}

javascript_code:
function minimumEffortPath(heights) {
    const directions = [[1, 0], [0, 1], [-1, 0], [0, -1]];
    const rows = heights.length;
    const cols = heights[0].length;
    const efforts = Array.from({ length: rows }, () => Array(cols).fill(Infinity));
    const pq = new PriorityQueue((a, b) => a[0] - b[0]);

    efforts[0][0] = 0;
    pq.offer([0, 0, 0]);

    while (!pq.isEmpty()) {
        const [effort, x, y] = pq.poll();

        if (x === rows - 1 && y === cols - 1) {
            return effort;
        }

        for (const [dx, dy] of directions) {
            const nx = x + dx;
            const ny = y + dy;
            if (nx >= 0 && nx < rows && ny >= 0 && ny < cols) {
                const newEffort = Math.max(effort, Math.abs(heights[nx][ny] - heights[x][y]));
                if (newEffort < efforts[nx][ny]) {
                    efforts[nx][ny] = newEffort;
                    pq.offer([newEffort, nx, ny]);
                }
            }
        }
    }

    return -1;
}

class PriorityQueue {
    constructor(comparator) {
        this.comparator = comparator;
        this.data = [];
    }

    offer(elem) {
        let i = this.data.length;
        this.data.push(elem);

        while (i > 0) {
            const parent = Math.floor((i - 1) / 2);
            if (this.comparator(this.data[i], this.data[parent]) >= 0) {
                break;
            }
            [this.data[i], this.data[parent]] = [this.data[parent], this.data[i]];
            i = parent;
        }
    }

    poll() {
        if (this.isEmpty()) return null;

        const result = this.data[0];
        const last = this.data.pop();

        if (!this.isEmpty()) {
            this.data[0] = last;
            let i = 0;

            while (true) {
                const left = 2 * i + 1;
                const right = 2 * i + 2;
                let smallest = i;

                if (left < this.data.length && this.comparator(this.data[left], this.data[smallest]) < 0) {
                    smallest = left;
                }

                if (right < this.data.length && this.comparator(this.data[right], this.data[smallest]) < 0) {
                    smallest = right;
                }

                if (smallest === i) break;

                [this.data[i], this.data[smallest]] = [this.data[smallest], this.data[i]];
                i = smallest;
            }
        }

        return result;
    }

    isEmpty() {
        return this.data.length === 0;
    }
}

