std::string largestMerge(std::string word1, std::string word2) {
    std::string result;
    while (!word1.empty() || !word2.empty()) {
        if (word1 > word2) {
            result += word1[0];
            word1.erase(word1.begin());
        } else {
            result += word2[0];
            word2.erase(word2.begin());
        }
    }
    return result;
}

