public int minDeletions(String s) {
    int aCount = 0, bCount = 0, deletions = 0;
    for (char c : s.toCharArray()) {
        if (c == 'a') {
            aCount++;
        } else {
            if (aCount > 0) {
                aCount--;
            } else {
                deletions++;
            }
        }
    }
    return deletions;
}

