        right[n - 1 - i] = lowerBound(right.slice(n - 1 - i, n).reverse(), nums[n - 1 - i]);
    }
    let result = n;
    for (let i = 1; i < n - 1; ++i)
        result = Math.min(result, n - (left[i] + 1) - (right[i] + 1));

    return result;
}

