    unordered_set<int> used;
    int deletions = 0;

    for (char c : s) {
        freq[c]++;
    }

    for (auto const& [char, count] : freq) {
        while (used.find(count) != used.end() && count > 0) {
            deletions++;
            count--;
        }
        used.insert(count);
    }

    return deletions;
}

