import java.util.TreeSet;

class Solution {
    final int MOD = 1000000007;

    public int createSortedArray(int[] instructions) {
        TreeSet<Integer> set = new TreeSet<>();
        int cost = 0;

        for (int i : instructions) {
            set.add(i);
            int less_than = set.headSet(i).size();
            int greater_than = set.tailSet(i + 1).size();
            cost = (cost + Math.min(less_than, greater_than)) % MOD;
        }

        return cost;
    }
}

cpp_code:
#include <set>

const int MOD = 1e9 + 7;

int createSortedArray(vector<int>& instructions) {
    multiset<int> s;
    int cost = 0;

    for (int i : instructions) {
        s.insert(i);
        int less_than = distance(s.begin(), s.lower_bound(i));
        int greater_than = distance(s.upper_bound(i), s.end());
        cost = (cost + min(less_than, greater_than)) % MOD;
    }

    return cost;
}

javascript_code:
const MOD = 1e9 + 7

function createSortedArray(instructions) {
    let nums = new Set();
    let cost = 0;

    for (let i of instructions) {
        nums.add(i);
        let sortedNums = Array.from(nums).sort((a, b) => a - b);
        let less_than = sortedNums.filter(x => x < i).length;
        let greater_than = sortedNums.filter(x => x > i).length;
        cost = (cost + Math.min(less_than, greater_than)) % MOD;
        nums = new Set(sortedNums);
    }

    return cost;
}

