from itertools import product

def closest_cost(base_costs, topping_costs, target):
    closest = float('inf')
    topping_combinations = list(product([0, 1, 2], repeat=len(topping_costs)))

    for base in base_costs:
        for combination in topping_combinations:
            combination_cost = sum(x * y for x, y in zip(topping_costs, combination))
            diff = abs(target - (base + combination_cost))
            if diff < closest:
                closest = diff
            if diff == 0:
                return target

    return target - closest

javascript_code:
function closestCost(baseCosts, toppingCosts, target) {
    let closest = Infinity;

    function dfs(index, cost) {
        if (index === toppingCosts.length || cost >= target + closest) {
            closest = Math.min(closest, Math.abs(cost - target));
            return;
        }

        dfs(index + 1, cost);
        dfs(index + 1, cost + toppingCosts[index]);
        dfs(index + 1, cost + 2 * toppingCosts[index]);
    }

    for (const base of baseCosts) {
        dfs(0, base);
    }

    return target - (closest > target ? -closest : closest);
}

