using namespace std;

string getSmallestString(int n, int k) {
    string result(n, 'a');
    k -= n;
    for (int i = n - 1; i >= 0; --i) {
        int value = min(k, 25);
        result[i] += value;
        k -= value;
        if (k == 0) break;
    }
    return result;
}

python_code:
def get_smallest_string(n: int, k: int) -> str:
    result = ['a'] * n
    k -= n
    idx = n - 1
    while k > 0:
        value = min(k, 25)
        result[idx] = chr(ord(result[idx]) + value)
        k -= value
        idx -= 1
    return ''.join(result)

