java_code:
public int stoneGameVI(int[] aliceValues, int[] bobValues) {
    int n = aliceValues.length;
    Integer[] indexes = new Integer[n];
    for (int i = 0; i < n; ++i) {
        indexes[i] = i;
    }

    Arrays.sort(indexes, (a, b) -> (bobValues[b] + aliceValues[b]) - (bobValues[a] + aliceValues[a]));

    int aliceScore = 0, bobScore = 0;
    for (int i = 0; i < n; ++i) {
        if (i % 2 == 0) aliceScore += aliceValues[indexes[i]];
        else bobScore += bobValues[indexes[i]];
    }

    return Integer.compare(aliceScore, bobScore);
}

cpp_code:
int stoneGameVI(vector<int>& aliceValues, vector<int>& bobValues) {
    int n = aliceValues.size();
    vector<pair<int, int>> sums;

    for (int i = 0; i < n; ++i) {
        sums.push_back({aliceValues[i] + bobValues[i], i});
    }

    sort(sums.rbegin(), sums.rend());

    int aliceScore = 0, bobScore = 0;
    for (int i = 0; i < n; ++i) {
        if (i % 2 == 0) aliceScore += aliceValues[sums[i].second];
        else bobScore += bobValues[sums[i].second];
    }

    return (aliceScore == bobScore) ? 0 : (aliceScore > bobScore) ? 1 : -1;
}

