    let aliceScore = 0, bobScore = 0;
    for (let i = 0; i < n; ++i) {
        if (i % 2 === 0) aliceScore += aliceValues[sums[i][1]];
        else bobScore += bobValues[sums[i][1]];
    }

    return aliceScore === bobScore ? 0 : aliceScore > bobScore ? 1 : -1;
}

