    vector<int> delta(2 * limit + 2, 0);

    for (int i = 0; i < n / 2; i++) {
        int lo = min(nums[i], nums[n - 1 - i]) + 1;
        int hi = max(nums[i], nums[n - 1 - i]) + limit;
        delta[lo]--;
        delta[nums[i] + nums[n - 1 - i]]--;
        delta[hi + 1]++;
    }
    int moves = n, current = n;
    for (int i = 2; i <= 2 * limit; i++) {
        current += delta[i];
        moves = min(moves, current);
    }
    return moves;
}

