        const lo = Math.min(nums[i], nums[n - 1 - i]) + 1;
        const hi = Math.max(nums[i], nums[n - 1 - i]) + limit;
        delta[lo]--;
        delta[nums[i] + nums[n - 1 - i]]--;
        delta[hi + 1]++;
    }
    let moves = n, current = n;
    for (let i = 2; i <= 2 * limit; i++) {
        current += delta[i];
        moves = Math.min(moves, current);
    }
    return moves;
}

