#include <unordered_map>

int maxOperations(std::vector<int>& nums, int k) {
    std::unordered_map<int, int> count;
    int operations = 0;

    for (int num : nums) {
        if (count[k - num] > 0) {
            --count[k - num];
            ++operations;
        }
        else {
            ++count[num];
        }
    }

    return operations;
}

