    for (int student : students)
        q.push(student);

    int index = 0, attempts = 0;
    while (!q.empty()) {
        int student = q.front();
        if (student == sandwiches[index]) {
            q.pop();
            index++;
            attempts = 0;
        } else {
            q.pop();
            q.push(student);
            attempts++;
        }
        if (attempts == q.size())
            break;
    }

    return q.size();
}

