public double averageWaitingTime(int[][] customers) {
    double waitTime = 0;
    int currTime = 0;

    for (int[] customer : customers) {
        currTime = Math.max(currTime, customer[0]) + customer[1];
        waitTime += currTime - customer[0];
    }

    return waitTime / customers.length;
}

