int minMoves(vector<int>& nums, int k) {
    int n = nums.size();
    vector<int> ones;
    for(int i = 0; i < n; ++i){
        if(nums[i] == 1){
            ones.push_back(i - ones.size());
        }
    }

    int moves = 0;
    for(int i = 0; i < k; ++i){
        moves += (ones[i] - ones[k / 2]);
    }

    int min_moves = moves;
    for(int i = k; i < ones.size(); ++i){
        moves += ones[i] - ones[i - k] - k;
        min_moves = min(min_moves, moves);
    }

    return min_moves;
}

javascript_code:
function minMoves(nums, k) {
    const n = nums.length;
    const ones = [];

    for(let i = 0; i < n; ++i){
        if(nums[i] === 1){
            ones.push(i - ones.length);
        }
    }

    let moves = 0;
    for(let i = 0; i < k; ++i){
        moves += (ones[i] - ones[k / 2]);
    }

    let min_moves = moves;
    for(let i = k; i < ones.length; ++i){
        moves += ones[i] - ones[i - k] - k;
        min_moves = Math.min(min_moves, moves);
    }

    return min_moves;
}

