class Solution {
public:
    int findShortestPath(GridMaster &master) {
        dfs(master, 0, 0);
        if(target.first == INT_MAX) {
            return -1;
        }
        return bfs();
    }

private:
    map<pair<int, int>, int> grid;
    pair<int, int> target = {INT_MAX, INT_MAX};
    int dirs[5] = {-1, 0, 1, 0, -1};

    void dfs(GridMaster &master, int x, int y) {
        if (master.isTarget()) {
            target = {x, y};
        }
        for (int i = 0; i < 4; i++) {
            int nx = x + dirs[i], ny = y + dirs[i + 1];
            if(grid.count({nx, ny})) continue;
            if (master.canMove(dir_char[i])) {
                int cost = master.move(dir_char[i]);
                grid[{nx, ny}] = cost;
                dfs(master, nx, ny);
                master.move(opposite_dir_char[i]);
            }
        }
    }

    int bfs() {
        queue<pair<int, int>> q;
        q.push({0, 0});
        grid[{0, 0}] = 0;
        while(!q.empty()) {
            auto [x, y] = q.front();
            q.pop();
            for (int i = 0; i < 4; i++) {
                int nx = x + dirs[i], ny = y + dirs[i + 1];
                int cost = grid[{x, y}] + grid[{nx, ny}];
                if(grid.count({nx, ny}) && grid[{nx, ny}] > cost) {
                    grid[{nx, ny}] = cost;
                    if (nx != target.first || ny != target.second) {
                        q.push({nx, ny});
                    }
                }
            }
        }
        return grid[target];
    }

    char dir_char[4] = {'U', 'R', 'D', 'L'};
    char opposite_dir_char[4] = {'D', 'L', 'U', 'R'};
};

python_code:
class Solution:
    def findShortestPath(self, master: 'GridMaster') -> int:
        def dfs(master, x, y):
            nonlocal target
            if master.isTarget():
                target = (x, y)
            for i in range(4):
                nx, ny = x + dirs[i], y + dirs[i + 1]
                if (nx, ny) in grid:
                    continue
                if master.canMove(DIR_CHAR[i]):
                    cost = master.move(DIR_CHAR[i])
                    grid[(nx, ny)] = cost
                    dfs(master, nx, ny)
                    master.move(OPPOSITE_DIR_CHAR[i])

        def bfs():
            q = deque([(0, 0)])
            grid[(0, 0)] = 0
            while q:
                x, y = q.popleft()
                for i in range(4):
                    nx, ny = x + dirs[i], y + dirs[i + 1]
                    cost = grid[(x, y)] + grid.get((nx, ny), 0)
                    if (nx, ny) in grid and grid[(nx, ny)] > cost:
                        grid[(nx, ny)] = cost
                        if (nx, ny) != target:
                            q.append((nx, ny))
            return grid.get(target, -1)

        dirs = [-1, 0, 1, 0, -1]
        DIR_CHAR = "URDL"
        OPPOSITE_DIR_CHAR = "DLUR"
        grid = {}
        target = None

        dfs(master, 0, 0)
        if target is None:
            return -1

        return bfs()

javascript_code:
class Solution {
    dirs = [-1, 0, 1, 0, -1];
    dirChar = ['U', 'R', 'D', 'L'];
    oppositeDirChar = ['D', 'L', 'U', 'R'];
    grid = new Map();
    target = [Infinity, Infinity];

    findShortestPath(master) {
        this.dfs(master, 0, 0);
        if (this.target[0] === Infinity) {
            return -1;
        }
        return this.bfs();
    }

    cellKey(x, y) {
        return `${x},${y}`;
    }

    dfs(master, x, y) {
        if (master.isTarget()){
            this.target = [x, y];
        }
        for (let i = 0; i < 4; i++) {
            let nx = x + this.dirs[i], ny = y + this.dirs[i + 1];
            let newPos = this.cellKey(nx, ny);
            if (this.grid.has(newPos)) continue;
            if (master.canMove(this.dirChar[i])) {
                let cost = master.move(this.dirChar[i]);
                this.grid.set(newPos, cost);
                this.dfs(master, nx, ny);
                master.move(this.oppositeDirChar[i]);
            }
        }
    }

    bfs() {
        let q = [[0, 0]];
        this.grid.set(this.cellKey(0, 0), 0);
        while (q.length > 0) {
            let pos = q.shift();
            let x = pos[0], y = pos[1];
            for (let i = 0; i < 4; i++) {
                let nx = x + this.dirs[i], ny = y + this.dirs[i + 1];
                let newPos = this.cellKey(nx, ny), oldPos = this.cellKey(x, y);
                let cost = this.grid.get(oldPos) + (this.grid.get(newPos) || 0);
                if (this.grid.has(newPos) && this.grid.get(newPos) > cost) {
                    this.grid.set(newPos, cost);
                    if (nx !== this.target[0] || ny !== this.target[1]) {
                        q.push([nx, ny]);
                    }
                }
            }
        }
        return this.grid.get(this.cellKey(this.target[0], this.target[1])) || -1;
    }
}

java_code:
public String reformatNumber(String number) {
    String cleanedNumber = "";
    for (char c : number.toCharArray()) {
        if (Character.isDigit(c)) {
            cleanedNumber += c;
        }
    }

    List<String> blocks = new ArrayList<>();
    int n = cleanedNumber.length();
    for (int i = 0; i < n;) {
        if (n - i == 2 || n - i == 4) {
            blocks.add(cleanedNumber.substring(i, i + 2));
            i += 2;
        } else {
            blocks.add(cleanedNumber.substring(i, i + 3));
            i += 3;
        }
    }

    String formattedNumber = blocks.get(0);
    for (int i = 1; i < blocks.size(); i++) {
        formattedNumber += '-' + blocks.get(i);
    }
    return formattedNumber;
}

