import java.util.*;

class Solution {
    public boolean[] distanceLimitedPathsExist(int n, int[][] edgeList, int[][] queries) {
        int[] queryIDs = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            queryIDs[i] = i;
        }
        Arrays.sort(queryIDs, (i, j) -> Integer.compare(queries[i][2], queries[j][2]));
        Arrays.sort(edgeList, (a, b) -> Integer.compare(a[2], b[2]));

        int[] parent = new int[n];
        for (int i = 0; i < n; i++) {
            parent[i] = i;
        }

        boolean[] res = new boolean[queries.length];
        int idx = 0;
        for (int queryID : queryIDs) {
            int[] query = queries[queryID];
            int p = query[0], q = query[1], limit = query[2];

            while (idx < edgeList.length && edgeList[idx][2] < limit) {
                int u = edgeList[idx][0], v = edgeList[idx][1];
                int ru = find(u, parent), rv = find(v, parent);
                if (ru != rv) {
                    parent[ru] = rv;
                }
                idx++;
            }
            res[queryID] = find(p, parent) == find(q, parent);
        }
        return res;
    }

    private int find(int x, int[] parent) {
        if (x != parent[x]) {
            parent[x] = find(parent[x], parent);
        }
        return parent[x];
    }
}

cpp_code:
#include <vector>
#include <queue>
using namespace std;

vector<bool> distanceLimitedPathsExist(int n, vector<vector<int>>& edgeList, vector<vector<int>>& queries) {
    for (int i = 0; i < queries.size(); ++i) {
        queries[i].push_back(i);
    }
    sort(queries.begin(), queries.end(), [](const vector<int> &a, const vector<int> &b) {
        return a[2] < b[2];
    });
    sort(edgeList.begin(), edgeList.end(), [](const vector<int> &a, const vector<int> &b) {
        return a[2] < b[2];
    });

    vector<int> parent(n);
    for (int i = 0; i < n; ++i) {
        parent[i] = i;
    }

    function<int(int)> find = [&](int x) {
        return x == parent[x] ? x : parent[x] = find(parent[x]);
    };

    vector<bool> res(queries.size());
    int idx = 0;
    for (const auto &query : queries) {
        int p = query[0], q = query[1], limit = query[2], id = query[3];
        while (idx < edgeList.size() && edgeList[idx][2] < limit) {
            int u = edgeList[idx][0], v = edgeList[idx][1];
            int ru = find(u), rv = find(v);
            if (ru != rv) {
                parent[ru] = rv;
            }
            idx++;
        }
        res[id] = find(p) == find(q);
    }
    return res;
}

javascript_code:
function distanceLimitedPathsExist(n, edgeList, queries) {
    edgeList.sort((a, b) => a[2] - b[2]);
    queries = queries.map((query, idx) => [...query, idx]).sort((a, b) => a[2] - b[2]);

    function find(x, parent) {
        if (x !== parent[x]) {
            parent[x] = find(parent[x], parent);
        }
        return parent[x];
    }

    const parent = Array.from({ length: n }, (_, idx) => idx);
    const res = new Array(queries.length).fill(false);
    let idx = 0;

    for (const query of queries) {
        const [p, q, limit, queryId] = query;
        while (idx < edgeList.length && edgeList[idx][2] < limit) {
            const [u, v] = edgeList[idx];
            const [ru, rv] = [find(u, parent), find(v, parent)];
            if (ru !== rv) {
                parent[ru] = rv;
            }
            idx++;
        }
        res[queryId] = find(p, parent) === find(q, parent);
    }

    return res;
}

