class Solution {
    public String truncateSentence(String s, int k) {
        String[] words = s.split(" ");
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < k; ++i) {
            sb.append(words[i]).append(" ");
        }
        return sb.toString().trim();
    }
}

