#include <string>
#include <sstream>
using namespace std;

string truncateSentence(string s, int k) {
    istringstream is(s);
    string result, tmp;
    while (k--) {
        is >> tmp;
        result += tmp + " ";
    }
    result.pop_back();
    return result;
}

