    int ans = 0;

    for (int i = 0; i < n || !pq.empty(); ++i) {
        if (i < n && apples[i] > 0) {
            pq.push({i + days[i], apples[i]});
        }

        while (!pq.empty() && pq.top().first <= i) {
            pq.pop();
        }

        if (!pq.empty()) {
            ans++;
            auto curr_apple = pq.top();
            pq.pop();
            if (curr_apple.second > 1) {
                curr_apple.second--;
                pq.push(curr_apple);
            }
        }
    }

    return ans;
}

