from bisect import bisect_left

def min_operations(target, arr):
    index_map = {num: i for i, num in enumerate(target)}

    lis = []
    for num in arr:
        if num in index_map:
            pos = bisect_left(lis, index_map[num])
            if pos == len(lis):
                lis.append(index_map[num])
            else:
                lis[pos] = index_map[num]

    return len(target) - len(lis)

javascript_code:
function minOperations(target, arr) {
    const indexMap = new Map();

    for (let i = 0; i < target.length; ++i) {
        indexMap.set(target[i], i);
    }

    const lis = [];
    for (const num of arr) {
        if (indexMap.has(num)) {
            const pos = lowerBound(lis, indexMap.get(num));
            if (pos === lis.length) {
                lis.push(indexMap.get(num));
            } else {
                lis[pos] = indexMap.get(num);
            }
        }
    }

    return target.length - lis.length;
}

function lowerBound(arr, target) {
    let low = 0;
    let high = arr.length;

    while (low < high) {
        const mid = Math.floor((low + high) / 2);
        if (arr[mid] < target) {
            low = mid + 1;
        } else {
            high = mid;
        }
    }

    return low;
}

