using namespace std;

const int MOD = 1e9 + 7;

vector<int> productWays(vector<vector<int>>& queries) {
    vector<int> res;
    for (auto& q : queries) {
        int n = q[0], k = q[1];

        vector<int> pf;
        map<int, int> pm;
        for (int i = 2; i * i <= k; ++i) {
            int cnt = 0;
            while (k % i == 0) {
                cnt++;
                k /= i;
            }
            if (cnt) {
                pf.push_back(cnt);
                pm[cnt]++;
            }
        }

        if (k > 1) {
            pm[k]++;
            pf.push_back(1);
        }

        long long ans = 1;
        for (int p : pf) {
            ans = (ans * (p * (n - 1) + 1)) % MOD;
        }

        res.push_back(ans);
    }
    return res;
}

javascript_code:
const MOD = 1e9 + 7;

function productWays(queries) {
    const res = [];
    for (const [n, k] of queries) {
        const pf = [];
        const pm = {};

        for (let i = 2; i * i <= k; i++) {
            let cnt = 0;
            let kMutable = k;
            while (kMutable % i === 0) {
                cnt++;
                kMutable /= i;
            }
            if (cnt !== 0) {
                pf.push(cnt);
                if (!pm[cnt]) pm[cnt] = 0;
                pm[cnt]++;
            }
        }

        if (k > 1) {
            if (!pm[k]) pm[k] = 0;
            pm[k]++;
            pf.push(1);
        }

        let ans = 1;
        for (const p of pf) {
            ans = (ans * (p * (n - 1) + 1)) % MOD;
        }

        res.push(ans);
    }
    return res;
}

