from collections import defaultdict

def dfs(node, visited, graph, group):
    if visited[node]:
        return
    visited[node] = 1
    group.append(node)
    for neighbor in graph[node]:
        dfs(neighbor, visited, graph, group)

def minimumHammingDistance(source, target, allowedSwaps):
    n = len(source)
    graph = defaultdict(list)
    for a, b in allowedSwaps:
        graph[a].append(b)
        graph[b].append(a)

    res = 0
    visited = [0] * n
    for i in range(n):
        if not visited[i]:
            group = []
            dfs(i, visited, graph, group)
            count = defaultdict(int)

            for node in group:
                count[source[node]] += 1
            for node in group:
                if count[target[node]] > 0:
                    res += 1
                    count[target[node]] -= 1

    return n - res

javascript_code:
function minimumHammingDistance(source, target, allowedSwaps) {
    const n = source.length;
    const graph = new Map();

    for (const [a, b] of allowedSwaps) {
        if (!graph.has(a)) graph.set(a, []);
        if (!graph.has(b)) graph.set(b, []);
        graph.get(a).push(b);
        graph.get(b).push(a);
    }

    function dfs(node, visited, group) {
        if (visited[node]) return;
        visited[node] = 1;
        group.push(node);
        for (const neighbor of (graph.get(node) || [])) dfs(neighbor, visited, group);
    }

    let res = 0;
    const visited = new Array(n).fill(0);
    for (let i = 0; i < n; ++i) {
        if (!visited[i]) {
            const group = [];
            dfs(i, visited, group);
            const count = new Map();

            for (const node of group) count.set(source[node], (count.get(source[node]) || 0) + 1);
            for (const node of group) {
                if (count.get(target[node]) > 0) {
                    res++;
                    count.set(target[node], count.get(target[node]) - 1);
                }
            }
        }
    }

    return n - res;
}

java_code:
import java.util.Arrays;

public class Solution {
    public String nextPalindrome(String num) {
        int n = num.length();
        char[] firstHalf = num.substring(0, (n + 1) / 2).toCharArray();
        if (!nextPermutation(firstHalf)) return "";

        String secondHalf = new StringBuilder(String.valueOf(firstHalf)).reverse().toString();
        if (n % 2 == 1) secondHalf = secondHalf.substring(1);
        return String.valueOf(firstHalf) + secondHalf;
    }

    private boolean nextPermutation(char[] array) {
        int n = array.length;
        int k = n - 2;
        while (k >= 0 && array[k] >= array[k + 1]) k--;

        if (k == -1) return false;

        int l = n - 1;
        while (array[l] <= array[k]) l--;

        char temp = array[k];
        array[k] = array[l];
        array[l] = temp;

        int left = k + 1, right = n - 1;
        while (left < right) {
            temp = array[left];
            array[left++] = array[right];
            array[right--] = temp;
        }

        return true;
    }
}

