string nextPalindrome(string num) {
    int n = num.size();
    string firstHalf = num.substr(0, (n + 1) / 2);
    next_permutation(firstHalf.begin(), firstHalf.end());

    if (firstHalf > num.substr(0, (n + 1) / 2)) {
        string secondHalf = firstHalf;
        reverse(secondHalf.begin(), secondHalf.end());
        if (n % 2 == 1) secondHalf = secondHalf.substr(1);
        return firstHalf + secondHalf;
    }

    return "";
}

javascript_code:
function nextPermutation(array) {
    let n = array.length;
    let k = n - 2;
    while (k >= 0 && array[k] >= array[k + 1]) k--;

    if (k === -1) return false;

    let l = n - 1;
    while (array[l] <= array[k]) l--;

    [array[k], array[l]] = [array[l], array[k]];

    let left = k + 1, right = n - 1;
    while (left < right) {
        [array[left], array[right]] = [array[right], array[left]];
        left++;
        right--;
    }

    return true;
}

function nextPalindrome(num) {
    let n = num.length;
    let firstHalf = num.slice(0, (n + 1) / 2).split('');
    if (!nextPermutation(firstHalf)) return "";

    let secondHalf = firstHalf.slice().reverse();
    if (n % 2 === 1) secondHalf.shift();
    return firstHalf.join('') + secondHalf.join('');
}

