    std::vector<int> boxCounts(46, 0);
    for(int i = lowLimit; i <= highLimit; i++) {
        int boxNumber = 0;
        int num = i;
        while(num) {
            boxNumber += num % 10;
            num /= 10;
        }
        boxCounts[boxNumber]++;
    }
    return *std::max_element(boxCounts.begin(), boxCounts.end());
}

