import java.util.*;

class Solution {
    public int[] closestRoom(int[][] rooms, int[][] queries) {
        Arrays.sort(rooms, (a, b) -> b[1] - a[1]);
        int[] result = new int[queries.length];

        for (int i = 0; i < queries.length; ++i) {
            int[] q = new int[]{queries[i][0], queries[i][1], i};
            queries[i] = q;
        }

        Arrays.sort(queries, (a, b) -> b[1] - a[1]);

        TreeSet<Integer> ids = new TreeSet<>();
        int j = 0;
        for (int[] q : queries) {
            while (j < rooms.length && rooms[j][1] >= q[1]) {
                ids.add(rooms[j++][0]);
            }
            if (ids.isEmpty()) {
                result[q[2]] = -1;
            } else {
                Integer cid1 = ids.ceiling(q[0]);
                Integer cid2 = ids.floor(q[0]);
                if (cid1 == null) {
                    result[q[2]] = cid2;
                } else if (cid2 == null) {
                    result[q[2]] = cid1;
                } else {
                    result[q[2]] = (q[0] - cid2 <= cid1 - q[0]) ? cid2 : cid1;
                }
            }
        }

        return result;
    }
}

cpp_code:
#include <vector>
#include <set>
#include <limits>
using namespace std;

vector<int> closestRoom(vector<vector<int>>& rooms, vector<vector<int>>& queries) {
    sort(rooms.begin(), rooms.end(), [](const vector<int>& a, const vector<int>& b) {
        return a[1] > b[1];
    });

    vector<int> result(queries.size());
    for (int i = 0; i < queries.size(); ++i) {
        queries[i].push_back(i);
    }

    sort(queries.begin(), queries.end(), [](const vector<int>& a, const vector<int>& b) {
        return a[1] > b[1];
    });

    set<int> ids;
    int j = 0;
    for (const auto& q : queries) {
        while (j < rooms.size() && rooms[j][1] >= q[1]) {
            ids.insert(rooms[j++][0]);
        }
        if (ids.empty()) {
            result[q[2]] = -1;
        } else {
            int closestDiff = numeric_limits<int>::max();
            int closestId = -1;
            for (int id : {q[0], *ids.upper_bound(q[0]), *prev(ids.upper_bound(q[0]))}) {
                if (ids.count(id)) {
                    int diff = abs(id - q[0]);
                    if (diff < closestDiff) {
                        closestDiff = diff;
                        closestId = id;
                    }
                }
            }
            result[q[2]] = closestId;
        }
    }

    return result;
}

