#include <algorithm>
#include <set>

int minAbsDifference(std::vector<int>& nums, int goal) {
    int n = nums.size();
    std::vector<int> left(nums.begin(), nums.begin() + n / 2);
    std::vector<int> right(nums.begin() + n / 2, nums.end());
    std::set<int> sums;

    for (int mask = 0; mask < (1 << left.size()); ++mask) {
        int sum = 0;
        for (int i = 0; i < left.size(); ++i) {
            if (mask & (1 << i)) {
                sum += left[i];
            }
        }
        sums.insert(sum);
    }

    int ans = std::abs(goal);

    for (int mask = 0; mask < (1 << right.size()); ++mask) {
        int sum = 0;
        for (int i = 0; i < right.size(); ++i) {
            if (mask & (1 << i)) {
                sum += right[i];
            }
        }
        auto it = sums.lower_bound(goal - sum);
        if (it != sums.end()) {
            ans = std::min(ans, std::abs((*it) + sum - goal));
        }
        if (it != sums.begin()) {
            ans = std::min(ans, std::abs((*std::prev(it)) + sum - goal));
        }
    }

    return ans;
}

javascript_code:
function minAbsDifference(nums, goal) {
    const n = nums.length;
    const left = nums.slice(0, n / 2);
    const right = nums.slice(n / 2);
    const sums = new Set();

    for (let mask = 0; mask < (1 << left.length); ++mask) {
        let sum = 0;
        for (let i = 0; i < left.length; ++i) {
            if (mask & (1 << i)) {
                sum += left[i];
            }
        }
        sums.add(sum);
    }

    let ans = Math.abs(goal);

    for (let mask = 0; mask < (1 << right.length); ++mask) {
        let sum = 0;
        for (let i = 0; i < right.length; ++i) {
            if (mask & (1 << i)) {
                sum += right[i];
            }
        }
        const target = goal - sum;
        const candidate = [...sums].reduce((a, b) => Math.abs(b - target) < Math.abs(a - target) ? b : a);

        ans = Math.min(ans, Math.abs(candidate + sum - goal));
    }

    return ans;
}

