            double t = dist[i] / double(speed) + (j != -1);
            dp[i + 1][j + 1] = min(dp[i + 1][j + 1], dp[i][j] + t);
            double skipped_t = ceil(dp[i][j] + dist[i] / double(speed)) - dp[i][j];
            dp[i + 1][j] = min(dp[i + 1][j], dp[i][j] + skipped_t);
        }
    }

    for (int i = 0; i <= n; ++i) {
        if (dp[n][i] <= hoursBefore) return i;
    }
    return -1;
}

