int minimumSize(std::vector<int>& nums, int maxOperations) {
    std::priority_queue<int> pq(nums.begin(), nums.end());
    while (maxOperations > 0) {
        int maxBalls = pq.top();
        pq.pop();
        pq.push(maxBalls / 2);
        pq.push(maxBalls - (maxBalls / 2));
        maxOperations--;
    }
    return pq.top();
}

