public int countMatches(List<List<String>> items, String ruleKey, String ruleValue) {
    Map<String, Integer> rule = new HashMap<>();
    rule.put("type", 0);
    rule.put("color", 1);
    rule.put("name", 2);
    int count = 0;

    for (List<String> item : items) {
        if (item.get(rule.get(ruleKey)).equals(ruleValue)) {
            count++;
        }
    }

    return count;
}

