class AuthenticationManager {
    constructor(timeToLive) {
        this.timeToLive = timeToLive;
        this.tokens = new Map();
    }

    generate(tokenId, currentTime) {
        this.tokens.set(tokenId, currentTime + this.timeToLive);
    }

    renew(tokenId, currentTime) {
        if (this.tokens.has(tokenId) && this.tokens.get(tokenId) > currentTime) {
            this.tokens.set(tokenId, currentTime + this.timeToLive);
        }
    }

    countUnexpiredTokens(currentTime) {
        let count = 0;
        for (const expirationTime of this.tokens.values()) {
            if (expirationTime > currentTime) count++;
        }
        return count;
    }
}

java_code:
public int maxScore(int[] nums) {
    int n = nums.length;
    int[][] dp = new int[n + 1][n * 2 + 1];

    for (int i = 0; i <= n; i++) {
        Arrays.fill(dp[i], -1);
    }

    return dfs(1, 0, n, nums, dp);
}

private int gcd(int x, int y) {
    if (y == 0) return x;
    return gcd(y, x % y);
}

private int dfs(int i, int j, int n, int[] nums, int[][] dp) {
    if (i > n) return 0;
    if (dp[i][j] != -1) return dp[i][j];
    int ans = 0;
    for (int k = j + 1; k < n * 2; k++) {
        ans = Math.max(ans, dfs(i + 1, k, n, nums, dp) + i * gcd(nums[j], nums[k]));
    }
    return dp[i][j] = ans;
}

