#include <vector>
#include <queue>
#include <utility>

using namespace std;

const int mod = 1e9 + 7;

int countRestrictedPaths(int n, vector<vector<int>>& edges) {
    vector<vector<pair<int, int>>> graph(n + 1);
    vector<long long> dist(n + 1, 1e18);

    for (auto& edge : edges) {
        int u = edge[0], v = edge[1], weight = edge[2];
        graph[u].push_back({v, weight});
        graph[v].push_back({u, weight});
    }

    priority_queue<pair<long long, int>> pq;
    pq.push({0, n});
    dist[n] = 0;

    while (!pq.empty()) {
        int u = pq.top().second;
        long long d = -pq.top().first;
        pq.pop();

        if (d != dist[u]) continue;

        for (auto& to : graph[u]) {
            int v = to.first, w = to.second;
            if (dist[u] + w < dist[v]) {
                dist[v] = dist[u] + w;
                pq.push({-dist[v], v});
            }
        }
    }

    vector<int> dp(n + 1, -1);
    function<int(int)> dfs = [&](int u) {
        if (u == n) return 1;
        if (dp[u] != -1) return dp[u];
        int ans = 0;
        for (auto& to : graph[u]) {
            int v = to.first;
            if (dist[v] < dist[u]) {
                ans = (ans + dfs(v)) % mod;
            }
        }
        return dp[u] = ans;
    };

    return dfs(1);
}

