    std::vector<int> min_dp(k, n);

    for (int i = 1; i <= n; ++i) {
        int x = xor_prefix[i] ^ xor_prefix[i - k];

        if (i >= k) {
            dp[0][x]++;
        }

        for (int j = 1; i - j * k >= 0; ++j) {
            dp[j][x]++;
            min_dp[j] = std::min(min_dp[j], dp[j-1][x] - dp[j][x]);
        }
    }

    int answer = n;
    for (int j = 0; j < k; ++j) {
        answer = std::min(answer, min_dp[j] + j);
    }
    return answer;
}

