    int n = grid[0].size(); // number of columns
    int numLayers = std::min(m, n) / 2;

    for (int layer = 0; layer < numLayers; ++layer) {
        int numToRotate = (m - 2 * layer) * 2 + (n - 2 * layer - 2) * 2; // number of elements in the outer ring
        int effective_k = k % numToRotate; // effective number of rotations

        while (effective_k--) {
            int temp = grid[layer][layer];
            for (int i = layer + 1; i < m - layer; ++i) std::swap(temp, grid[i][layer]);
            for (int j = layer + 1; j < n - layer; ++j) std::swap(temp, grid[m - layer - 1][j]);
            for (int i = m - layer - 2; i >= layer; --i) std::swap(temp, grid[i][n - layer - 1]);
            for (int j = n - layer - 2; j > layer; --j) std::swap(temp, grid[layer][j]);
        }
    }

    return grid;
}

javascript_code:
function rotateGrid(grid, k) {
    if (!grid || grid.length === 0) return grid;

    let m = grid.length; // number of rows
    let n = grid[0].length; // number of columns
    let numLayers = Math.min(m, n) / 2;

    for (let layer = 0; layer < numLayers; ++layer) {
        let numToRotate = (m - 2 * layer) * 2 + (n - 2 * layer - 2) * 2; // number of elements in the outer ring
        let effective_k = k % numToRotate; // effective number of rotations

        while (effective_k--) {
            let temp = grid[layer][layer];
            for (let i = layer + 1; i < m - layer; ++i) [temp, grid[i][layer]] = [grid[i][layer], temp];
            for (let j = layer + 1; j < n - layer; ++j) [temp, grid[m - layer - 1][j]] = [grid[m - layer - 1][j], temp];
            for (let i = m - layer - 2; i >= layer; --i) [temp, grid[i][n - layer - 1]] = [grid[i][n - layer - 1], temp];
            for (let j = n - layer - 2; j > layer; --j) [temp, grid[layer][j]] = [grid[layer][j], temp];
        }
    }

    return grid;
}

java_code:
public boolean areAlmostEqual(String s1, String s2) {
    int diffCount = 0;
    int firstDiff = -1;
    int secondDiff = -1;
    for (int i = 0; i < s1.length(); i++) {
        if (s1.charAt(i) != s2.charAt(i)) {
            diffCount++;
            if (diffCount == 1)
                firstDiff = i;
            else if (diffCount == 2)
                secondDiff = i;
            else
                return false;
        }
    }
    return diffCount == 0 || (diffCount == 2 && s1.charAt(firstDiff) == s2.charAt(secondDiff) && s1.charAt(secondDiff) == s2.charAt(firstDiff));
}

