public int maxScore(int[] nums, int k) {
    int n = nums.length;
    int result = 0;
    for (int i = k; i >= 0; i--) {
        for (int j = k; j < n; j++) {
            int minVal = nums[i];
            for (int x = i; x <= j; x++)
                minVal = Math.min(minVal, nums[x]);
            result = Math.max(result, minVal * (j - i + 1));
        }
    }
    return result;
}

