        time_to_reach_city[i] = (dist[i] + speed[i] - 1) / speed[i];
    }
    sort(time_to_reach_city.begin(), time_to_reach_city.end());
    int eliminated = 0;
    for (int i = 0; i < n && time_to_reach_city[i] > i; i++) {
