        eliminated++;
    }
    return eliminated;
}

java_code:
public long goodDigitStrings(int n) {
    final int mod = 1000000007;
    long evenCount = 1, primeCount = 1;
    for (int i = 0; i < n; ++i) {
        if (i % 2 == 0) evenCount = (evenCount * 5) % mod;
        else primeCount = (primeCount * 4) % mod;
    }
    return (evenCount * primeCount) % mod;
}

