        words1[0] === words2[0]
    ) {
        words1.shift();
        words2.shift();
    }

    while (
        words1.length && words2.length &&
        words1[words1.length - 1] === words2[words2.length - 1]
    ) {
        words1.pop();
        words2.pop();
    }

    return !words1.length || !words2.length;
}

java_code:
public int maxHappyGroups(int batchSize, int[] groups) {
    int[] remainders = new int[batchSize];
    for (int g : groups) {
        remainders[g % batchSize]++;
    }

    int result = remainders[0];
    int i = 1, j = batchSize - 1;

    while (i < j) {
        result += Math.min(remainders[i], remainders[j]);
        i++;
        j--;
    }
    if (i == j) {
        result += remainders[i] / 2;
    }

    return result;
}

