    for (let g of groups) {
        remainders[g % batchSize]++;
    }

    let result = remainders[0];
    let i = 1, j = batchSize - 1;

    while (i < j) {
        result += Math.min(remainders[i], remainders[j]);
        i++;
        j--;
    }
    if (i === j) {
        result += Math.floor(remainders[i] / 2);
    }

    return result;
}

