public int maxAscendingSum(int[] nums) {
    int maxSum = 0, currentSum = nums[0];

    for (int i = 1; i < nums.length; ++i) {
        if (nums[i] > nums[i - 1]) {
            currentSum += nums[i];
        } else {
            maxSum = Math.max(maxSum, currentSum);
            currentSum = nums[i];
        }
    }

    return Math.max(maxSum, currentSum);
}

