#include <queue>
#include <vector>

int getNumberOfBacklogOrders(std::vector<std::vector<int>>& orders) {
    auto cmpSell = [](std::vector<int>& a, std::vector<int>& b) {
        return a[0] > b[0];
    };
    auto cmpBuy = [](std::vector<int>& a, std.stringvector<int>&b) {
        return a[0] < b[0];
    };

    std::priority_queue<std::vector<int>, std::vector<std::vector<int>>, decltype(cmpSell)> sell(cmpSell);
    std::priority_queue<std::vector<int>, std::vector<std::vector<int>>, decltype(cmpBuy)> buy(cmpBuy);

    for (auto& order : orders) {
        if (order[2] == 0) {
            while (!sell.empty() && order[1] > 0 && sell.top()[0] <= order[0]) {
                std::vector<int>& currOrder = sell.top();
                int executedAmount = std::min(order[1], currOrder[1]);
                order[1] -= executedAmount;
                currOrder[1] -= executedAmount;
                if (currOrder[1] == 0) {
                    sell.pop();
                }
            }
            if (order[1] > 0) {
                buy.push(order);
            }
        } else {
            while (!buy.empty() && order[1] > 0 && buy.top()[0] >= order[0]) {
                std::vector<int>& currOrder = buy.top();
                int executedAmount = std::min(order[1], currOrder[1]);
                order[1] -= executedAmount;
                currOrder[1] -= executedAmount;
                if (currOrder[1] == 0) {
                    buy.pop();
                }
            }
            if (order[1] > 0) {
                sell.push(order);
            }
        }
    }

    int64_t res = 0;
    while (!buy.empty()) {
        res += buy.top()[1];
        buy.pop();
    }
    while (!sell.empty()) {
        res += sell.top()[1];
        sell.pop();
    }

    res %= 1000000007;
    return static_cast<int>(res);
}

python_code:
from heapq import heappush, heappop

def getNumberOfBacklogOrders(orders):
    buy, sell = [], []

    for price, amount, orderType in orders:
        if orderType == 0:
            while amount > 0 and sell and -sell[0][0] <= price:
                executedAmount = min(amount, sell[0][1])
                amount -= executedAmount
                sell[0] = [-sell[0][0], sell[0][1] - executedAmount]
                if sell[0][1] == 0:
                    heappop(sell)
            if amount:
                heappush(buy, [-price, amount])
        else:
            while amount > 0 and buy and buy[0][0] >= price:
                executedAmount = min(amount, buy[0][1])
                amount -= executedAmount
                buy[0] = [buy[0][0], buy[0][1] - executedAmount]
                if buy[0][1] == 0:
                    heappop(buy)
            if amount:
                heappush(sell, [-price, amount])

    res = sum(item[1] for item in buy) + sum(item[1] for item in sell)
    return res % 1000000007

