import java.util.Arrays;

public int maxConsecutiveValues(int[] coins) {
    Arrays.sort(coins);
    int maxValue = 0;
    for (int coin : coins) {
        if (coin <= maxValue + 1) {
            maxValue += coin;
        } else {
            break;
        }
    }
    return maxValue + 1;
}

