struct TreeNode {
    int val;
    TreeNode* left;
    TreeNode* right;
    TreeNode(int x) : val(x), left(NULL), right(NULL) {}
};

TreeNode* canMerge(vector<TreeNode*>& trees) {
    unordered_map<int, int> leafCount;
    unordered_map<int, TreeNode*> rootMap;
    for (TreeNode* tree : trees) {
        if (tree->left) {
            leafCount[tree->left->val]++;
        }
        if (tree->right) {
            leafCount[tree->right->val]++;
        }
        rootMap[tree->val] = tree;
    }

    function<bool(TreeNode*, int, int)> isValidBST = [&](TreeNode* node, int minVal, int maxVal) {
        if (!node) {
            return true;
        }
        if (node->val <= minVal || node->val >= maxVal) {
            return false;
        }
        return isValidBST(node->left, minVal, node->val) && isValidBST(node->right, node->val, maxVal);
    };

    for (TreeNode* tree : trees) {
        if (leafCount[tree->val] == 0) {
            if (isValidBST(tree, 0, 5e4 + 1)) {
                return tree;
            }
            break;
        }
    }
    return NULL;
}

