function canMerge(trees) {
    const leafCount = new Map();
    const rootMap = new Map();

    for (const tree of trees) {
        if (tree.left) {
            leafCount.set(tree.left.val, (leafCount.get(tree.left.val) || 0) + 1);
        }
        if (tree.right) {
            leafCount.set(tree.right.val, (leafCount.get(tree.right.val) || 0) + 1);
        }
        rootMap.set(tree.val, tree);
    }

    function isValidBST(node, minVal, maxVal) {
        if (!node) {
            return true;
        }
        if (node.val <= minVal || node.val >= maxVal) {
            return false;
        }
        if (node.left && rootMap.has(node.left.val)) {
            const leftChild = rootMap.get(node.left.val);
            leafCount.set(node.left.val, leafCount.get(node.left.val) - 1);
            rootMap.delete(node.left.val);
            node.left = leftChild;
        }
        if (node.right && rootMap.has(node.right.val)) {
            const rightChild = rootMap.get(node.right.val);
            leafCount.set(node.right.val, leafCount.get(node.right.val) - 1);
            rootMap.delete(node.right.val);
            node.right = rightChild;
        }
        return isValidBST(node.left, minVal, node.val) && isValidBST(node.right, node.val, maxVal);
    }

    for (const tree of trees) {
        if ((leafCount.get(tree.val) || 0) === 0) {
            if (isValidBST(tree, 0, 5e4 + 1)) {
                return tree;
            }
            break;
        }
    }

    return null;
}

java_code:
import java.util.HashSet;
import java.util.Set;

public int numDifferentIntegers(String word) {
    for (int i = 0; i < word.length(); i++) {
        if (!Character.isDigit(word.charAt(i))) {
            word = word.substring(0, i) + " " + word.substring(i + 1);
        }
    }
    String[] nums = word.split("\\s+");
    Set<String> uniqueNums = new HashSet<>();
    for (String num : nums) {
        num = num.replaceFirst("^0+(?!$)", "");
        uniqueNums.add(num);
    }
    return uniqueNums.size();
}

cpp_code:
#include <string>
#include <unordered_set>

int numDifferentIntegers(std::string word) {
    for (char &c : word) {
        if (c < '0' || c > '9') {
            c = ' ';
        }
    }
    std::istringstream iss(word);
    std::string num;
    std::unordered_set<std::string> uniqueNums;
    while (iss >> num) {
        num.erase(0, num.find_first_not_of('0'));
        uniqueNums.insert(num);
    }
    return uniqueNums.size();
}

