        for (int c1 = 0; c1 < n; ++c1) {
            long score = dp[c1] + row[c1] - c1;
            for (int c2 = 0; c2 < n; ++c2) {
                next_dp[c2] = max(next_dp[c2], score - row[c1] + c2);
            }
        }
        dp.swap(next_dp);
    }
    return *max_element(dp.begin(), dp.end());
}

