def make_string_sorted(s):
    mod = 1000000007
    n = len(s)
    fact = [1] * (n + 1)
    inv = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = fact[i - 1] * i % mod
        inv[i] = inv[i - 1] * (mod - mod // i) % mod

    ans = 0
    for i in range(n):
        less_than = 0
        for j in range(i + 1, n):
            if s[j] < s[i]:
                less_than += 1
        ans = (ans + less_than * fact[n - i - 1]) % mod
    return ans

javascript_code:
function makeStringSorted(s) {
    const mod = 1e9 + 7;
    const n = s.length;
    const fact = new Array(n + 1).fill(1);
    const inv = new Array(n + 1).fill(1);

    for (let i = 1; i <= n; ++i) {
        fact[i] = BigInt(fact[i - 1] * i % mod);
        inv[i] = BigInt(inv[i - 1] * (mod - Math.floor(mod / i)) % mod);
    }

    let ans = 0;
    for (let i = 0; i < n; ++i) {
        let less_than = 0;
        for (let j = i + 1; j < n; ++j) {
            if (s[j] < s[i]) ++less_than;
        }
        ans = Number((BigInt(ans) + BigInt(less_than) * fact[n - i - 1]) % BigInt(mod));
    }

    return ans;
}

