#include <vector>
#include <map>
using namespace std;

vector<vector<int>> splitPainting(vector<vector<int>>& segments) {
    map<int, int> line;
    for (const vector<int>& s : segments) {
        int start = s[0];
        int end = s[1];
        int color = s[2];
        line[start] += color;
        line[end] -= color;
    }
    vector<vector<int>> res;
    int pre = 0, sum = 0;
    for (auto it = line.begin(); it != line.end(); ++it) {
        if (pre > 0) {
            if (sum > 0) {
                res.push_back({pre, it->first, sum});
            }
        }
        pre = it->first;
        sum += it->second;
    }
    return res;
}

python_code:
def splitPainting(segments):
    line = {}
    for s in segments:
        start, end, color = s
        if start not in line:
            line[start] = 0
        if end not in line:
            line[end] = 0
        line[start] += color
        line[end] -= color
    res = []
    pre = 0
    sum = 0
    for key in sorted(line.keys()):
        if pre > 0:
            if sum > 0:
                res.append([pre, key, sum])
        pre = key
        sum += line[key]
    return res

