    for (const s of segments) {
        let start = s[0];
        let end = s[1];
        let color = s[2];
        line.set(start, (line.get(start) || 0) + color);
        line.set(end, (line.get(end) || 0) - color);
    }
    let res = [];
    let pre = 0, sum = 0;
    for (const [key, value] of Array.from(line.entries()).sort()) {
        if (pre > 0) {
            if (sum > 0) {
                res.push([pre, key, sum]);
            }
        }
        pre = key;
        sum += value;
    }
    return res;
}

