#include <string>
#include <sstream>
using namespace std;

string truncateSentence(string s, int k) {
    istringstream iss(s);
    string word, result;
    while (k > 0 && iss >> word) {
        result += word;
        k--;
        if (k > 0) result += " ";
    }
    return result;
}

