import java.util.Arrays;

public int minAbsoluteSumDiff(int[] nums1, int[] nums2) {
    int n = nums1.length;
    long total = 0;
    int maxDiff = 0;
    int mod = 1_000_000_007;
    int[] sortedNums1 = nums1.clone();
    Arrays.sort(sortedNums1);

    for (int i = 0; i < n; i++) {
        int diff = Math.abs(nums1[i] - nums2[i]);
        total += diff;

        int pos = Arrays.binarySearch(sortedNums1, nums2[i]);
        if (pos < 0) {
            pos = ~pos;
        }
        if (pos != n) {
            maxDiff = Math.max(maxDiff, diff - Math.abs(sortedNums1[pos] - nums2[i]));
        }
        if (pos != 0) {
            maxDiff = Math.max(maxDiff, diff - Math.abs(sortedNums1[pos - 1] - nums2[i]));
        }
    }
    return (int)((total - maxDiff + mod) % mod);
}

