    std::sort(sorted_nums1.begin(), sorted_nums1.end());

    for (int i = 0; i < n; ++i) {
        int diff = abs(nums1[i] - nums2[i]);
        total += diff;

        int pos = lower_bound(sorted_nums1.begin(), sorted_nums1.end(), nums2[i]) - sorted_nums1.begin();
        if (pos != n) {
            maxDiff = max(maxDiff, diff - abs(sorted_nums1[pos] - nums2[i]));
        }
        if (pos != 0) {
            maxDiff = max(maxDiff, diff - abs(sorted_nums1[pos - 1] - nums2[i]));
        }
    }
    return (total - maxDiff + mod) % mod;
}

