#include <set>
#include <queue>
#include <algorithm>

class MKAverage {
public:
    int m, k;
    long long sum = 0;
    multiset<int> minSet, midSet, maxSet;
    queue<int> q;

    MKAverage(int m, int k) : m(m), k(k) {}

    void addElement(int num) {
        if (q.size() == m) {
            removeElement();
        }

        minSet.insert(num);
        sum += num;

        if (minSet.size() > k) {
            int temp = *minSet.rbegin();
            minSet.erase(minSet.find(temp));
            midSet.insert(temp);
            sum += temp;
        }

        if (!midSet.empty() && *minSet.rbegin() > *midSet.begin()) {
            int temp1 = *minSet.rbegin();
            int temp2 = *midSet.begin();
            minSet.erase(minSet.find(temp1));
            midSet.erase(midSet.find(temp2));
            minSet.insert(temp2);
            midSet.insert(temp1);
            sum += temp2 - temp1;
        }

        maxSet.insert(*midSet.rbegin());
        sum -= *midSet.rbegin();
        midSet.erase(prev(midSet.end()));

        if (maxSet.size() > k) {
            int temp = *maxSet.begin();
            maxSet.erase(maxSet.find(temp));
            midSet.insert(temp);
            sum += temp;
        }

        q.push(num);
    }

    int calculateMKAverage() {
        if (q.size() < m) {
            return -1;
        }
        return sum / (m - 2 * k);
    }

    void removeElement() {
        int temp = q.front();
        q.pop();

        if (minSet.count(temp)) {
            minSet.erase(minSet.find(temp));
        } else if (midSet.count(temp)) {
            midSet.erase(midSet.find(temp));
            sum -= temp;
        } else {
            maxSet.erase(maxSet.find(temp));
        }
    }
};

javascript_code:
class MKAverage {
    constructor(m, k) {
        this.m = m;
        this.k = k;
        this.sum = 0;
        this.minSet = new Set();
        this.midSet = new Set();
        this.maxSet = new Set();
        this.q = [];
    }

    addElement(num) {
        if (this.q.length === this.m) {
            this.removeElement();
        }

        this.minSet.add(num);
        this.sum += num;

        if (this.minSet.size > this.k) {
            let temp = Math.max(...this.minSet);
            this.minSet.delete(temp);
            this.midSet.add(temp);
            this.sum += temp;
        }

        if (this.midSet.size && Math.max(...this.minSet) > Math.min(...this.midSet)) {
            let temp1 = Math.max(...this.minSet);
            let temp2 = Math.min(...this.midSet);
            this.minSet.delete(temp1);
            this.midSet.delete(temp2);
            this.minSet.add(temp2);
            this.midSet.add(temp1);
            this.sum += temp2 - temp1;
        }

        const maxVal = Math.max(...this.midSet);
        this.maxSet.add(maxVal);
        this.sum -= maxVal;
        this.midSet.delete(maxVal);

        if (this.maxSet.size > this.k) {
            let temp = Math.min(...this.maxSet);
            this.maxSet.delete(temp);
            this.midSet.add(temp);
            this.sum += temp;
        }

        this.q.push(num);
    }

    calculateMKAverage() {
        if (this.q.length < this.m) {
            return -1;
        }
        return Math.floor(this.sum / (this.m - 2 * this.k));
    }

    removeElement() {
        const temp = this.q.shift();

        if (this.minSet.has(temp)) {
            this.minSet.delete(temp);
        } else if (this.midSet.has(temp)) {
            this.midSet.delete(temp);
            this.sum -= temp;
        } else {
            this.maxSet.delete(temp);
        }
    }
}

