#include <vector>
#include <queue>
#include <algorithm>
using namespace std;

vector<int> getOrder(vector<vector<int>>& tasks) {
    vector<int> taskIndices(tasks.size());
    for (int i = 0; i < tasks.size(); i++) taskIndices[i] = i;

    sort(taskIndices.begin(), taskIndices.end(), [&](int a, int b) {
        return tasks[a][0] < tasks[b][0];
    });

    priority_queue<pair<int, int>, vector<pair<int, int>>, greater<>> minHeap;
    long long time = 0;
    int taskIdx = 0;
    vector<int> result;

    while (!taskIndices.empty()) {
        while (taskIdx < taskIndices.size() && tasks[taskIndices[taskIdx]][0] <= time) {
            int idx = taskIndices[taskIdx];
            minHeap.push({tasks[idx][1], idx});
            taskIdx++;
        }

        if (!minHeap.empty()) {
            auto [processingTime, index] = minHeap.top();
            minHeap.pop();
            time += processingTime;
            result.push_back(index);
            taskIndices.erase(remove(taskIndices.begin(), taskIndices.end(), index), taskIndices.end());
        } else if (taskIdx < taskIndices.size()) {
            time = max(time, (long long)tasks[taskIndices[taskIdx]][0]);
        }
    }

    return result;
}

