function minNonZeroProduct(p) {
    const mod = 1e9 + 7;
    const x = (1n << BigInt(p)) - 1n;
    const y = (1n << BigInt(p)) - 2n;
    const z = modPow(y, x - 1n, mod);
    return Number(x * z % BigInt(mod));
}

function modPow(x, y, mod) {
    let res = 1n;
    while (y) {
        if (y & 1n) res = res * x % BigInt(mod);
        x = x * x % BigInt(mod);
        y >>= 1n;
    }
    return res;
}

