import java.util.*;

public String sortSentence(String s) {
    String[] tokens = s.split(" ");
    String[] words = new String[tokens.length];

    for (String token : tokens) {
        int pos = Integer.parseInt(token.substring(token.length() - 1)) - 1;
        words[pos] = token.substring(0, token.length() - 1);
    }

    return String.join(" ", words);
}

cpp_code:
#include <sstream>
#include <vector>
#include <algorithm>

std::string sortSentence(const std::string& s) {
    std::istringstream iss(s);
    std::vector<std::pair<int, std::string>> words;
    std::string word;

    while (iss >> word) {
        int pos = word.back() - '0';
        word.pop_back();
        words.emplace_back(pos, word);
    }

    std::sort(words.begin(), words.end());

    std::string result;
    for (const auto& pair : words) {
        if (!result.empty()) {
            result += " ";
        }
        result += pair.second;
    }

    return result;
}

