    while (true) {
        if (memory1 >= memory2) {
            if (memory1 >= crashTime) {
                memory1 -= crashTime;
            } else {
                break;
            }
        } else {
            if (memory2 >= crashTime) {
                memory2 -= crashTime;
            } else {
                break;
            }
        }
        crashTime++;
    }
    return new int[]{crashTime, memory1, memory2};
}

