public int findGCD(int[] nums) {
    int min_val = Arrays.stream(nums).min().getAsInt();
    int max_val = Arrays.stream(nums).max().getAsInt();
    while(max_val % min_val != 0) {
        int temp = min_val;
        min_val = max_val % min_val;
        max_val = temp;
    }
    return min_val;
}

