import java.util.*;

class Solution {
    public int[] recoverArray(int n, int[] sums) {
        TreeSet<Integer> ms = new TreeSet<>();
        for (int sum : sums) {
            ms.add(sum);
        }

        ArrayList<Integer> ans = new ArrayList<>();
        while (ans.size() < n) {
            ms.pollFirst();
            int cur = ms.first();
            TreeSet<Integer> tmp = new TreeSet<>(ms);
            for (int i : ans) {
                tmp.remove(cur - i);
            }
            ans.add(cur);
            ms = tmp;
        }

        return ans.stream().mapToInt(i -> i).toArray();
    }
}

cpp_code:
#include <vector>
#include <set>
#include <algorithm>

std::vector<int> recoverArray(int n, std::vector<int>& sums) {
    std::multiset<int> ms(sums.begin(), sums.end());
    std::vector<int> ans;

    while (ans.size() < n) {
        ms.erase(ms.begin());
        int cur = *ms.begin();
        std::multiset<int> tmp = ms;
        for (int i : ans) {
            tmp.erase(tmp.find(cur - i));
        }
        ans.push_back(cur);
        ms = tmp;
    }

    return ans;
}

javascript_code:
function recoverArray(n, sums) {
    let ms = new Set(sums.sort((a, b) => a - b));
    let ans = [];

    while (ans.length < n) {
        ms.delete(ms.values().next().value);
        let cur = ms.values().next().value;

        let tmp = new Set(ms);
        for (let i of ans) {
            tmp.delete(cur - i);
        }

        ans.push(cur);
        ms = tmp;
    }

    return ans;
}

