    for (int i = 0; i < n; ++i) {
        prefix[i + 1] = (prefix[i] + nums[i]) % mod;
    }

    for (int i = 0; i <= n; ++i) {
        while (!s.empty() && (i == n || nums[s.top()] > nums[i])) {
            int j = s.top();
            s.pop();
            res = max(res, nums[j] * (prefix[i] - prefix[s.empty() ? 0 : s.top() + 1]) % mod);
        }
        s.push(i);
    }

    return res;
}

