int dfs(int node, vector<unordered_set<int>> &graph, string &colors, vector<vector<int>> &cache) {
    if (!cache[node][colors[node] - 'a']) {
        cache[node][colors[node] - 'a'] = 1;
        for (int neighbor : graph[node]) {
            cache[node][colors[node] - 'a'] = max(cache[node][colors[node] - 'a'], 1 + dfs(neighbor, graph, colors, cache));
        }
    }
    return cache[node][colors[node] - 'a'];
}

int largestPathValue(string colors, vector<vector<int>> &edges) {
    int n = colors.size();
    vector<unordered_set<int>> graph(n);
    for (const auto &edge : edges) {
        graph[edge[0]].insert(edge[1]);
    }
    vector<vector<int>> cache(n, vector<int>(26));
    vector<int> in_degree(n);
    for (const auto &edge : edges) {
        in_degree[edge[1]]++;
    }
    int res = -1;
    for (int i = 0; i < n; ++i) {
        if (!in_degree[i]) {
            res = max(res, dfs(i, graph, colors, cache));
        }
    }
    return res;
}

