java_code:
int numberOfSticks(int n, int k) {
    final int MOD = (int) 1e9 + 7;
    if (n < k) return 0;
    int[][] dp = new int[n+1][n+1];

    for (int i = 1; i <= n; i++) {
        dp[i][1] = 1;
        for (int j = 2; j <= i; j++)
            dp[i][j] = (dp[i-1][j-1] + (i-1) * dp[i-1][j]) % MOD;
    }
    return dp[n][k];
}

