    for (int i = 1; i <= n; i++) {
        dp[i][1] = 1;
        for (int j = 2; j <= i; j++)
            dp[i][j] = (dp[i-1][j-1] + (i-1) * dp[i-1][j]) % MOD;
    }
    return dp[n][k];
}

