public int firstDayBeenInAllRooms(int[] nextVisit) {
    int n = nextVisit.length;
    long ans = 0;
    long MOD = 1000000007;
    long[] dp = new long[n];

    for (int i = 1; i < n; ++i) {
        dp[i] = (dp[i - 1] * 2 - dp[nextVisit[i - 1]] + 2) % MOD;
    }

    return (int)dp[n - 1];
}

