public int stoneGameVII(int[] stones) {
    int n = stones.length;
    int[][] dp = new int[n][n];

    for (int i = n - 1; i >= 0; i--)
        for (int j = i + 1; j < n; j++)
            dp[i][j] = Math.max(stones[i] - dp[i + 1][j], stones[j] - dp[i][j - 1]);

    return dp[0][n - 1];
}

cpp_code:
int stoneGameDp(vector<int>& stones, int start, int end, vector<vector<int>>& dp) {
    if (start == end) return stones[start];

    if (dp[start][end] != 0) return dp[start][end];

    dp[start][end] = max(stones[start] - stoneGameDp(stones, start + 1, end, dp),
                         stones[end] - stoneGameDp(stones, start, end - 1, dp));
    return dp[start][end];
}

int stoneGameVII(vector<int>& stones) {
    int n = stones.size();
    vector<vector<int>> dp(n, vector<int>(n, 0));

    for (int i = n - 1; i >= 0; --i)
        for (int j = i + 1; j < n; ++j)
            dp[i][j] = max(stones[i] - dp[i + 1][j], stones[j] - dp[i][j - 1]);

    return dp[0][n - 1];
}

