void dfs(int node, const vector<int>& parents, const vector<int>& nums,
         vector<set<int>>& children, vector<int>& ans) {
    for (int child : children[node]) {
        dfs(child, parents, nums, children, ans);
        children[node].erase(child);
        children[node].insert(ans[child]);
    }
    auto it = children[node].lower_bound(nums[node]);
    ans[node] = (it == children[node].end()) ? nums[node] + 1 : *it - 1;
}

