using namespace std;

int minOperationsToFlip(string expression) {
    vector<int> zero(1), one(1), op;
    for (const auto& c : expression) {
        if (c == '&') op.push_back(1);
        else if (c == '|') op.push_back(2);
        else if (isdigit(c)) {
            if (c == '0') {
                one.push_back(1);
                zero.push_back(0);
            } else {
                zero.push_back(1);
                one.push_back(0);
            }
        } else if (c == ')') {
            int cur_op = op.back(); op.pop_back();
            int new_zero, new_one;
            int x = zero.back(); zero.pop_back();
            int y = one.back() + 1; one.pop_back();
            if (cur_op == 1) {
                new_zero = max(x, y);
                new_one = one.back() + min(x, zero.back());
            } else {
                new_zero = zero.back() + min(x, one.back());
                new_one = max(y, one.back());
            }
            zero.pop_back(); one.pop_back();
            zero.push_back(new_zero);
            one.push_back(new_one);
        }
    }
    return zero.back() + 1;
}

