var minOperationsToFlip = function(expression) {
    let zero = [0], one = [0], op = [];
    for (let c of expression) {
        if (c == '&') op.push(1);
        else if (c == '|') op.push(2);
        else if (c == '0' || c == '1') {
            if (c == '0') {
                one.push(1);
                zero.push(0);
            } else {
                zero.push(1);
                one.push(0);
            }
        } else if (c == ')') {
            let cur_op = op.pop();
            let x = zero.pop();
            let y = one.pop() + 1;
            let new_zero, new_one;
            if (cur_op == 1) {
                new_zero = Math.max(x, y);
                new_one = one[one.length - 1] + Math.min(x, zero[zero.length - 1]);
            } else {
                new_zero = zero[zero.length - 1] + Math.min(x, one[one.length - 1]);
                new_one = Math.max(y, one[one.length - 1]);
            }
            zero.pop();
            one.pop();
            zero.push(new_zero);
            one.push(new_one);
        }
    }
    return zero[zero.length-1] + 1;
};

