std::vector<int> assignTasks(std::vector<int>& servers, std::vector<int>& tasks) {
    int n = servers.size(), m = tasks.size();
    std::vector<int> ans(m);
    std::priority_queue<std::pair<int, int>, std::vector<std::pair<int, int>>, std::greater<std::pair<int, int>>> freeServers;

    for (int i = 0; i < n; ++i) {
        freeServers.push({servers[i], i});
    }

    std::priority_queue<std::pair<int, int>, std::vector<std::pair<int, int>>, std::greater<std::pair<int, int>>> busyServers;
    int currentTask = 0;

    while (currentTask < m) {
        while (!busyServers.empty() && busyServers.top().first <= currentTask) {
            freeServers.push({servers[busyServers.top().second], busyServers.top().second});
            busyServers.pop();
        }

        while (!freeServers.empty() && currentTask < m) {
            ans[currentTask] = freeServers.top().second;
            busyServers.push({currentTask + tasks[currentTask], freeServers.top().second});
            freeServers.pop();
            currentTask++;
        }

        if(freeServers.empty()) {
            currentTask = busyServers.top().first;
        }
    }

    return ans;
}

javascript_code:
function assignTasks(servers, tasks) {
    const n = servers.length;
    const m = tasks.length;
    const ans = Array(m);
    const freeServers = new PriorityQueue((a, b) => a[0] - b[0] || a[1] - b[1]);

    for (let i = 0; i < n; i++) {
        freeServers.push([servers[i], i]);
    }

    const busyServers = new PriorityQueue((a, b) => a[0] - b[0] || a[1] - b[1]);
    let currentTask = 0;

    while (currentTask < m) {
        while (busyServers.size() > 0 && busyServers.peek()[0] <= currentTask) {
            const [_, idx] = busyServers.pop();
            freeServers.push([servers[idx], idx]);
        }

        while (!freeServers.isEmpty() && currentTask < m) {
            const [_, idx] = freeServers.pop();
            ans[currentTask] = idx;
            busyServers.push([currentTask + tasks[currentTask], idx]);
            currentTask++;
        }

        if (freeServers.isEmpty()) {
            currentTask = busyServers.peek()[0];
        }
    }

    return ans;
}

class PriorityQueue {
    constructor(comparator) {
        this.data = [];
        this.compare = comparator || ((a, b) => a - b);
    }

    push(value) { this.data.push(value); this.data.sort(this.compare); }
    pop() { return this.data.shift(); }
    peek() { return this.data[0]; }
    size() { return this.data.length; }
    isEmpty() { return this.data.length === 0; }
}

java_code:
public int minSkips(int[] dist, int speed, int hoursBefore) {
    int n = dist.length;
    double[][] dp = new double[n + 1][n + 1];

    for (int i = 0; i <= n; i++) {
        for (int j = 0; j <= n; j++) {
            dp[i][j] = 1e6;
        }
    }
    dp[0][0] = 0;
    for (int i = 1; i <= n; i++) {
        dp[i][0] = Math.ceil(dp[i - 1][0] + (double) dist[i - 1] / speed) - 1;
    }

    for (int i = 1; i <= n; i++) {
        for (int skip = 1; skip <= i; skip++) {
            dp[i][skip] = Math.min(dp[i][skip], dp[i - 1][skip - 1] + (double) dist[i - 1] / speed);
            dp[i][skip] = Math.min(dp[i][skip], Math.ceil(dp[i - 1][skip] + (double) dist[i - 1] / speed));
        }
    }

    for (int skip = 0; skip <= n; skip++) {
        if (dp[n][skip] <= hoursBefore) {
            return skip;
        }
    }
    return -1;
}

