#include <string>
#include <vector>

std::string longestSubsequenceRepeatedK(const std::string& s, int k) {
    std::vector<int> count(26, 0);
    for (auto c : s) { count[c - 'a']++; }
    std::string seq;
    for (char c = 'a'; c <= 'z'; c++) {
        if (count[c - 'a'] >= k) seq += std::string(count[c - 'a'] / k, c);
    }

    int n = seq.length();
    std::vector<std::vector<int>> dp(n + 1, std::vector<int>(n + 1, 0));
    for (int i = n - 1; i >= 0; i--) {
        for (int j = i + 1; j < n; j++) {
            if (seq[i] == seq[j]) {
                dp[i][j] = 1 + dp[i + 1][j + 1];
            } else {
                dp[i][j] = std::max(dp[i + 1][j], dp[i][j + 1]);
            }
        }
    }

    std::string res;
    int i = 0, j = 0;
    while (j < n && res.length() < n / k) {
        if (res.empty() || seq[j] > res.back()) {
            if (dp[i][j] >= (n / k - res.length()) * 2) {
                res.push_back(seq[j]);
                i = j + 1;
            }
        }
        j++;
    }

    return res;
}

