def longestSubsequenceRepeatedK(s, k):
    count = [0] * 26
    for c in s:
        count[ord(c) - ord('a')] += 1
    seq = "".join(chr(i + ord('a')) * (count[i] // k) for i in range(26) if count[i] >= k)

    def dp(i, j):
        if (i, j) in memo:
            return memo[(i, j)]
        if i >= len(seq) or j >= len(seq):
            return 0
        if seq[i] == seq[j]:
            res = 1 + dp(i + 1, j + 1)
        else:
            res = max(dp(i + 1, j), dp(i, j + 1))
        memo[(i, j)] = res
        return res

    memo = {}
    res = []
    i, j = 0, 0
    while j < len(seq) and len(res) < len(seq) // k:
        if not res or seq[j] > res[-1]:
            if dp(i, j) >= (len(seq) // k - len(res)) * 2:
                res.append(seq[j])
                i = j + 1
        j += 1

    return "".join(res)

javascript_code:
function longestSubsequenceRepeatedK(s, k) {
    let count = new Array(26).fill(0);
    for (let i = 0; i < s.length; i++) count[s.charCodeAt(i) - 'a'.charCodeAt(0)]++;
    let seq = Array.from({length: 26}, (_, i) => {
        return (count[i] >= k) ? String.fromCharCode(i + 'a'.charCodeAt(0)).repeat(count[i] / k) : '';
    }).join('');

    function dp(i, j, memo = new Map()) {
        if (memo.has(`${i},${j}`)) return memo.get(`${i},${j}`);
        if (i >= seq.length || j >= seq.length) return 0;
        let res = (seq[i] === seq[j]) ? 1 + dp(i + 1, j + 1, memo) : Math.max(dp(i + 1, j, memo), dp(i, j + 1, memo));
        memo.set(`${i},${j}`, res);
        return res;
    }

    let res = [];
    let i = 0, j = 0;
    while (j < seq.length && res.length < seq.length / k) {
        if (res.length === 0 || seq[j] > res[res.length - 1]) {
            if (dp(i, j) >= (seq.length / k - res.length) * 2) {
                res.push(seq[j]);
                i = j + 1;
            }
        }
        j++;
    }

    return res.join('');
}

