#include <vector>
#include <algorithm>
#include <climits>

using namespace std;

int minWastedSpace(vector<int>& packages, vector<vector<int>>& boxes) {
    constexpr int MOD = 1e9 + 7;
    sort(packages.begin(), packages.end());
    long long total_package_size = 0;
    for (int package_size : packages)
        total_package_size += package_size;
    long long min_wasted_space = LLONG_MAX;

    for (vector<int>& box_sizes : boxes) {
        sort(box_sizes.begin(), box_sizes.end());
        if (box_sizes.back() < packages.back())
            continue;
        long long wasted_space = 0;
        auto package_iter = packages.begin();
        for (int box_size : box_sizes) {
            package_iter = upper_bound(package_iter, packages.end(), box_size);
            wasted_space += box_size - *prev(package_iter);
        }
        min_wasted_space = min(min_wasted_space, wasted_space);
    }
    return min_wasted_space == LLONG_MAX ? -1 : (total_package_size + min_wasted_space) % MOD;
}

javascript_code:
function minWastedSpace(packages, boxes) {
    const MOD = 1e9 + 7;
    packages = packages.sort((a, b) => a - b);
    let total_package_size = packages.reduce((a, b) => a + b, 0);
    let min_wasted_space = Infinity;

    for (let box_sizes of boxes) {
        box_sizes = box_sizes.sort((a, b) => a - b);
        if (box_sizes[box_sizes.length - 1] < packages[packages.length - 1]) {
            continue;
        }
        let wasted_space = 0;
        let pkg_idx = 0;
        for (let box_size of box_sizes) {
            pkg_idx = packages.findIndex((x, i) => i >= pkg_idx && x > box_size);
            if (pkg_idx === -1) {
                break;
            }
            wasted_space += box_size - packages[pkg_idx - 1];
        }
        min_wasted_space = Math.min(min_wasted_space, wasted_space);
    }
    return min_wasted_space === Infinity ? -1 : (total_package_size + min_wasted_space) % MOD;
}

