python_code:
def sumOfPoints(s: str, answers: List[int]) -> int:
    correct = 0
    mul = 1
    add = 0
    for i in range(len(s)):
        if s[i].isdigit():
            num = int(s[i])
            mul *= num
            if i == len(s) - 1 or s[i + 1] == '+':
                add += mul
                mul = 1
    correct = add

    wrongOrder = int(s[0])
    for i in range(2, len(s), 2):
        if s[i - 1] == '+':
            wrongOrder += int(s[i])
        else:
            wrongOrder *= int(s[i])

    return sum(5 * (ans == correct) + 2 * (ans == wrongOrder) for ans in answers)

javascript_code:
function sumOfPoints(s, answers) {
    let correct = 0, wrongOrder = 0;
    let mul = 1, add = 0;
    for (let i = 0; i < s.length; ++i) {
        if (s[i] >= '0' && s[i] <= '9') {
            let num = parseInt(s[i]);
            mul *= num;
            if (i === s.length - 1 || s[i + 1] === '+') {
                add += mul;
                mul = 1;
            }
        }
    }

    wrongOrder = parseInt(s[0]);
    for (let i = 2; i < s.length; i += 2) {
        if (s[i - 1] === '+') wrongOrder += parseInt(s[i]);
        else wrongOrder *= parseInt(s[i]);
    }

    let sum = 0;
    answers.forEach(ans => {
        sum += (ans === correct) * 5 + (ans === wrongOrder) * 2;
    });
    return sum;
}

