from collections import defaultdict
from sortedcontainers import SortedList

class MovieRentingSystem:

    def __init__(self, n: int, entries: List[List[int]]):
        self.price = defaultdict(dict)
        self.rented = SortedList(key=lambda x: (x[0], x[1]))
        self.available = defaultdict(SortedList)
        for shop, movie, p in entries:
            self.price[shop][movie] = p
            self.available[movie].add((p, shop))

    def search(self, movie: int) -> List[int]:
        return [x[1] for x in self.available[movie][:5]]

    def rent(self, shop: int, movie: int) -> None:
        p = self.price[shop][movie]
        self.rented.add((p, shop))
        self.available[movie].discard((p, shop))

    def drop(self, shop: int, movie: int) -> None:
        p = self.price[shop][movie]
        self.rented.discard((p, shop))
        self.available[movie].add((p, shop))

    def report(self) -> List[List[int]]:
        return [[shop, movie] for p, shop, movie in self.rented]

javascript_code:
class MovieRentingSystem {
    constructor(n, entries) {
        this.price = new Map();
        this.rented = new Set();
        this.available = new Map();

        for (const [shop, movie, p] of entries) {
            if (!this.price.has(shop)) this.price.set(shop, new Map());
            this.price.get(shop).set(movie, p);

            if (!this.available.has(movie)) this.available.set(movie, new Set());
            this.available.get(movie).add([p, shop]);
        }
    }

    search(movie) {
        return [...this.available.get(movie).values()]
            .sort((a, b) => a[0] - b[0] || a[1] - b[1])
            .slice(0, 5)
            .map((item) => item[1]);
    }

    rent(shop, movie) {
        const p = this.price.get(shop).get(movie);
        this.rented.add([p, shop]);
        this.available.get(movie).delete([...this.available.get(movie)].find(a => a[1] === shop ));
    }

    drop(shop, movie) {
        const p = this.price.get(shop).get(movie);
        this.rented.delete([...this.rented].find(a => a[1] === shop ));
        this.available.get(movie).add([p, shop]);
    }

    report() {
        return [...this.rented.values()]
            .sort((a, b) => a[0] - b[0] || a[1] - b[1])
            .slice(0, 5)
            .map((item) => [item[1], item[0]]);
    }
}

java_code:
public int maxConsecutiveAnswers(String answerKey, int k) {
    int maxLen = 0, left = 0, TCount = 0, FCount = 0;

    for (int right = 0; right < answerKey.length(); ++right) {
        if (answerKey.charAt(right) == 'T') {
            ++TCount;
        } else {
            ++FCount;
        }

        if (Math.min(TCount, FCount) > k) {
            if (answerKey.charAt(left++) == 'T') {
                --TCount;
            } else {
                --FCount;
            }
        } else {
            maxLen = Math.max(maxLen, TCount + FCount);
        }
    }

    return maxLen;
}

