int maxConsecutiveAnswers(const string& answerKey, int k) {
    int max_len = 0, left = 0, T_cnt = 0, F_cnt = 0;

    for (int right = 0; right < answerKey.size(); ++right) {
        if (answerKey[right] == 'T') {
            ++T_cnt;
        } else {
            ++F_cnt;
        }

        if (min(T_cnt, F_cnt) > k) {
            if (answerKey[left++] == 'T') {
                --T_cnt;
            } else {
                --F_cnt;
            }
        } else {
            max_len = max(max_len, T_cnt + F_cnt);
        }
    }

    return max_len;
}

