#include <vector>
#include <string>

std::string smallestSubsequence(std::string s, int k, char letter, int repetition) {
    int n = s.size();
    int remaining = n - k;
    int letterCount = 0;

    std::vector<char> res;
    for (char c : s) {
        while (!res.empty() && res.back() > c && remaining > 0) {
            if (res.back() == letter) {
                if (letterCount > repetition) {
                    --letterCount;
                    res.pop_back();
                    --remaining;
                }
            } else {
                res.pop_back();
                --remaining;
            }
        }
        if (res.size() < k) {
            if (c == letter) {
                ++letterCount;
            } else if (k - res.size() > repetition - letterCount) {
            } else {
                continue;
            }
            res.push_back(c);
        }
    }

    return std::string(res.begin(), res.end());
}

python_code:
def smallestSubsequence(s, k, letter, repetition):
    n = len(s)
    remaining = n - k
    letter_count = 0

    res = []
    for c in s:
        while res and res[-1] > c and remaining > 0:
            if res[-1] == letter:
                if letter_count > repetition:
                    letter_count -= 1
                    res.pop()
                    remaining -= 1
            else:
                res.pop()
                remaining -= 1
        if len(res) < k:
            if c == letter:
                letter_count += 1
            elif k - len(res) > repetition - letter_count:
            else:
                continue
            res.append(c)

    return ''.join(res)

