java_code:
import java.util.*;

public int[] min_absolute_difference(int[] nums, int[][] queries) {
    int[] result = new int[queries.length];

    for (int i = 0; i < queries.length; i++) {
        int left = queries[i][0];
        int right = queries[i][1];
        TreeSet<Integer> unique = new TreeSet<>();

        for (int j = left; j <= right; j++)
            unique.add(nums[j]);

        if (unique.size() == 1) {
            result[i] = -1;
        } else {
            int min_diff = Integer.MAX_VALUE;
            for (Iterator<Integer> it = unique.iterator(); it.hasNext(); ) {
                int curr = (int) it.next();
                if (!it.hasNext()) break;
                int next = (int) it.next();
                min_diff = Math.min(min_diff, next - curr);
                it.previous();
            }

            result[i] = min_diff;
        }
    }

    return result;
}

cpp_code:
#include <vector>
#include <set>
#include <algorithm>

std::vector<int> min_absolute_difference(std::vector<int>& nums, std::vector<std::vector<int>>& queries) {
    std::vector<int> result;

    for (std::vector<int> query : queries) {
        int left = query[0];
        int right = query[1];
        std::set<int> unique;

        for (int i = left; i <= right; ++i)
            unique.insert(nums[i]);

        if (unique.size() == 1) {
            result.push_back(-1);
        } else {
            int min_diff = INT_MAX;
            for (auto it = std::next(unique.begin()); it != unique.end(); ++it)
                min_diff = std::min(min_diff, *it - *std::prev(it));

            result.push_back(min_diff);
        }
    }

    return result;
}

