function min_absolute_difference(nums, queries) {
    const result = [];

    for (const query of queries) {
        const left = query[0];
        const right = query[1];
        const unique = new Set(nums.slice(left, right + 1));

        if (unique.size === 1) {
            result.push(-1);
        } else {
            const sorted = Array.from(unique).sort((a, b) => a - b);
            let min_diff = Number.MAX_SAFE_INTEGER;
            for (let i = 1; i < sorted.length; i++)
                min_diff = Math.min(min_diff, sorted[i] - sorted[i - 1]);

            result.push(min_diff);
        }
    }

    return result;
}

