public int countSubIslands(int[][] grid1, int[][] grid2) {
    int count = 0;

    for (int i = 0; i < grid1.length; i++) {
        for (int j = 0; j < grid1[0].length; j++) {
            if (grid2[i][j] == 1) {
                boolean[] isSubIsland = new boolean[1];
                isSubIsland[0] = true;
                dfs(grid1, grid2, i, j, isSubIsland);
                if (isSubIsland[0]) {
                    count++;
                }
            }
        }
    }

    return count;
}

private void dfs(int[][] grid1, int[][] grid2, int i, int j, boolean[] isSubIsland) {
    if (i < 0 || i >= grid1.length || j < 0 || j >= grid1[0].length || grid2[i][j] == 0) {
        return;
    }

    if (grid1[i][j] == 0) {
        isSubIsland[0] = false;
    }

    grid2[i][j] = 0;

    dfs(grid1, grid2, i + 1, j, isSubIsland);
    dfs(grid1, grid2, i - 1, j, isSubIsland);
    dfs(grid1, grid2, i, j + 1, isSubIsland);
    dfs(grid1, grid2, i, j - 1, isSubIsland);
}

