        for (int j = 0; j < grid1[0].size(); ++j) {
            if (grid2[i][j] == 1) {
                bool isSubIsland = true;
                dfs(grid1, grid2, i, j, isSubIsland);
                if (isSubIsland) {
                    ++count;
                }
            }
        }
    }

    return count;
}

