        int size = q.size();
        for (int i = 0; i < size; ++i) {
            pair<int, int> cur = q.front(); q.pop();
            int x = cur.first;
            int y = cur.second;
            if ((x == 0 || x == m - 1 || y == 0 || y == n - 1) && (x != entrance[0] || y != entrance[1]))
                return steps;

            for (auto dir : directions) {
                int xx = x + dir[0];
                int yy = y + dir[1];
                if (xx >= 0 && xx < m && yy >= 0 && yy < n && maze[xx][yy] == '.') {
                    maze[xx][yy] = '+';
                    q.push({xx, yy});
                }
            }
        }
        ++steps;
    }

    return -1;
}

