using namespace std;

int minCost(int maxTime, vector<vector<int>>& edges, vector<int>& passingFees) {
    int n = passingFees.size();
    vector<vector<pair<int, int>>> graph(n);
    for (const auto& edge : edges) {
        graph[edge[0]].emplace_back(edge[1], edge[2]);
        graph[edge[1]].emplace_back(edge[0], edge[2]);
    }

    vector<vector<int>> dp(n, vector<int>(maxTime + 1, INT_MAX));
    dp[0][0] = passingFees[0];
    priority_queue<tuple<int, int, int>, vector<tuple<int, int, int>>, greater<>> pq;
    pq.emplace(0, 0, passingFees[0]);

    while (!pq.empty()) {
        auto [time, city, cost] = pq.top();
        pq.pop();
        if (city == n - 1) {
            return cost;
        }
        for (const auto& [neighbor, t] : graph[city]) {
            int next_time = time + t;
            if (next_time > maxTime) continue;
            int new_cost = cost + passingFees[neighbor];
            if (new_cost < dp[neighbor][next_time]) {
                dp[neighbor][next_time] = new_cost;
                pq.emplace(next_time, neighbor, new_cost);
            }
        }
    }

    return -1;
}

