function minCost(maxTime, edges, passingFees) {
    const n = passingFees.length;
    const graph = new Array(n).fill(null).map(() => []);
    for (const edge of edges) {
        graph[edge[0]].push([edge[1], edge[2]]);
        graph[edge[1]].push([edge[0], edge[2]]);
    }

    const dp = new Array(n).fill(null).map(() => new Array(maxTime + 1).fill(Infinity));
    dp[0][0] = passingFees[0];

    const pq = [[0, 0, passingFees[0]]];
    while (pq.length > 0) {
        pq.sort((a, b) => a[2] - b[2]);
        const [time, city, cost] = pq.shift();
        if (city === n - 1) {
            return cost;
        }

        for (const [neighbor, t] of graph[city]) {
            const next_time = time + t;
            if (next_time > maxTime) continue;

            const new_cost = cost + passingFees[neighbor];
            if (new_cost < dp[neighbor][next_time]) {
                dp[neighbor][next_time] = new_cost;
                pq.push([next_time, neighbor, new_cost]);
            }
        }
    }

    return -1;
}

