function secondMinimum(n, edges, time, change) {
    const graph = Array(n + 1).fill(null).map(() => []);
    for (const [u, v] of edges) {
        graph[u].push(v);
        graph[v].push(u);
    }

    const dist = new Array(n + 1).fill(Infinity);
    const dist2 = new Array(n + 1).fill(Infinity);
    dist[1] = 0;

    const q = [1];

    while (q.length) {
        const cur = q.shift();

        let nextDist = dist[cur] + time;
        const waitTime = (nextDist / change) % 2 === 1 ? change : 0;
        nextDist += waitTime;

        for (const next of graph[cur]) {
            if (nextDist < dist[next]) {
                [nextDist, dist[next]] = [dist[next], nextDist];
                q.push(next);
            }
            if (nextDist < dist2[next]) {
                [nextDist, dist2[next]] = [dist2[next], nextDist];
                q.push(next);
            }
        }
    }
    return dist2[n];
}

