public int[] findPeakGrid(int[][] mat) {
    int m = mat.length, n = mat[0].length;
    int l = 0, r = n - 1;

    while (l < r) {
        int mid = (l + r) / 2;
        int max_row = 0;

        for (int i = 1; i < m; i++) {
            if (mat[i][mid] > mat[max_row][mid]) {
                max_row = i;
            }
        }

        if (mat[max_row][mid] < mat[max_row][mid + 1]) {
            l = mid + 1;
        } else {
            r = mid;
        }
    }

    int max_row = 0;
    for (int i = 1; i < m; i++) {
        if (mat[i][l] > mat[max_row][l]) {
            max_row = i;
        }
    }

    return new int[]{max_row, l};
}

