public int count_good_digit_strings(int n) {
    final int mod = (int)1e9 + 7;
    int even_digits = 5, prime_digits = 4;
    long total = 1;
    for (int i = 0; i < n; ++i) {
        total = (total * (i % 2 == 0 ? even_digits : prime_digits)) % mod;
    }
    return (int)total;
}

