#include <string>
#include <limits>

using namespace std;

int minCost(string sentence, int k) {
    vector<string> words;
    string word;
    for (const char c : sentence) {
        if (c == ' ') {
            words.push_back(word);
            word.clear();
        } else {
            word.push_back(c);
        }
    }
    words.push_back(word);
    vector<int> dp(words.size() + 1, numeric_limits<int>::max());
    dp[0] = 0;
    for (int i = 0; i < words.size(); ++i) {
        int length = 0;
        for (int j = i; j >= 0; --j) {
            length += words[j].size();
            if (length + (i - j) <= k) {
                dp[i + 1] = min(dp[i + 1], dp[j] + (k - length - (i - j)) * (k - length - (i - j)));
            } else {
                break;
            }
            length += 1;
        }
    }
    return dp.back();
}

