def minCost(sentence: str, k: int) -> int:
    words = sentence.split()
    dp = [float('inf')] * (len(words) + 1)
    dp[0] = 0
    for i in range(len(words)):
        length = 0
        j = i
        while j >= 0:
            length += len(words[j])
            if length + (i - j) <= k:
                dp[i + 1] = min(dp[i + 1], dp[j] + (k - length - (i - j)) * (k - length - (i - j)))
            else:
                break
            length += 1
            j -= 1
    return dp[-1]

