    for (auto& event : events) {
        if (event.second >= 0) {
            int friend_id = event.second;
            chairs[friend_id] = *available_chairs.begin();
            available_chairs.erase(available_chairs.begin());
            if (friend_id == target_friend) {
                return chairs[friend_id];
            }
        } else {
            int friend_id = ~event.second;
            available_chairs.insert(chairs[friend_id]);
        }
    }
    return -1;
}

