#include <vector>
#include <map>
#include <algorithm>

using namespace std;

vector<vector<int>> splitPainting(vector<vector<int>>& segments) {
    map<int, int> changes;
    for (auto& segment : segments) {
        changes[segment[0]] += segment[2];
        changes[segment[1]] -= segment[2];
    }

    vector<vector<int>> result;
    int start = 0, color_sum = 0;
    for (auto& change : changes) {
        if (start != change.first) {
            if (color_sum) result.push_back({start, change.first, color_sum});
            start = change.first;
        }
        color_sum += change.second;
    }

    return result;
}

python_code:
from collections import defaultdict

def splitPainting(segments):
    changes = defaultdict(int)
    for start, end, color in segments:
        changes[start] += color
        changes[end] -= color

    result = []
    start, color_sum = 0, 0
    for key in sorted(changes.keys()):
        if start != key:
            if color_sum:
                result.append([start, key, color_sum])
            start = key
        color_sum += changes[key]

    return result

javascript_code:
function splitPainting(segments) {
    const changes = new Map();
    for (const [start, end, color] of segments) {
        changes.set(start, (changes.get(start) || 0) + color);
        changes.set(end, (changes.get(end) || 0) - color);
    }

    const result = [];
    let start = 0, color_sum = 0;
    for (const key of [...changes.keys()].sort((a, b) => a - b)) {
        if (start !== key) {
            if (color_sum) {
                result.push([start, key, color_sum]);
            }
            start = key;
        }
        color_sum += changes.get(key);
    }

    return result;
}

java_code:
import java.util.List;
import java.util.ArrayList;

public int countValidCombos(List<String> pieces, List<List<Integer>> positions, int index) {
    if (index == pieces.size()) { return 1; }

    int r = positions.get(index).get(0), c = positions.get(index).get(1);
    int[] dr = {0, 1, 0, -1, 1, 1, -1, -1};
    int[] dc = {1, 0, -1, 0, 1, -1, 1, -1};
    int valids = 0;

    for (int x = 0; x < 8; ++x) {
        if (pieces.get(index).equals("bishop") && x < 4) continue;
        if (pieces.get(index).equals("rook") && x >= 4) break;

        for (int dist = 1; dist <= 8; dist++) {
            int nr = r + dr[x] * dist;
            int nc = c + dc[x] * dist;
            if (nr < 1 || nr > 8 || nc < 1 || nc > 8) break;
            if (nr == r && nc == c) continue;

            boolean valid = true;
            for (int other = 0; other < positions.size(); ++other) {
                if (other == index) continue;
                int orr = positions.get(other).get(0), occ = positions.get(other).get(1);
                if (orr == nr && occ == nc) { valid = false; break; }
                if (orr + occ == nr + nc || orr - occ == nr - nc) { valid = false; break; }
                if (orr == nr || occ == nc) { valid = false; break; }
            }

            if (valid) {
                List<Integer> tmp = new ArrayList<>();
                tmp.add(nr);
                tmp.add(nc);
                positions.set(index, tmp);
                valids += countValidCombos(pieces, positions, index + 1);
                positions.set(index, List.of(r, c));
            }
        }
    }

    return valids;
}

