#include <vector>
#include <string>
using namespace std;

int countValidCombos(vector<string>& pieces, vector<vector<int>>& positions, int index = 0) {
    if (index == pieces.size()) { return 1; }

    int r = positions[index][0], c = positions[index][1];
    int dr[] = {0, 1, 0, -1, 1, 1, -1, -1};
    int dc[] = {1, 0, -1, 0, 1, -1, 1, -1};
    int valids = 0;

    for (int x = 0; x < 8; ++x) {
        if (pieces[index] == "bishop" && x < 4) continue;
        if (pieces[index] == "rook" && x >= 4) break;

        for (int dist = 1; dist <= 8; dist++) {
            int nr = r + dr[x] * dist;
            int nc = c + dc[x] * dist;
            if (nr < 1 || nr > 8 || nc < 1 || nc > 8) break;
            if (nr == r && nc == c) continue;

            bool valid = true;
            for (int other = 0; other < positions.size(); ++other) {
                if (other == index) continue;
                int orr = positions[other][0], occ = positions[other][1];
                if (orr == nr && occ == nc) { valid = false; break; }
                if (orr + occ == nr + nc || orr - occ == nr - nc) { valid = false; break; }
                if (orr == nr || occ == nc) { valid = false; break; }
            }

            if (valid) {
                vector<int> tmp = {nr, nc};
                positions[index] = tmp;
                valids += countValidCombos(pieces, positions, index + 1);
                positions[index] = {r, c};
            }
        }
    }

    return valids;
}

