def count_valid_combos(pieces, positions, index=0):
    if index == len(pieces):
        return 1

    r, c = positions[index]
    dr = [0, 1, 0, -1, 1, 1, -1, -1]
    dc = [1, 0, -1, 0, 1, -1, 1, -1]
    valids = 0

    for x in range(8):
        if pieces[index] == "bishop" and x < 4:
            continue
        if pieces[index] == "rook" and x >= 4:
            break

        for dist in range(1, 9):
            nr, nc = r + dr[x] * dist, c + dc[x] * dist
            if nr < 1 or nr > 8 or nc < 1 or nc > 8:
                break
            if nr == r and nc == c:
                continue

            valid = True
            for other in range(len(positions)):
                if other == index:
                    continue
                orr, occ = positions[other]
                if orr == nr and occ == nc:
                    valid = False
                    break
                if orr + occ == nr + nc or orr - occ == nr - nc:
                    valid = False
                    break
                if orr == nr or occ == nc:
                    valid = False
                    break

            if valid:
                positions[index] = [nr, nc]
                valids += count_valid_combos(pieces, positions, index + 1)
                positions[index] = [r, c]

    return valids

javascript_code:
function countValidCombos(pieces, positions, index=0) {
    if (index === pieces.length) { return 1; }

    let r = positions[index][0], c = positions[index][1];
    let dr = [0, 1, 0, -1, 1, 1, -1, -1];
    let dc = [1, 0, -1, 0, 1, -1, 1, -1];
    let valids = 0;

    for (let x = 0; x < 8; ++x) {
        if (pieces[index] === "bishop" && x < 4) continue;
        if (pieces[index] === "rook" && x >= 4) break;

        for (let dist = 1; dist <= 8; dist++) {
            let nr = r + dr[x] * dist;
            let nc = c + dc[x] * dist;
            if (nr < 1 || nr > 8 || nc < 1 || nc > 8) break;
            if (nr === r && nc === c) continue;

            let valid = true;
            for (let other = 0; other < positions.length; ++other) {
                if (other === index) continue;
                let orr = positions[other][0], occ = positions[other][1];
                if (orr === nr && occ === nc) { valid = false; break; }
                if (orr + occ === nr + nc || orr - occ === nr - nc) { valid = false; break; }
                if (orr === nr || occ === nc) { valid = false; break; }
            }

            if (valid) {
                positions[index] = [nr, nc];
                valids += countValidCombos(pieces, positions, index + 1);
                positions[index] = [r, c];
            }
        }
    }

    return valids;
}

