public TreeNode mergeTrees(List<TreeNode> trees) {
    while (trees.size() > 1) {
        TreeNode tree1 = trees.remove(trees.size() - 1);
        TreeNode tree2 = trees.remove(trees.size() - 1);

        if (tree1.val < tree2.val) {
            tree1.right = tree2;
            trees.add(tree1);
        } else {
            tree2.right = tree1;
            trees.add(tree2);
        }
    }
    return trees.isEmpty() ? null : trees.get(0);
}

