        long long int temp = dp[1];
        dp[1] = (dpf[1] * 2) % mod;
        dp[0] = temp;
        dpf[1] = (dpf[1] + dpf[0]) % mod;
        dpf[0] = (dpf[0] + temp) % mod;
    }

    return (dp[m == 1] * dpf[n == 1]) % mod;
}

