#include <vector>
#include <algorithm>

int maxScore(std::vector<std::vector<int>>& points) {
    int m = points.size(), n = points[0].size();
    std::vector<std::vector<int>> dp(m, std::vector<int>(n));
    dp[0] = points[0];

    for (int r = 1; r < m; r++) {
        for (int c = 0; c < n; c++) {
            int score = points[r][c];
            for (int c_prev = 0; c_prev < n; c_prev++) {
                dp[r][c] = std::max(dp[r][c], dp[r - 1][c_prev] + score - abs(c - c_prev));
            }
        }
    }

    return *std::max_element(dp[m - 1].begin(), dp[m - 1].end());
}

