java_code:
import java.util.ArrayList;
import java.util.List;

public class Solution {
    private static final int M = 17;
    private final List<List<Integer>> tr = new ArrayList<>();

    public int[] maxGeneticDifference(int[] parents, int[][] queries) {
        int n = parents.length;
        List<List<Integer>> edges = new ArrayList<>(n);
        for (int i = 0; i < n; ++i) {
            edges.add(new ArrayList<>());
        }
        int root = -1;
        for (int i = 0; i < n; ++i) {
            if (parents[i] == -1) {
                root = i;
            } else {
                edges.get(parents[i]).add(i);
            }
        }

        tr.add(new ArrayList<>(2));
        tr.get(0).add(0);
        tr.get(0).add(0);
        int[] ans = new int[n];
        dfs(root, 0, edges, ans);

        int[] result = new int[queries.length];
        for (int i = 0; i < queries.length; ++i) {
            result[i] = ans[queries[i][0]] ^ queries[i][1];
        }
        return result;
    }

    private void insert(int x) {
        int u = 0;
        for (int i = M - 1; i >= 0; --i) {
            int v = (x >> i) & 1;
            if (tr.get(u).get(v) == 0) {
                tr.get(u).set(v, tr.size());
                List<Integer> newRow = new ArrayList<>(2);
                newRow.add(0);
                newRow.add(0);
                tr.add(newRow);
            }
            u = tr.get(u).get(v);
        }
    }

    private int query(int x, int y) {
        int u = 0, ans = 0;
        for (int i = M - 1; i >= 0; --i) {
            int v = ((x >> i) & 1) ^ 1;
            if (tr.get(u).get(v) == 0) v ^= 1;
            ans |= (y = (y << 1) | v);
            u = tr.get(u).get(v);
        }
        return ans;
    }

    private void dfs(int u, int tree, List<List<Integer>> g, int[] ans) {
        insert(tree ^= u);
        ans[u] = query(tree);
        for (int v : g.get(u)) {
            dfs(v, tree, g, ans);
        }
    }
}

cpp_code:
#include <vector>
#include <bitset>

using namespace std;

const int M = 17;
vector<int> tr[1 << M];

void insert(int x) {
    int u = 0;
    for (int i = M - 1; i >= 0; --i) {
        int v = (x >> i) & 1;
        if (!tr[u][v]) tr[u][v] = tr.size(), tr.emplace_back(2);
        u = tr[u][v];
    }
}

int query(int x, int y = 0) {
    int u = 0, ans = 0;
    for (int i = M - 1; i >= 0; --i) {
        int v = ((x >> i) & 1) ^ 1;
        if (!tr[u][v]) v ^= 1;
        ans |= (y = (y << 1) | v);
        u = tr[u][v];
    }
    return ans;
}

void dfs(int u, int tree = 0, vector<vector<int>>& g = {}, vector<int>& ans = {}) {
    insert(tree ^= u);
    ans[u] = query(tree);
    for (int v : g[u]) dfs(v, tree, g, ans);
}

vector<int> maxGeneticDifference(vector<int>& parents, vector<vector<int>>& queries) {
    int n = parents.size();
    vector<vector<int>> edges(n);
    int root;
    for (int i = 0; i < n; ++i) {
        if (parents[i] == -1) {
            root = i;
        } else {
            edges[parents[i]].push_back(i);
        }
    }
    vector<int> ans(n);
    dfs(root, 0, edges, ans);
    vector<int> result(queries.size());
    for (int i = 0; i < queries.size(); ++i) {
        result[i] = ans[queries[i][0]] ^ queries[i][1];
    }
    return result;
}

javascript_code:
const M = 17;
const tr = [[0, 0]];

function insert(x) {
    let u = 0;
    for (let i = M - 1; i >= 0; --i) {
        const v = (x >> i) & 1;
        if (!tr[u][v]) {
            const idx = tr.length;
            tr[u][v] = idx;
            tr.push([0, 0]);
        }
        u = tr[u][v];
    }
}

function query(x, y = 0) {
    let u = 0;
    let ans = 0;
    for (let i = M - 1; i >= 0; --i) {
        let v = ((x >> i) & 1) ^ 1;
        if (!tr[u][v]) v ^= 1;
        ans |= (y = (y << 1) | v);
        u = tr[u][v];
    }
    return ans;
}

function dfs(u, tree = 0, g = [], ans = []) {
    insert(tree ^= u);
    ans[u] = query(tree);
    for (const v of g[u]) {
        dfs(v, tree, g, ans);
    }
}

function maxGeneticDifference(parents, queries) {
    const n = parents.length;
    const edges = Array.from({length: n}, () => []);
    let root = -1;
    for (let i = 0; i < n; ++i) {
        if (parents[i] === -1) {
            root = i;
        } else {
            edges[parents[i]].push(i);
        }
    }

    const ans = Array(n).fill(0);
    dfs(root, 0, edges, ans);

    const result = queries.map(([node, val]) => ans[node] ^ val);
    return result;
}

