using namespace std;

vector<int> maxPrices(const vector<vector<int>>& items, const vector<int>& queries) {
  vector<int> answer(queries.size());
  vector<int> sorted_items(items.size(), 0);

  for (const auto& item : items) {
    sorted_items.push_back(item[0]);
  }
  sort(sorted_items.begin(), sorted_items.end());

  int max_beauty = 0;
  for (int i = 0; i < sorted_items.size(); ++i) {
    max_beauty = max(max_beauty, items[i][1]);
    sorted_items[i] = max_beauty;
  }

  for (int j = 0; j < queries.size(); ++j) {
    int idx = upper_bound(sorted_items.begin(), sorted_items.end(), queries[j]) - sorted_items.begin() - 1;
    answer[j] = idx >= 0 ? sorted_items[idx] : 0;
  }

  return answer;
}

