import java.util.Arrays;

public int maxTasks(int[] tasks, int[] workers, int pills, int strength) {
  Arrays.sort(tasks);
  Arrays.sort(workers);

  int cnt = 0;
  for (int i = 0, j = 0; j < pills; ++j) {
    while (i < tasks.length && tasks[i] > workers[j] + strength) {
      ++i;
    }
    if (i < tasks.length) {
      ++cnt;
      ++i;
    }
  }

  for (int i = 0, j = pills; i < tasks.length && j < workers.length; ++i) {
    if (tasks[i] <= workers[j]) {
      ++cnt;
      ++j;
    }
  }

  return cnt;
}

