};

javascript_code:
class Solution {
    reverseGroup(head, k) {
        if (!head || k === 1) return head;
        let prev = null;
        let cur = head;
        for (let i = 0; i < k; i++) {
            const next = cur.next;
            cur.next = prev;
            prev = cur;
            cur = next;
        }
        head.next = cur;
        return prev;
    }

    reverseEvenGroups(head) {
        const dummy = new ListNode(0);
        dummy.next = head;
        let prev = dummy;
        let n = 0;
        for (let cur = head; cur !== null; cur = cur.next)
            n++;
        for (let i = 1, k = 1; n >= 0 && k <= n; i++, k += i) {
            if (i % 2 === 0) {
                const tail = prev.next;
                let next = prev.next;
                for (let j = 0; j < k; j++)
                    next = next.next;
                prev.next = this.reverseGroup(tail, k);
                tail.next = next;
            }
            n -= k;
            for (let j = 0; j < k && prev !== null; j++)
                prev = prev.next;
        }
        return dummy.next;
    }
}

