function slanted_transposition_cipher(encodedText, rows) {
    if(rows === 1)
        return encodedText;

    const n = encodedText.length;
    const cols = Math.floor((n + rows - 2) / (rows - 1));
    let pos = 0;
    const matrix = new Array(rows).fill(null).map(() => new Array(cols).fill(' '));
    for(let k = 0; k < cols; ++k) {
        for(let i = 0; i < rows; ++i) {
            if(k % 2 === 0 || i !== 0) {
                matrix[i][k] = encodedText[pos++];
            }
        }
    }
    let originalText = '';
    for(const row of matrix) {
        originalText += row.join('');
    }
    return originalText;
}

