java_code:
import java.util.Arrays;

public int maxCompatibilitySum(int[][] students, int[][] mentors) {
    Arrays.sort(students, (a, b) -> Arrays.toString(a).compareTo(Arrays.toString(b)));
    Arrays.sort(mentors, (a, b) -> Arrays.toString(a).compareTo(Arrays.toString(b)));
    return helper(students, mentors, 0);
}

private int helper(int[][] students, int[][] mentors, int idx) {
    if (idx == students.length)
        return 0;
    int ans = 0;
    for (int i = 0; i < mentors.length; i++) {
        if (mentors[i] != null) {
            int[] temp = mentors[i];
            int count = 0;
            for (int j = 0; j < students[idx].length; j++) {
                if (students[idx][j] == temp[j])
                    count++;
            }
            mentors[i] = null;
            ans = Math.max(ans, count + helper(students, mentors, idx + 1));
            mentors[i] = temp;
        }
    }
    return ans;
}

cpp_code:
#include <vector>
#include <algorithm>

int maxCompatibilitySum(std::vector<std::vector<int>>& students, std::vector<std::vector<int>>& mentors) {
    std::sort(students.begin(), students.end());
    std::sort(mentors.begin(), mentors.end());
    int ans = 0;
    do {
        int cur_sum = 0;
        for (int i = 0; i < students.size(); i++) {
            int match = 0;
            for (int j = 0; j < students[i].size(); j++) {
                if (students[i][j] == mentors[i][j]) match++;
            }
            cur_sum += match;
        }
        ans = std::max(ans, cur_sum);
    } while (std::next_permutation(mentors.begin(), mentors.end()));
    return ans;
}

