std::vector<std::vector<std::string>> deleteDuplicateFolder(std::vector<std::vector<std::string>>& paths) {
    std::unordered_map<std::string, std::unordered_set<std::string>> graph;
    std::unordered_map<std::string, int> count;

    for (const auto& path : paths) {
        std::string serialized_path;
        for (const auto& folder : path) {
            serialized_path += "/" + folder;
            graph[serialized_path].insert(folder);
        }
