    for (const auto& path : paths) {
        std::string serialized_path;
        bool duplicate = false;
        for (const auto& folder : path) {
            serialized_path += "/" + folder;
            if (count[graph[serialized_path]] > 1) {
                duplicate = true;
                break;
            }
        }
        if (!duplicate)
            ans.push_back(path);
    }

    return ans;
}

