boolean hasThreeDivisors(int n) {
    int count = 0;
    for (int i = 1; i <= Math.sqrt(n); i++) {
        if (n % i == 0) {
            if (n / i == i)
                count++;
            else
                count += 2;
        }
        if (count > 3)
            break;
    }
    return count == 3;
}

