public int num_special_subsequences(int[] nums) {
    long zeros = 0, ones = 0, twos = 0;
    int mod = 1000000007;
    for (int num : nums) {
        if (num == 0) {
            zeros = (zeros + 1) % mod;
        } else if (num == 1) {
            ones = (ones + zeros) % mod;
        } else {
            twos = (twos + ones) % mod;
        }
    }
    return (int) twos;
}

