#include <vector>
#include <queue>
using namespace std;

const int MODULO = 1000000007;

int countPaths(int n, vector<vector<int>>& roads) {
    vector<vector<pair<int, int>>> adj_list(n);

    for (auto& road : roads) {
        adj_list[road[0]].emplace_back(road[1], road[2]);
        adj_list[road[1]].emplace_back(road[0], road[2]);
    }

    vector<int> dist(n, 1e9);
    dist[0] = 0;
    vector<int> count(n);
    count[0] = 1;
    priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> pq;
    pq.push({0, 0});

    while (!pq.empty()) {
        int node = pq.top().second;
        int distance = pq.top().first;
        pq.pop();

        if (distance > dist[node]) continue;

        for (auto& neighbor : adj_list[node]) {
            int next_node = neighbor.first;
            int edge_distance = neighbor.second;

            if (distance + edge_distance > dist[next_node]) continue;

            if (distance + edge_distance == dist[next_node]) {
                count[next_node] = (count[next_node] + count[node]) % MODULO;
            } else {
                count[next_node] = count[node];
                dist[next_node] = distance + edge_distance;
                pq.push({dist[next_node], next_node});
            }
        }
    }

    return count[n - 1];
}

