const MODULO = 1000000007;

function countPaths(n, roads) {
    const adjList = Array.from({ length: n }, () => []);

    for (const [u, v, time] of roads) {
        adjList[u].push([v, time]);
        adjList[v].push([u, time]);
    }

    const dist = new Array(n).fill(Number.MAX_VALUE);
    dist[0] = 0;
    const count = new Array(n).fill(0);
    count[0] = 1;
    const pq = [[0, 0]];

    while (pq.length > 0) {
        pq.sort((a, b) => a[0] - b[0]);
        const [distance, node] = pq.shift();

        if (distance > dist[node]) continue;

        for (const [nextNode, edgeDistance] of adjList[node]) {
            if (distance + edgeDistance > dist[nextNode]) continue;

            if (distance + edgeDistance === dist[nextNode]) {
                count[nextNode] = (count[nextNode] + count[node]) % MODULO;
            } else {
                count[nextNode] = count[node];
                dist[nextNode] = distance + edgeDistance;
                pq.push([dist[nextNode], nextNode]);
            }
        }
    }

    return count[n - 1];
}

