def find_secret_sharers(n, meetings, first_person):
    secret_holders = [-1] * n
    secret_holders[0] = 0
    secret_holders[first_person] = 0

    meetings.sort(key=lambda x: x[2])

    for x, y, time in meetings:
        if secret_holders[x] != -1 and secret_holders[x] <= time:
            secret_holders[y] = time
        if secret_holders[y] != -1 and secret_holders[y] <= time:
            secret_holders[x] = time

    return [i for i in range(n) if secret_holders[i] != -1]

javascript_code:
function findSecretSharers(n, meetings, firstPerson) {
    let secret_holders = Array(n).fill(-1);
    secret_holders[0] = 0;
    secret_holders[firstPerson] = 0;

    meetings.sort((a, b) => a[2] - b[2]);

    for (let [x, y, time] of meetings) {
        if (secret_holders[x] !== -1 && secret_holders[x] <= time) secret_holders[y] = time;
        if (secret_holders[y] !== -1 && secret_holders[y] <= time) secret_holders[x] = time;
    }

    return secret_holders.reduce((result, has_secret, i) => {
        if (has_secret !== -1) result.push(i);
        return result;
    }, []);
}

