import java.util.Arrays;

public int minStonesRemaining(int[] piles, int k) {
    for (int i = 0; i < k; i++) {
        int max_pile_index = 0;
        for (int j = 1; j < piles.length; j++) {
            if (piles[j] > piles[max_pile_index]) {
                max_pile_index = j;
            }
        }
        piles[max_pile_index] -= piles[max_pile_index] / 2;
    }

    int total_stones = 0;
    for (int pile : piles) {
        total_stones += pile;
    }
    return total_stones;
}

