int minStonesRemaining(int piles[], int n, int k) {
    for (int i = 0; i < k; i++) {
        int max_pile_index = std::distance(piles, std::max_element(piles, piles + n));
        piles[max_pile_index] = piles[max_pile_index] - (piles[max_pile_index] / 2);
    }

    int total_stones = 0;
    for (int i = 0; i < n; i++) {
        total_stones += piles[i];
    }
    return total_stones;
}

