public int minSwaps(String s) {
    int openBrackets = 0;
    int swaps = 0;

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);

        if (c == '[') {
            openBrackets++;
        } else {
            if (openBrackets == 0) {
                swaps++;
                openBrackets++;
            } else {
                openBrackets--;
            }
        }
    }

    return swaps;
}

