import java.util.Arrays;

public int[] longestObstacleCourse(int[] obstacles) {
    int[] ans = new int[obstacles.length], active = new int[obstacles.length];
    int activeLen = 0;
    for (int i = 0; i < obstacles.length; i++) {
        int idx = Arrays.binarySearch(active, 0, activeLen, obstacles[i] + 1);
        idx = idx < 0 ? -idx - 1 : idx;
        ans[i] = idx + 1;
        if (idx == activeLen) {
            active[activeLen++] = obstacles[i];
        } else {
            active[idx] = obstacles[i];
        }
    }
    return ans;
}

cpp_code:
#include <vector>
#include <algorithm>

std::vector<int> longest_obstacle_course(std::vector<int>& obstacles) {
    std::vector<int> ans(obstacles.size()), active;
    for (int i = 0; i < obstacles.size(); ++i) {
        auto it = std::upper_bound(active.begin(), active.end(), obstacles[i]);
        ans[i] = (it - active.begin()) + 1;
        if (it == active.end()) {
            active.push_back(obstacles[i]);
        } else {
            *it = obstacles[i];
        }
    }
    return ans;
}

