            evens.push_back(num);
        } else {
            odds.push_back(num);
        }
    }
    sort(evens.rbegin(), evens.rend());
    sort(odds.rbegin(), odds.rend());

    int sum = 0;
    for (int i = 0; i < k && !evens.empty(); i++) {
        sum += evens.back();
        evens.pop_back();
    }

    for (int i = 0; i < k - 1 && !odds.empty(); i += 2) {
        int first = odds.back();
        odds.pop_back();
        if (!odds.empty()) {
            int second = odds.back();
            odds.pop_back();
            sum += first + second;
        }
    }

    if (sum % 2 == 0) {
        return sum;
    } else {
        return -1;
    }
}

