def largest_even_sum(nums, k):
    evens = sorted([num for num in nums if num % 2 == 0], reverse=True)
    odds = sorted([num for num in nums if num % 2 != 0], reverse=True)

    sum = 0
    for _ in range(k):
        if evens:
            sum += evens.pop()

    for _ in range(0, k - 1, 2):
        if odds:
            first = odds.pop()
            if odds:
                second = odds.pop()
                sum += first + second

    return sum if sum % 2 == 0 else -1

javascript_code:
function largestEvenSum(nums, k) {
  const evens = nums.filter(num => num % 2 === 0).sort((a, b) => b - a);
  const odds = nums.filter(num => num % 2 !== 0).sort((a, b) => b - a);

  let sum = 0;
  for (let i = 0; i < k && evens.length > 0; i++) {
    sum += evens.pop();
  }

  for (let i = 0; i < k - 1 && odds.length > 0; i += 2) {
    let first = odds.pop();
    if (odds.length > 0) {
      let second = odds.pop();
      sum += first + second;
    }
  }

  return sum % 2 === 0 ? sum : -1;
}

