function minNonZeroProduct(p) {
    const MOD = 1e9 + 7;
    let prod = 1;
    let a = (1n << BigInt(p)) - 2n;
    let b = ((1n << BigInt(p)) - 1n) % MOD;

    while (a > 0) {
        if (a % 2n == 1n) {
            prod = (prod * b) % MOD;
        }
        b = (b * b) % MOD;
        a /= 2n;
    }
    return prod;
}

