def can_reach_bottom(grid, row, col):
    if row == len(grid) - 1:
        return True
    grid[row][col] = 1

    directions = [(-1, 0), (0, 1), (1, 0), (0, -1)]

    for dr, dc in directions:
        nr, nc = row + dr, col + dc
        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and grid[nr][nc] == 0:
            if can_reach_bottom(grid, nr, nc):
                return True

    return False

def latestDayToCross(row, col, cells):
    grid = [[0] * col for _ in range(row)]
    ans = 0

    for day, cell in enumerate(cells):
        grid[cell[0] - 1][cell[1] - 1] = 1

        found = False
        for j in range(col):
            if grid[0][j] == 0 and can_reach_bottom(grid, 0, j):
                found = True
                break

        if not found:
            ans = day
            break

    return ans

javascript_code:
function canReachBottom(grid, row, col) {
    if (row === grid.length - 1) return true;
    grid[row][col] = 1;

    const directions = [[-1, 0], [0, 1], [1, 0], [0, -1]];

    for (const [dr, dc] of directions) {
        const nr = row + dr;
        const nc = col + dc;
        if (nr >= 0 && nc >= 0 && nr < grid.length && nc < grid[0].length && grid[nr][nc] === 0) {
            if (canReachBottom(grid, nr, nc)) return true;
        }
    }

    return false;
}

function latestDayToCross(row, col, cells) {
    const grid = Array.from({ length: row }, () => Array(col).fill(0));
    let ans = 0;

    for (const [i, cell] of cells.entries()) {
        grid[cell[0] - 1][cell[1] - 1] = 1;

        let found = false;
        for (let j = 0; j < col; ++j) {
            if (grid[0][j] === 0 && canReachBottom(grid, 0, j)) {
                found = true;
                break;
            }
        }

        if (!found) {
            ans = i;
            break;
        }
    }
    return ans;
}

