using namespace std;

class LockingTree {
public:
    vector<int> parent;
    vector<unordered_set<int>> children;
    vector<int> locks;

    LockingTree(vector<int>& parent) : parent(parent) {
        children.resize(parent.size());
        locks.resize(parent.size(), -1);
        for(int i = 1; i < parent.size(); i++)
            children[parent[i]].insert(i);
    }

    bool lock(int num, int user) {
        if(locks[num] == -1) {
            locks[num] = user;
            return true;
        }
        return false;
    }

    bool unlock(int num, int user) {
        if(locks[num] == user) {
            locks[num] = -1;
            return true;
        }
        return false;
    }

    bool upgrade(int num, int user) {
        if(locks[num] != -1) return false;

        int cur = num;
        while(cur != -1) {
            if(locks[cur] != -1) return false;
            cur = parent[cur];
        }

        bool locked_descendant = false;
        function<bool(int)> has_locked_descendants = [&](int node) {
            for(int child : children[node]) {
                if(locks[child] != -1) {
                    locked_descendant = true;
                    locks[child] = -1;
                }
                has_locked_descendants(child);
            }
            return locked_descendant;
        };

        if(has_locked_descendants(num)) {
            locks[num] = user;
            return true;
        }
        return false;
    }
};

