class LockingTree {
    constructor(parent) {
        this.parent = parent;
        this.children = Array(parent.length).fill().map(() => new Set());
        this.locks = Array(parent.length).fill(-1);
        for(let i = 1; i < parent.length; i++)
            this.children[parent[i]].add(i);
    }

    lock(num, user) {
        if(this.locks[num] === -1) {
            this.locks[num] = user;
            return true;
        }
        return false;
    }

    unlock(num, user) {
        if(this.locks[num] === user) {
            this.locks[num] = -1;
            return true;
        }
        return false;
    }

    upgrade(num, user) {
        if(this.locks[num] !== -1) return false;

        let cur = num;
        while(cur !== -1) {
            if(this.locks[cur] !== -1) return false;
            cur = this.parent[cur];
        }

        const lockedDescendant = this._hasLockedDescendants(num);
        if(lockedDescendant) {
            this.locks[num] = user;
        }
        return lockedDescendant;
    }

    _hasLockedDescendants(node) {
        let lockedDescendant = false;
        for(const child of this.children[node]) {
            if(this.locks[child] !== -1) {
                lockedDescendant = true;
                this.locks[child] = -1;
            }
            lockedDescendant = lockedDescendant || this._hasLockedDescendants(child);
        }
        return lockedDescendant;
    }
}

