def numberOfGoodSubsets(nums: list[int]) -> int:
    MOD = 10**9 + 7

    def is_prime(n: int) -> bool:
        if n <= 1:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    primes = [i for i in range(2, 91) if is_prime(i)]
    cnt = [0] * 100
    for n in nums:
        cnt[n] += 1

    dp = [0] * (1 << 20)
    dp[0] = 1

    for i in range(30, 0, -1):
        if cnt[i] == 0:
            continue
        mask = [j for j in primes if i % j == 0]
        i = i // j
        if i > 1:
            continue

        m = 0
        for j in mask:
            m |= 1 << (j - 2)

        for j in range(len(dp)-1, -1, -1):
            if dp[j] == 0:
                continue
            cur = 1
            for k in range(cnt[m]):
                cur = (cur * 2) % MOD
                dp[j | m] = (dp[j | m] + dp[j] * cur) % MOD

    ans = sum(dp) % MOD
    ans = (ans - dp[0] + MOD) % MOD
    return (ans * (1 << (cnt[1] - 1))) % MOD

