function numberOfGoodSubsets(nums) {
    const MOD = 1e9 + 7;

    function isPrime(n) {
        if (n <= 1) return false;
        for (let i = 2; i ** 2 <= n; i++) {
            if (n % i === 0) return false;
        }
        return true;
    }

    const primes = [];
    for (let i = 2; i <= 90; i++) {
        if (isPrime(i)) primes.push(i);
    }

    const cnt = Array(100).fill(0);
    nums.forEach(n => cnt[n]++);

    const dp = Array(1 << 20).fill(0);
    dp[0] = 1;

    for (let i = 30; i > 0; i--) {
        if (cnt[i] === 0) continue;
        const mask = [];
        primes.forEach(j => {
            if (i % j === 0) {
                mask.push(j);
                while (i % j === 0) i /= j;
            }
        });
        if (i > 1) continue;

        let m = 0;
        mask.forEach(j => m |= 1 << (j - 2));

        for (let j = dp.length - 1; j >= 0; j--) {
            if (dp[j] === 0) continue;
            let cur = 1;
            for (let k = 0; k < cnt[m]; k++) {
                cur = (cur * 2) % MOD;
                dp[j | m] = (dp[j | m] + dp[j] * cur) % MOD;
            }
        }
    }

    let ans = 0;
    dp.forEach(n => ans = (ans + n) % MOD);

    ans = (ans - dp[0] + MOD) % MOD;
    return (ans * (1 << (cnt[1] - 1))) % MOD;
}

