    for (int i = 0; i < m; ++i) {
        fill(new_dp.begin(), new_dp.end(), 0);
        for (int j = 0; j < n; ++j) {
            for (int k = 0; k + mat[i][j] < 4901; ++k) {
                new_dp[k + mat[i][j]] |= dp[k];
            }
        }
        dp.swap(new_dp);
