#include <vector>
#include <map>
#include <algorithm>

std::vector<int> recoverArray(int n, std::vector<int>& sums) {
    std::multiset<int> set(sums.begin(), sums.end());
    std::vector<int> ans(n);
    for (int i = 0; i < n; ++i) {
        int num = *next(set.begin());
        set.erase(set.begin());
        for (int prevNum : ans) {
            set.erase(set.find(num - prevNum));
        }
        ans[i] = num;
    }
    return ans;
}

