    const ans = [];
    for (let i = 0; i < n; ++i) {
        const [num, count] = [...counter.entries()].sort((a, b) => b[1] - a[1])[0];
        counter.set(num, count - 1);
        for (const prevNum of ans) {
            const prevCount = counter.get(num - prevNum);
            if (prevCount === 1) {
                counter.delete(num - prevNum);
            } else {
                counter.set(num - prevNum, count - 1);
            }
        }
        ans.push(num);
    }
    return ans;
}

