public int minOperations(int[] arr, int k) {
    int[] dp = new int[arr.length];
    for (int i = k; i < arr.length; i++) {
        dp[i] = Math.max(dp[i - k] + 1 - (arr[i] - arr[i - k]), 0);
    }
    return Arrays.stream(dp).sum();
}

