    for (int task : tasks) {
        bool added = false;
        for (int& session : sessions) {
            if (session + task <= sessionTime) {
                session += task;
                added = true;
                break;
            }
        }

        if (!added) {
            sessions.push_back(task);
        }
    }

    return sessions.size();
}

