public int numDistinct(String binary) {
    int mod = 1000000007;
    int zero_count = 0, ones_count = 0;

    for (char c : binary.toCharArray()) {
        if (c == '0') {
            zero_count = (zero_count + ones_count) % mod;
        } else {
            ones_count = (ones_count * 2 + 1) % mod;
        }
    }
    return zero_count;
}

