int minOperations(vector<int>& nums) {
    sort(nums.begin(), nums.end());
    nums.erase(unique(nums.begin(), nums.end()), nums.end());
    int n = nums.size();
    int ans = n;
    for (int i = 0; i < n; ++i) {
        int j = upper_bound(nums.begin() + i, nums.end(), nums[i] + n - 1) - nums.begin();
        ans = min(ans, n - (j - i));
    }
    return ans;
}

