java_code:
public boolean canSortUsingSwap(int[] nums) {
    for (int i = 1; i < nums.length; i++) {
        if (nums[i] < nums[i - 1]) {
            int temp = nums[i];
            nums[i] = nums[i - 1];
            nums[i - 1] = temp;
            if (isSorted(nums)) {
                return true;
            }
            temp = nums[i];
            nums[i] = nums[i - 1];
            nums[i - 1] = temp;
        }
    }
    return false;
}

private boolean isSorted(int[] nums) {
    for (int i = 1; i < nums.length; i++) {
        if (nums[i] < nums[i - 1]) {
            return false;
        }
    }
    return true;
}

cpp_code:
#include <vector>

bool canSortUsingSwap(std::vector<int>& nums) {
    for (size_t i = 1; i < nums.size(); i++) {
        if (nums[i] < nums[i - 1]) {
            std::swap(nums[i], nums[i - 1]);
            if (std::is_sorted(nums.begin(), nums.end())) {
                return true;
            }
            std::swap(nums[i], nums[i - 1]);
        }
    }
    return false;
}

