function canSortUsingSwap(nums) {
    function isSorted(arr) {
        for (let i = 1; i < arr.length; i++) {
            if (arr[i] < arr[i - 1]) {
                return false;
            }
        }
        return true;
    }

    for (let i = 1; i < nums.length; i++) {
        if (nums[i] < nums[i - 1]) {
            [nums[i], nums[i - 1]] = [nums[i - 1], nums[i]];
            if (isSorted(nums)) {
                return true;
            }
            [nums[i], nums[i - 1]] = [nums[i - 1], nums[i]];
        }
    }
    return false;
}

