public int maxInvited(int[] favorite) {
    int[] inDegree = new int[favorite.length];
    for (int fav : favorite) {
        inDegree[fav]++;
    }
    int result = 0;
    for (int degree : inDegree) {
        result += Math.max(degree - 1, 0);
    }
    return Math.min(result + 2, favorite.length);
}

