#include <vector>
#include <set>
using namespace std;

void dfs(int node, const vector<int>& parents, const vector<int>& nums, vector<set<int>>& tree, vector<int>& ans) {
    tree[node].insert(nums[node]);
    for (int i = 1; i < (int)parents.size(); ++i) {
        if (parents[i] == node) {
            dfs(i, parents, nums, tree, ans);
            tree[node].insert(tree[i].begin(), tree[i].end());
        }
    }
    int missing = 1;
    while (tree[node].count(missing)) ++missing;
    ans[node] = missing;
}

vector<int> smallestMissingValueSubtree(vector<int>& parents, vector<int>& nums) {
    int n = parents.size();
    vector<int> ans(n);
    vector<set<int>> tree(n);

    dfs(0, parents, nums, tree, ans);
    return ans;
}

python_code:
def smallest_missing_value_subtree(parents, nums):
    def dfs(node, parents, nums, tree, ans):
        tree[node].add(nums[node])
        for i in range(1, len(parents)):
            if parents[i] == node:
                dfs(i, parents, nums, tree, ans)
                tree[node].update(tree[i])
        missing = 1
        while missing in tree[node]:
            missing += 1
        ans[node] = missing

    n = len(parents)
    ans = [0] * n
    tree = [set() for _ in range(n)]

    dfs(0, parents, nums, tree, ans)
    return ans

javascript_code:
function smallestMissingValueSubtree(parents, nums) {
    const n = parents.length;
    const ans = new Array(n).fill(0);
    const tree = Array.from({ length: n }, () => new Set());

    function dfs(node, parents, nums, tree, ans) {
        tree[node].add(nums[node]);
        for (let i = 1; i < parents.length; ++i) {
            if (parents[i] === node) {
                dfs(i, parents, nums, tree, ans);
                tree[node] = new Set([...tree[node], ...tree[i]]);
            }
        }
        let missing = 1;
        while (tree[node].has(missing)) ++missing;
        ans[node] = missing;
    }

    dfs(0, parents, nums, tree, ans);
    return ans;
}

