public int countPairs(List<String> nums, String target) {
    int count = 0;
    for (int i = 0; i < nums.size(); i++) {
        for (int j = i + 1; j < nums.size(); j++) {
            if (nums.get(i).concat(nums.get(j)).equals(target) || nums.get(j).concat(nums.get(i)).equals(target)) {
                count++;
            }
        }
    }
    return count;
}

