    vector<int> count(2, 0);

    for (int end = 0; end < n; ++end) {
        maxCount = max(maxCount, ++count[answerKey[end] == 'T']);

        if (end - start + 1 - maxCount > k) {
            count[answerKey[start] == 'T']--;
            start++;
        }

        maxLen = max(maxLen, end - start + 1);
    }

    return maxLen;
}

