    start, max_len, max_count = 0, 0, 0
    count = {'T': 0, 'F': 0}

    for end in range(n):
        max_count = max(max_count, count.__setitem__(answer_key[end], count[answer_key[end]] + 1))

        if end - start + 1 - max_count > k:
            count[answer_key[start]] -= 1
            start += 1

        max_len = max(max_len, end - start + 1)

    return max_len

