public int numOfWays(int[] nums, int k) {
    int count = 0, left = 0, right = 0;
    for (int i = 0; i < nums.length; ++i) {
        if (nums[i] < k) ++left;
        if (nums[i] <= k) ++right;
    }

    if (left == nums.length) return 0;
    if (right - left != nums.length - right) return left + 1;
    return left;
}

