int earliestBlooms(vector<int>& plantTime, vector<int>& growTime) {
    int n = plantTime.size();
    vector<pair<int, int>> processTime;
    for (int i = 0; i < n; ++i) {
        processTime.push_back({plantTime[i], growTime[i]});
    }
    sort(processTime.begin(), processTime.end());

    int day = 0;
    int blooms = 0;
    for (auto& p : processTime) {
        day += p.first;
        blooms = max(blooms, day + p.second);
    }
    return blooms;
}

