class DetectSquares {
    constructor() {
        this.points = new Map();
    }

    add(point) {
        if (!this.points.has(point[0])) {
            this.points.set(point[0], new Map());
        }
        const currPoint = this.points.get(point[0]);
        currPoint.set(point[1], (currPoint.get(point[1]) || 0) + 1);
    }

    count(point) {
        let ans = 0;
        if (!this.points.has(point[0])) return ans;
        for (const [x2, countX2] of this.points.get(point[0])) {
            if (x2 === point[1]) continue;
            for (const [y2, countY2] of this.points.get(x2)) {
                if (y2 === point[1] || Math.abs(x2 - point[1]) !== Math.abs(y2 - point[0])) continue;
                ans += countX2 * countY2 * (this.points.get(point[0]).get(y2) || 0);
            }
        }
        return ans;
    }
}

