#include <string>

std::string longestSubsequenceRepeatedK(const std::string& s, int k) {
    int counts[26] = {0};
    for (char c : s)
        counts[c - 'a'] += 1;
    std::string seq;
    for (int i = 25; i >= 0; --i)
        seq += std::string(counts[i] / k, 'a' + i);
    return seq;
}

