function longestSubsequenceRepeatedK(s, k) {
    const counts = new Array(26).fill(0);
    for (const c of s)
        counts[c.charCodeAt(0) - 'a'.charCodeAt(0)]++;
    let seq = '';
    for (let i = 25; i >= 0; i--)
        seq += String.fromCharCode('a'.charCodeAt(0) + i).repeat(Math.floor(counts[i] / k));
    return seq;
}

