public int numberOfBalancedRanges(int[] nums1, int[] nums2) {

    int n = nums1.length;
    int[][][][] dp = new int[n][n][n][3];
    dp[0][0][0][0] = 2;
    int[] sums1 = new int[n + 1], sums2 = new int[n + 1];
    for (int i = 0, s1 = 0, s2 = 0; i < nums1.length; i++) {
        s1 += nums1[i];
        s2 += nums2[i];
        sums1[i + 1] = s1;
        sums2[i + 1] = s2;
    }
    int MOD = 1_000_000_007;

    int ans = 0;
    for (int r = 0; r < nums1.length; ++r) {
        for (int l = r + 1; --l >= 0;) {
            for (int k = l; k <= r; ++k) {
                int leftSum1 = sums1[l];
                int rightSum1 = sums1[n] - sums1[k + 1];
                int leftSum2 = sums2[l];
                int rightSum2 = sums2[n] - sums2[r + 1];

                if (leftSum1 + rightSum2 == leftSum2 && leftSum1 + rightSum1 == rightSum2) {
                    for (int last = 0; last <= 2; ++last) {
                        ans += dp[l][r][k][last];
                        ans %= MOD;
                        int next = last == 2 ? k + 1 : k;
                        dp[next][k != 0 ? k : r + 1][k != 0 ? k - 1 : r + 2][last] +=
                            dp[l][r][k][last];
                        dp[l][r][k][last] =
                            (dp[l][r][k][last] + (!last || last == 2)) % MOD;
                    }
                }
            }
        }
    }
    return ans;
}

cpp_code:
int numberOfBalancedRanges(vector<int>& nums1, vector<int>& nums2) {
    int MOD = 1e9 + 7, transitions[101][101][101][3] = {}; // <l1, r1, k1, last> = Number of Ways
    transitions[0][0][0][0] = 2;
    int sum1[101] = {}, sum2[101] = {};
    for (int i = 0, s1 = 0, s2 = 0; i < nums1.size(); ++i) {
        s1 += nums1[i], s2 += nums2[i];
        sum1[i + 1] = s1, sum2[i + 1] = s2;
    }
    auto valid = [&](int l, int r, int k) {
        int leftN1 = sum1[nums1.size()] - sum1[k + 1];
        return sum1[l] + sum2[r] - sum2[l] == sum2[k] &&
               sum2[l] + sum1[nums1.size()] - sum1[r + 1] == rightN1;
    };
    int ans = 0;
    for (int r = 0; r < nums1.size(); ++r) {
        for (int l = r + 1; --l >= 0;) {
            for (int k = l; k <= r; ++k) {
                if (valid(l, r, k)) {
                    for (int last = 0; last <= 2; ++last) {
                        ans += transitions[l][r][k][last], ans %= MOD;
                        int next = last == 2 ? k + 1 : k;
                        transitions[next][k ? k : r + 1][k ? k - 1 : r + 2][last] +=
                            transitions[l][r][k][last];
                        transitions[l][r][k][last] =
                            (transitions[l][r][k][last] + (!last || last == 2)) % MOD;
                    }
                }
            }
        }
    }
    return ans;
}

javascript_code:
var numberOfBalancedRanges = function (nums1, nums2) {
    const MOD = 1e9 + 7;
    const dp = Array.from({ length: 101 }, () =>
        Array.from({ length: 101 }, () => Array(101).fill(0))
    );
    dp[0][0] = 2;

    const sums1 = [0];
    const sums2 = [0];
    for (let i = 0; i < nums1.length; ++i) {
        sums1.push(sums1[i] + nums1[i]);
        sums2.push(sums2[i] + nums2[i]);
    }

    let ans = 0;
    for (let r = 0; r < nums1.length; ++r) {
        for (let l = r + 1; --l >= 0;) {
            for (let k = l; k <= r; ++k) {
                const leftSum1 = sums1[l];
                const rightSum1 = sums1[nums1.length] - sums1[k + 1];
                const leftSum2 = sums2[l];
                const rightSum2 = sums2[nums1.length] - sums2[r + 1];

                if (
                    leftSum1 + rightSum2 == leftSum2 &&
                    leftSum1 + rightSum1 == rightSum2
                ) {
                    for (let last = 0; last <= 2; ++last) {
                        ans += dp[l][r][k][last];
                        ans %= MOD;
                        const next = last == 2 ? k + 1 : k;
                        dp[next][k ? k : r + 1][k ? k - 1 : r + 2][last] +=
                            dp[l][r][k][last];
                        dp[l][r][k][last] =
                            (dp[l][r][k][last] + (!last || last == 2)) % MOD;
                    }
                }
            }
        }
    }
    return ans;
};

