public int maxDifference(int[] nums) {
    int min_val = nums[0];
    int max_diff = -1;

    for (int i = 1; i < nums.length; ++i) {
        if (nums[i] > min_val) {
            max_diff = Math.max(max_diff, nums[i] - min_val);
        } else {
            min_val = nums[i];
        }
    }
    return max_diff;
}

