public int minSecondRobotPoints(int[][] grid) {
    int n = grid[0].length;
    for (int r = 0; r < 2; ++r) {
        for (int c = 1; c < n; ++c) {
            grid[r][c] += grid[r][c - 1];
        }
    }
    int[] dp = {grid[0][n - 1], 0};
    for (int c = n - 2; c >= 0; --c) {
        int[] dpNew = {Math.max(dp[0] - grid[0][c], dp[1] + grid[1][c]), Math.max(dp[1] - grid[1][c], dp[0] + grid[0][c])};
        dp[0] = dpNew[0];
        dp[1] = dpNew[1];
    }
    return Math.max(dp[0], dp[1]);
}

