using namespace std;

vector<int> lonelyNumbers(vector<int>& nums) {
    unordered_map<int, int> count;
    vector<int> result;

    for (int num : nums) {
        count[num]++;
    }

    for (const auto& entry : count) {
        if (entry.second == 1 && count.find(entry.first - 1) == count.end() && count.find(entry.first + 1) == count.end()) {
            result.push_back(entry.first);
        }
    }

    return result;
}

