int minStraightLines(vector<vector<int>>& points) {
    int len = points.size();
    unordered_set<int> uh;
    for (int i = 0; i < len; i++) {
        for (int j = i + 1; j < len; j++) {
            if (i != j) {
                int delta_x = points[j][0] - points[i][0];
                int delta_y = points[j][1] - points[i][1];
                int gcd = __gcd(delta_x, delta_y);
                delta_x /= gcd;
                delta_y /= gcd;
                uh.insert(delta_y * 1000 + delta_x);
            }
        }
    }
    return uh.size();
}

