from math import gcd
from itertools import combinations

def minStraightLines(points):
    lines = set()
    for p1, p2 in combinations(points, 2):
        dy, dx = p2[1] - p1[1], p2[0] - p1[0]
        g = gcd(dx, dy)
        lines.add((dy // g, dx // g))
    return len(lines)

