        return (b === 0) ? a : gcd(b, a % b);
    }

    for (let i = 0; i < len; i++) {
        for (let j = i + 1; j < len; j++) {
            const deltaX = points[j][0] - points[i][0];
            const deltaY = points[j][1] - points[i][1];
            const g = gcd(deltaY, deltaX);
            const hash = deltaY / g * 1000 + deltaX / g;
            set.add(hash);
        }
    }
    return set.size;
}

