public boolean aliceWins(int[] stones) {
    int sum = 0, count[] = new int[3];
    for (int stone : stones) {
        sum += stone;
        count[stone % 3]++;
    }
    if (sum % 3 != 0) {
        return count[sum % 3] % 2 == 1;
    }
    return count[1] % 2 == 0 || count[2] % 2 == 0 || count[1] == 0 || count[2] == 0;
}

