import java.util.PriorityQueue;

public String smallestSubsequence(String s, int k, char letter, int repetition) {
    StringBuilder result = new StringBuilder();
    int letterCount = 0, n = s.length();
    for (char c : s.toCharArray()) if (c == letter) letterCount++;

    PriorityQueue<Character> pq = new PriorityQueue<>();
    for (int i = 0; i < n; i++) {
        if (s.charAt(i) <= letter || letterCount > repetition) {
            while (!pq.isEmpty() && pq.peek() > s.charAt(i)) {
                if (pq.poll() == letter) letterCount--;
            }
            pq.add(s.charAt(i));
            if (pq.size() > k) pq.poll();
        }
        if (k - pq.size() == repetition) letterCount--;
        repetition = Math.max(0, repetition);
    }

    while (!pq.isEmpty()) {
        result.append(pq.poll());
    }
    return result.toString();
}

cpp_code:
#include <string>
#include <queue>

std::string smallestSubsequence(std::string s, int k, char letter, int repetition) {
    std::string result;
    int letter_count = 0, n = s.length();
    for (char c : s) if (c == letter) letter_count++;

    std::priority_queue<char, std::vector<char>, std::greater<char>> pq;
    for (int i = 0; i < n; i++) {
        if (s[i] <= letter || letter_count > repetition) {
            while (!pq.empty() && pq.top() > s[i]) {
                if (pq.top() == letter) letter_count--;
                pq.pop();
            }
            pq.push(s[i]);
            if (pq.size() > k) pq.pop();
        }
        if (k - pq.size() == repetition) letter_count--;
        repetition = std::max(0, repetition);
    }

    while (!pq.empty()) {
        result.push_back(pq.top());
        pq.pop();
    }
    return result;
}

