function smallestSubsequence(s, k, letter, repetition) {
    let result = "";
    let letterCount = 0, n = s.length;
    for (let c of s) if (c === letter) letterCount++;

    let pq = [];
    for (let i = 0; i < n; i++) {
        if (s[i] <= letter || letterCount > repetition) {
            while (pq.length > 0 && pq[0] > s[i]) {
                if (pq.shift() === letter) letterCount--;
            }
            pq.push(s[i]);
            pq.sort();
            if (pq.length > k) pq.shift();
        }
        if (k - pq.length === repetition) letterCount--;
        repetition = Math.max(0, repetition);
    }

    return pq.join("");
}

