function minOperations(grid, x) {
  const minElement = Math.min(...grid.map(row => Math.min(...row)));
  let minOps = Infinity;

  let base = minElement;
  while (true) {
      let operations = 0;
      let impossible = false;
      for (let row of grid) {
          if (impossible) break;
          for (let cell of row) {
              const diff = Math.abs(cell - base);
              if (diff % x !== 0) {
                  impossible = true;
                  break;
              }
              operations += diff / x;
          }
      }
      if (impossible) break;
      minOps = Math.min(minOps, operations);
      base -= 1;
  }

  return minOps === Infinity ? -1 : minOps;
}

