#include<vector>
#include<algorithm>
using namespace std;

int maxValue(vector<vector<int>>& events) {
    sort(events.begin(), events.end(), [](const vector<int>& a, const vector<int>& b) {
        return a[1] < b[1];
    });

    vector<int> dp(events.size());
    dp[0] = events[0][2];

    for (int i = 1; i < events.size(); i++) {
        int lastNonConflict = -1;
        for (int j = i - 1; j >= 0; j--) {
            if (events[j][1] < events[i][0]) {
                lastNonConflict = j;
                break;
            }
        }

        int includedValue = events[i][2];
        if (lastNonConflict != -1) {
            includedValue += dp[lastNonConflict];
        }

        dp[i] = max(includedValue, dp[i - 1]);
    }

    return dp.back();
}

python_code:
def maxValue(events):
    events.sort(key=lambda a: a[1])

    dp = [0] * len(events)
    dp[0] = events[0][2]

    for i in range(1, len(events)):
        lastNonConflict = -1
        for j in range(i - 1, -1, -1):
            if events[j][1] < events[i][0]:
                lastNonConflict = j
                break

        includedValue = events[i][2]
        if lastNonConflict != -1:
            includedValue += dp[lastNonConflict]

        dp[i] = max(includedValue, dp[i - 1])

    return dp[-1]

javascript_code:
function maxValue(events) {
    events.sort((a, b) => a[1] - b[1]);

    let dp = new Array(events.length);
    dp[0] = events[0][2];

    for (let i = 1; i < events.length; i++) {
        let lastNonConflict = -1;
        for (let j = i - 1; j >= 0; j--) {
            if (events[j][1] < events[i][0]) {
                lastNonConflict = j;
                break;
            }
        }

        let includedValue = events[i][2];
        if (lastNonConflict !== -1) {
            includedValue += dp[lastNonConflict];
        }

        dp[i] = Math.max(includedValue, dp[i - 1]);
    }

    return dp[dp.length - 1];
}

