std::vector<int> platesBetweenCandles(const std::string& s, const std::vector<std::vector<int>>& queries) {
    int n = s.length();
    std::vector<int> prefix(n, 0);
    int plates = 0;

    for (int i = 1; i < n; ++i) {
        prefix[i] = prefix[i - 1];
        if (s[i] == '*' && s[i - 1] == '|') plates++;
        prefix[i] += plates;
    }
    std::vector<int> res;
    for (const auto& q : queries) {
        int left = q[0], right = q[1];
        res.push_back(prefix[right] - (left > 0 ? prefix[left - 1] : 0));
    }
    return res;
}

