public int validMoveCombinations(String[] pieces, int[][] positions) {
    int n = pieces.length;
    int count = 0;

    for(int i = 0; i < n; i++) {
        for(int j = 0; j < n; j++) {
            if(i != j && !(pieces[i].equals("bishop") && (positions[i][0] + positions[i][1]) % 2 != (positions[j][0] + positions[j][1]) % 2)) {
                count++;
            }
        }
    }

    return count;
}

