bool areNumbersIncreasing(std::string s) {
    std::istringstream iss(s);
    std::string token;
    std::vector<int> numbers;

    while (iss >> token) {
        if (isdigit(token[0])) {
            int num = std::stoi(token);
            if (!numbers.empty() && numbers.back() >= num) {
                return false;
            }
            numbers.push_back(num);
        }
    }

    return true;
}

