import heapq

def second_minimum(n: int, edges: List[List[int]], time: int, change: int) -> int:
    adj = [[] for _ in range(n + 1)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    dist = [-1] * (n + 1)
    queue = [(0, 1)]
    dist[1] = 0

    while queue:
        t1, v1 = heapq.heappop(queue)

        if v1 == n:
            return t1

        for v2 in adj[v1]:
            t2 = t1 + time
            waiting = change - (t2 % change) if (t2 // change) % 2 == 1 else 0

            if dist[v2] == -1 or dist[v2] > t2 + waiting:
                if dist[v2] != -1:
                    heapq.heappush(queue, (dist[v2], v2))
                dist[v2] = t2 + waiting
                heapq.heappush(queue, (dist[v2], v2))

    return -1

javascript_code:
function secondMinimum(n, edges, time, change) {
    const adj = new Array(n + 1).fill(null).map(() => []);
    for (const [u, v] of edges) {
        adj[u].push(v);
        adj[v].push(u);
    }

    const dist = new Array(n + 1).fill(-1);
    const queue = [[0, 1]];
    dist[1] = 0;

    while (queue.length > 0) {
        queue.sort((a, b) => a[0] - b[0]);
        const [t1, v1] = queue.shift();

        if (v1 === n) {
            return t1;
        }

        for (const v2 of adj[v1]) {
            const t2 = t1 + time;
            const waiting = (t2 / change) % 2 === 1 ? change - (t2 % change) : 0;

            if (dist[v2] === -1 || dist[v2] > t2 + waiting) {
                if (dist[v2] !== -1) {
                    queue.push([dist[v2], v2]);
                }
                dist[v2] = t2 + waiting;
                queue.push([dist[v2], v2]);
            }
        }
    }

    return -1;
}

