public int maxAndSum(int[] nums, int numSlots, int idx, int used, int sum) {
    if (idx == nums.length) {
        return sum;
    }
    int max_sum = 0;
    for (int i = 1; i <= numSlots; ++i) {
        if ((used & (1 << (i - 1))) == 0) {
            int new_sum = sum + (nums[idx] & i);
            int new_used = (used | (1 << (i - 1)));
            max_sum = Math.max(max_sum, maxAndSum(nums, numSlots, idx + 1, new_used, new_sum));
            if (idx + 1 < nums.length) {
                new_sum = new_sum + (nums[idx + 1] & i);
                max_sum = Math.max(max_sum, maxAndSum(nums, numSlots, idx + 2, new_used, new_sum));
            }
        }
    }
    return max_sum;
}

public int maxAndSum(int[] nums, int numSlots) {
    return maxAndSum(nums, numSlots, 0, 0, 0);
}

