    }

    for (let c = 'a'.charCodeAt(0); c <= 'z'.charCodeAt(0); c++) {
        let char = String.fromCharCode(c);
        if (Math.abs((freq1[char] || 0) - (freq2[char] || 0)) > 3) {
            return false;
        }
    }

    return true;
}

