class Robot {
    int x, y, dir;
    Robot() { x = 0; y = 0; dir = 1; }
    void move(int steps) {
        switch (dir) {
            case 0: y += steps; break;
            case 1: x += steps; break;
            case 2: y -= steps; break;
            case 3: x -= steps; break;
        }
    }
    void turnLeft() { dir = (dir + 3) % 4; }
    void turnRight() { dir = (dir + 1) % 4; }
}

