vector<int> maxBeauty(vector<vector<int>>& items, vector<int>& queries) {
    vector<int> sortedItems(10001, 0);
    for (auto& item : items) {
        sortedItems[item[0]] = max(sortedItems[item[0]], item[1]);
    }

    for (int i = 1; i < sortedItems.size(); ++i) {
        sortedItems[i] = max(sortedItems[i], sortedItems[i-1]);
    }

    vector<int> result;
    for (int query : queries) {
        result.push_back(sortedItems[query]);
    }
    return result;
}

