import java.util.Arrays;

public int maxTasks(int[] tasks, int[] workers, int pills, int strength) {
    Arrays.sort(tasks);
    Arrays.sort(workers);
    int taskIndex = 0;
    int pillIndex = pills;
    int completedTasks = 0;

    for (int workerStrength : workers) {
        while (pillIndex > 0 && workerStrength + strength >= tasks[taskIndex]) {
            workerStrength += strength;
            --pillIndex;
        }

        if (workerStrength >= tasks[taskIndex]) {
            ++taskIndex;
            ++completedTasks;
        }

        if (taskIndex >= tasks.length) {
            break;
        }
    }

    return completedTasks;
}

