from collections import deque

def minOperations(nums, start, goal):
    seen = {start}
    q = deque([start])
    level = 0

    while q:
        size = len(q)
        for i in range(size):
            x = q.popleft()
            if x == goal:
                return level
            for num in nums:
                next_x = x + num
                if 0 <= next_x <= 1000 and next_x not in seen:
                    seen.add(next_x)
                    q.append(next_x)
        level += 1

    return -1

