bool areEncodedStringsEqual(string s1, string s2) {
    string decoded1 = "", decoded2 = "";

    for(int i = 0; i < s1.size(); ++i) {
        if(isdigit(s1[i])) {
            int count = s1[i] - '0';
            while(count--) decoded1 += s1[i - 1];
        } else decoded1 += s1[i];
    }

    for(int i = 0; i < s2.size(); ++i) {
        if(isdigit(s2[i])) {
            int count = s2[i] - '0';
            while(count--) decoded2 += s2[i - 1];
        } else decoded2 += s2[i];
    }

    return decoded1 == decoded2;
}

