def are_encoded_strings_equal(s1: str, s2: str) -> bool:
    decoded1, decoded2 = "", ""

    for i, c in enumerate(s1):
        if c.isdigit():
            count = int(c)
            decoded1 += s1[i - 1] * count
        else:
            decoded1 += c

    for i, c in enumerate(s2):
        if c.isdigit():
            count = int(c)
            decoded2 += s2[i - 1] * count
        else:
            decoded2 += c

    return decoded1 == decoded2

