from collections import defaultdict

def maxQualityRec(adjDict, values, node, timeLeft, visited):
    if timeLeft < 0:
        return float('-inf')

    maxQuality = 0
    visited.add(node)
    for neighbor, time in adjDict[node]:
        adjDict[neighbor].remove((node, time))
        maxQuality = max(maxQuality, maxQualityRec(adjDict, values, neighbor, timeLeft - time, visited))
        adjDict[neighbor].append((node, time))

    visited.remove(node)
    return maxQuality + (values[node] if node not in visited else 0)

def maxQuality(n, values, edges, maxTime):
    adjDict = defaultdict(list)
    for u, v, time in edges:
        adjDict[u].append((v, time))
        adjDict[v].append((u, time))

    visited = set()
    return maxQualityRec(adjDict, values, 0, maxTime, visited)

javascript_code:
function maxQualityRec(adjMatrix, values, node, timeLeft, visited) {
    if (timeLeft < 0) {
        return Number.MIN_SAFE_INTEGER;
    }

    let maxQuality = 0;
    visited.add(node);
    for (let i = 0; i < adjMatrix[node].length; ++i) {
        if (adjMatrix[node][i] !== -1) {
            let time = adjMatrix[node][i];
            let oldValue = adjMatrix[node][i];
            adjMatrix[node][i] = adjMatrix[i][node] = -1;
            maxQuality = Math.max(maxQuality, maxQualityRec(adjMatrix, values, i, timeLeft - time, visited));
            adjMatrix[node][i] = adjMatrix[i][node] = oldValue;
        }
    }
    visited.delete(node);
    return maxQuality + (visited.has(node + 1) ? 0 : values[node]);
}

function maxQuality(n, values, edges, maxTime) {
    let adjMatrix = new Array(n).fill(null).map(() => new Array(n).fill(-1));

    for (let edge of edges) {
        adjMatrix[edge[0]][edge[1]] = adjMatrix[edge[1]][edge[0]] = edge[2];
    }

    let visited = new Set();
    return maxQualityRec(adjMatrix, values, 0, maxTime, visited);
}

