int minBuckets(String street) {
    int buckets = 0, i = 0, n = street.length();
    while(i < n) {
        if(street.charAt(i) == 'H') {
            if (i + 1 < n && street.charAt(i+1) == '.') {
                buckets++;
                i += 2;
            } else if (i + 2 < n && street.charAt(i+2) == '.') {
                buckets++;
                i += 3;
            } else {
                return -1;
            }
        } else {
            i += 1;
        }
    }
    return buckets;
}

