public int countPyramids(int[][] grid) {
    int m = grid.length, n = grid[0].length, count = 0;
    for (int i = 1; i < m - 1; ++i) {
        for (int j = 1; j < n - 1; ++j) {
            if (grid[i][j] == grid[i - 1][j] + grid[i][j - 1] - grid[i - 1][j - 1]
                && grid[i][j] == grid[i + 1][j] + grid[i][j + 1] - grid[i + 1][j + 1]) {
                count += grid[i][j];
            }
        }
    }
    return count;
}

