#include <vector>
#include <string>

std::vector<std::string> cellRange(const std::string& s) {
    int r1 = s[1] - '0';
    int r2 = s[4] - '0';
    int c1 = s[0] - 'A' + 1;
    int c2 = s[3] - 'A' + 1;

    std::vector<std::string> res;
    for (int c = c1; c <= c2; ++c) {
        for (int r = r1; r <= r2; ++r) {
            res.push_back(std::string(1, 'A' + c - 1) + std::to_string(r));
        }
    }
    return res;
}

