    const c2 = s.charCodeAt(3) - 'A'.charCodeAt(0) + 1;

    const res = [];
    for (let c = c1; c <= c2; ++c) {
        for (let r = r1; r <= r2; ++r) {
            res.push(String.fromCharCode('A'.charCodeAt(0) + c - 1) + r.toString());
        }
    }
    return res;
}

