public class ListNode {
   int val;
   ListNode next;
   ListNode(int x) { val = x; }
}

public ListNode reverseEvenGroups(ListNode head) {
    ListNode dummy = new ListNode(-1);
    dummy.next = head;
    ListNode prev = dummy, curr = head;
    int count = 0;
    while (curr != null) {
        count++;
        curr = curr.next;
    }
    curr = head;
    for (int i = 2; i <= count; i += 2) {
        ListNode nextGroupHead = curr;
        for (int j = 0; j < i; j++) {
            if (nextGroupHead == null) break;
            nextGroupHead = nextGroupHead.next;
        }
        ListNode prevGroupTail = prev;
        for (int j = 0; j < i; j++) {
            if (curr == null) break;
            ListNode nextNode = curr.next;
            curr.next = prevGroupTail.next;
            prevGroupTail.next = curr;
            curr = nextNode;
        }
        for (int j = 0; j < i; j++) {
            prev = prev.next;
        }
    }
    return dummy.next;
}

