class ListNode:
    def __init__(self, x):
        self.val = x
        self.next = None

def reverse_even_groups(head: ListNode) -> ListNode:
    dummy = ListNode(-1)
    dummy.next = head
    prev, curr = dummy, head
    count = 0
    while curr:
        count += 1
        curr = curr.next
    curr = head
    i = 2
    while i <= count:
        next_group_head = curr
        for _ in range(i):
            if not next_group_head:
                break
            next_group_head = next_group_head.next
        prev_group_tail = prev
        for _ in range(i):
            if not curr:
                break
            next_node = curr.next
            curr.next = prev_group_tail.next
            prev_group_tail.next = curr
            curr = next_node
        for _ in range(i):
            prev = prev.next
        i += 2
    return dummy.next

