        curr = curr.next;
    }
    curr = head;
    for (let i = 2; i <= count; i += 2) {
        let nextGroupHead = curr;
        for (let j = 0; j < i; j++) {
            if (nextGroupHead === null) break;
            nextGroupHead = nextGroupHead.next;
        }
        let prevGroupTail = prev;
        for (let j = 0; j < i; j++) {
            if (curr === null) break;
            const nextNode = curr.next;
            curr.next = prevGroupTail.next;
            prevGroupTail.next = curr;
            curr = nextNode;
        }
        for (let j = 0; j < i; j++) {
            prev = prev.next;
        }
    }
    return dummy.next;
}

java_code:
public String decodeSlantedCipher(String encodedText, int rows) {
    StringBuilder[] matrix = new StringBuilder[rows];
    for(int i = 0; i < rows; i++) {
        matrix[i] = new StringBuilder("");
    }

    int index = 0;
    for(int diagonal = 0; diagonal < 2 * (rows - 1); diagonal++) {
        for(int row = Math.max(0, diagonal - rows + 1); row <= Math.min(diagonal, rows - 1); row++) {
            if(index < encodedText.length()) {
                matrix[row].append(encodedText.charAt(index++));
            }
        }
    }

    StringBuilder originalText = new StringBuilder();
    for(int i = 0; i < rows; i++) {
        originalText.append(matrix[i]);
    }
    return originalText.toString();
}

cpp_code:
#include <string>
#include <vector>

std::string decodeSlantedCipher(const std::string &encodedText, int rows) {
    std::vector<std::string> matrix(rows, std::string(encodedText.size() / rows + 1, ' '));
    int index = 0;
    for(int diagonal = 0; diagonal < 2 * (rows - 1); ++diagonal) {
        for(int row = std::max(0, diagonal - rows + 1); row <= std::min(diagonal, rows - 1); ++row) {
            if(index < encodedText.size()) {
                matrix[row][diagonal - row] = encodedText[index++];
            }
        }
    }
    std::string originalText;
    for(int i = 0; i < rows; ++i) {
        originalText += matrix[i];
    }
    return originalText;
}

python_code:
def decode_slanted_cipher(encoded_text, rows):
    matrix = ['' for _ in range(rows)]
    index = 0

    for diagonal in range(2 * (rows - 1)):
        for row in range(max(0, diagonal - rows + 1), min(diagonal, rows - 1) + 1):
            if index < len(encoded_text):
                matrix[row] += encoded_text[index]
                index += 1

    return ''.join(matrix)

