from collections import defaultdict

def check_friends(n, restrictions, requests):
    friends = defaultdict(set)
    for a, b in restrictions:
        friends[a].add(b)
        friends[b].add(a)

    result = []
    for a, b in requests:
        if b not in friends[a] and a not in friends[b]:
            friends[a].add(b)
            friends[b].add(a)
            result.append(True)
        else:
            result.append(False)
    return result

