function canFitStamps(grid, stampHeight, stampWidth) {
    let m = grid.length, n = grid[0].length;
    for (let i = 0; i + stampHeight - 1 < m; ++i) {
        for (let j = 0; j + stampWidth - 1 < n; ++j) {
            let canFit = true;
            for (let x = 0; x < stampHeight && canFit; ++x) {
                for (let y = 0; y < stampWidth && canFit; ++y) {
                    if (grid[i + x][j + y] === 1) {
                        canFit = false;
                    }
                }
            }
            if (canFit) {
                return true;
            }
        }
    }
    return false;
}

