import java.util.*;

public List<List<Integer>> arrangePairs(List<List<Integer>> pairs) {
    Map<Integer, List<Integer>> adj = new HashMap<>();
    for (List<Integer> pair : pairs) {
        adj.put(pair.get(0), pair);
    }

    List<List<Integer>> result = new ArrayList<>();
    int start = pairs.get(0).get(0);
    while (!adj.isEmpty()) {
        List<Integer> pair = adj.get(start);
        result.add(pair);
        start = pair.get(1);
        adj.remove(start);
    }

    return result;
}

cpp_code:
#include <vector>
#include <unordered_map>

std::vector<std::vector<int>> arrangePairs(std::vector<std::vector<int>>& pairs) {
    std::unordered_map<int, std::vector<int>> adj;
    for (const auto& pair : pairs) {
        adj[pair[0]] = pair;
    }

    std::vector<std::vector<int>> result;
    int start = pairs[0][0];
    while (!adj.empty()) {
        auto it = adj.find(start);
        result.push_back(it->second);
        start = it->second[1];
        adj.erase(it);
    }

    return result;
}

