function arrangePairs(pairs) {
    const adj = {};
    for (const pair of pairs) {
        adj[pair[0]] = pair;
    }

    const result = [];
    let start = pairs[0][0];
    while (Object.keys(adj).length > 0) {
        const pair = adj[start];
        result.push(pair);
        start = pair[1];
        delete adj[start];
    }

    return result;
}

