def to_base_k(num, k):
    base_k_num = ''
    while num:
        base_k_num = str(num % k) + base_k_num
        num //= k
    return base_k_num

def is_k_mirror(num, k):
    base_10_num = str(num)
    base_k_num = to_base_k(num, k)
    return base_10_num == base_10_num[::-1] and base_k_num == base_k_num[::-1]

def sum_k_mirror_numbers(k, n):
    total = 0
    num = 0
    while n:
        if is_k_mirror(num, k):
            total += num
            n -= 1
        num += 1
    return total

