#include <vector>
#include <queue>
#include <limits>

using namespace std;

int min_weight_subgraph(int n, vector<vector<int>>& edges, int src1, int src2, int dest) {
    vector<vector<pair<int, int>>> adj(n);
    for (auto &edge : edges) {
        adj[edge[0]].emplace_back(edge[1], edge[2]);
    }

    auto dijkstra = [&](int src) {
        vector<int> dist(n, numeric_limits<int>::max());
        priority_queue<pair<int, int>, vector<pair<int, int>>, greater<>> pq;
        dist[src] = 0;
        pq.emplace(0, src);

        while (!pq.empty()) {
            int u = pq.top().second;
            int d = pq.top().first;
            pq.pop();
            if (d != dist[u]) continue;
            for (auto &[v, w] : adj[u]) {
                if (d + w < dist[v]) {
                    dist[v] = d + w;
                    pq.emplace(dist[v], v);
                }
            }
        }

        return dist;
    };

    vector<int> dist1 = dijkstra(src1);
    vector<int> dist2 = dijkstra(src2);

    int res = dist1[dest] + dist2[dest];
    for (auto &edge : edges) {
        int u = edge[0], v = edge[1], w = edge[2];
        res = min(res, dist1[u] + dist2[v] + w);
        res = min(res, dist1[v] + dist2[u] + w);
    }

    return res == numeric_limits<int>::max() ? -1 : res;
}

python_code:
from heapq import heappop, heappush
from sys import maxsize

def dijkstra(src, adj):
    dist = [maxsize] * len(adj)
    dist[src] = 0
    pq = [(0, src)]

    while pq:
        d, u = heappop(pq)
        if d != dist[u]:
            continue
        for v, w in adj[u]:
            if d + w < dist[v]:
                dist[v] = d + w
                heappush(pq, (dist[v], v))

    return dist

def min_weight_subgraph(n, edges, src1, src2, dest):
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    dist1 = dijkstra(src1, adj)
    dist2 = dijkstra(src2, adj)

    res = dist1[dest] + dist2[dest]
    for u, v, w in edges:
        res = min(res, dist1[u] + dist2[v] + w)
        res = min(res, dist1[v] + dist2[u] + w)

    return res if res != maxsize else -1

javascript_code:
function dijkstra(src, adj) {
    const dist = new Array(adj.length).fill(Infinity);
    dist[src] = 0;
    const pq = [[0, src]];

    while (pq.length > 0) {
        const [d, u] = pq.shift();
        if (d !== dist[u]) continue;
        for (const [v, w] of adj[u]) {
            if (d + w < dist[v]) {
                dist[v] = d + w;
                pq.push([dist[v], v]);
                pq.sort((a, b) => a[0] - b[0]);
            }
        }
    }

    return dist;
}

function minWeightSubgraph(n, edges, src1, src2, dest) {
    const adj = Array.from({ length: n }, () => []);
    for (const [u, v, w] of edges) {
        adj[u].push([v, w]);
    }

    const dist1 = dijkstra(src1, adj);
    const dist2 = dijkstra(src2, adj);

    let res = dist1[dest] + dist2[dest];
    for (const [u, v, w] of edges) {
        res = Math.min(res, dist1[u] + dist2[v] + w);
        res = Math.min(res, dist1[v] + dist2[u] + w);
    }

    return res === Infinity ? -1 : res;
}

