#include <vector>
#include <queue>

std::vector<int> largestSumSequence(std::vector<int>& nums, int k) {
    std::priority_queue<int, std::vector<int>, std::greater<int>> min_heap;

    for (int num : nums) {
        min_heap.push(num);
        if (min_heap.size() > k) {
            min_heap.pop();
        }
    }

    std::vector<int> result(min_heap.size());
    while (!min_heap.empty()) {
        result[min_heap.size() - 1] = min_heap.top();
        min_heap.pop();
    }

    return result;
}

