import heapq

def largest_sum_sequence(nums, k):
    min_heap = []

    for num in nums:
        heapq.heappush(min_heap, num)
        if len(min_heap) > k:
            heapq.heappop(min_heap)

    result = [0] * k
    for i in range(k-1, -1, -1):
        result[i] = heapq.heappop(min_heap)

    return result

