#include <vector>

std::vector<int> kRadiusAverage(std::vector<int>& nums, int k) {
    int n = nums.size();
    std::vector<int> avgs(n, -1);
    for (int i = k; i < n - k; ++i) {
        int sum = 0;
        for (int j = i - k; j <= i + k; ++j) {
            sum += nums[j];
        }
        avgs[i] = sum / (2 * k + 1);
    }
    return avgs;
}

python_code:
def k_radius_average(nums, k):
    n = len(nums)
    avgs = [-1] * n
    for i in range(k, n - k):
        sum = 0
        for j in range(i - k, i + k + 1):
            sum += nums[j]
        avgs[i] = sum // (2 * k + 1)
    return avgs

javascript_code:
function kRadiusAverage(nums, k) {
    const n = nums.length;
    const avgs = Array(n).fill(-1);
    for (let i = k; i < n - k; i++) {
        let sum = 0;
        for (let j = i - k; j <= i + k; j++) {
            sum += nums[j];
        }
        avgs[i] = Math.floor(sum / (2 * k + 1));
    }
    return avgs;
}

