public int minDeletions(int[] nums) {
    int n = nums.length;
    if (n <= 2)
        return 0;

    int minIdx = 0, maxIdx = 0;

    for (int i = 1; i < n; i++) {
        if (nums[i] < nums[minIdx])
            minIdx = i;
        if (nums[i] > nums[maxIdx])
            maxIdx = i;
    }

    return Math.min(Math.min(Math.max(minIdx, maxIdx), n - Math.min(minIdx, maxIdx) - 1), minIdx + n - maxIdx - 1);
}

