#include <vector>
#include <unordered_set>
using namespace std;

vector<int> peopleWithSecret(int n, vector<vector<int>>& meetings, int firstPerson) {
    unordered_set<int> secretHolders;
    secretHolders.insert(firstPerson);

    for (int time = 0; !meetings.empty(); ++time) {
        vector<vector<int>> future_meetings;
        for (const auto& meeting : meetings) {
            if (meeting[2] > time) {
                future_meetings.push_back(meeting);
                continue;
            }
            if (secretHolders.count(meeting[0]) || secretHolders.count(meeting[1])) {
                secretHolders.insert(meeting[0]);
                secretHolders.insert(meeting[1]);
            }
        }
        meetings = future_meetings;
    }

    return vector<int>(secretHolders.begin(), secretHolders.end());
}

python_code:
from collections import defaultdict

def people_with_secret(n: int, meetings: List[List[int]], firstPerson: int) -> List[int]:
    secret_holders = set([firstPerson])
    meetings_by_time = defaultdict(list)

    for meeting in meetings:
        meetings_by_time[meeting[2]].append(tuple(meeting[:2]))

    for time in range(n):
        if time in meetings_by_time:
            for x, y in meetings_by_time[time]:
                if x in secret_holders or y in secret_holders:
                    secret_holders.add(x)
                    secret_holders.add(y)

    return list(secret_holders)

javascript_code:
function peopleWithSecret(n, meetings, firstPerson) {
  const secretHolders = new Set([firstPerson]);

  const meetingsByTime = {};
  for (const meeting of meetings) {
    if (!(meeting[2] in meetingsByTime)) {
      meetingsByTime[meeting[2]] = [];
    }
    meetingsByTime[meeting[2]].push([meeting[0], meeting[1]]);
  }

  for (let time = 0; time < n; time++) {
    if (time in meetingsByTime) {
      for (const [x, y] of meetingsByTime[time]) {
        if (secretHolders.has(x) || secretHolders.has(y)) {
          secretHolders.add(x);
          secretHolders.add(y);
        }
      }
    }
  }

  return Array.from(secretHolders);
}

