public int minHealth(int[] damage, int armor) {
    int health = 0;
    for (int i = damage.length - 1; i >= 0; --i) {
        health += damage[i];
        if (health > armor) {
            health -= armor;
            armor = 0;
        }
    }
    return health + 1;
}

