#include <vector>
#include <set>
#include <algorithm>
#include <functional>
using namespace std;

void helper(vector<int>& digits, vector<int>& current, set<int>& result, vector<bool>& used) {
    if (current.size() == digits.size()) {
        int num = 0;
        for (int d : current) {
            num = num * 10 + d;
        }
        result.insert(num);
        return;
    }
    for (int i = 0; i < digits.size(); ++i) {
        if (!used[i]) {
            used[i] = true;
            current.push_back(digits[i]);
            helper(digits, current, result, used);
            current.pop_back();
            used[i] = false;
        }
    }
}

vector<int> uniquePermutations(vector<int>& digits) {
    vector<int> current;
    set<int> result;
    vector<bool> used(digits.size(), false);
    sort(digits.begin(), digits.end());

    helper(digits, current, result, used);

    return vector<int>(result.begin(), result.end());
}

javascript_code:
function helper(digits, current, result, used) {
    if (current.length === digits.length) {
        let num = parseInt(current.join(''), 10);
        result.add(num);
        return;
    }
    for (let i = 0; i < digits.length; ++i) {
        if (!used[i]) {
            used[i] = true;
            current.push(digits[i]);
            helper(digits, current, result, used);
            current.pop();
            used[i] = false;
        }
    }
}

function uniquePermutations(digits) {
    let current = [];
    let result = new Set();
    let used = new Array(digits.length).fill(false);
    digits.sort((a, b) => a - b);

    helper(digits, current, result, used);

    return Array.from(result).sort((a, b) => a - b);
}

