    string tPath = findPath(root, destValue, "");
    int i = 0;
    while (i < sPath.size() && i < tPath.size() && sPath[i] == tPath[i]) i++;
    string res = "";
    for (int j = sPath.size() - 1; j >= i; j--) res += "U";
    for (int j = i; j < tPath.size(); j++) res += tPath[j];
    return res;
}

