class TreeNode {
    constructor(val, left = null, right = null) {
        this.val = val;
        this.left = left;
        this.right = right;
    }
}

function findPath(root, target, path) {
    if (!root) return "";
    if (root.val === target) return path;
    let left = findPath(root.left, target, path + "L");
    let right = findPath(root.right, target, path + "R");
    return left ? left : right;
}

function shortestPath(root, startValue, destValue) {
    let sPath = findPath(root, startValue, "");
    let tPath = findPath(root, destValue, "");
    let i = 0;
    while (i < sPath.length && i < tPath.length && sPath[i] === tPath[i]) i++;
    let res = "";
    for (let j = sPath.length - 1; j >= i; j--) res += "U";
    for (let j = i; j < tPath.length; j++) res += tPath[j];
    return res;
}

