#include <vector>
#include <queue>
using namespace std;

int maxCoins(vector<vector<int>>& piles, int k) {
    priority_queue<int> pq;
    for (const auto& pile : piles) {
        for (const auto& coin : pile) {
            pq.push(coin);
        }
    }

    int max_value = 0;
    while (k > 0) {
        max_value += pq.top();
        pq.pop();
        k--;
    }
    return max_value;
}

python_code:
import heapq

def maxCoins(piles, k):
    pq = []
    for pile in piles:
        for coin in pile:
            heapq.heappush(pq, -coin)

    max_value = 0
    while k > 0:
        max_value += -heapq.heappop(pq)
        k -= 1
    return max_value

javascript_code:
function maxCoins(piles, k) {
    let pq = new PriorityQueue((a, b) => b - a);
    for (let pile of piles) {
        for (let coin of pile) {
            pq.enqueue(coin);
        }
    }

    let maxValue = 0;
    while (k > 0) {
        maxValue += pq.dequeue();
        k--;
    }
    return maxValue;
}

class PriorityQueue {
    constructor(comparator) {
        this.data = [];
        this.comparator = comparator;
    }

    enqueue(element) {
        this.data.push(element);
        this.data.sort(this.comparator);
    }

    dequeue() {
        return this.data.shift();
    }

    isEmpty() {
        return this.data.length === 0;
    }
}

