import java.util.ArrayList;

public int maxWordsInSentence(ArrayList<String> sentences) {
    int maxWords = 0;
    for (String sentence : sentences) {
        String[] words = sentence.split(" ");
        maxWords = Math.max(maxWords, words.length);
    }
    return maxWords;
}

cpp_code:
#include<string>
#include<vector>
#include<sstream>
int maxWordsInSentence(std::vector<std::string>& sentences) {
    int maxWords = 0;
    for (const std::string& sentence : sentences) {
        std::istringstream iss(sentence);
        int words = 0;
        std::string word;
        while (iss >> word) {
            words++;
        }
        maxWords = std::max(maxWords, words);
    }
    return maxWords;
}

