import java.util.*;

class Solution {
    public List<String> makeableRecipes(String[] recipes, String[][] ingredients, String[] supplies) {
        Map<String, Set<String>> dependentRecipes = new HashMap<>();
        Set<String> availableSupplies = new HashSet<>(Arrays.asList(supplies));
        for (int i = 0; i < recipes.length; i++) {
            dependentRecipes.put(recipes[i], new HashSet<>(Arrays.asList(ingredients[i])));
        }

        Queue<String> q = new LinkedList<>();
        for (String supply : availableSupplies) {
            q.offer(supply);
        }

        while (!q.isEmpty()) {
            String currentItem = q.poll();
            for (Map.Entry<String, Set<String>> recipe : dependentRecipes.entrySet()) {
                if (recipe.getValue().contains(currentItem)) {
                    recipe.getValue().remove(currentItem);
                    if (recipe.getValue().isEmpty()) {
                        availableSupplies.add(recipe.getKey());
                        q.offer(recipe.getKey());
                    }
                }
            }
        }

        List<String> result = new ArrayList<>();
        for (String recipe : recipes) {
            if (availableSupplies.contains(recipe)) {
                result.add(recipe);
            }

cpp_code:
#include <vector>
#include <string>
#include <unordered_map>
#include <unordered_set>
#include <queue>

std::vector<std::string> makeableRecipes(std::vector<std::string>& recipes, std::vector<std::vector<std::string>>& ingredients, std::vector<std::string>& supplies) {
    std::unordered_map<std::string, std::unordered_set<std::string>> dependentRecipes;
    std::unordered_set<std::string> availableSupplies(supplies.begin(), supplies.end());
    for (size_t i = 0; i < recipes.size(); ++i) {
        dependentRecipes[recipes[i]] = std::unordered_set<std::string>(ingredients[i].begin(), ingredients[i].end());
    }

    std::queue<std::string> q;
    for (const auto& supply : availableSupplies) {
        q.push(supply);
    }

    while (!q.empty()) {
        const std::string currentItem = q.front();
        q.pop();
        for (const auto& recipe : dependentRecipes) {
            if (recipe.second.count(currentItem)) {
                recipe.second.erase(currentItem);
                if (recipe.second.empty()) {
                    availableSupplies.insert(recipe.first);
                    q.push(recipe.first);
                }
            }
        }
    }

    std::vector<std::string> result;
    for (const auto& recipe : recipes) {
        if (availableSupplies.count(recipe)) {
            result.push_back(recipe);
        }
    }
    return result;
}

java_code:
boolean isValidParenthesesString(String s, String locked) {
    int balance = 0;
    for (int i = 0; i < s.length(); i++) {
        if (locked.charAt(i) == '0') {
            balance += s.charAt(i) == '(' ? 1 : -1;
            if (balance < 0) return false;
        }
    }
    return balance == 0;
}

