bool isValidParenthesesString(std::string s, std::string locked) {
    int balance = 0;
    for (int i = 0; i < s.length(); i++) {
        if (locked[i] == '0') {
            s[i] == '(' ? balance++ : balance--;
            if (balance < 0) return false;
        }
    }
    return balance == 0;
}

