def is_valid_parentheses_string(s: str, locked: str) -> bool:
    balance = 0
    for i in range(len(s)):
        if locked[i] == '0':
            balance += 1 if s[i] == '(' else -1
            if balance < 0:
                return False
    return balance == 0

