def string_sum_scores(s):
    score = 0
    prefix_length = 0

    for i in range(len(s) - 1, -1, -1):
        if s[i] == s[-1]:
            prefix_length += 1
        else:
            prefix_length = 0
        score += prefix_length

    return score

