        int loser = match[1];
        loss_count[loser]++;
        participants.insert(winner);
        participants.insert(loser);
    }

    std::set<int> no_losses;
    std::set<int> one_loss;

    for (int participant : participants) {
        if (loss_count[participant] == 0) {
            no_losses.insert(participant);
        } else if (loss_count[participant] == 1) {
            one_loss.insert(participant);
        }
    }

    return {no_losses, one_loss};
}

