from collections import defaultdict
from typing import List, Set

def twoLists(matches: List[List[int]]) -> List[Set[int]]:
    loss_count = defaultdict(int)
    participants = set()

    for winner, loser in matches:
        loss_count[loser] += 1
        participants.add(winner)
        participants.add(loser)

    no_losses = {participant for participant in participants if loss_count[participant] == 0}
    one_loss = {participant for participant in participants if loss_count[participant] == 1}

    return [no_losses, one_loss]

javascript_code:
function twoLists(matches) {
    const loss_count = new Map();
    const participants = new Set();

    for (const [winner, loser] of matches) {
        loss_count.set(loser, (loss_count.get(loser) || 0) + 1);
        participants.add(winner);
        participants.add(loser);
    }

    const no_losses = new Set();
    const one_loss = new Set();

    for (const participant of participants) {
        const count = loss_count.get(participant) || 0;
        if (count === 0) {
            no_losses.add(participant);
        } else if (count === 1) {
            one_loss.add(participant);
        }
    }

    return [no_losses, one_loss];
}

