java_code:
import java.util.HashMap;
import java.util.Map;

public int longestPalindrome(String[] words) {
    HashMap<Character, Integer> dict = new HashMap<>();
    int result = 0;
    boolean hasOdd = false;

    for (String word : words) {
        dict.put(word.charAt(0), dict.getOrDefault(word.charAt(0), 0) + 1);
        dict.put(word.charAt(1), dict.getOrDefault(word.charAt(1), 0) + 1);
    }

    for (Map.Entry<Character, Integer> entry : dict.entrySet()) {
        result += entry.getValue() / 2 * 2;
        hasOdd |= entry.getValue() % 2 == 1;
    }

    return result + (hasOdd ? 1 : 0);
}

cpp_code:
#include <unordered_map>
#include <string>
#include <vector>
#include <algorithm>

int longest_palindrome(std::vector<std::string>& words) {
    std::unordered_map<char, int> dict;
    int result = 0;
    bool has_odd = false;

    for (const auto& word : words) {
        dict[word[0]]++;
        dict[word[1]]++;
    }

    for (const auto& pair : dict) {
        result += pair.second / 2 * 2;
        has_odd |= pair.second % 2;
    }

    return result + has_odd;
}

javascript_code:
function longestPalindrome(words) {
    let dict = {};
    let result = 0;
    let hasOdd = false;

    for (let word of words) {
        dict[word[0]] = (dict[word[0]] || 0) + 1;
        dict[word[1]] = (dict[word[1]] || 0) + 1;
    }

    for (let count of Object.values(dict)) {
        result += Math.floor(count / 2) * 2;
        hasOdd |= count % 2;
    }

    return result + (hasOdd ? 1 : 0);
}

