        int row = startPos[0];
        int col = startPos[1];

        for (int i = idx; i < s.length(); ++i) {
            if (s[i] == 'L') --col;
            else if (s[i] == 'R') ++col;
            else if (s[i] == 'U') --row;
            else if (s[i] == 'D') ++row;

            if (row < 0 || row >= n || col < 0 || col >= n) {
                break;
            }

            answer[idx]++;
        }
    }

    return answer;
}

