public int numOfBeams(String[] bank) {
    int m = bank.length;
    int n = bank[0].length();
    int beams = 0;

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (bank[i].charAt(j) == '1') {
                for (int k = j + 1; k < n && bank[i].charAt(k) != '1'; k++) {
                    beams += bank[i].charAt(k) == '0' ? 1 : 0;
                }
                for (int k = i + 1; k < m && bank[k].charAt(j) != '1'; k++) {
                    beams += bank[k].charAt(j) == '0' ? 1 : 0;
                }
            }
        }
    }

    return beams;
}

