java_code:
import java.util.*;

class Solution {
    public int[][] kHighestRankedItems(int[][] grid, int[] pricing, int[] start, int k) {
        int m = grid.length, n = grid[0].length;
        int[][] directions = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        List<int[]> res = new ArrayList<>();
        PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[0] * 1000000 - a[1]));
        boolean[][] visited = new boolean[m][n];

        pq.offer(new int[]{0, -grid[start[0]][start[1]], start[0], start[1]});
        visited[start[0]][start[1]] = true;

        while (!pq.isEmpty() && k > 0) {
            int size = pq.size();
            for (int i = 0; i < size; i++) {
                int[] curr = pq.poll();
                int steps = curr[0], price = -curr[1], row = curr[2], col = curr[3];

                if (price >= pricing[0] && price <= pricing[1]) {
                    res.add(new int[]{row, col});
                    k--;
                }

                for (int[] direction : directions) {
                    int newRow = row + direction[0];
                    int newCol = col + direction[1];
                    if (newRow >= 0 && newRow < m && newCol >= 0 && newCol < n && !visited[newRow][newCol]) {
                        visited[newRow][newCol] = true;
                        pq.offer(new int[]{steps + 1, -grid[newRow][newCol], newRow, newCol});
                    }
                }
            }
        }

        int[][] result = new int[res.size()][2];
        for (int i = 0; i < res.size(); i++) {
            result[i] = res.get(i);
        }
        return result;
    }
}

cpp_code:
#include <vector>
#include <queue>
#include <algorithm>
using namespace std;

vector<vector<int>> kHighestRankedItems(vector<vector<int>>& grid, vector<int>& pricing, vector<int>& start, int k) {
    int m = grid.size(), n = grid[0].size();
    vector<vector<int>> directions = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
    vector<vector<int>> res;
    priority_queue<vector<int>, vector<vector<int>>, greater<vector<int>>> pq;
    vector<vector<bool>> visited(m, vector<bool>(n));

    pq.push({0, -grid[start[0]][start[1]], start[0], start[1]});
    visited[start[0]][start[1]] = true;

    while (!pq.empty() && k > 0) {
        int size = pq.size();
        for (int i = 0; i < size; i++) {
            auto curr = pq.top();
            pq.pop();
            int steps = curr[0], price = -curr[1], row = curr[2], col = curr[3];

            if (price >= pricing[0] && price <= pricing[1]) {
                res.push_back({row, col});
                k--;
            }

            for (const auto& direction : directions) {
                int newRow = row + direction[0];
                int newCol = col + direction[1];
                if (newRow >= 0 && newRow < m && newCol >= 0 && newCol < n && !visited[newRow][newCol]) {
                    visited[newRow][newCol] = true;
                    pq.push({steps + 1, -grid[newRow][newCol], newRow, newCol});
                }
            }
        }
    }

    return res;
}

