#include <vector>
#include <algorithm>

int earliestBloomingDay(std::vector<int>& plantTime, std::vector<int>& growTime) {
    std::vector<int> bloomTime;
    for (size_t i = 0; i < plantTime.size(); i++) {
        bloomTime.push_back(plantTime[i] + growTime[i]);
    }
    std::sort(bloomTime.begin(), bloomTime.end());
    int earliestDay = 0;
    for (size_t i = 0; i < bloomTime.size(); i++) {
        earliestDay = std::max(earliestDay, bloomTime[i]);
        earliestDay++;
    }
    return earliestDay;
}

