python_code:
from collections import deque

dx = [0, 1, 0, -1]
dy = [1, 0, -1, 0]

def getMaxSafeMinutes(grid):
    m, n = len(grid), len(grid[0])
    dist = [[-1 for _ in range(n)] for _ in range(m)]
    q = deque()

    if grid[m - 1][n - 1] != 1:
        dist[m - 1][n - 1] = 0
        q.append((m - 1, n - 1))

    while q:
        x, y = q.popleft()
        for d in range(4):
            nx, ny = x + dx[d], y + dy[d]
            if 0 <= nx < m and 0 <= ny < n and grid[nx][ny] == 0 and dist[nx][ny] == -1:
                dist[nx][ny] = dist[x][y] + 1
                q.append((nx, ny))

    if dist[0][0] == -1:
        return -1

    res = 0
    for test in range(dist[0][0], int(1e9)):
        ok = True
        for x in range(m):
            for y in range(n):
                if grid[x][y] == 1:
                    for d in range(4):
                        nx, ny = x + dx[d], y + dy[d]
                        if 0 <= nx < m and 0 <= ny < n and grid[nx][ny] == 2:
                            break
                    else:
                        ok = False
                        break
        if ok:
            res = test
        else:
            break
    return res

