const dx = [0, 1, 0, -1];
const dy = [1, 0, -1, 0];

function getMaxSafeMinutes(grid) {
    const m = grid.length;
    const n = grid[0].length;
    const dist = Array.from({length: m}, () => Array(n).fill(-1));
    const q = [];

    if (grid[m - 1][n - 1] !== 1) {
        dist[m - 1][n - 1] = 0;
        q.push([m - 1, n - 1]);
    }

    while (q.length > 0) {
        const [x, y] = q.shift();
        for (let d = 0; d < 4; d++) {
            const nx = x + dx[d];
            const ny = y + dy[d];
            if (nx >= 0 && nx < m && ny >= 0 && ny < n && grid[nx][ny] === 0 && dist[nx][ny] === -1) {
                dist[nx][ny] = dist[x][y] + 1;
                q.push([nx, ny]);
            }
        }
    }

    if (dist[0][0] === -1) return -1;

    let res = 0;
    for (let test = dist[0][0]; test < 1e9; test++) {
        let ok = true;
        for (let x = 0; x < m; x++) {
            for (let y = 0; y < n; y++) {
                if (grid[x][y] === 1) {
                    for (let d = 0; d < 4; d++) {
                        const nx = x + dx[d];
                        const ny = y + dy[d];
                        if (nx >= 0 && nx < m && ny >= 0 && ny < n && grid[nx][ny] === 2) {
                            break;
                        }
                    }
                    if (d === 4) {
                        ok = false;
                        break;
                    }
                }
            }
            if (!ok) break;
        }
        if (ok) {
            res = test;
        } else {
            break;
        }
    }
    return res;
}

