import java.util.ArrayList;

public ArrayList<String> partitionString(String s, int k, char fill) {
    ArrayList<String> partitions = new ArrayList<>();
    StringBuilder currentPartition = new StringBuilder();
    for(char c : s.toCharArray()) {
        currentPartition.append(c);
        if(currentPartition.length() == k) {
            partitions.add(currentPartition.toString());
            currentPartition.setLength(0); // clear the contents
        }
    }
    if(currentPartition.length() != 0) {
        while(currentPartition.length() < k) {
            currentPartition.append(fill);
        }
        partitions.add(currentPartition.toString());
    }
    return partitions;
}

cpp_code:
#include <vector>
#include <string>

std::vector<std::string> partition_string(const std::string& s, int k, char fill) {
    std::vector<std::string> partitions;
    std::string current_partition;
    for(char c : s) {
        current_partition += c;
        if(current_partition.size() == k) {
            partitions.push_back(current_partition);
            current_partition.clear();
        }
    }
    if(!current_partition.empty()) {
        current_partition += std::string(k - current_partition.size(), fill);
        partitions.push_back(current_partition);
    }
    return partitions;
}

python_code:
def partition_string(s, k, fill):
    partitions = []
    current_partition = ''
    for c in s:
        current_partition += c
        if len(current_partition) == k:
            partitions.append(current_partition)
            current_partition = ''
    if current_partition:
        current_partition += fill * (k - len(current_partition))
        partitions.append(current_partition)
    return partitions

