function partitionString(s, k, fill) {
    const partitions = [];
    let currentPartition = '';
    for (const c of s) {
        currentPartition += c;
        if (currentPartition.length === k) {
            partitions.push(currentPartition);
            currentPartition = '';
        }
    }
    if (currentPartition.length > 0) {
        currentPartition += fill.repeat(k - currentPartition.length);
        partitions.push(currentPartition);
    }
    return partitions;
}

