import java.util.Arrays;

public int maxRunningTime(int n, int[] batteries) {
    Arrays.sort(batteries);
    int total_time = 0;
    for (int i = batteries.length - 1; i >= batteries.length - n; --i) {
        total_time += batteries[i];
    }
    return total_time / n;
}

