public int minKeypresses(String s) {
    int[] keypresses = new int[26];
    for (int i = 0; i < 26; ++i) {
        keypresses[i] = (i % 9) + 1;
    }
    int result = 0;
    for (char c : s.toCharArray()) {
        result += keypresses[c - 'a'];
    }
    return result;
}

