vector<int> lonelyNumbers(vector<int>& nums) {
    unordered_set<int> num_set(nums.begin(), nums.end());
    vector<int> lonely;
    for (int num : nums) {
        if (!num_set.count(num - 1) && !num_set.count(num + 1)) {
            lonely.push_back(num);
        }
    }
    return lonely;
}

