import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public List<String> anagramOperations(String[] words) {
    List<String> result = new ArrayList<>();
    result.add(words[0]);

    for (int i = 1; i < words.length; i++) {
        char[] first = words[i].toCharArray();
        char[] second = words[i - 1].toCharArray();
        Arrays.sort(first);
        Arrays.sort(second);

        if (!Arrays.equals(first, second)) {
            result.add(words[i]);
        }
    }

    return result;
}

cpp_code:
#include <vector>
#include <string>
#include <algorithm>

std::vector<std::string> anagramOperations(std::vector<std::string> &words) {
    for (int i = 1; i < words.size(); ++i) {
        std::string s1 = words[i];
        std::string s2 = words[i - 1];
        std::sort(s1.begin(), s1.end());
        std::sort(s2.begin(), s2.end());
        if (s1 == s2) {
            words.erase(words.begin() + i);
            --i;
        }
    }
    return words;
}

python_code:
def anagramOperations(words):
    i = 1
    while i < len(words):
        word1 = sorted(words[i])
        word2 = sorted(words[i - 1])
        if word1 == word2:
            del words[i]
        else:
            i += 1
    return words

