public String findSubstring(String s, int power, int modulo, int k, int hashValue) {
    long currentHash = 0;
    long powerK = 1;

    for (int i = 0; i < k; i++) {
        currentHash = (currentHash * power + (s.charAt(i) - 'a' + 1)) % modulo;
        powerK = (powerK * power) % modulo;
    }

    if (currentHash == hashValue) return s.substring(0, k);

    for (int i = k; i < s.length(); i++) {
        currentHash = ((currentHash - (s.charAt(i - k) - 'a' + 1) * powerK) % modulo + modulo) % modulo;
        currentHash = (currentHash * power + (s.charAt(i) - 'a' + 1)) % modulo;
        if (currentHash == hashValue) return s.substring(i - k + 1, i + 1);
    }

    throw new RuntimeException("No matching substring found");
}

cpp_code:
#include <string>
#include <stdexcept>
using std::string;

string findSubstring(const string& s, int power, int modulo, int k, int hashValue) {
    long long currentHash = 0;
    long long powerK = 1;

    for (int i = 0; i < k; ++i) {
        currentHash = (currentHash * power + (s[i] - 'a' + 1)) % modulo;
        powerK = (powerK * power) % modulo;
    }

    if (currentHash == hashValue) return s.substr(0, k);

    for (int i = k; i < s.size(); ++i) {
        currentHash = ((currentHash - (s[i - k] - 'a' + 1) * powerK) % modulo + modulo) % modulo;
        currentHash = (currentHash * power + (s[i] - 'a' + 1)) % modulo;
        if (currentHash == hashValue) return s.substr(i - k + 1, k);
    }

    throw std::runtime_error("No matching substring found");
}

python_code:
def find_substring(s, power, modulo, k, hash_value):
    current_hash = 0
    power_k = 1

    for i in range(k):
        current_hash = (current_hash * power + (ord(s[i]) - ord('a') + 1)) % modulo
        power_k = (power_k * power) % modulo

    if current_hash == hash_value:
        return s[:k]

    for i in range(k, len(s)):
        current_hash = ((current_hash - (ord(s[i - k]) - ord('a') + 1) * power_k) % modulo + modulo) % modulo
        current_hash = (current_hash * power + (ord(s[i]) - ord('a') + 1)) % modulo
        if current_hash == hash_value:
            return s[i - k + 1:i + 1]

    raise AssertionError("No matching substring found")

javascript_code:
function findSubstring(s, power, modulo, k, hashValue) {
    let currentHash = 0;
    let powerK = 1;

    for (let i = 0; i < k; i++) {
        currentHash = (currentHash * power + (s.charCodeAt(i) - 'a'.charCodeAt(0) + 1)) % modulo;
        powerK = (powerK * power) % modulo;
    }

    if (currentHash === hashValue) return s.slice(0, k);

    for (let i = k; i < s.length; i++) {
        currentHash = (((currentHash - (s.charCodeAt(i - k) - 'a'.charCodeAt(0) + 1) * powerK) % modulo) + modulo) % modulo;
        currentHash = (currentHash * power + (s.charCodeAt(i) - 'a'.charCodeAt(0) + 1)) % modulo;
        if (currentHash === hashValue) return s.slice(i - k + 1, i + 1);
    }

    throw Error("No matching substring found");
}

java_code:
import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;

public int[] groupStrings(String[] words) {
    Map<String, Integer> groups = new HashMap<>();
    int groupsCount = 0;

    for (String word : words) {
        char[] chars = word.toCharArray();
        Arrays.sort(chars);
        String sKey = new String(chars);

        if (!groups.containsKey(sKey)) {
            groups.put(sKey, groupsCount);
            groupsCount++;
        }
    }

    return new int[]{groupsCount, words.length - groupsCount};
}

cpp_code:
#include <vector>
#include <set>
#include <string>
#include <unordered_map>

std::vector<int> groupStrings(std::vector<std::string>& words) {
    std::unordered_map<std::string, int> groups;
    int groupsCount = 0;

    for (const std::string& word : words) {
        std::string sKey(word);
        sort(sKey.begin(), sKey.end());

        if (groups.find(sKey) == groups.end()) {
            groups[sKey] = groupsCount;
            groupsCount++;
        }
    }

    return {groupsCount, words.size() - groupsCount};
}

