#include <vector>
#include <queue>

std::vector<int> closestNodes(int n, std::vector<std::vector<int>>& edges, std::vector<std::vector<int>>& query) {
    std::vector<int> answer;

    std::vector<std::vector<int>> tree(n);
    for (auto& edge : edges) {
        tree[edge[0]].push_back(edge[1]);
        tree[edge[1]].push_back(edge[0]);
    }

    auto bfs = [&](int start, int end) {
        std::queue<int> q;
        std::vector<bool> visited(n, false);
        q.push(start);
        visited[start] = true;

        while (!q.empty()) {
            int current = q.front();
            q.pop();

            if (current == end) {
                return current;
            }

            for (int neighbor : tree[current]) {
                if (!visited[neighbor]) {
                    q.push(neighbor);
                    visited[neighbor] = true;
                }
            }
        }
        return -1;
    };

    for (auto& q : query) {
        int lca = bfs(q[0], q[1]);
        int node1 = bfs(lca, q[0]);
        int node2 = bfs(lca, q[1]);
        answer.push_back(node1 == q[2] ? q[0] : q[1]);
    }

    return answer;
}

python_code:
from collections import deque

def closest_nodes(n, edges, query):
    answer = []
    tree = [[] for _ in range(n)]

    for edge in edges:
        tree[edge[0]].append(edge[1])
        tree[edge[1]].append(edge[0])

    def bfs(start, end):
        queue = deque([start])
        visited = {start}

        while queue:
            current = queue.popleft()

            if current == end:
                return current

            for neighbor in tree[current]:
                if neighbor not in visited:
                    queue.append(neighbor)
                    visited.add(neighbor)

    for q in query:
        lca = bfs(q[0], q[1])
        node1 = bfs(lca, q[0])
        node2 = bfs(lca, q[1])
        answer.append(q[0] if node1 == q[2] else q[1])

    return answer

javascript_code:
function closestNodes(n, edges, query) {
    const answer = [];
    const tree = Array.from({ length: n }, () => []);

    for (const edge of edges) {
        tree[edge[0]].push(edge[1]);
        tree[edge[1]].push(edge[0]);
    }

    function bfs(start, end) {
        const queue = [start];
        const visited = new Set([start]);

        while (queue.length > 0) {
            const current = queue.shift();

            if (current === end) {
                return current;
            }

            for (const neighbor of tree[current]) {
                if (!visited.has(neighbor)) {
                    queue.push(neighbor);
                    visited.add(neighbor);
                }
            }
        }
    }

    for (const q of query) {
        const lca = bfs(q[0], q[1]);
        const node1 = bfs(lca, q[0]);
        const node2 = bfs(lca, q[1]);
        answer.push(node1 === q[2] ? q[0] : q[1]);
    }

    return answer;
}

