int mod = 1000000007;
public int sum_of_strength(int[] strength) {
    int res = 0, total = 0, minimum = 0;
    for (int i = 0; i < strength.length; ++i) {
        minimum = total = strength[i];
        for (int j = i; j < strength.length; ++j) {
            minimum = Math.min(minimum, strength[j]);
            total += strength[j];
            res = (res + minimum * total % mod) % mod;
        }
    }
    return res;
}

