import java.util.Arrays;

public int rearrangeDigits(int num) {
    if (num == 0)
        return 0;
    char[] chars = Integer.toString(num).toCharArray();
    Arrays.sort(chars);

    if (chars[0] != '-' && chars[0] == '0') {
        int nonzeroIndex = 1;
        while (chars[nonzeroIndex] == '0') {
            nonzeroIndex++;
        }
        char temp = chars[0];
        chars[0] = chars[nonzeroIndex];
        chars[nonzeroIndex] = temp;
    }

    return Integer.parseInt(String.valueOf(chars));
}

cpp_code:
#include <algorithm>
#include <string>
#include <vector>

int rearrangeDigits(int num) {
    if (num == 0)
        return 0;
    std::string str_num = std::to_string(num);
    std::vector<char> digits(str_num.begin(), str_num.end());
    std::sort(digits.begin(), digits.end());

    if (str_num[0] != '-' && digits[0] == '0') {
        auto nonzero_digit_iter = std::find_if(digits.begin(), digits.end(), [](char ch) { return ch != '0'; });
        std::swap(digits[0], *nonzero_digit_iter);
    }

    std::string res(digits.begin(), digits.end());
    return std::stoi(res);
}

