    const chars = num.toString().split('').sort();

    if (chars[0] !== '-' && chars[0] === '0') {
        let nonzeroIndex = 1;
        while (chars[nonzeroIndex] === '0') {
            nonzeroIndex++;
        }
        [chars[0], chars[nonzeroIndex]] = [chars[nonzeroIndex], chars[0]];
    }

    return parseInt(chars.join(''));
}

