class BitSet {
    private int[] bits;

    public BitSet(int size) {
        bits = new int[(size + 31) / 32];
    }

    public void set(int index) {
        bits[index / 32] |= (1 << (index % 32));
    }

    public boolean get(int index) {
        return (bits[index / 32] & (1 << (index % 32))) != 0;
    }
}

