def maxNumberOfCopies(s, target):
    s_counts = [0] * 26
    target_counts = [0] * 26

    for c in s:
        s_counts[ord(c) - ord('a')] += 1

    for c in target:
        target_counts[ord(c) - ord('a')] += 1

    max_copies = float('inf')
    for i in range(26):
        if target_counts[i] > 0:
            max_copies = min(max_copies, s_counts[i] // target_counts[i])
    return max_copies

javascript_code:
function maxNumberOfCopies(s, target) {
    let sCounts = new Array(26).fill(0);
    let targetCounts = new Array(26).fill(0);

    for (let c of s)
        sCounts[c.charCodeAt(0) - 'a'.charCodeAt(0)]++;

    for (let c of target)
        targetCounts[c.charCodeAt(0) - 'a'.charCodeAt(0)]++;

    let maxCopies = Number.MAX_SAFE_INTEGER;
    for (let i = 0; i < 26; i++) {
        if (targetCounts[i] > 0)
            maxCopies = Math.min(maxCopies, Math.floor(sCounts[i] / targetCounts[i]));
    }
    return maxCopies;
}

