java_code:
import java.util.Map;
import java.util.HashMap;

public int minNumberOfBeansToRemove(int[] beans) {
    Map<Integer, Integer> count = new HashMap<>();
    for (int bean : beans) {
        count.put(bean, count.getOrDefault(bean, 0) + 1);
    }

    int min_remove = beans.length;
    for (Map.Entry<Integer, Integer> item : count.entrySet()) {
        int remove = 0;
        for (Map.Entry<Integer, Integer> other : count.entrySet()) {
            if (!other.getKey().equals(item.getKey())) {
                remove += other.getValue() * Math.max(0, other.getKey() - item.getKey());
            }
        }
        min_remove = Math.min(min_remove, remove);
    }

    return min_remove;
}

cpp_code:
#include <unordered_map>

int minNumberOfBeansToRemove(const std::vector<int>& beans) {
    std::unordered_map<int, int> count;
    for (int bean : beans) {
        count[bean]++;
    }

    int min_remove = beans.size();
    for (const auto& item : count) {
        int remove = 0;
        for (const auto& other : count) {
            if (other.first != item.first) {
                remove += other.second * std::max(0, other.first - item.first);
            }
        }
        min_remove = std::min(min_remove, remove);
    }

    return min_remove;
}

