def min_number_of_beans_to_remove(beans):
    count = {}
    for bean in beans:
        if bean not in count:
            count[bean] = 0
        count[bean] += 1

    min_remove = len(beans)
    for key, value in count.items():
        remove = 0
        for other_key, other_value in count.items():
            if other_key != key:
                remove += other_value * max(0, other_key - key)
        min_remove = min(min_remove, remove)

    return min_remove

javascript_code:
function minNumberOfBeansToRemove(beans) {
    const count = {};
    for (const bean of beans) {
        if (!count.hasOwnProperty(bean)) {
            count[bean] = 0;
        }
        count[bean]++;
    }

    let min_remove = beans.length;
    for (const [key, value] of Object.entries(count)) {
        let remove = 0;
        for (const [other_key, other_value] of Object.entries(count)) {
            if (other_key !== key) {
                remove += other_value * Math.max(0, other_key - key);
            }
        }
        min_remove = Math.min(min_remove, remove);
    }

    return min_remove;
}

