using namespace std;

int minSteps(string s, string t) {
    unordered_map<char, int> charCount;
    for (char c : s) charCount[c]++;
    for (char c : t) charCount[c]--;

    int steps = 0;
    for (auto& pair : charCount) {
        steps += abs(pair.second);
    }

    return steps / 2;
}

