def minimum_time_for_trips(time, total_trips):
    time.sort()

    start, end = 0, time[-1] * total_trips
    while start < end:
        mid = start + (end - start) // 2
        trips = sum(mid // t for t in time)
        if trips < total_trips:
            start = mid + 1
        else:
            end = mid

