class TextEditor {
    constructor() {
        this.text = "";
        this.cursor = 0;
    }

    addText(newText) {
        this.text = this.text.slice(0, this.cursor) + newText + this.text.slice(this.cursor);
        this.cursor += newText.length;
    }

    deleteText(k) {
        const deleted = Math.min(k, this.cursor);
        this.text = this.text.slice(0, this.cursor - deleted) + this.text.slice(this.cursor);
        this.cursor -= deleted;
        return deleted;
    }

    cursorLeft(k) {
        this.cursor -= Math.min(k, this.cursor);
        return this.text.slice(Math.max(0, this.cursor - 10), this.cursor);
    }

    cursorRight(k) {
        this.cursor += Math.min(k, this.text.length - this.cursor);
        return this.text.slice(Math.max(0, this.cursor - 10), this.cursor);
    }
}

java_code:
public int minHeightJump(int[] nums, int[] costs) {
    int n = nums.length;
    int[] dp = new int[n];

    dp[0] = 0;
    for (int i = 1; i < n; ++i) {
        dp[i] = Integer.MAX_VALUE;
        for (int j = i - 1; j >= 0; --j) {
            if ((nums[j] <= nums[i] && (j == 0 || nums[j - 1] < nums[i])) || (nums[j] > nums[i] && (j == 0 || nums[j - 1] >= nums[i]))) {
                dp[i] = Math.min(dp[i], dp[j] + costs[i]);
            }
        }
    }
    return dp[n - 1];
}

cpp_code:
#include <vector>

int minHeightJump(const std::vector<int>& nums, const std::vector<int>& costs) {
    int n = nums.size();
    std::vector<int> dp(n, 1e9);

    dp[0] = 0;
    for (int i = 1; i < n; ++i) {
        int j = i - 1;
        while (j >= 0) {
            if ((nums[j] <= nums[i] && (j == 0 || nums[j - 1] < nums[i])) || (nums[j] > nums[i] && (j == 0 || nums[j - 1] >= nums[i]))) {
                dp[i] = std::min(dp[i], dp[j] + costs[i]);
            }
            --j;
        }
    }
    return dp[n - 1];
}

