        if (cur->val == 0) {
            int tmp_sum = 0;
            while (cur->next && cur->next->val != 0) {
                tmp_sum += cur->next->val;
                cur = cur->next;
            }
            prev->next = new ListNode(tmp_sum);
            prev = prev->next;
            cur = cur->next;
