#include <algorithm>
#include <string>

std::string repeatLimitedString(std::string s, int repeatLimit) {
    std::string result = "";
    std::sort(s.begin(), s.end(), std::greater<char>());

    for (char c : s) {
        size_t pos = result.find(c);

        if (pos == std::string::npos) {
            result.push_back(c);
        } else {
            int count = 1;

            while (pos + count < result.size() && result[pos + count] == c) {
                count++;
            }

            if (count < repeatLimit) {
                result.insert(pos + count, 1, c);
            }
        }
    }

    return result;
}

