    let count = 0;

    for (const num of nums) {
        mod_count[num % k]++;
    }

    count += mod_count[0] * (mod_count[0] - 1) / 2;

    for (let i = 1; i <= Math.floor(k / 2); i++) {
        if (i != k - i) {
            count += mod_count[i] * mod_count[k-i];
        } else {
            count += mod_count[i] * (mod_count[i] - 1) / 2;
        }
    }

    return count;
}

