#include <vector>
#include <string>

std::vector<std::string> excelSheetCells(std::string s) {
    int r1, r2, c1, c2;
    sscanf(s.c_str(), "%c%d:%c%d", &c1, &r1, &c2, &r2);
    std::vector<std::string> result;

    for (int c = c1; c <= c2; ++c) {
        for (int r = r1; r <= r2; ++r) {
            result.emplace_back(std::string(1, char(c)) + std::to_string(r));
        }
    }
    return result;
}

