def excel_sheet_cells(s: str):
    c1, r1, c2, r2 = s.split(':')
    r1, r2 = int(r1[1:]), int(r2[1:])
    c1, c2 = ord(c1[0]), ord(c2[0])
    result = []

    for c in range(c1, c2 + 1):
        for r in range(r1, r2 + 1):
            result.append(chr(c) + str(r))

