public class Node {
    int val;
    Node left;
    Node right;
}

public int minOperations(Node root, int result) {
    if (root == null) {
        return 0;
    }
    if (root.val <= 1) {
        return (root.val == result) ? 0 : 1;
    } else {
        int leftOperations = minOperations(root.left, root.val == 4 ? result ^ 1 : result);
        int rightOperations = minOperations(root.right, root.val == 4 ? result ^ 1 : result);
        if (root.val == 3) {
            return Math.min(leftOperations, rightOperations);
        } else if (root.val == 2) {
            return Math.max(leftOperations, rightOperations);
        } else {
            return leftOperations + rightOperations;
        }
    }
}

