#include <vector>
#include <queue>
#include <climits>

using namespace std;

int shortestPath(int n, vector<vector<int>>& edges, int src1, int src2, int dest) {
    vector<vector<pair<int, int>>> graph(n);

    for (const auto& edge : edges) {
        graph[edge[0]].emplace_back(edge[1], edge[2]);
    }

    auto dijkstra = [&](int src) {
        vector<int> dist(n, INT_MAX);
        priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> pq;

        dist[src] = 0;
        pq.emplace(0, src);

        while (!pq.empty()) {
            int u = pq.top().second;
            int d = pq.top().first;
            pq.pop();

            if (d != dist[u]) continue;

            for (const auto& edge : graph[u]) {
                int v = edge.first;
                int w = edge.second;

                if (dist[u] + w < dist[v]) {
                    dist[v] = dist[u] + w;
                    pq.emplace(dist[v], v);
                }
            }
        }

        return dist;
    };

    vector<int> src1_to_all = dijkstra(src1);
    vector<int> src2_to_all = dijkstra(src2);

    int min_weight = INT_MAX;
    for (const auto& edge : edges) {
        int u = edge[0];
        int v = edge[1];
        int w = edge[2];
        min_weight = min(min_weight, src1_to_all[u] + w + src2_to_all[v]);
    }

    return min_weight == INT_MAX ? -1 : min_weight;
}

python_code:
import heapq
from collections import defaultdict

def shortest_path(n, edges, src1, src2, dest):
    graph = defaultdict(list)

    for u, v, w in edges:
        graph[u].append((v, w))

    def dijkstra(src):
        dist = [float('inf')] * n
        pq = [(0, src)]

        dist[src] = 0

        while pq:
            d, u = heapq.heappop(pq)

            if d != dist[u]:
                continue

            for v, w in graph[u]:
                if dist[u] + w < dist[v]:
                    dist[v] = dist[u] + w
                    heapq.heappush(pq, (dist[v], v))

        return dist

    src1_to_all = dijkstra(src1)
    src2_to_all = dijkstra(src2)

    min_weight = float('inf')
    for u, v, w in edges:
        min_weight = min(min_weight, src1_to_all[u] + w + src2_to_all[v])

    return -1 if min_weight == float('inf') else min_weight

javascript_code:
function shortestPath(n, edges, src1, src2, dest) {
    const graph = new Array(n).fill(null).map(() => []);

    edges.forEach(([u, v, w]) => {
        graph[u].push([v, w]);
    });

    function dijkstra(src) {
        const dist = new Array(n).fill(Infinity);
        const pq = [[0, src]];

        dist[src] = 0;

        while (pq.length > 0) {
            pq.sort((a, b) => a[0] - b[0]);
            const [d, u] = pq.shift();

            if (d !== dist[u]) continue;

            for (const [v, w] of graph[u]) {
                if (dist[u] + w < dist[v]) {
                    dist[v] = dist[u] + w;
                    pq.push([dist[v], v]);
                }
            }
        }

        return dist;
    }

    const src1ToAll = dijkstra(src1);
    const src2ToAll = dijkstra(src2);

    let minWeight = Infinity;
    edges.forEach(([u, v, w]) => {
        minWeight = Math.min(minWeight, src1ToAll[u] + w + src2ToAll[v]);
    });

    return minWeight === Infinity ? -1 : minWeight;
}

