#include <string>
#include <algorithm>

std::string largestSwap(std::string num) {
    std::string even_digits = "";
    std::string odd_digits = "";

    for (char c : num) {
        if ((c - '0') % 2 == 0) {
            even_digits.push_back(c);
        } else {
            odd_digits.push_back(c);
        }
    }

    std::sort(even_digits.rbegin(), even_digits.rend());
    std::sort(odd_digits.rbegin(), odd_digits.rend());

    std::string result = "";
    size_t even_index = 0, odd_index = 0;

    for (char c : num) {
        if ((c - '0') % 2 == 0) {
            result.push_back(even_digits[even_index++]);
        } else {
            result.push_back(odd_digits[odd_index++]);
        }
    }

    return result;
}

int largestSwapPermutations(int num) {
    std::string num_str = std::to_string(num);
    return std::stoi(largestSwap(num_str));
}

python_code:
def largest_swap_permutations(num):
    num_str = str(num)
    even_digits = sorted([c for c in num_str if int(c) % 2 == 0], reverse=True)
    odd_digits = sorted([c for c in num_str if int(c) % 2 == 1], reverse=True)

    result = []
    for c in num_str:
        if int(c) % 2 == 0:
            result.append(even_digits.pop(0))
        else:
            result.append(odd_digits.pop(0))

    return int(''.join(result))

javascript_code:
function largestSwapPermutations(num) {
    const numStr = num.toString();
    const evenDigits = numStr.split('').filter(c => c % 2 === 0).sort((a, b) => b - a);
    const oddDigits = numStr.split('').filter(c => c % 2 !== 0).sort((a, b) => b - a);

    const result = numStr.split('').map(c => {
        if (c % 2 === 0) {
            return evenDigits.shift();
        } else {
            return oddDigits.shift();
        }
    }).join('');

    return parseInt(result, 10);
}

