}

java_code:
int minSumOfSquaredDifference(int[] nums1, int[] nums2, int k1, int k2) {
    long res = 0;
    for (int i = 0; i < nums1.length; ++i) {
        int diff = Math.abs(nums1[i] - nums2[i]);
        int steps = Math.min(k1 + k2, diff);
        diff -= steps;
        k1 -= Math.min(k1, steps);
        res += (long)diff * diff;
    }
    return (int)res;
}

cpp_code:
int minSumOfSquaredDifference(vector<int>& nums1, vector<int>& nums2, int k1, int k2) {
    int64_t res = 0;
    for (int i = 0; i < nums1.size(); ++i) {
        int diff = abs(nums1[i] - nums2[i]);
        int steps = min(k1 + k2, diff);
        diff -= steps;
        k1 -= min(k1, steps);
        res += 1LL * diff * diff;
    }
    return (int)res;
}

