class SmallestInfiniteSet {
public:
    std::set<int> available;
    int counter = 1;

    SmallestInfiniteSet() {
        for (int i = 1; i <= 1000; ++i)
            available.insert(i);
    }

    int popSmallest() {
        int smallest = counter;
        if (available.find(counter) != available.end())
            available.erase(counter);
        else
            counter++;
        return smallest;
    }

    void addBack(int num) {
        available.insert(num);
    }
};

