java_code:
public boolean canTransform(String start, String target) {
    int n = start.length();
    int p = 0, q = 0;

    while (p < n && q < n) {
        while (p < n && start.charAt(p) == '_') p++;
        while (q < n && target.charAt(q) == '_') q++;

        if (p == n || q == n) break;

        if (start.charAt(p) != target.charAt(q)) return false;

        if (start.charAt(p) == 'L' && p < q) return false;
        if (start.charAt(p) == 'R' && p > q) return false;

        p++; q++;
    }

    return p == n && q == n;
}

cpp_code:
bool canTransform(string start, string target) {
    int n = start.length();
    int p = 0, q = 0;

    while (p < n && q < n) {
        // Move pointers until there is a letter.
        while (p < n && start[p] == '_') p++;
        while (q < n && target[q] == '_') q++;

        if (p == n || q == n) break;

        // Check if the chars at pointers are the same.
        if (start[p] != target[q]) return false;

        if (start[p] == 'L' && p < q) return false;
        if (start[p] == 'R' && p > q) return false;

        p++; q++;
    }

    return p == n && q == n;
}

javascript_code:
function canTransform(start, target) {
    let n = start.length;
    let p = 0, q = 0;

    while (p < n && q < n) {
        while (p < n && start[p] === '_') p++;
        while (q < n && target[q] === '_') q++;

        if (p === n || q === n) break;

        if (start[p] !== target[q]) return false;

        if (start[p] === 'L' && p < q) return false;
        if (start[p] === 'R' && p > q) return false;

        p++; q++;
    }

    return p === n && q === n;
}

