        for (int temp = num; temp; temp /= 10) {
            sum_of_digits += temp % 10;
        }

        int prev_max = digit_sum_to_max[sum_of_digits];
        if (prev_max) {
            ans = max(ans, num + prev_max);
        }
        digit_sum_to_max[sum_of_digits] = max(num, prev_max);
    }

    return ans;
}

