java_code:
import java.util.*;

public class Solution {
    public int[] kthSmallestIndex(String[] nums, int[][] queries) {
        int[] answer = new int[queries.length];
        int[][] indices = new int[nums.length][2];
        for (int i = 0; i < nums.length; ++i) {
            indices[i][0] = Integer.parseInt(nums[i]);
            indices[i][1] = i;
        }

        Arrays.sort(indices, (a, b) -> (a[0] - b[0]) == 0 ? (a[1] - b[1]) : (a[0] - b[0]));

        for (int i = 0; i < queries.length; ++i) {
            int k = queries[i][0];
            int trim = queries[i][1];
            for (int j = 0; j < nums.length; ++j) {
                indices[j][0] = Integer.parseInt(nums[j].substring(nums[j].length() - trim));
            }
            Arrays.sort(indices, (a, b) -> (a[0] - b[0]) == 0 ? (a[1] - b[1]) : (a[0] - b[0]));
            answer[i] = indices[k - 1][1];
        }

        return answer;
    }
}

cpp_code:
#include <vector>
#include <algorithm>
#include <string>
using namespace std;

vector<int> kthSmallestIndex(vector<string>& nums, vector<vector<int>>& queries) {
    vector<int> answer;
    vector<pair<int, int>> indices(nums.size());
    for (size_t i = 0; i < nums.size(); ++i) {
        indices[i] = {stoi(nums[i]), i};
    }

    for (auto& query : queries) {
        auto k = query[0];
        auto trim = query[1];
        for (size_t i = 0; i < nums.size(); ++i) {
            indices[i].first = stoi(nums[i].substr(nums[i].size() - trim));
        }
        sort(indices.begin(), indices.end());
        answer.push_back(indices[k - 1].second);
    }

    return answer;
}

