    std::map<char, int> suit_count;
    for (int i = 0; i < ranks.size(); ++i) {
        rank_count[ranks[i]]++;
        suit_count[suits[i]]++;
    }
    if (suit_count.size() == 1) return "Flush ";
    if (rank_count.size() == 3) return "Three of a Kind ";
    for (const auto &pair : rank_count) {
        if (pair.second == 2) return "Pair ";
    }
    return "High Card ";
}

