#include <unordered_map>
#include <map>

class NumberContainers {
public:
    NumberContainers() {
    }

    void change(int index, int number) {
        if (indices.count(index)) {
            int old_number = indices[index];
            nums[old_number].erase(index);
            if (nums[old_number].empty()) {
                nums.erase(old_number);
            }
        }
        indices[index] = number;
        nums[number].insert(index);
    }

    int find(int number) {
        if (nums.count(number)) {
            return *nums[number].begin();
        }
        return -1;
    }

private:
    std::unordered_map<int, int> indices;
    std::map<int, std::set<int>> nums;
};

python_code:
class NumberContainers:
    def __init__(self):
        self.indices = {}
        self.nums = {}

    def change(self, index: int, number: int) -> None:
        if index in self.indices:
            old_number = self.indices[index]
            self.nums[old_number].remove(index)
            if not self.nums[old_number]:
                del self.nums[old_number]
        self.indices[index] = number
        if number not in self.nums:
            self.nums[number] = set()
        self.nums[number].add(index)

    def find(self, number: int) -> int:
        if number in self.nums:
            return min(self.nums[number])
        return -1

