class FoodRatings {
public:
    FoodRatings(vector<string>& foods, vector<string>& cuisines, vector<int>& ratings) {
        for (int i = 0; i < foods.size(); ++i) {
            food_ratings[foods[i]] = ratings[i];
            if ((highest_rated.find(cuisines[i]) == highest_rated.end()) ||
                (ratings[i] > food_ratings[highest_rated[cuisines[i]]]) ||
                (ratings[i] == food_ratings[highest_rated[cuisines[i]]] && foods[i] < highest_rated[cuisines[i]])) {
                highest_rated[cuisines[i]] = foods[i];
            }
        }
    }

    void changeRating(string food, int newRating) {
        string cuisine;
        for (const auto& it : highest_rated) {
            if (it.second == food) {
                cuisine = it.first;
                break;
            }
        }
        food_ratings[food] = newRating;
        for (const auto& it : food_ratings) {
            if (highest_rated[cuisine] == food ||
                (newRating > it.second && cuisine == it.first) ||
                (newRating == it.second && food < it.first)) {
                highest_rated[cuisine] = food;
            }
        }
    }

    string highestRated(string cuisine) {
        return highest_rated[cuisine];
    }

private:
    unordered_map<string, int> food_ratings;
    unordered_map<string, string> highest_rated;
};

