        if (task_last_complete.find(task) != task_last_complete.end()) {
            int passed_days = days - task_last_complete[task];
            if (passed_days < space) {
                days += space - passed_days;
            }
        }
        task_last_complete[task] = ++days;
    }

    return days;
}

