#include <set>
#include <unordered_map>
#include <vector>

int maxNodesWithoutRestricted(int n, const std::vector<std::vector<int>>& edges, const std::vector<int>& restricted) {
    std::unordered_map<int, std::vector<int>> tree;
    std::set<int> blocked_nodes(restricted.begin(), restricted.end());

    for (const auto& edge : edges) {
        tree[edge[0]].push_back(edge[1]);
        tree[edge[1]].push_back(edge[0]);
    }

    int max_nodes = 0;
    std::function<void(int, int, int)> dfs = [&](int node, int depth, int parent) {
        if (blocked_nodes.count(node)) return;
        max_nodes = std::max(max_nodes, depth);
        for (int child : tree[node]) {
            if (child != parent) dfs(child, depth + 1, node);
        }
    };

    dfs(0, 1, -1);
    return max_nodes;
}

