from collections import defaultdict

def max_nodes_without_restricted(n, edges, restricted):
    tree = defaultdict(list)
    blocked_nodes = set(restricted)

    for a, b in edges:
        tree[a].append(b)
        tree[b].append(a)

    max_nodes = [0]

    def dfs(node, depth, parent):
        if node in blocked_nodes:
            return
        max_nodes[0] = max(max_nodes[0], depth)
        for child in tree[node]:
            if child != parent:
                dfs(child, depth + 1, node)

    dfs(0, 1, -1)
    return max_nodes[0]

javascript_code:
function maxNodesWithoutRestricted(n, edges, restricted) {
    const tree = new Map();
    const blockedNodes = new Set(restricted);

    for (const [a, b] of edges) {
        if (!tree.has(a)) tree.set(a, []);
        if (!tree.has(b)) tree.set(b, []);
        tree.get(a).push(b);
        tree.get(b).push(a);
    }

    let maxNodes = 0;

    function dfs(node, depth, parent) {
        if (blockedNodes.has(node)) return;
        maxNodes = Math.max(maxNodes, depth);
        for (const child of tree.get(node)) {
            if (child !== parent) dfs(child, depth + 1, node);
        }
    }

    dfs(0, 1, -1);
    return maxNodes;
}

