    for (char c : s) {
        int current = 1;
        for (int i = 0; i < 26; ++i) {
            if (abs(i - (c - 'a')) <= k)
                current = max(current, dp[i] + 1);
        }
        dp[c - 'a'] = max(dp[c - 'a'], current);
    }

    return *max_element(dp.begin(), dp.end());
}

