    for (let c of s) {
        let current = 1;
        for (let i = 0; i < 26; ++i) {
            if (Math.abs(i - (c.charCodeAt() - 'a'.charCodeAt())) <= k)
                current = Math.max(current, dp[i] + 1);
        }
        dp[c.charCodeAt() - 'a'.charCodeAt()] = Math.max(dp[c.charCodeAt() - 'a'.charCodeAt()], current);
    }

    return Math.max(...dp);
}

