    i = 0
    while i < len(pattern):
        if pattern[i] == 'D':
            j = i
            while j < len(pattern) and pattern[j] == 'D':
                j += 1
            num = num[:i] + num[i:j+1][::-1] + num[j+1:]
            i = j
