function shiftCharacters(s, shifts) {
    const shiftValues = new Array(s.length).fill(0);
    for (const shift of shifts) {
        let [start, end, direction] = shift;
        let value = (direction === 1) ? 1 : -1;
        shiftValues[start] += value;
        if (end + 1 < s.length) shiftValues[end + 1] -= value;
    }

    for (let i = 1; i < s.length; i++) {
        shiftValues[i] += shiftValues[i - 1];
    }

    return s.split('').map((c, i) => String.fromCharCode((c.charCodeAt(0) - 'a'.charCodeAt(0) + shiftValues[i]) % 26 + 'a'.charCodeAt(0))).join('');
}

