class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode() {}
    TreeNode(int val) { this.val = val; }
    TreeNode(int val, TreeNode left, TreeNode right) {
        this.val = val;
        this.left = left;
        this.right = right;
    }
}

int timeToInfect(TreeNode node, int start, int minutes) {
    if (node == null) return 0;
    if (node.val == start) return minutes;
    return Math.max(timeToInfect(node.left, start, minutes+1),
                    timeToInfect(node.right, start, minutes+1));
}

int totalInfectionTime(TreeNode root, int total_minutes) {
    if (root == null) return total_minutes;
    int time_needed = Math.max(Math.max(total_minutes,
                                  timeToInfect(root, root.val, 0)),
               Math.max(totalInfectionTime(root.left, total_minutes + 1),
                        totalInfectionTime(root.right, total_minutes + 1)));
    return time_needed;
}

