    if (!root) return total_minutes;
    int time_needed = max({total_minutes,
                           timeToInfect(root, root->val, 0),
                           totalInfectionTime(root->left, total_minutes + 1),
                           totalInfectionTime(root->right, total_minutes + 1)});
    return time_needed;
}

