import java.util.Arrays;

public int[] maxSizeSubsequenceSumQueries(int[] nums, int[] queries) {
    Arrays.sort(nums);
    int[] prefixSums = new int[nums.length + 1];
    for (int i = 0; i < nums.length; ++i) {
        prefixSums[i + 1] = prefixSums[i] + nums[i];
    }

    int[] answer = new int[queries.length];
    for (int i = 0; i < queries.length; ++i) {
        int idx = Arrays.binarySearch(prefixSums, queries[i]);
        if (idx < 0) {
            idx = -idx - 1;
        }
        answer[i] = idx - 1;
    }

    return answer;
}

cpp_code:
#include <vector>
#include <algorithm>
#include <numeric>

std::vector<int> maxSizeSubsequenceSumQueries(std::vector<int>& nums, std::vector<int>& queries) {
    std::sort(nums.begin(), nums.end());
    std::vector<int> prefixSums(nums.size() + 1);
    std::partial_sum(nums.begin(), nums.end(), prefixSums.begin() + 1);

    std::vector<int> answer(queries.size());
    for (int i = 0; i < queries.size(); ++i) {
        answer[i] = std::upper_bound(prefixSums.begin(), prefixSums.end(), queries[i]) - prefixSums.begin() - 1;
    }

    return answer;
}

javascript_code:
function maxSizeSubsequenceSumQueries(nums, queries) {
    nums.sort((a, b) => a - b);
    const prefixSums = Array(nums.length + 1).fill(0);
    for (let i = 0; i < nums.length; ++i) {
        prefixSums[i + 1] = prefixSums[i] + nums[i];
    }

    const answer = [];
    for (const query of queries) {
        const idx = prefixSums.upperBound(query);
        answer.push(idx - 1);
    }

    if (!Array.prototype.upperBound) {
        Array.prototype.upperBound = function(val) {
            let left = 0;
            let right = this.length;
            while (left < right) {
                const mid = (left + right) >>> 1;
                if (this[mid] <= val) {
                    left = mid + 1;
                } else {
                    right = mid;
                }
            }
            return left;
        };
    }

    return answer;
}

