    std::vector<int> row(k + 1, 0), col(k + 1, 0);
    for (const auto& condition : rowConditions) {
        if (row[condition[0]] >= row[condition[1]]) return {};
        row[condition[1]] = row[condition[0]] + 1;
    }
    for (const auto& condition : colConditions) {
        if (col[condition[0]] >= col[condition[1]]) return {};
        col[condition[1]] = col[condition[0]] + 1;
    }
    std::vector<std::vector<int>> matrix(k, std::vector<int>(k));
    for (int i = 1; i <= k; ++i) {
        matrix[row[i]][col[i]] = i;
    }
    return matrix;
}

