function buildMatrix(k, rowConditions, colConditions) {
    let row = new Array(k + 1).fill(0), col = new Array(k + 1).fill(0);
    for (const condition of rowConditions) {
        if (row[condition[0]] >= row[condition[1]]) return [];
        row[condition[1]] = row[condition[0]] + 1;
    }
    for (const condition of colConditions) {
        if (col[condition[0]] >= col[condition[1]]) return [];
        col[condition[1]] = col[condition[0]] + 1;
    }
    let matrix = Array.from({length: k}, () => new Array(k).fill(0));
    for (let i = 1; i <= k; ++i) {
        matrix[row[i]][col[i]] = i;
    }
    return matrix;
}

