    int n = nums.length;
    int count = 0, sum = 0;
    for (int i = 1; i < n; ++i) {
        if (nums[i] > nums[i - 1]) {
            count++;
        } else {
            count = 0;
        }
        sum += count;
    }
    return sum + n;
}

