bool wellSpacedString(std::string s, std::vector<int> distance) {
    std::unordered_map<char, int> first;
    for (int i = 0; i < s.size(); ++i) {
        char c = s[i];
        if (first.find(c) == first.end()) {
            first[c] = i;
        } else {
            if (distance[c - 'a'] != i - first[c] - 1) {
                return false;
            }
        }
    }
    return true;
}

