#include <vector>
#include <queue>
#include <algorithm>

int mostVisitedRoom(int n, std::vector<std::vector<int>>& meetings) {
    std::sort(meetings.begin(), meetings.end());
    std::priority_queue<std::pair<int, int>, std::vector<std::pair<int, int>>, std::greater<>> pq;
    std::vector<int> rooms(n);

    for (const auto& meeting : meetings) {
        while (!pq.empty() && pq.top().first <= meeting[0]) {
            ++rooms[pq.top().second];
            pq.pop();
        }
        pq.push({meeting[1], pq.size() % n});
    }
    int result = 0;
    for (int i = 1; i < n; ++i) {
        if (rooms[i] > rooms[result]) {
            result = i;
        }
    }
    return result;
}

