function minDays(power) {
    const n = power.length;
    const ans = 1e9;
    const dp = new Array(1 << n).fill(1e9);

    dp[0] = 0;
    const sortedPower = [...power].sort((a, b) => a - b);

    for (let i = 0; i < (1 << n); ++i) {
        let powerSum = 0;
        for (let j = 0; j < n; ++j) {
            if (i & (1 << j)) {
                powerSum += sortedPower[j];
            }
        }
        const gain = 1 + countBits(i);
        for (let j = 0; j < n; ++j) {
            if (!(i & (1 << j)) && gain > sortedPower[j]) {
                dp[i | (1 << j)] = Math.min(dp[i | (1 << j)], dp[i] + 1);
            }
        }
    }
    return dp[(1 << n) - 1];

    function countBits(num) {
        let count = 0;
        while (num) {
            num &= (num - 1);
            ++count;
        }
        return count;
    }
}

java_code:
public int mostFrequentEven(int[] nums) {
    Map<Integer, Integer> count = new HashMap<>();
    for (int num : nums) {
        if (num % 2 == 0) {
            count.put(num, count.getOrDefault(num, 0) + 1);
        }
    }
    int maxCount = Integer.MIN_VALUE;
    int mostFrequent = -1;
    for (Map.Entry<Integer, Integer> entry : count.entrySet()) {
        int num = entry.getKey();
        int freq = entry.getValue();
        if (freq > maxCount || (freq == maxCount && num < mostFrequent)) {
            maxCount = freq;
            mostFrequent = num;
        }
    }
    return mostFrequent;
}

