int mostFrequentEven(vector<int>& nums) {
    unordered_map<int, int> count;
    for (int num : nums) {
        if (num % 2 == 0) {
            count[num]++;
        }
    }
    int max_count = INT_MIN;
    int most_frequent = -1;
    for (auto& [num, freq] : count) {
        if (freq > max_count || (freq == max_count && num < most_frequent)) {
            max_count = freq;
            most_frequent = num;
        }
    }
    return most_frequent;
}

