function mostFrequentEven(nums) {
    let count = {};
    for (let num of nums) {
        if (num % 2 === 0) {
            count[num] = (count[num] || 0) + 1;
        }
    }
    let maxCount = Number.MIN_SAFE_INTEGER;
    let mostFrequent = -1;
    for (let num in count) {
        let freq = count[num];
        if (freq > maxCount || (freq === maxCount && parseInt(num) < mostFrequent)) {
            maxCount = freq;
            mostFrequent = parseInt(num);
        }
    }
    return mostFrequent;
}

