            pq.shift();
        }
        pq.push(interval[1]);
        pq.sort((a, b) => a - b);
    }
    return pq.length;
}

java_code:
public int longestSubsequence(int[] nums, int k) {
    int n = nums.length;
    TreeMap<Integer, Integer> dp = new TreeMap<>();
    int ans = 0;

    for (int num : nums) {
        int temp = 0;
        Integer key = dp.lowerKey(num - k);
        if (key != null) {
            temp = dp.get(key);
        }
        dp.put(num, Math.max(dp.getOrDefault(num, 0), temp + 1));
        ans = Math.max(ans, dp.get(num));
    }

    return ans;
}

cpp_code:
int longestSubsequence(vector<int>& nums, int k) {
    int n = nums.size();
    map<int, int> dp;
    int ans = 0;

    for (int num : nums) {
        int temp = 0;
        auto it = dp.upper_bound(num - k - 1);
        if (it != dp.begin()) {
            --it;
            temp = it->second;
        }
        dp[num] = max(dp[num], temp + 1);
        ans = max(ans, dp[num]);
    }

    return ans;
}

