def longestSubsequence(nums, k):
    n = len(nums)
    dp = {}
    ans = 0

    for num in nums:
        temp = 0
        keys = [key for key in dp if num - k <= key]
        if keys:
            temp = dp[max(keys)]

        dp[num] = max(dp.get(num, 0), temp + 1)
        ans = max(ans, dp[num])

    return ans

