#include <unordered_map>
#include <string>
#include <vector>

class SQL {
public:
    SQL(vector<string>& names, vector<int>& columns) {
        for (size_t i = 0; i < names.size(); ++i) {
            tables[names[i]] = {columns[i], {}};
        }
    }

    void insertRow(string name, vector<string>& row) {
        tables[name].second.push_back({++tables[name].first, row});
    }

    void deleteRow(string name, int rowId) {
        auto& rows = tables[name].second;
        rows.erase(remove_if(rows.begin(), rows.end(),
                             [rowId](auto&& p) { return p.first == rowId; }),
                   rows.end());
    }

    string selectCell(string name, int rowId, int columnId) {
        auto& rows = tables[name].second;
        auto it = find_if(rows.begin(), rows.end(), [rowId](auto&& p) { return p.first == rowId; });
        return it->second[columnId - 1];
    }

private:
    unordered_map<string, pair<int, vector<pair<int, vector<string>>>> tables;
};

