        }
    }

    insertRow(name, row) {
        this.tables[name].insertRow(row);
    }

    deleteRow(name, rowId) {
        this.tables[name].deleteRow(rowId);
    }

    selectCell(name, rowId, columnId) {
        return this.tables[name].selectCell(rowId, columnId);
    }
