class Table {
    constructor(columns) {
        this.columns = columns;
        this.rows = [];
        this.nextId = 1;
    }

    insertRow(row) {
        this.rows.push({ id: this.nextId++, values: row });
    }

    deleteRow(rowId) {
        this.rows = this.rows.filter(row => row.id !== rowId);
    }

    selectCell(rowId, columnId) {
        const row = this.rows.find(row => row.id === rowId);
        return row.values[columnId - 1];
    }
}

