import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public List<Integer> prefixScoreSum(List<String> words) {
    List<Integer> result = new ArrayList<>(words.size());
    Map<String, Integer> prefixCount = new HashMap<>();

    for (String word : words) {
        String prefix = "";
        for (char c : word.toCharArray()) {
            prefix += c;
            prefixCount.put(prefix, prefixCount.getOrDefault(prefix, 0) + 1);
        }
    }

    for (String word : words) {
        String prefix = "";
        int sum = 0;
        for (char c : word.toCharArray()) {
            prefix += c;
            sum += prefixCount.getOrDefault(prefix, 0);
        }
        result.add(sum);
    }

    return result;
}

