#include <vector>
#include <string>
#include <unordered_map>

std::vector<int> prefix_score_sum(std::vector<std::string>& words) {
    std::vector<int> result(words.size(), 0);
    std::unordered_map<std::string, int> prefix_count;

    for (const auto& word : words) {
        std::string prefix = "";
        for (const auto& c : word) {
            prefix += c;
            prefix_count[prefix]++;
        }
    }

    for (int i = 0; i < words.size(); ++i) {
        std::string prefix = "";
        for (const auto& c : words[i]) {
            prefix += c;
            result[i] += prefix_count[prefix];
        }
    }

    return result;
}

