int smallestFairNumber(int n) {
    while (true) {
        int k = n;
        int even = 0, odd = 0;
        while (k > 0) {
            k % 2 == 0 ? even++ : odd++;
            k /= 10;
        }
        if (even == odd) return n;
        n++;
    }
}

python_code:
def smallest_fair_number(n):
    while True:
        k = n
        even = 0
        odd = 0
        while k > 0:
            if k % 2 == 0:
                even += 1
            else:
                odd += 1
            k //= 10
        if even == odd:
            return n
        n += 1

javascript_code:
function smallestFairNumber(n) {
    while (true) {
        let k = n;
        let even = 0, odd = 0;
        while (k > 0) {
            k % 2 === 0 ? even++ : odd++;
            k = Math.floor(k / 10);
        }
        if (even === odd) return n;
        n++;
    }
}

