import java.util.ArrayList;
import java.util.Arrays;
import java.util.Comparator;
import java.util.List;

public List<String> sortNamesByHeight(String[] names, int[] heights) {
    List<Pair> nameHeightPairs = new ArrayList<>();

    for(int i = 0; i < names.length; i++) {
        nameHeightPairs.add(new Pair(heights[i], names[i]));
    }

    nameHeightPairs.sort((a, b) -> b.height - a.height);

    List<String> sortedNames = new ArrayList<>();
    for(Pair pair : nameHeightPairs) {
        sortedNames.add(pair.name);
    }

    return sortedNames;
}

class Pair {
    int height;
    String name;

    public Pair(int height, String name) {
        this.height = height;
        this.name = name;
    }
}

cpp_code:
#include <vector>
#include <string>
#include <algorithm>

std::vector<std::string> sortNamesByHeight(std::vector<std::string>& names, std::vector<int>& heights) {
    std::vector<std::pair<int, std::string>> name_height_pairs;

    for(int i = 0; i < names.size(); i++) {
        name_height_pairs.push_back(std::make_pair(heights[i], names[i]));
    }

    std::sort(name_height_pairs.rbegin(), name_height_pairs.rend());

    std::vector<std::string> sorted_names;
    for(auto& pair : name_height_pairs) {
        sorted_names.push_back(pair.second);
    }

    return sorted_names;
}

