#include <vector>

std::vector<int> findGoodIndices(const std::vector<int>& nums, int k) {
    std::vector<int> good_indices;
    for(int i = k; i < nums.size() - k; ++i) {
        bool left_non_inc = true;
        bool right_non_dec = true;

        for(int j = 0; j < k - 1; ++j) {
            if (nums[i - j - 1] < nums[i - j - 2]) {
                left_non_inc = false;
                break;
            }
        }

        for(int j = 0; j < k - 1; ++j) {
            if (nums[i + j + 1] < nums[i + j + 2]) {
                right_non_dec = false;
                break;
            }
        }

        if (left_non_inc && right_non_dec) {
            good_indices.push_back(i);
        }
    }
    return good_indices;
}

