void dfs(int node, int parent, const vector<vector<int>>& adj, const vector<int>& vals, int curMax, int& count) {
    if (vals[node] >= curMax) {
        if (vals[node] > curMax) {
            count++;
            curMax = vals[node];
        }
        for (int next : adj[node]) {
            if (next != parent) {
                dfs(next, node, adj, vals, curMax, count);
            }
        }
    }
}

int NumberOfGoodPaths(const vector<int>& vals, const vector<vector<int>>& edges) {
    int n = vals.size();
    vector<vector<int>> adj(n);
    for (const auto& edge : edges) {
        adj[edge[0]].push_back(edge[1]);
        adj[edge[1]].push_back(edge[0]);
    }
    int count = 0;
    for (int i = 0; i < n; i++) {
        dfs(i, -1, adj, vals, -1, count);
    }
    return count;
}

