import java.util.HashMap;

public boolean canEqualFrequency(String word) {
    HashMap<Character, Integer> freq = new HashMap<>();
    for (char c : word.toCharArray()) {
        freq.put(c, freq.getOrDefault(c, 0) + 1);
    }

    HashMap<Integer, Integer> count_freq = new HashMap<>();
    for (int f : freq.values()) {
        count_freq.put(f, count_freq.getOrDefault(f, 0) + 1);
    }

    if (count_freq.size() != 2) {
        return false;
    }

    int a = (int) count_freq.keySet().toArray()[0];
    int acount = count_freq.get(a);
    int b = (int) count_freq.keySet().toArray()[1];
    int bcount = count_freq.get(b);

    return (acount == 1 && (a - 1 == b || a == 1)) || (bcount == 1 && (b - 1 == a || b == 1));
}

cpp_code:
#include <unordered_map>

bool canEqualFrequency(std::string word) {
    std::unordered_map<char, int> freq;
    for (char c : word) {
        freq[c]++;
    }

    std::unordered_map<int, int> count_freq;
    for (auto &[c, f] : freq) {
        count_freq[f]++;
    }

    if (count_freq.size() != 2) {
        return false;
    }

    auto it = count_freq.begin();
    auto &[a, acount] = *it;
    it++;
    auto &[b, bcount] = *it;

    return (acount == 1 && (a - 1 == b || a == 1)) || (bcount == 1 && (b - 1 == a || b == 1));
}

python_code:
def can_equal_frequency(word: str) -> bool:
    freq = {}
    for c in word:
        freq[c] = freq.get(c, 0) + 1

    count_freq = {}
    for f in freq.values():
        count_freq[f] = count_freq.get(f, 0) + 1

    if len(count_freq) != 2:
        return False

    a, acount = next(iter(count_freq.items()))
    b, bcount = next(reversed(list(count_freq.items())))

    return (acount == 1 and (a - 1 == b or a == 1)) or (bcount == 1 and (b - 1 == a or b == 1))

