class LUPrefix {
public:
    LUPrefix(int n) : max_prefix_length(0), next_video(1), uploaded(n + 1, false) {}

    void upload(int video) {
        uploaded[video] = true;
        if (video == next_video) {
            while (uploaded[next_video]) ++next_video;
        }
    }

    int longest() {
        return next_video - 1;
    }

private:
    int max_prefix_length, next_video;
    std::vector<bool> uploaded;
};

python_code:
class LUPrefix:
    def __init__(self, n: int):
        self.max_prefix_length = 0
        self.next_video = 1
        self.uploaded = [False] * (n + 1)

    def upload(self, video: int) -> None:
        self.uploaded[video] = True
        if video == self.next_video:
            while self.uploaded[self.next_video]:
                self.next_video += 1

    def longest(self) -> int:
        return self.next_video - 1

javascript_code:
class LUPrefix {
    constructor(n) {
        this.maxPrefixLength = 0;
        this.nextVideo = 1;
        this.uploaded = new Array(n + 1).fill(false);
    }

    upload(video) {
        this.uploaded[video] = true;
        if (video === this.nextVideo) {
            while (this.uploaded[this.nextVideo]) this.nextVideo++;
        }
    }

    longest() {
        return this.nextVideo - 1;
    }
}

