def common_factors(a: int, b: int) -> int:
    from math import gcd

    g = gcd(a, b)
    count = 0
    for i in range(1, int(g**0.5) + 1):
        if g % i == 0:
            count += 1
            if i * i != g:
                count += 1
    return count

javascript_code:
function commonFactors(a, b) {
    let gcd = (a, b) => b === 0 ? a : gcd(b, a % b);
    let g = gcd(a, b);
    let count = 0;
    for (let i = 1; i * i <= g; i++) {
        if (g % i === 0) {
            count++;
            if (i * i !== g)
                count++;
        }
    }
    return count;
}

