function maxHourglassSum(grid) {
    let m = grid.length, n = grid[0].length;
    let maxSum = -Infinity;
    for(let i = 1; i < m - 1; ++i) {
        for(let j = 1; j < n - 1; ++j) {
            let sum = grid[i-1][j-1] + grid[i-1][j] + grid[i-1][j+1]
                      + grid[i][j]
                      + grid[i+1][j-1] + grid[i+1][j] + grid[i+1][j+1];
            maxSum = Math.max(maxSum, sum);
        }
    }
    return maxSum;
}

