    }
    return x ^ num1;
}

python_code:
def minSetXor(num1: int, num2: int) -> int:
    set_count = bin(num2).count('1')
    x = 0
    for i in range(32):
        if set_count <= 0:
            break
        if num2 & (1 << i):
            x |= (1 << i)
            set_count -= 1
    return x ^ num1

