            x |= (1 << i);
            set_count--;
        }
    }
    return x ^ num1;
}

java_code:
public int maxOperations(String s) {
    int count = 0;
    while (!s.isEmpty()) {
        for (int i = s.length() / 2; i > 0; i--) {
            if (s.substring(0, i).equals(s.substring(i, 2 * i))) {
                s = s.substring(i);
                count++;
                break;
            } else if (i == 1) {
                s = s.substring(1);
                count++;
            }
        }
    }
    return count;
}

cpp_code:
int maxOperations(std::string s) {
    int count = 0;
    while (!s.empty()) {
        for (int i = s.length() / 2; i > 0; i--) {
            if (s.substr(0, i) == s.substr(i, i)) {
                s.erase(0, i);
                count++;
                break;
            } else if (i == 1) {
                s.erase(0, 1);
                count++;
            }
        }
    }
    return count;
}

