def maxOperations(s: str) -> int:
    count = 0
    while s:
        for i in range(len(s) // 2, 0, -1):
            if s[:i] == s[i:2*i]:
                s = s[i:]
                count += 1
                break
            elif i == 1:
                s = s[1:]
                count += 1
    return count

