public String robotSort(String s) {
    StringBuilder sb = new StringBuilder();
    for (char c : s.toCharArray()) {
        while (sb.length() > 0 && sb.charAt(sb.length() - 1) <= c) {
            sb.setLength(sb.length() - 1);
        }
        sb.append(c);
    }
    return sb.toString();
}

cpp_code:
std::string robotSort(std::string s) {
    std::string t;
    for (char c : s) {
        while (!t.empty() && t.back() <= c) {
            t.pop_back();
        }
        t.push_back(c);
    }
    return t;
}

python_code:
def robot_sort(s):
    t = []
    for c in s:
        while t and t[-1] <= c:
            t.pop()
        t.append(c)
    return ''.join(t)

