public int countValidTimes(String time) {
    int count = 1;
    if(time.charAt(0) == '?') {
        count *= (time.charAt(1) == '?' || time.charAt(1) < '4') ? 3 : 2;
    }
    if(time.charAt(1) == '?') {
        count *= (time.charAt(0) == '2') ? 4 : 10;
    }
    if(time.charAt(3) == '?') {
        count *= 6;
    }
    if(time.charAt(4) == '?') {
        count *= 10;
    }
    return count;
}

