#include <vector>
using namespace std;
typedef long long ll;
const int mod = 1e9 + 7;

vector<int> getPowers(int n) {
    vector<int> powers;
    while (n > 0) {
        powers.push_back(n & (-n));
        n -= n & (-n);
    }
    return powers;
}

vector<int> productOfPowers(int n, vector<vector<int>>& queries) {
    vector<int> powers = getPowers(n);
    vector<int> answers;

    for(auto query : queries) {
        ll product = 1;
        for(int i = query[0]; i <= query[1]; i++) {
            product = (product * powers[i]) % mod;
        }
        answers.push_back(product);
    }

    return answers;
}

