using namespace std;

int dfs(int node, int parent, vector<int>& nums, vector<vector<int>>& graph, int total, int& result) {
    int sum = nums[node];
    for (int neighbor : graph[node]) {
        if (neighbor != parent) {
            sum += dfs(neighbor, node, nums, graph, total, result);
        }
    }
    if (sum == total / 2) {
        result++;
        return 0;
    }
    return sum;
}

int delete_edges_to_balance_tree(vector<int>& nums, vector<vector<int>>& edges) {
    int n = nums.size();
    vector<vector<int>> graph(n);
    for (auto& e : edges) {
        graph[e[0]].push_back(e[1]);
        graph[e[1]].push_back(e[0]);
    }

    int total = 0;
    for (int num : nums) {
        total += num;
    }
    if (total % 2 != 0) {
        return 0;  // It is impossible to split the tree fairly.
    }

    int result = 0;
    dfs(0, -1, nums, graph, total, result);
    return result - 1;
}

