function dfs(node, parent, nums, graph, total, result) {
    let sum = nums[node];
    for (let neighbor of graph[node]) {
        if (neighbor !== parent) {
            sum += dfs(neighbor, node, nums, graph, total, result);
        }
    }
    if (sum === Math.floor(total / 2)) {
        result.push(1);
        return 0;
    }
    return sum;
