#include <vector>
#include <unordered_map>

int flipTrees(int n, std::vector<int>& queries) {
    std::unordered_map<int, bool> flipped_nodes;
    for (int query : queries) {
        flipped_nodes[query] = !flipped_nodes[query];
        while (query > 1) {
            query /= 2;
            flipped_nodes[query] = !flipped_nodes[query];
        }
    }

    int count = 0;
    for (const auto& node : flipped_nodes) {
        if (node.second) {
            count++;
        }
    }
    return count;
}

python_code:
def flip_trees(n, queries):
    flipped_nodes = {}
    for query in queries:
        flipped_nodes[query] = not flipped_nodes.get(query, False)
        while query > 1:
            query //= 2
            flipped_nodes[query] = not flipped_nodes.get(query, False)

    count = 0
    for value in flipped_nodes.values():
        if value:
            count += 1

    return count

