        flippedNodes.set(query, !flippedNodes.get(query));
        while (query > 1) {
            query = Math.floor(query / 2);
            flippedNodes.set(query, !flippedNodes.get(query));
        }
    });

    let count = 0;
    flippedNodes.forEach(value => {
        if (value) {
            count++;
        }
    });

    return count;
}

