int distinctStrings(string s, int k) {
    int n = s.length(), cnt = 0;
    unordered_set<string> st;

    for (int i = 0; i <= n - k; ++i) {
        string temp = s.substr(0, i) + s.substr(i + k);
        if (st.count(temp) == 0) {
            st.insert(temp);
            cnt = (cnt + 1) % MOD;
        }
    }
    return cnt + 1; // Add 1 for the original string 
}

