#include <vector>
#include <string>
#include <unordered_map>

std::vector<std::vector<std::string>> highestPopularity(std::vector<std::string>& creators, std::vector<std::string>& ids, std::vector<int>& views) {
    std::unordered_map<std::string, int> popularity;
    std::unordered_map<std::string, std::pair<std::string, int>> most_viewed;
    for(int i = 0; i < creators.size(); i++) {
        popularity[creators[i]] += views[i];
        if (!most_viewed.count(creators[i]) || views[i] > most_viewed[creators[i]].second
            || (views[i] == most_viewed[creators[i]].second && ids[i] < most_viewed[creators[i]].first)) 
        {
            most_viewed[creators[i]] = {ids[i], views[i]};
        }
    }

    int max_popularity = 0;
    for(auto& [creator, popular] : popularity) {
        max_popularity = std::max(max_popularity, popular);
    }

    std::vector<std::vector<std::string>> result;
    for(auto& [creator, popular] : popularity) {
        if (popular == max_popularity) {
            result.push_back({creator, most_viewed[creator].first});
        }
    }
    return result;
}

