from collections import defaultdict

def highest_popularity(creators, ids, views):
    popularity = defaultdict(int)
    most_viewed = {}

    for i in range(len(creators)):
        popularity[creators[i]] += views[i]
        if creators[i] not in most_viewed or views[i] > most_viewed[creators[i]][1] or (views[i] == most_viewed[creators[i]][1] and ids[i] < most_viewed[creators[i]][0]):
            most_viewed[creators[i]] = (ids[i], views[i])

    max_popularity = max(popularity.values())

    return [[creator, most_viewed[creator][0]] for creator, pop in popularity.items() if pop == max_popularity]

javascript_code:
function highestPopularity(creators, ids, views) {
    const popularity = {};
    const mostViewed = {};

    for (let i = 0; i < creators.length; i++) {
        const creator = creators[i];
        const id = ids[i];
        const view = views[i];

        popularity[creator] = (popularity[creator] || 0) + view;
        if (!mostViewed[creator] || view > mostViewed[creator].view
            || (view === mostViewed[creator].view && id < mostViewed[creator].id))
        {
            mostViewed[creator] = { id, view };
        }
    }

    const maxPopularity = Math.max(...Object.values(popularity));

    const result = [];
    for (const [creator, value] of Object.entries(popularity)) {
        if (value === maxPopularity) {
            result.push([creator, mostViewed[creator].id]);
        }
    }
    return result;
}

