// Definition for a binary tree node.
function TreeNode(val, left, right) {
    this.val = (val === undefined ? 0 : val);
    this.left = (left === undefined ? null : left);
    this.right = (right === undefined ? null : right);
}

/**
 * @param {TreeNode} root
 * @param {number[]} queries
 * @return {number[]}
 */
var removeSubtrees = function(root, queries) {
    const removeSubtree = (node, val) => {
        if (!node) return;

        if (node.left && node.left.val === val) {
            node.left = null;
        } else {
            removeSubtree(node.left, val);
        }

        if (node.right && node.right.val === val) {
            node.right = null;
        } else {
            removeSubtree(node.right, val);
        }
    };

    const findHeight = (node) => {
        if (!node) return -1;

        return 1 + Math.max(findHeight(node.left), findHeight(node.right));
    };

    const answer = [];
    for (const query of queries) {
        removeSubtree(root, query);
        answer.push(findHeight(root));
    }

    return answer;
};

