java_code:
public int maxSubarraySumWithDistinctElements(int[] nums, int k) {
    int max_sum = 0, window_sum = 0;
    HashMap<Integer, Integer> freq_map = new HashMap<>();

    for (int i = 0; i < nums.length; i++) {
        freq_map.put(nums[i], freq_map.getOrDefault(nums[i], 0) + 1);
        window_sum += nums[i];
        if (i >= k) {
            freq_map.put(nums[i - k], freq_map.get(nums[i - k]) - 1);
            window_sum -= nums[i - k];
        }
        if (i >= k - 1) {
            boolean is_distinct = true;
            for (Integer value : freq_map.values()) {
                if (value > 1) {
                    is_distinct = false;
                    break;
                }
            }
            if (is_distinct) {
                max_sum = Math.max(max_sum, window_sum);
            }
        }
    }
    return max_sum;
}

cpp_code:
int maxSubarraySumWithDistinctElements(vector<int>& nums, int k) {
    int max_sum = 0, window_sum = 0;
    unordered_map<int, int> freq_map;

    for (int i = 0; i < nums.size(); i++) {
        freq_map[nums[i]]++;
        window_sum += nums[i];
        if (i >= k) {
            freq_map[nums[i - k]]--;
            window_sum -= nums[i - k];
        }
        if (i >= k - 1) {
            bool is_distinct = true;
            for (const auto& pair : freq_map) {
                if (pair.second > 1) {
                    is_distinct = false;
                    break;
                }
            }
            if (is_distinct) {
                max_sum = max(max_sum, window_sum);
            }
        }
    }
    return max_sum;
}

python_code:
def maxSubarraySumWithDistinctElements(nums: List[int], k: int) -> int:
    max_sum = 0
    window_sum = 0
    freq_map = collections.defaultdict(int)

    for i, num in enumerate(nums):
        freq_map[num] += 1
        window_sum += num
        if i >= k:
            freq_map[nums[i - k]] -= 1
            window_sum -= nums[i - k]
        if i >= k - 1:
            is_distinct = all(value <= 1 for value in freq_map.values())
            if is_distinct:
                max_sum = max(max_sum, window_sum)

    return max_sum

