public int modPow(long x, int n, int mod) {
    long res = 1;
    while (n > 0) {
        if (n % 2 == 1) {
            res = (res * x) % mod;
        }
        x = (x * x) % mod;
        n /= 2;
    }
    return (int) res;
}

public int goodStrings(int low, int high, int zero, int one) {
    long mod = 1000000007;
    return (int) (((modPow(2, high, (int) mod) - modPow(2, low - 1, (int) mod) + 1) * (zero + 1)) % mod * (one + 1)) % mod;
}

