function dfs(node, parent, bob, time, aliceIncome, amount, tree) {
    if (time < bob || amount[node] >= 0) {
        aliceIncome.val += amount[node];
    } else {
        aliceIncome.val += amount[node] / 2;
    }
    amount[node] = 0;
    let isLeaf = true;
    for (let child of tree[node]) {
        if (child !== parent) {
            isLeaf = false;
            const tempIncome = {val: aliceIncome.val};
            dfs(child, node, bob, time + 1, tempIncome, amount, tree);
        }
    }
    if (isLeaf) {
        aliceIncome.max = Math.max(aliceIncome.max, aliceIncome.val);
    }
}

function maxNetIncome(edges, bob, amount) {
    const tree = new Map();
    for (let edge of edges) {
        if (!tree.has(edge[0])) tree.set(edge[0], []);
        if (!tree.has(edge[1])) tree.set(edge[1], []);
        tree.get(edge[0]).push(edge[1]);
        tree.get(edge[1]).push(edge[0]);
    }
    const aliceIncome = {val: 0, max: -100000};
    dfs(0, -1, bob, 0, aliceIncome, amount, tree);
    return aliceIncome.max;
}

