#include<algorithm>
#include<queue>
#include<vector>
using namespace std;

struct TreeNode {
    int val;
    TreeNode* left;
    TreeNode* right;
    TreeNode() : val(0), left(nullptr), right(nullptr) {}
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
    TreeNode(int x, TreeNode* left, TreeNode* right) : val(x), left(left), right(right) {}
};

int minSwaps(TreeNode* root) {
    int count = 0;
    queue<pair<TreeNode*, int>> que;
    que.push({root, 0});

    vector<int> levelVals;
    int prevDepth = -1;

    while (!que.empty()) {
        auto curr = que.front();
        que.pop();
        TreeNode* node = curr.first;
        int depth = curr.second;

        if (prevDepth != depth) {
            sort(levelVals.begin(), levelVals.end());
            for (int i = 1; i < levelVals.size(); ++i) {
                count += abs(levelVals[i] - levelVals[i-1]) - 1;
            }
            prevDepth = depth;
            levelVals.clear();
        }
        levelVals.push_back(node->val);

        if (node->left) que.push({node->left, depth + 1});
        if (node->right) que.push({node->right, depth + 1});
    }

    sort(levelVals.begin(), levelVals.end());
    for (int i = 1; i < levelVals.size(); ++i) {
        count += abs(levelVals[i] - levelVals[i-1]) - 1;
    }

    return count;
}

