function maxXorSubtree(n, edges, values) {
    const tree = new Map();

    for (const edge of edges) {
        if (!tree.has(edge[0])) {
            tree.set(edge[0], []);
        }

        if (!tree.has(edge[1])) {
            tree.set(edge[1], []);
        }

        tree.get(edge[0]).push(edge[1]);
        tree.get(edge[1]).push(edge[0]);
    }

    let firstMax = 0;
    const rootSum = dfs(0, -1, tree, values, { firstMax });

    return rootSum ^ firstMax;
}

function dfs(node, parent, tree, values, ref) {
    let currentSum = values[node];

    for (const child of tree.get(node)) {
        if (child !== parent) {
            currentSum ^= dfs(child, node, tree, values, ref);
        }
    }

    ref.firstMax = Math.max(ref.firstMax, currentSum);

    return currentSum;
}

