        for (int d2 = 0; d2 < 10; ++d2) {
            ans += (1LL * dp[d1][n - 5] * dp[d2][n - 1]) % mod;
        }
    }
    return ans % mod;
}

python_code:
def palindrome_subsequence(s):
    n = len(s)
    mod = 1000000007
    dp = [[0] * n for _ in range(10)]
    for i in range(n): dp[int(s[i])][i] = 1
    for len_ in range(1, 5):
        for d in range(10):
            for i, j in zip(range(n - len_), range(len_, n)):
                dp[d][j] = (dp[d][j - 1] + (1 if s[j] == str(d) else 0)) % mod
    ans = 0
    for d1 in range(10):
        for d2 in range(10):
            ans += dp[d1][n - 5] * dp[d2][n - 1] % mod
    return ans % mod

javascript_code:
function palindromeSubsequence(s) {
    const n = s.length;
    const mod = 1000000007;
    const dp = Array.from({length: 10}, () => new Array(n).fill(0));
    for (let i = 0; i < n; ++i) dp[parseInt(s[i])][i] = 1;
    for (let len = 1; len <= 4; ++len) {
        for (let d = 0; d < 10; ++d) {
            for (let i = 0, j = len; j < n; ++i, ++j) {
                dp[d][j] = (dp[d][j - 1] + (parseInt(s[j]) === d ? 1 : 0)) % mod;
            }
        }
    }
    let ans = 0;
    for (let d1 = 0; d1 < 10; ++d1) {
        for (let d2 = 0; d2 < 10; ++d2) {
            ans = (ans + dp[d1][n - 5] * dp[d2][n - 1]) % mod;
        }
    }
    return ans;
}

