        for (int right = left; right < nums.size(); ++right) {
            count += (nums[right] == k);
            subarray.insert(lower_bound(subarray.begin(), subarray.end(), nums[right]), nums[right]);
            if ((subarray.size() % 2 == 1) && (subarray[subarray.size() / 2] == k)) {
                ans += count;
            }
        }
    }
    return ans;
}

