java_code:
public boolean isCircular(String sentence) {
    String[] words = sentence.split(" ");
    for (int i = 1; i < words.length; i++) {
        if (words[i - 1].charAt(words[i - 1].length() - 1) != words[i].charAt(0)) {
            return false;
        }
    }
    return words[words.length - 1].charAt(words[words.length - 1].length() - 1) == words[0].charAt(0);
}

cpp_code:
bool isCircular(std::string sentence) {
    std::stringstream ss(sentence);
    std::string word, prev;

    while (ss >> word) {
        if (!prev.empty() && prev.back() != word.front()) {
            return false;
        }
        prev = word;
    }

    return word.back() == sentence.front();
}

