from heapq import heappush, heappop
from collections import defaultdict

def minimumScore(n, roads):
    adj = defaultdict(list)
    for road in roads:
        adj[road[0]].append((road[1], road[2]))
        adj[road[1]].append((road[0], road[2]))

    INF = int(1e9)
    pq = [(0, 1)]

    minDist = [INF] * (n + 1)
    while pq:
        curDist, curCity = heappop(pq)

        if curCity == n:
            return curDist

        if curDist < minDist[curCity]:
            minDist[curCity] = curDist
            for nextCity, nextDist in adj[curCity]:
                candidate_dist = max(curDist, nextDist)
                if candidate_dist < minDist[nextCity]:
                    heappush(pq, (candidate_dist, nextCity))

    return -1

javascript_code:
function minimumScore(n, roads) {
    const adj = new Array(n + 1).fill(null).map(() => []);

    for (const [a, b, distance] of roads) {
        adj[a].push({nextCity: b, nextDist: distance});
        adj[b].push({nextCity: a, nextDist: distance});
    }

    const INF = 1e9;
    const pq = [{curDist: 0, curCity: 1}];

    const minDist = new Array(n + 1).fill(INF);
    while (pq.length) {
        const {curDist, curCity} = pq.shift();

        if (curCity === n) {
            return curDist;
        }

        if (curDist < minDist[curCity]) {
            minDist[curCity] = curDist;
            for (const {nextCity, nextDist} of adj[curCity]) {
                const candidateDist = Math.max(curDist, nextDist);
                if (candidateDist < minDist[nextCity]) {
                    pq.push({curDist: candidateDist, curCity: nextCity});
                }
            }
        }
    }

    return -1;
}

