def max_star_sum(vals, edges, k):
    adj = [[] for _ in range(len(vals))]

    for edge in edges:
        adj[edge[0]].append(vals[edge[1]])
        adj[edge[1]].append(vals[edge[0]])

    ans = float("-inf")
    for i in range(len(vals)):
        adj[i].sort(reverse=True)
        ans = max(ans, vals[i] + sum(adj[i][:k]))

    return ans

javascript_code:
function maxStarSum(vals, edges, k) {
    const adj = Array.from({ length: vals.length }, () => []);

    for (const [a, b] of edges) {
        adj[a].push(vals[b]);
        adj[b].push(vals[a]);
    }

    let ans = -Infinity;
    for (let i = 0; i < vals.length; i++) {
        adj[i].sort((a, b) => b - a);
        const sum = vals[i] + adj[i].slice(0, k).reduce((a, b) => a + b, 0);
        ans = Math.max(ans, sum);
    }

    return ans;
}

