        value_to_indices[nums1[i]].push_back(i);
    }

    int result = 0;
    for (int val : nums2) {
        if (value_to_indices[val].empty()) return -1;
        result += value_to_indices[val].back();
        value_to_indices[val].pop_back();
    }

    return result;
}

