            auto it = max_element(grid[i].begin(), grid[i].end());
            if(*it > maxVal) {
                maxVal = *it;
                maxRow = i;
            }
            grid[i].erase(it);
        }

        ans += maxVal;
        if (grid[maxRow].empty()) {
            grid.erase(grid.begin() + maxRow);
        }
    }

    return ans;
}

