int longest_square_streak(std::vector<int>& nums) {
    std::unordered_set<int> num_set(nums.begin(), nums.end());
    int longest_streak = -1;

    for (int num : num_set) {
        int streak = 1;

        while (num_set.count(static_cast<int>(std::pow(num, 0.5))) > 0) {
            ++streak;
            num = static_cast<int>(std::pow(num, 0.5));
        }

        longest_streak = std::max(longest_streak, streak);
    }

    return longest_streak >= 2 ? longest_streak : -1;
}

