#include <vector>
#include <set>
#include <utility>
using namespace std;

vector<int> traverseMatrix(vector<vector<int>>& grid, const vector<int>& queries, int m, int n) {
    vector<int> dx = {-1, 0, 1, 0};
    vector<int> dy = {0, 1, 0, -1};
    vector<int> answer(queries.size(), 0);

    for (int k = 0; k < queries.size(); ++k) {
        int q = queries[k];
        int points = 0;
        set<pair<int, int>> visited;

        function<void(int, int)> dfs = [&](int x, int y) {
            if (visited.find({x, y}) == visited.end() && grid[x][y] < q) {
                visited.insert({x, y});
                points++;
                for (int i = 0; i < 4; ++i) {
                    int nx = x + dx[i], ny = y + dy[i];
                    if (nx >= 0 && nx < m && ny >= 0 && ny < n) {
                        dfs(nx, ny);
                    }
                }
            }
        };

        dfs(0, 0);
        answer[k] = points;
    }

    return answer;
}

vector<int> maxPoints(vector<vector<int>>& grid, vector<int>& queries) {
    int m = grid.size();
    int n = grid[0].size();
    return traverseMatrix(grid, queries, m, n);
}

javascript_code:
function maxPoints(grid, queries) {
    const m = grid.length;
    const n = grid[0].length;
    const dx = [-1, 0, 1, 0];
    const dy = [0, 1, 0, -1];

    function dfs(x, y, q, visited) {
        if (0 <= x && x < m && 0 <= y && y < n && grid[x][y] < q && !visited.has(`${x},${y}`)) {
            visited.add(`${x},${y}`);
            let points = 1;
            for (let i = 0; i < 4; i++) {
                const nx = x + dx[i], ny = y + dy[i];
                points += dfs(nx, ny, q, visited);
            }
            return points;
        }
        return 0;
    }

    return queries.map(query => dfs(0, 0, query, new Set()));
}

