#include <vector>

std::vector<int> length_of_cycle(int n, const std::vector<std::vector<int>>& queries) {
    std::vector<int> result;
    for (const auto& query : queries) {
        int depth_A = 0, depth_B = 0, A = query[0], B = query[1];
        while (A != B) {
            if (A < B) std::swap(A, B);
            A >>= 1;
            depth_A++;
        }
        result.push_back(depth_A + depth_B);
    }
    return result;
}

