        let depth_A = 0, depth_B = 0, A = query[0], B = query[1];
        while (A !== B) {
            if (A < B) [A, B] = [B, A];
            A >>= 1;
            depth_A++;
        }
        result.push(depth_A + depth_B);
    }
    return result;
}

