#include <vector>
#include <string>
#include <unordered_map>
#include <algorithm>

std::vector<int> top_k_students(const std::vector<std::string>& positive_feedback,
                                 const std::vector<std::string>& negative_feedback,
                                 const std::vector<std::string>& report,
                                 const std::vector<int>& student_id,
                                 int k) {
    std::unordered_map<int, int> points;
    for (size_t i = 0; i < report.size(); ++i) {
        int pos_count = 0, neg_count = 0;
        for (const auto& pos : positive_feedback) {
            size_t pos_index = report[i].find(pos);
            while (pos_index != std::string::npos) {
                ++pos_count;
                pos_index = report[i].find(pos, pos_index + pos.length());
            }
        }
        for (const auto& neg : negative_feedback) {
            size_t neg_index = report[i].find(neg);
            while (neg_index != std::string::npos) {
                ++neg_count;
                neg_index = report[i].find(neg, neg_index + neg.length());
            }
        }
        points[student_id[i]] += 3 * pos_count - neg_count;
    }

    std::vector<int> students(student_id.begin(), student_id.end());
    std::sort(students.begin(), students.end(), [&points](int a, int b) {
        return points[a] != points[b] ? points[a] > points[b] : a < b;
    });

    return std::vector<int>(students.begin(), students.begin() + k);
}

