int maxFrequencyScore(std::vector<int>& nums, int k) {
    int n = nums.size();
    int right = 0, count = 0, max_score = 0;
    long long score = 0;
    std::unordered_map<int, int> freqMap;

    for (int left = 0; left < n; ++left) {
        while (right < n && count < k) {
            score = (score + (long long)nums[right] * freqMap[nums[right]]) % 1000000007;
            freqMap[nums[right]]++;
            count++;
            right++;
        }

        max_score = std::max(max_score, (int)score);

        if (count == k) {
            score -= nums[left] * (freqMap[nums[left]] - 1);
            freqMap[nums[left]]--;
            count--;
        }
    }

    return max_score;
}

