import java.util.*;

class DataStream {
    private int value;
    private int k;
    private Queue<Integer> stream;

    public DataStream(int value, int k) {
        this.value = value;
        this.k = k;
        this.stream = new LinkedList<>();
    }

    public boolean consec(int num) {
        stream.add(num);
        if (stream.size() > k)
            stream.poll();

        return stream.size() == k && Collections.frequency(stream, value) == k;
    }
}

