#include <deque>

class DataStream {
public:
    DataStream(int value, int k) : value(value), k(k) {}

    bool consec(int num) {
        stream.push_back(num);
        if (stream.size() > k)
            stream.pop_front();

        return stream.size() == k && count(stream.begin(), stream.end(), value) == k;
    }

private:
    int value;
    int k;
    std::deque<int> stream;
};

