def xor_beauty(nums):
    n = len(nums)
    maxXOR = 1024
    counter = [0] * maxXOR

    for num in nums:
        counter[num % maxXOR] += 1

    xor_beauty = 0
    for i in range(maxXOR):
        for j in range(i, maxXOR):
            k = (i | j) & (~(i ^ j))
            if k < maxXOR and k >= j:
                count = counter[i] * counter[j] * (1 if i == j else 2)
                if k != i and k != j:
                    count *= counter[k]
                xor_beauty ^= count

    return xor_beauty

javascript_code:
function xorBeauty(nums) {
    const n = nums.length;
    const maxXOR = 1024;
    const counter = new Array(maxXOR).fill(0);

    for (const num of nums) {
        counter[num % maxXOR]++;
    }

    let xor_beauty = 0;
    for (let i = 0; i < maxXOR; i++) {
        for (let j = i; j < maxXOR; j++) {
            const k = (i | j) & (~(i ^ j));
            if (k < maxXOR && k >= j) {
                let count = counter[i] * counter[j] * (i === j ? 1 : 2);
                if (k !== i && k !== j) {
                    count *= counter[k];
                }
                xor_beauty ^= count;
            }
        }
    }

    return xor_beauty;
}

