import java.util.PriorityQueue;
import java.util.Collections;
import java.util.List;

public int maxScore(List<Integer> nums, int k) {
    PriorityQueue<Integer> pq = new PriorityQueue<>(Collections.reverseOrder());
    pq.addAll(nums);
    int score = 0;

    for (int i = 0; i < k; i++) {
        int cur = pq.poll();
        score += cur;
        pq.add(cur / 3);
    }

    return score;
}

