int maxScore(const vector<int>& nums, int k) {
    priority_queue<int> pq(nums.begin(), nums.end());
    int score = 0;

    for (int i = 0; i < k; i++) {
        int cur = pq.top();
        pq.pop();
        score += cur;
        pq.push(cur / 3);
    }

    return score;
}

javascript_code:
function maxScore(nums, k) {
    const pq = new PriorityQueue();
    nums.forEach(e => pq.enqueue(e, -e));
    let score = 0;

    for (let i = 0; i < k; i++) {
        let cur = pq.dequeue()['element'];
        score += cur;
        pq.enqueue(cur / 3, -cur / 3);
    }

    return score;
}

class PriorityQueue {
    constructor() {
        this.collection = [];
    }

    enqueue(element, priority) {
        if (this.isEmpty()) {
            this.collection.push({ element: element, priority: priority });
        } else {
            let added = false;
            for (let i = 0; i < this.collection.length; i++) {
                if (priority < this.collection[i].priority) {
                    this.collection.splice(i, 0, { element: element, priority: priority });
                    added = true;
                    break;
                }
            }
            if(!added) {
                this.collection.push({ element: element, priority: priority });
            }
        }
    }

    dequeue() {
        return this.collection.shift();
    }

    isEmpty() {
        return this.collection.length === 0;
    }
}

