import java.util.*;

public int getLastMoment(int n, int k, int[][] time) {
    PriorityQueue<int[]> left = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));
    PriorityQueue<int[]> right = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));

    for (int i = 0; i < k; i++) {
        left.offer(new int[]{time[i][0] + time[i][2], i});
    }

    while (n > 0) {
        while (!right.isEmpty() && right.peek()[0] <= left.peek()[0]) {
            int[] rightTop = right.poll();
            left.offer(new int[]{rightTop[0] + time[rightTop[1]][0] + time[rightTop[1]][2], rightTop[1]});
        }
        int[] leftTop = left.poll();
        time[leftTop[1]][2] += time[leftTop[1]][3] + time[leftTop[1]][0] + time[leftTop[1]][1];
        right.offer(new int[]{leftTop[0] + time[leftTop[1]][1], leftTop[1]});
        n--;
    }

    int lastMoment = -1;
    while (!right.isEmpty()) {
        lastMoment = Math.max(lastMoment, time[right.poll()[1]][2]);
    }
    return lastMoment;
}

cpp_code:
#include <vector>
#include <queue>
#include <algorithm>
using namespace std;

int getLastMoment(int n, int k, vector<vector<int>>& time) {
    priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> left, right;
    for (int i = 0; i < k; i++) {
        left.push({time[i][0] + time[i][2], i});
    }

    while (n) {
        while (!right.empty() && right.top().first <= left.top().first) {
            auto rightTop = right.top(); right.pop();
            left.push({rightTop.first + time[rightTop.second][0] + time[rightTop.second][2], rightTop.second});
        }
        auto leftTop = left.top(); left.pop();
        time[leftTop.second][2] += time[leftTop.second][3] + time[leftTop.second][0] + time[leftTop.second][1];
        right.push({leftTop.first + time[leftTop.second][1], leftTop.second});
        n--;
    }

    int lastMoment = -1;
    while (!right.empty()) {
        lastMoment = max(lastMoment, time[right.top().second][2]);
        right.pop();
    }
    return lastMoment;
}

javascript_code:
function getLastMoment(n, k, time) {
    const left = time.map((item, index) => [item[0] + item[2], index]);
    left.sort(([a], [b]) => a - b);
    let right = [];

    while (n) {
        while (right.length && right[0][0] <= left[0][0]) {
            let rightTop = right.shift();
            left.push([rightTop[0] + time[rightTop[1]][0] + time[rightTop[1]][2], rightTop[1]]);
            left.sort(([a], [b]) => a - b);
        }
        let leftTop = left.shift();
        time[leftTop[1]][2] += time[leftTop[1]][3] + time[leftTop[1]][0] + time[leftTop[1]][1];
        right.push([leftTop[0] + time[leftTop[1]][1], leftTop[1]]);
        right.sort(([a], [b]) => a - b);
        n--;
    }

    let lastMoment = -1;
    while (right.length) {
        let rightTop = right.shift();
        lastMoment = Math.max(lastMoment, time[rightTop[1]][2]);
    }
    return lastMoment;
}

