void dfs(int u, int p) {
    dp[u].first[0] = price[u];
    dp[u].first[1] = 0;
    dp[u].second[0] = price[u];
    dp[u].second[1] = 0;

    for (int v : adj[u]) {
        if (v == p) continue;
        dfs(v, u);
        dp[u].first.push_back(dp[v].first[0] + price[u] - dp[v].second[0]);
        dp[u].first.push_back(dp[v].first[1]);
        dp[u].second.push_back(dp[v].second[0] + price[u] - dp[v].first[0]);
        dp[u].second.push_back(dp[v].second[1]);

        sort(dp[u].first.begin(), dp[u].first.end());
        sort(dp[u].second.begin(), dp[u].second.end());
    }
}

int getMaxCost(int n, vector<vector<int>>& edges, vector<int>& _price) {
    adj.resize(n);
    price = _price;
    dp.resize(n, pair<vector<long long>, vector<long long>>(vector<long long>(2), vector<long long>(2)));

    for (vector<int>& e : edges) {
        adj[e[0]].push_back(e[1]);
        adj[e[1]].push_back(e[0]);
    }

    dfs(0, -1);

    long long ans = 0;
    for (int i = 0; i < n; ++i) {
        ans = max(ans, dp[i].first.back() - dp[i].second.back());
    }

    return ans;
}

javascript_code:
function dfs(u, p, adj, price, dp) {
  dp[u] = [[price[u], 0], [price[u], 0]];

  for (const v of adj[u]) {
    if (v == p) continue;
    dfs(v, u, adj, price, dp);
    const tmpF = [dp[v][0][0] + price[u] - dp[v][1][0], dp[v][0][1]].sort((a, b) => a - b);
    const tmpS = [dp[v][1][0] + price[u] - dp[v][0][0], dp[v][1][1]].sort((a, b) => a - b);

    dp[u][0] = tmpF;
    dp[u][1] = tmpS;
  }
}

function getMaxCost(n, edges, price) {
  const adj = Array.from({length: n}, () => []);
  const dp = Array(n);

  for (const e of edges) {
    adj[e[0]].push(e[1]);
    adj[e[1]].push(e[0]);
  }

  dfs(0, -1, adj, price, dp);

  let ans = 0;
  for (let i = 0; i < n; ++i) {
    ans = Math.max(ans, dp[i][0][1] - dp[i][1][1]);
  }

  return ans;
}

