public int numberOfGoodSubsequences(String s) {
    int[] count = new int[26];
    long ans = 0;
    final int MOD = 1000000007;

    for (char c : s.toCharArray()) {
        count[c - 'a']++;
    }

    for (int val : count) {
        ans = (ans + (1L << val) - 1) % MOD;
    }

    return (int)ans;
}

