function numberOfGoodSubsequences(s) {
    let count = new Array(26).fill(0);
    let ans = 0;
    const MOD = 1000000007;

    for (let c of s) {
        count[c.codePointAt(0) - 'a'.codePointAt(0)]++;
    }

    for (let val of count) {
        ans = (ans + (BigInt(1) << BigInt(val)) - BigInt(1)) % BigInt(MOD);
    }

    return Number(ans);
}

