public int minChanges(int[] nums1, int[] nums2, int k) {
    int n = nums1.length;
    int operations = 0;
    for (int i = 0; i < n; ++i) {
        int diff = Math.abs(nums1[i] - nums2[i]);
        if (diff % k != 0) return -1;
        operations += diff / k;
    }
    return operations;
}

