public int maxScore(int[] nums1, int[] nums2, int k) {
    int n = nums1.length;
    int res = 0;
    int sum_n1 = 0, min_n2 = nums2[0];
    for (int i = 0, j = 0; j < n; j++) {
        sum_n1 += nums1[j];
        min_n2 = Math.min(min_n2, nums2[j]);
        if (j - i + 1 > k) sum_n1 -= nums1[i++];
        if (j + 1 >= k) res = Math.max(res, sum_n1 * min_n2);
    }
    return res;
}

