java_code:
public int minCost(int[] nums, int k) {
    int n = nums.length;
    int[] count = new int[1001], dp = new int[n + 1];
    Arrays.fill(dp, Integer.MAX_VALUE);
    dp[0] = 0;

    for (int i = 0, j = 0; j < n; ++j) {
        ++count[nums[j]];
        if (count[nums[j]] == 2)
            dp[j + 1] = dp[i] + k + (j - i + 1);
        else if (count[nums[j]] > 2)
            dp[j + 1] = Math.min(dp[j], dp[j - 1] + 1);
        else
            dp[j + 1] = dp[j] + 1;

        while (i < j + 1 && count[nums[i]] >= 2) {
            --count[nums[i]];
            ++i;
        }
    }
    return dp[n] + n * k;
}

cpp_code:
int minCost(vector<int>& nums, int k) {
    int n = nums.size(), INF = 1e9 + 7;
    vector<int> count(1001, 0), dp(n + 1, 0); // count for frequency, dp for dynamic programming

    for (int i = 0, j = 0; j < n; ++j) {
        ++count[nums[j]];

        if (count[nums[j]] == 2) // if occurrence is 2, change dp
            dp[j + 1] = dp[i] + k + (j - i + 1);
        else if (count[nums[j]] > 2) // if occurrence is more than 2
            dp[j + 1] = min(dp[j], dp[j - 1] - (count[nums[j]] - 2)); 
        else
            dp[j + 1] = dp[j] + getCost(j, count) + k;

        while (i < j + 1 && count[nums[i]] >= 2) {
            --count[nums[i]];
            ++i; // update first pointer i when nums[i] has occurred more than once
        }
    }

    return dp[n];
}

int getCost(int j, vector<int> &count) {
    return count[nums[j]] == 1 ? 1 : 0;
}

