const int MOD = 1e9 + 7;

int ways_to_collide(int n) {
    int power_of_2 = 1;
    for (int i = 0; i < n; i++) {
        power_of_2 = (2LL * power_of_2) % MOD;
    }
    return (power_of_2 - n - 1 + MOD) % MOD;
}

