#include <vector>
#include <algorithm>
#include <numeric>

int maximizeScore(std::vector<int>& weights, int k) {
    int n = weights.size();
    std::vector<int> prefix_sum(n + 1);
    std::partial_sum(weights.begin(), weights.end(), prefix_sum.begin() + 1);
    std::vector<std::vector<int>> dp(n, std::vector<int>(k + 1));

    for (int i = 0; i < n; i++) {
        for (int j = 1; j <= k; j++) {
            dp[i][j] = -1e9;
        }
    }

    for (int i = 0; i < n; i++) {
        dp[i][1] = prefix_sum[i + 1];
        if (i > 0) {
            dp[i][i + 1] = prefix_sum[i + 1] - prefix_sum[1];
        }
        for (int j = 2; j <= std::min<int>(i + 1, k); j++) {
            for (int q = 1; q <= i - j + 2; q++) {
                dp[i][j] = std::max(dp[i][j], dp[i - q][j - 1] + weights[i] + weights[i - q]);
            }
        }
    }

    return dp[n - 1][k] - dp[n - 1][1];
}

