int increasing_quadruplets(vector<int>& nums) {
    int n = nums.size(), count = 0;
    for(int i = 0; i < n - 3; i++) {
        for(int j = i + 1; j < n - 2; j++) {
            for(int k = j + 1; k < n - 1; k++) {
                if(nums[i] < nums[k] && nums[k] < nums[j]) {
                    for(int l = k + 1; l < n; l++) {
                        if(nums[j] < nums[l]) {
                            count++;
                        }
                    }
                }
            }
        }
    } 
    return count;
}

