int maxChosenIntegers(vector<int>& banned, int n, int maxSum) {
    unordered_set<int> bannedSet(banned.begin(), banned.end());
    int count = 0, sum = 0;
    for (int i = n; i >= 1 && maxSum - sum >= i; --i) {
        if (bannedSet.find(i) == bannedSet.end()) {
            sum += i;
            ++count;
        }
    }
    return count;
}

