public int maxPrizes(int[] prizePositions, int k) {
    int n = prizePositions.length;
    int ans = 0;
    for (int i = 0; i < n; ++i) {
        int left_segment_end = prizePositions[i] + k;
        int right_segment_start = Arrays.binarySearch(prizePositions, left_segment_end + 1);
        if (right_segment_start < 0) {
            right_segment_start = -right_segment_start - 1;
        }
        int right_segment_end = prizePositions[right_segment_start] + k;
        ans = Math.max(ans, Arrays.binarySearch(prizePositions, right_segment_end + 1)
                       - Arrays.binarySearch(prizePositions, prizePositions[i]));
    }
    return ans;
}

cpp_code:
int maxPrizes(vector<int>& prizePositions, int k) {
    int n = prizePositions.size();
    int ans = 0;
    for (int i = 0; i < n; ++i) {
        int left_segment_end = prizePositions[i] + k;
        int right_segment_start = upper_bound(prizePositions.begin(), prizePositions.end(), left_segment_end) - prizePositions.begin();
        int right_segment_end = prizePositions[right_segment_start] + k;
        ans = max(ans, int(upper_bound(prizePositions.begin(), prizePositions.end(), right_segment_end)
                          - lower_bound(prizePositions.begin(), prizePositions.end(), prizePositions[i])));
    }
    return ans;
}

javascript_code:
function maxPrizes(prizePositions, k) {
    function bs(arr, x) {
        let l = 0, r = arr.length;
        while (l < r) {
            const m = Math.floor((l + r) / 2);
            if (arr[m] < x) l = m + 1;
            else r = m;
        }
        return l;
    }
    const n = prizePositions.length;
    let ans = 0;
    for (let i = 0; i < n; ++i) {
        const left_segment_end = prizePositions[i] + k;
        const right_segment_start = bs(prizePositions, left_segment_end + 1);
        const right_segment_end = prizePositions[right_segment_start] + k;
        ans = Math.max(ans, bs(prizePositions, right_segment_end + 1) - bs(prizePositions, prizePositions[i]));
    }
    return ans;
}

java_code:
boolean canReach(int[][] grid, int row, int col) {
    if (row < 0 || col < 0 || row >= grid.length || col >= grid[0].length || grid[row][col] == 0) return false;

    if (row == grid.length - 1 && col == grid[0].length - 1) return true;

    grid[row][col] = 0;

    return canReach(grid, row + 1, col) || canReach(grid, row, col + 1);
}

boolean canDisconnect(int[][] grid) {
    int reachableCount = 0;

    for (int row = 1; row < grid.length; row++) {
        for (int col = 1; col < grid[0].length; col++) {
            if (grid[row][col] == 1 && (canReach(grid, row - 1, col) || canReach(grid, row, col - 1))) {
                reachableCount++;
                if (reachableCount > 1) return true;
            }
        }
    }

    return reachableCount <= 1;
}

