import java.util.Arrays;

public int giftsRemaining(int[] gifts, int k) {
    for (int i = 0; i < k; i++) {
        Arrays.sort(gifts);
        int maxIndex = gifts.length - 1;
        gifts[maxIndex] -= (int) Math.sqrt(gifts[maxIndex]);
    }
    int remaining_gifts = 0;
    for (int gift : gifts) remaining_gifts += gift;
    return remaining_gifts;
}

