function giftsRemaining(gifts, k) {
    for (let i = 0; i < k; i++) {
        gifts.sort((a, b) => a - b);
        let maxIndex = gifts.length - 1;
        gifts[maxIndex] -= Math.floor(Math.sqrt(gifts[maxIndex]));
    }
    return gifts.reduce((accumulator, currentValue) => accumulator + currentValue, 0);
}

