bool isVowel(char c) {
    return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
}

std::vector<int> countVowelStrings(std::vector<std::string>& words, std::vector<std::vector<int>>& queries) {
    std::vector<int> ans;
    for (auto& query : queries) {
        int count = 0;
        for (int i = query[0]; i <= query[1]; i++) {
            if (isVowel(words[i].front()) && isVowel(words[i].back())) {
                count++;
            }
        }
        ans.push_back(count);
    }
    return ans;
}

