public int minCostToEqualBaskets(int[] basket1, int[] basket2) {
    Map<Integer, Integer> diffCount = new HashMap<>();
    for (int i = 0; i < basket1.length; i++) {
        diffCount.put(basket1[i] - basket2[i], diffCount.getOrDefault(basket1[i] - basket2[i], 0) + 1);
    }

    int minCost = Integer.MAX_VALUE, cost = 0;
    for (Map.Entry<Integer, Integer> entry : diffCount.entrySet()) {
        if (entry.getValue().equals(diffCount.get(-entry.getKey()))) {
            cost = 0;
            for (int i = 0; i < basket1.length; i++) {
                if (basket1[i] - basket2[i] == entry.getKey()) {
                    cost += Math.min(basket1[i], basket2[i]);
                }
            }
            minCost = Math.min(minCost, cost);
        }
    }

    return minCost == Integer.MAX_VALUE ? -1 : minCost / 2;
}

cpp_code:
int minCostToEqualBaskets(vector<int>& basket1, vector<int>& basket2) {
    unordered_map<int, int> diff_count;
    for (int i = 0; i < basket1.size(); i++) {
        diff_count[basket1[i] - basket2[i]]++;
    }

    int min_cost = INT_MAX, cost = 0;
    for (const auto& entry : diff_count) {
        if (entry.second == diff_count[-entry.first]) {
            cost = 0;
            for (int i = 0; i < basket1.size(); i++) {
                if (basket1[i] - basket2[i] == entry.first) {
                    cost += min(basket1[i], basket2[i]);
                }
            }
            min_cost = min(min_cost, cost);
        }
    }

    return min_cost == INT_MAX ? -1 : min_cost / 2;
}

python_code:
def min_cost_to_equal_baskets(basket1, basket2):
    diff_count = {}
    for i in range(len(basket1)):
        diff = basket1[i] - basket2[i]
        diff_count[diff] = diff_count.get(diff, 0) + 1

    min_cost = float('inf')
    for diff, count in diff_count.items():
        if count == diff_count.get(-diff, 0):
            cost = sum(min(basket1[i], basket2[i]) for i in range(len(basket1)) if basket1[i] - basket2[i] == diff)
            min_cost = min(min_cost, cost)

    return -1 if min_cost == float('inf') else min_cost // 2

