#include <vector>
#include <string>
#include <unordered_map>

std::vector<std::vector<int>> shortestSubstringQueries(const std::string& s, const std::vector<std::vector<int>>& queries) {
    int n = s.length();
    std::unordered_map<int, int> dp;

    for (int i = 0, val = 0, mask = 0; i < n; i++) {
        mask |= 1 << (s[i] - '0');
        val = (val << 1) | (s[i] - '0');

        for (int j = 0; j <= 9 && i + 1 - (1 << j) >= 0; j++) {
            int newVal = val & ((1 << (j + 1)) - 1);
            if (dp.count(newVal) == 0) dp[newVal] = i + 1 - (1 << j);
        }
    }

    std::vector<std::vector<int>> ans;
    for (const auto& query : queries) {
        int target = query[0] ^ query[1];
        if (dp.count(target)) ans.push_back({dp[target], dp[target] + static_cast<int>(log2(target))});
        else ans.push_back({-1, -1});
    }

    return ans;
}

