def shortestSubstringQueries(s, queries):
    n = len(s)
    dp = {}
    val = 0
    mask = 0

    for i in range(n):
        mask |= 1 << int(s[i])
        val = (val << 1) | int(s[i])

        for j in range(10):
            if i + 1 - (1 << j) >= 0:
                newVal = val & ((1 << (j + 1)) - 1)
                if newVal not in dp:
