                word[i + lcp[i][j] - 1] = std::max(word[i + lcp[i][j] - 1], (char) (word[i - 1] + 1));
            } else if (lcp[i][j] < std::min(lcp[i - 1][j], lcp[i][j - 1])) {
                return "";
