#include <queue>
#include <vector>
#include <algorithm>

struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
};

int kthLargestLevelSum(TreeNode* root, int k) {
    std::vector<int> level_sums;
    std::queue<TreeNode*> q;
    q.push(root);

    while (!q.empty()) {
        int level_sum = 0;
        int level_size = q.size();
        for (int i = 0; i < level_size; ++i) {
            TreeNode* node = q.front(); q.pop();
            level_sum += node->val;

            if (node->left) q.push(node->left);
            if (node->right) q.push(node->right);
        }

        level_sums.push_back(level_sum);
    }

    std::sort(level_sums.begin(), level_sums.end(), std::greater<int>());
    return (k > level_sums.size() ? -1 : level_sums[k-1]);
}

