#include <map>
#include <vector>
#include <algorithm>
#include <string>

class TodoList {
public:
    struct Task {
        int id;
        std::string description;
        int dueDate;
        std::vector<std::string> tags;
        bool completed;

        Task(int _id, const std::string& _desc, int _dueDate, const std::vector<std::string>& _tags)
            : id(_id), description(_desc), dueDate(_dueDate), tags(_tags), completed(false) {}
    };

    TodoList() : taskId(1) {}

    int addTask(int userId, std::string taskDescription, int dueDate, std::vector<std::string> tags) {
        tasks[userId].emplace_back(taskId, taskDescription, dueDate, tags);
        return taskId++;
    }

    std::vector<std::string> getAllTasks(int userId) {

        std::vector<std::string> res;
        std::vector<Task>& userTasks = tasks[userId];

        std::sort(userTasks.begin(), userTasks.end(), [](const Task& a, const Task& b) {
            return a.dueDate < b.dueDate;
        });

        for (const auto& task : userTasks) {
            if (!task.completed) {
                res.push_back(task.description);
            }
        }

        return res;
    }

    std::vector<std::string> getTasksForTag(int userId, std::string tag) {
        std::vector<std::string> res;
        std::vector<Task>& userTasks = tasks[userId];

        std::sort(userTasks.begin(), userTasks.end(), [](const Task& a, const Task& b) {
            return a.dueDate < b.dueDate;
        });

        for (const auto& task : userTasks) {
            if (!task.completed && std::find(task.tags.begin(), task.tags.end(), tag) != task.tags.end()) {
                res.push_back(task.description);
            }
        }

        return res;
    }

    void completeTask(int userId, int taskId) {
        std::vector<Task>& userTasks = tasks[userId];
        for (auto& task : userTasks) {
            if (task.id == taskId) {
                task.completed = true;
                break;
            }
        }
    }

private:
    int taskId;
    std::map<int, std::vector<Task>> tasks;
};

