public int maxGreatness(int[] nums) {
    Arrays.sort(nums);
    int greatness = 0;
    for (int i = 1; i < nums.length; ++i) {
        if (nums[i - 1] < nums[i]) {
            int temp = nums[i - 1];
            nums[i - 1] = nums[i];
            nums[i] = temp;
            ++greatness;
        }
    }
    return greatness;
}

