public int[] evenOddIndices(int n) {
    int[] answer = new int[2];
    int index = 0;
    while (n > 0) {
        if (n % 2 == 1)
            answer[index % 2] += 1;
        n /= 2;
        index += 1;
    }
    return answer;
}

