int maximum_mex(std::vector<int>& nums, int value) {
    std::unordered_set<int> st(nums.begin(), nums.end());

    for (int i = 0; i <= 100000; i++) {
        if (!st.count(i))
            st.insert(i + value);
    }

    int mex = 0;
    while (st.count(mex))
        mex++;

    return mex;
}

