public int minOperations(int[] nums) {
    int minPrefix = 0;
    int prefix = 0;
    for (int num : nums) {
        prefix += num;
        minPrefix = Math.min(minPrefix, prefix);
    }
    return minPrefix < 0 ? -minPrefix : 0;
}

