java_code:
public boolean strictlyIncreasingArray(int[] nums) {
    for (int i = 0; i < nums.length - 1; ++i) {
        nums[i] -= i;
        if (nums[i] >= nums[i + 1]) {
            return false;
        }
    }
    return true;
}

