#include <vector>
#include <utility>

using std::vector;
using std::pair;

pair<int, int> dfs(const vector<vector<int>>& adj, const vector<int>& coins, int node, int parent) {
    int sum = coins[node], distance = 0;
    for (int neighbor : adj[node]) {
        if (neighbor != parent) {
            auto result = dfs(adj, coins, neighbor, node);
            sum += result.first;
            distance += 2 * result.first + result.second;
        }
    }
    return {sum, distance};
}

int minEdgesToCollectCoins(const vector<int>& coins, const vector<vector<int>>& edges) {
    int n = coins.size();
    vector<vector<int>> adj(n);
    for (const auto& edge : edges) {
        adj[edge[0]].push_back(edge[1]);
        adj[edge[1]].push_back(edge[0]);
    }
    return dfs(adj, coins, 0, -1).second / 2;
}

