        adj[a].push(b);
        adj[b].push(a);
    }
    return dfs(adj, coins, 0, -1)[1] / 2;
}

function dfs(adj, coins, node, parent) {
    let sum_coins = coins[node];
    let distance = 0;
    for (let neighbor of adj[node]) {
        if (neighbor !== parent) {
            let result = dfs(adj, coins, neighbor, node);
            sum_coins += result[0];
            distance += 2 * result[0] + result[1];
        }
    }
    return [sum_coins, distance];
}

