int maxValueSubstring(std::string s, std::string chars, std::vector<int> vals) {
    std::unordered_map<char, int> values;

    for (int i = 0; i < chars.length(); i++) {
        values[chars[i]] = vals[i];
    }

    int max_cost = 0;
    int cost = 0;

    for (char c : s) {
        int value = values.count(c) ? values[c] : static_cast<int>(c - 'a' + 1);

        cost = std::max(0, cost + value);
        max_cost = std::max(max_cost, cost);
    }

    return max_cost;
}

