def max_value_substring(s, chars, vals):
    values = {key: val for key, val in zip(chars, vals)}

    max_cost = 0
    cost = 0

    for c in s:
        value = values.get(c) if c in values else ord(c) - ord('a') + 1

        cost = max(0, cost + value)
        max_cost = max(max_cost, cost)

    return max_cost

