using namespace std;

int shortestCycleLength(int n, vector<vector<int>>& edges) {
    vector<vector<int>> graph(n);
    for (const vector<int>& edge : edges) {
        graph[edge[0]].push_back(edge[1]);
        graph[edge[1]].push_back(edge[0]);
    }

    int shortestCycle = n + 1;
    for (int start = 0; start < n; ++start) {
        vector<int> dist(n, n + 1);
        dist[start] = 0;
        queue<int> q;
        q.push(start);

        while (!q.empty()) {
            int cur = q.front();
            q.pop();
            for (int neigh : graph[cur]) {
                if (dist[neigh] == n + 1) {
                    dist[neigh] = dist[cur] + 1;
                    q.push(neigh);
                } else if (dist[neigh] >= dist[cur] - 1) {
                    shortestCycle = min(shortestCycle, dist[cur] + dist[neigh] + 1);
                }
            }
        }
    }

    return shortestCycle == n + 1 ? -1 : shortestCycle;
}

