import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;

public List<List<Integer>> distinctRowsFrom(int[] nums) {
    List<HashSet<Integer>> rows = new ArrayList<>();

    for(int num : nums) {
        boolean inserted = false;
        for(HashSet<Integer> row : rows) {
            if(!row.contains(num)) {
                row.add(num);
                inserted = true;
                break;
            }
        }

        if(!inserted) {
            HashSet<Integer> newRow = new HashSet<>();
            newRow.add(num);
            rows.add(newRow);
        }
    }

    List<List<Integer>> result = new ArrayList<>();
    for (HashSet<Integer> row : rows) {
        result.add(new ArrayList<Integer>(row));
    }

    return result;
}

cpp_code:
#include <vector>
#include <unordered_set>

std::vector<std::vector<int>> distinctRowsFrom(nums std::vector<int>& nums) {
    std::vector<std::unordered_set<int>> rows;

    for(int num : nums) {
        bool inserted = false;
        for(auto& row : rows) {
            if(row.find(num) == row.end()) {
                row.insert(num);
                inserted = true;
                break;
            }
        }

        if(!inserted) rows.push_back({num});
    }

    std::vector<std::vector<int>> result;
    for(auto& row : rows) {
        result.emplace_back(row.begin(), row.end());
    }

    return result;
}

