def distinct_rows_from(nums):
    rows = []

    for num in nums:
        inserted = False
        for row in rows:
            if num not in row:
                row.add(num)
                inserted = True
                break

        if not inserted:
            rows.append({num})

    return [list(row) for row in rows]

