#include <vector>
#include <algorithm>

int maxPoints(const std::vector<int>& reward1, const std::vector<int>& reward2, int k) {
    std::vector<std::pair<int, int>> gap(reward1.size());
    for (size_t i = 0; i < reward1.size(); ++i) {
        gap[i] = {reward2[i] - reward1[i], i};
    }
    std::sort(gap.rbegin(), gap.rend());
    int firstMousePoints = 0;
    int secondMousePoints = 0;
    for (int i = 0; i < k; ++i) {
        firstMousePoints += reward1[gap[i].second];
    }
    for (int i = k; i < reward1.size(); ++i) {
        secondMousePoints += reward2[gap[i].second];
    }
    return firstMousePoints + secondMousePoints;
}

